INSERT INTO news_item (
    id, tenant_id, category_id, slug, title, summary, status, author_name,
    featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
    ('news-item-7b709068bfd3d7d1', '100001', 'news-category-finance-flash', 'em-202611243938295816-c091d4d7f7', '广东布局AI关键战场：聚焦“六大场景”实施“五个计划”', '11月24日，2026粤港澳大湾区文化产业投资大会在广州开幕。广东在会上提出，将重点聚焦“六大场景”、实施“五个计划”，纵深推进“人工智能+文化”深度融合发展，以抢占AI这一制胜未来的重要战场。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:21:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d7ed62467e5abc8a', '100001', 'news-category-finance-flash', 'em-202611243938299918-056cf25dae', '安恒信息在雄安成立信息技术公司', '天眼查App显示，11月20日，安恒（雄安）信息技术有限公司成立，法定代表人为陈思宇，注册资本1100万元人民币，经营范围包括网络与信息安全软件开发、信息安全设备制造、信息安全设备销售等。股东信息显示，该公司由杭州安恒信息技术股份有限公司全资持股。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:19:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-21b6c19194a5d72f', '100001', 'news-category-finance-flash', 'em-202611243938297842-91e83636ec', '享界V8入局家用MPV，华为“五界”全品类拼图完成，“不造车” 的承诺还能守多久', '11月20日下午，华为鸿蒙智行首款家庭智慧旗舰MPV（多用途汽车）享界V8正式上市，售价31.98万元至42.98万元。至此，享界补上了MPV品类，华为智选车旗下的问界、智界、享界、尊界、尚界“五界”全品类也全部就位。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:17:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8d9d82bd69c8ce49', '100001', 'news-category-finance-flash', 'em-202611243938299249-7b38e3a0f9', '港股大模型股高开低走 智谱震幅近20%', '"大模型双雄"港股早盘高开低走。截至发稿智谱(02513.HK)跌3.17%，报329.4港元，成交逾29亿港元，早盘一度涨15%；MINIMAX-W(00100.HK)也跌近1%。消息面上，英伟达复聘黄仁勋、恒生科技指数扩容。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:16:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-13dc7fb058873225', '100001', 'news-category-finance-flash', 'em-202611243938297983-e1ee6c3bdb', '马斯克旗下Grok惹上官司 美国两州指控其纵容AI生成色情图片', '北京时间11月24日，据The Verge报道，美国俄勒冈州和弗吉尼亚州周一分别对埃隆·马斯克旗下SpaceX提起诉讼，指控其AI聊天机器人Grok生成未经当事人同意的色情深度伪造内容，并在产品安全保障方面误导消费者。两州检察长认为，Grok缺乏有效安全防护并非技术失误，而是产品设计中的有意选择。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:15:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bccbf945ec8683f6', '100001', 'news-category-finance-flash', 'em-202611243938298773-6deeaf2f49', '伦铜日内走低2%', '伦铜日内走低2%，报12220.5美元/吨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:15:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9c6bb2d0271fe84e', '100001', 'news-category-finance-flash', 'em-202611243938297478-78b471d588', '谷歌拟给浏览器AI加道“权限锁”：允许看商品 不许进支付页', '科技媒体 NeoWin 昨日（11 月 23 日）发布博文，报道称谷歌工程师提出实验性方案，计划在浏览器层面为 AI 智能体设置权限边界，避免其获得过大的操作权限。该方案目前仍处于原型提议阶段，尚未确定是否上线 Chrome 浏览器。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:13:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f6faf327bdd3f206', '100001', 'news-category-finance-flash', 'em-202611243938298884-991b48f54d', '2026年6G发展大会启动“6G创新发展部省协同试点”', '在2026年6G发展大会，由北京市、河北省、上海市、江苏省、浙江省、安徽省、湖北省、广东省共同启动“6G创新发展部省协同试点”，搭建起国家统筹协调、地方差异推进、多方积极参与的组织模式，集聚科研、产业、场景、人才等各类资源，推动形成全国6G创新“一盘棋”格局。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:13:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4e549692ef4a1127', '100001', 'news-category-finance-flash', 'em-202611243938275749-babcbcb0b6', '黄仁勋回归现场画面曝光！马斯克再次发声：逆境朋友才是真朋友', '当地时间周一，在英伟达董事会一致决定让黄仁勋重返CEO岗位后，特斯拉与SpaceX首席执行官埃隆·马斯克接连发声。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:12:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-43ab16a4e2d1b290', '100001', 'news-category-finance-flash', 'em-202611243938282194-85708b982f', '15%最低税红线！沙特2027年起对跨国巨头利润征补充税', '据沙特阿拉伯天课、税务和海关总局称，沙特将于2027年起对跨国企业在该国境内取得的利润征收补充税，前提是其有效税率低于15%的全球最低税率。该税种适用于过去四年合并财务报表显示年收入达到7.5亿欧元（8.238亿美元）或以上的跨国企业，没有海外分支机构的本地企业可获豁免。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:10:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1c8f2fc2c277ff95', '100001', 'news-category-finance-flash', 'em-202611243938294465-1eda9187fc', '三七互娱投资成立智算科技公司', '企查查APP显示，近日，芜湖三七智算科技有限公司成立，经营范围包含：动漫游戏开发；数字文化创意软件开发；数字内容制作服务（不含出版发行）等。企查查股权穿透显示，该公司由三七互娱间接全资持股。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:09:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef96c77eb3efda0e', '100001', 'news-category-finance-flash', 'em-202611243938296160-5e4ee1dfa3', '自变量机器人与马来西亚国家邮政签署合作备忘录', '11月24日，自变量机器人与马来西亚国家邮政（PosMalaysiaBerhad）在吉隆坡签署合作备忘录，将共同推进具身智能在邮政物流领域的应用。面向马来西亚邮政的真实作业需求，双方将探索通用具身模型驱动的物流分拣方案。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:09:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6d341dd28199f5a6', '100001', 'news-category-finance-flash', 'em-202611243938294965-ba71294ed3', '英伟达财报超预期点燃AI链，科创创业人工智能ETF华泰柏瑞涨超4.12%', '今日市场整体上行，半导体板块领涨全市场，AI链一开盘就表现活跃。消息面上，英伟达最新财季营收1158亿美元、下一财季指引1300亿美元，均高于市场预期，同时董事会批准1500亿美元回购授权，直接给全球AI硬件提供了短线估值锚。国内方面也有配合，中国移动刚启动2026年至2027年新一代人工智能超节点设备第二批集采，采购规模合计52160卡，运营商智算基础设施采购明显提速。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:08:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6d4cd009e4cdea7b', '100001', 'news-category-finance-flash', 'em-202611243938292291-63e4852d1e', 'AI眼镜概念震荡走高 天键股份、明月镜片双双涨超10%', 'AI眼镜概念盘中震荡走高，天键股份、明月镜片涨超10%，歌尔股份、奥莱德、龙旗科技、瀛通通讯、博士眼镜等多股涨超5%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:06:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-626c9e46cbec1e14', '100001', 'news-category-finance-flash', 'em-202611243938294373-6a6b81d9d2', '太古：仍是国泰航空最大股东，无意进一步减持', '太古发言人表示，是次配售是公司资本配置策略的一部分，对太古与国泰航空均有利，而太古仍然是国泰航空的最大股东；太古把握当前市场环境，借此强化资产负债表及提升财务灵活性；目前无意进一步减持国泰，而国泰的管治、管理及营运方式亦不会因此改变。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:06:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0ee273cc1b39a3e4', '100001', 'news-category-finance-flash', 'em-202611243938293245-c6045e5055', '海外管制收紧强化国产替代，科创半导体设备ETF华泰柏瑞涨超4.36%', '今日市场整体上行，39个板块飘红，半导体方向领涨全场。科创半导体材料设备板块涨幅+4.67%，位居全市场第二，海外出口管制持续收紧与国内政策端修复形成双向驱动。美国商务部11月中旬的临时最终规则将马来西亚、新加坡等五国纳入先进半导体出口许可范围，收紧晶圆代工与先进封装推定，国产替代紧迫性再度被推高。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:06:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-94c54c4b597e53c7', '100001', 'news-category-finance-flash', 'em-202611243938291196-a33d148fad', '恒指、恒生科技指数双双转跌', '恒指、恒生科技指数双双转跌。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:05:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d9e396acb56487a5', '100001', 'news-category-finance-flash', 'em-202611243938290952-1d8cceb66e', '豆包正式发布个人AI助理产品“小豆”', '记者获悉，豆包旗下个人AI助理产品“小豆”开启公测，目前采用邀请制开放体验。据介绍，小豆是豆包在个人智能体（Personal Agent）方向推出的一款探索性产品，在问答、信息检索的基础上，更侧重主动服务、基于记忆更懂用户和任务执行。豆包方面透露，小豆的相关能力和体验未来也将逐步放开，在豆包主端推出，为更多豆包用户提供服务。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:04:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1a17ad12c4542393', '100001', 'news-category-finance-flash', 'em-202611243938290793-6891dd485f', '日本为何盯着核动力潜艇不放？专家分析背后更大企图', '据日本《共同社》22日报道，围绕日本政府拟于年底修订的“安保三文件”，自民党安全保障调查会干事长大野敬太郎当天在日本广播协会的节目中称，并未排除对于拥有核动力潜艇的讨论。对于“无核三原则”中的“不运进核武器”，他表示，写入允许运进核武器的例外情况也是一种选项。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:03:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b1d824286da14282', '100001', 'news-category-finance-flash', 'em-202611243938293194-e4d2e2f7ab', '神舟二十四号瞄准北京时间明日08时18分发射，卫星ETF鹏华涨超3%', '消息面上，今天（11月24日）上午，神舟二十四号载人飞行任务新闻发布会在酒泉卫星发射中心召开。发言人介绍，经研究决定，瞄准北京时间11月25日08时18分发射神舟二十四号载人飞船。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:02:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7fffb736a5b67759', '100001', 'news-category-finance-flash', 'em-202611243938290690-59bde50b05', '罗永浩所持锤子科技百万股权被冻结', '企查查APP显示，近日，罗永浩名下新增一则股权冻结信息，股权所在企业为锤子科技（成都）股份有限公司，冻结股权数额713.95万余元人民币，冻结期限自2026年11月15日至2029年11月14日，执行法院为北京市第一中级人民法院。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:01:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1e0c4cfcac78cf69', '100001', 'news-category-finance-flash', 'em-202611243938290430-1c4511f1aa', '沪深两市成交额突破1万亿元 较上一个交易日此时放量超2300亿元', '沪深两市成交额突破1万亿元，较上一个交易日此时放量超2300亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:00:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4600aea1b29a739a', '100001', 'news-category-finance-flash', 'em-202611243938291086-999459decf', '深圳中小学秋假结束 深圳铁路累计到发旅客246万人次', '记者从深圳铁路部门获悉，11月17日至20日为深圳中小学秋假。据统计，秋假4天时间内，深圳铁路累计到发旅客246.40万人次，其中发送126.75万人次，到达119.65万人次。', 'published', NULL, FALSE, 100, 1, '2026-11-24T03:00:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-de4e3037f15881b1', '100001', 'news-category-finance-flash', 'em-202611243938284498-b38386b3cc', '对话华尔街巨头：黄仁勋回来了，但AI泡沫的底层逻辑解决了吗？', '“随着英伟达CEO人选的落地（黄仁勋回归），市场将逐渐回归平静。圣诞反弹、标普500重返8000点是可能的，虽然我不会说这是高确信度的判断。整体而言，我们仍做多美国股市。”美国资管巨头富兰克林邓普顿（Franklin Templeton）高级副总裁、AI和数字资产解决方案负责人Max Gokhman表示。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:57:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-76c36c600e7d1a5d', '100001', 'news-category-finance-flash', 'em-202611243938289918-e7185ed41a', '工信部：截至9月底我国智能算力规模达2592EFLOPS，同比增长146%', '据工信部，前三季度，我国数字产业整体延续向优向好发展态势。“双千兆”网络持续深化。截至9月底，已建成5G基站525.4万座，其中5GRedCap基站数达290.9万个，5G-A网络覆盖逐步推进，千兆光网10GPON端口达3340万个，万兆光网在小区、工厂、园区等场景实现试点部署。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:56:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a4e9c4db50201d98', '100001', 'news-category-finance-flash', 'em-202611243938290181-60780b36b1', '主力资金监控：工业富联净买入超19亿', '今日早盘主力资金净流入电子、半导体、通信等板块，净流出医药、证券、非银金融等板块，其中电子板块净流入超109亿元。个股方面，工业富联主力资金净买入超19亿元位居首位，东山精密、中际旭创、寒武纪获主力资金净流入居前；华东重机遭净卖出超6亿元，超声电子、长鑫科技资金净流出额居前。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:56:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3c51c7b4270b487b', '100001', 'news-category-finance-flash', 'em-202611243938290040-ab4875338d', '黄仁勋回归带动AI产业链全线反弹，科创创业人工智能ETF鹏华涨超3%，科创AIETF鹏华涨超2%', '消息面上，英伟达官网11月23日发布公告称，公司董事会已一致投票决定，即日起恢复黄仁勋的总裁、首席执行官及董事职务。受此影响，AI产业链集体反弹。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:55:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d192d74d5548efec', '100001', 'news-category-finance-flash', 'em-202611243938290256-796987f10a', '“全球6G发展理念宣言”发布', '在24日上午举行的20266G发展大会上，“全球6G发展理念宣言”发布。（IMT-2030（6G）推进组组长、中国信通院副院长王志勤介绍《全球6G发展理念宣言》。当前，6G发展已进入标准研制全面启动、技术研发加快突破的关键阶段，需要全球产学研用各方更加紧密地合作、更加开放地融通、更加务实地创新。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:55:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d6941a5b69711b7c', '100001', 'news-category-finance-flash', 'em-202611243938289168-c56a65a566', '工信部：前三季度数字产业实现收入32.41万亿元 同比增长14.8%', '据工信部消息，前三季度，数字产业实现收入32.41万亿元，同比增长14.8%，增速较上年同期加快5.2个百分点。其中，制造业部分实现收入19.32万亿元，同比增长20.5%，服务业部分实现收入13.09万亿元，同比增长7.3%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:54:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a40439669643ea1d', '100001', 'news-category-finance-flash', 'em-202611243938288923-c94a74cc17', '港股恒生科技指数转跌', '港股恒生科技指数转跌，早前一度涨超2%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:53:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0320d8fa741642a0', '100001', 'news-category-finance-flash', 'em-202611243938288524-c0dff27efe', '台积电、中芯国际财报验证全球半导体需求强度，半导体设备ETF万家标的指数涨4.68%', '黄仁勋复职带动AI产业链普涨，费城半导体指数大涨14%，创2025年以来单日涨幅纪录；英伟达涨31.48%，台积电涨逾14%，阿斯麦涨逾9%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:53:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c949994805b2e0af', '100001', 'news-category-finance-flash', 'em-202611243938289431-cb1e31027b', '成长风格强势反弹，资金借道ETF积极入市，科创成长ETF万家标的指数盘中一度涨超6%', '2026年11月24日早盘，A股三大指数高开，成长风格表现活跃，截至10:00，上证科创板成长指数(000690)强势上涨4.77%，盘中一度涨超6%；成分股福立旺上涨12.77%，奥来德上涨11.76%，华光新材上涨9.61%，欧莱新材，利扬芯片等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:53:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6215719ef1efb220', '100001', 'news-category-finance-flash', 'em-202611243938288642-7f58384532', '工信部：前三季度重点平台智能眼镜销售额同比增长1.1倍，具身智能机器人销售额同比增长22.6%', '据工信部，人工智能创新活跃、应用纵深推进。大模型迭代明显加快，人工智能应用普及率加速提升，词元（Token）调用量大幅增长。据中国互联网络信息中心调查数据，目前我国生成式人工智能产品应用普及率已超50%。智能终端加快市场化应用。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:52:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e179ffaebee7c916', '100001', 'news-category-finance-flash', 'em-202611243938287160-5db09a4928', '“90%编程无需手敲代码”：微软拉曼纳称AI让程序员少写代码 却要思考更多', '在微软高管查尔斯·拉曼纳（CharlesLamanna）表示，AI正在重塑软件工程师的工作重心，让其大幅减少“手搓”代码逐行敲打的工作，但对于系统设计、验证、测试和安全上线等提出了更高的思考要求。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:52:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4eb7bfb91fec2225', '100001', 'news-category-finance-flash', 'em-202611243938284852-620f3fabf5', '郭明錤：黄仁勋复职移除了部分不确定性 英伟达仍面临现实瓶颈', '郭明錤发表了对黄仁勋回归担任英伟达CEO一事的分析。他表示，被消除的不确定性主要涉及公司战略、产品规划、技术发展及供应链管理等方面。这些不确定性在过去1至2周内对科技股造成压力，因此当不确定性消除后，股价立刻大幅上涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:49:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-690899df5103fa6f', '100001', 'news-category-finance-flash', 'em-202611243938284381-129dd799f8', 'AI应用端持续走高 值得买20cm涨停', 'AI应用端持续走高，值得买、遥望科技、新炬网络涨停，此前浙文影业、利欧股份、横店影视涨停，青木科技、光云科技、壹网壹创、蓝色光标、引力传媒涨幅靠前。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:47:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b985287ad9f3d919', '100001', 'news-category-finance-flash', 'em-202611243938284152-ea59d71ef5', '全球PCB短缺与AI硬件共振 消费电子ETF易方达涨4.47%', '截至上午10时38分盘中快照显示，消费电子ETF易方达（562950）上涨4.47%，最新成交价报1.146元，较昨日收盘价1.097元显著走高；该ETF今日以1.15元高开，盘中最高上探至1.154元，最低回踩1.136元，区间成交额约6682.2万元，整体呈现高开后强势震荡格局。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:46:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-68cfaf3be6c3e62c', '100001', 'news-category-finance-flash', 'em-202611243938284568-addf8f708a', '十五五新型储能方案落地 储能电池ETF易方达涨5.01%', '截至2026年11月24日10时38分，储能电池ETF易方达（159566）涨5.01%报1.384元，较昨日收盘价1.318元上涨0.066元，今日开盘价为1.347元，开盘后价格快速上行，盘中最高触及1.384元，最低下探至1.337元，区间振幅约3.57%，成交额约1.46亿元；从盘口特征看，最新价与盘中高点持平，显示早盘交投较为活跃，价格维持在相对高位运行，该ETF早盘整体未出现明显回撤。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:46:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1cd82ec735c4c080', '100001', 'news-category-finance-flash', 'em-202611243938284087-00790657c1', 'AI模型越大越容易被投毒？一项新研究发现惊人风险', '北京时间11月24日，据加州大学伯克利分校、伊利诺伊大学厄巴纳-香槟分校（UIUC）及Anthropic研究人员的一项联合研究，仅需污染AI模型预训练阶段0.1%的文本数据，就可能在模型中植入难以清除的后门。即使随后使用完全干净的数据进行微调和强化学习，这些后门仍可能保留，并在特定条件下诱导AI智能体执行攻击者指定的命令。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:46:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-05e0bf57e2fa0ec7', '100001', 'news-category-finance-flash', 'em-202611243938283616-6e922c8135', '10点半快评：热点快速轮动 市场量能明显放大', '市场早盘走势分化，创业板指、深成指高开后震荡回落，沪指窄幅震荡。成交量方面，市场量能明显放大，第一个小时两市放量2278亿元，预计全天成交超2万亿。当前上涨个股超4200家。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:44:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ec42a0cd59690091', '100001', 'news-category-finance-flash', 'em-202611243938281422-93ac5a5488', '朝令夕改 美媒：黄仁勋的回归表明英伟达董事会已被“架空”', '北京时间11月24日，据《纽约时报》报道，英伟达董事会曾表示，黄仁勋不会复职，但现在又突然改变了决定。企业治理专家指出，特朗普实际上凌驾于英伟达董事会之上，推翻了董事会的决定，把董事会“架空”。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:42:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6a9a648871b83015', '100001', 'news-category-finance-flash', 'em-202611243938283030-e865e15c54', '我国400米大气环境气象梯度观测塔封顶', '今天（24日），坐落于合肥未来大科学城的400米大气环境气象梯度观测塔（庐州塔）项目主塔钢结构完成第42节吊装作业，主塔结构顺利封顶。庐州塔是一座集大气污染梯度、温室气体通量、气象全要素精细化连续观测为一体的大型科研设施，总高410米，在稳定边界层、逆温层、低空急流、城市热岛环流等过程研究中具有明显优势。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:42:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-59e75b64949e3db8', '100001', 'news-category-finance-flash', 'em-202611243938282089-501c6aea14', '奥飞娱乐在广州成立文旅产业投资公司', '天眼查App显示，11月20日，广东奥飞文旅产业投资有限公司成立，法定代表人为郭一兵，注册资本810万元人民币，经营范围包括以自有资金从事投资活动、酒店管理、餐饮管理等。股东信息显示，该公司由奥飞娱乐股份有限公司及旗下广东奥飞主题文化科技有限公司共同持股。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:42:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3e82bf12666c6236', '100001', 'news-category-finance-flash', 'em-202611243938281839-f7baf395dc', '惠普与京东达成战略合作', '11月23日，惠普与京东达成战略合作。根据协议，双方将围绕C2M产品共创、全渠道零售、品牌营销等领域开展合作，并明确未来三年惠普在京东全渠道销售实现100%增长目标。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:42:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2208611fdab7d9b7', '100001', 'news-category-finance-flash', 'em-202611243938280944-4281ed9283', '特朗普一小时独家对话揭秘黄仁勋复职内幕', '特朗普说，自己确实说服了董事会，而且昨天说服他们，比一个半星期前容易得多。此前董事会成员看到英伟达经营状况良好，可能认为接手公司是一件很有吸引力的事情。但当公司股价开始下跌40%甚至50%时，情况就变了。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:40:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1f8c8a312148794d', '100001', 'news-category-finance-flash', 'em-202611243938281171-3c9a6cec66', '英国启动大规模AI辅助乳腺癌筛查试验', '英国剑桥大学23日发布公报说，英国已在剑桥郡率先启动一项人工智能（AI）辅助乳腺癌筛查试验，评估AI能否帮助医生更早发现乳腺癌，并减轻放射科医生判读乳腺X线筛查影像的工作负担。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:39:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5c9618f1476f5ded', '100001', 'news-category-finance-flash', 'em-202611243938280520-2a303230e1', '黄仁勋复职 一笔340万美元看涨期权交易引发内幕交易指控 不排除黄将接受闭门问询', '在英伟达复职公告发布前，市场出现一笔 340 万美元的英伟达看涨期权买入；股价上涨后，这笔持仓估算价值超过 3.12 亿美元。该笔交易的买入时点，引发市场内幕交易讨论。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:39:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1c8aff118cd6054b', '100001', 'news-category-finance-flash', 'em-202611243938280841-7aa2d6b24f', '电影《勇敢者游戏3：失控世界》确认引进，档期待定', '11月24日，索尼电影宣布，“巨石”强森、杰克·布莱克、凯文·哈特、凯伦·吉兰领衔主演，动作冒险喜剧电影《勇敢者游戏3》确认引进中国内地，档期待定，北美定档12月25日。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:38:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bbaaacfa6abc71fc', '100001', 'news-category-finance-flash', 'em-202611243938281224-e99000aa60', '神舟二十四号发射在即，低轨卫星应用扩容，卫星ETF永赢盘中涨超3%！', '11月24日，A股卫星通信及商业航天板块走强。相关ETF方面，卫星ETF永赢（159206）盘中涨超3%，成分股隆盛科技涨超8%，信维通信均涨超6%，华力创通、航天电器、通宇通讯、中国卫星等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:38:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a5cbbabaa650ddd1', '100001', 'news-category-finance-flash', 'em-202611243938304869-bab5dafb78', '珠海华发集团：拟全额赎回4亿元“23华发集团MTN008”', '珠海华发集团公告，拟于12月22日全额赎回4亿元“23华发集团MTN008”。本期债券发行总额4亿元，期限3+N年期，票息4.20%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:38:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-85b9ecd83bed8c0a', '100001', 'news-category-finance-flash', 'em-202611243938279417-7e2ed6dab4', '韩国全年出口额破1万亿美元，半导体贡献近半份额，半导体ETF博时(159582)跟踪指数盘中最高涨超5%', '截至2026年11月24日盘中，半导体ETF博时(159582)跟踪指数中证半导体产业指数(931865)强势上涨3.83%，盘中最高涨超5%。成分股芯源微上涨9.09%，安集科技上涨8.03%，华海诚科上涨7.16%，富创精密，珂玛科技等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:36:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9ae824769b6881e5', '100001', 'news-category-finance-flash', 'em-202611243938279312-d52c8e739d', '上海浦东新区：支持数字人民币在离岸业务中的应用和场景拓展', '近日，《上海市浦东新区促进离岸金融业务发展若干规定（草案）》公开征求意见，其中提出，支持依托数字人民币国际运营中心，在安全可控前提下建设和运营数字人民币跨境、离岸和区块链基础设施，稳妥推进与境外金融基础设施的互联互通。支持数字人民币在离岸业务中的应用和场景拓展，提升离岸业务支付清算效率。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:35:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2f420595adc16467', '100001', 'news-category-finance-flash', 'em-202611243938277670-cff72afe6c', '跨国车企正在重新认识中国市场：CEO们一句话点破真相', '中国汽车市场，正在成为全球汽车产业变革的重要试验场和创新策源地。从加大本土研发投入，到深化与中国企业的技术合作，再到将中国开发的产品和技术推向海外，越来越多跨国车企正在重新审视中国市场的战略价值。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:34:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-282a094db415981b', '100001', 'news-category-finance-flash', 'em-202611243938278018-35c77790b8', '黄仁勋重返英伟达+26年国产AI芯片市占率有望首次超过50%催化板块行情，科创综指ETF鹏华涨超3%', '半导体、算力产业链集体反弹，消息面上，黄仁勋重掌帅印，英伟达股价暴涨31%，市值单日增长近万亿。此外，BernsteinResearch预测，2026年以华为昇腾为首的国产AI芯片市占率有望首次超过50%；到2028年，中国本土AI芯片产量即可覆盖国内需求，供需比例预计达到104%。行业测算显示，2026年华为昇腾AI处理器业务收入将突破120亿美元，进一步拉开与国内其他厂商的差距。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:34:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a54230c0d6ba1606', '100001', 'news-category-finance-flash', 'em-202611243938279150-35c31e2448', '宇树已启动内部“物理AI模型自进化”计划，机器人ETF鹏华涨超3%', '消息面上，宇树科技创始人、董事长王兴兴日前透露，前几个月公司已启动内部“物理AI模型自进化”计划。此外，四部门发文鼓励发展适合养老场景的人工智能体、服务机器人、智能穿戴设备、外骨骼等新产品。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:34:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-666ea19ad7aa8467', '100001', 'news-category-finance-flash', 'em-202611243938275671-b5964f09e9', '光伏设备板块短线拉升 正泰电源涨停', '光伏设备板块短线拉升，正泰电源涨停，首航新能涨超10%，阳光电源、迈为股份、东方日升、固德威、锦浪科技等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:32:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-99efd28d5137e6aa', '100001', 'news-category-finance-flash', 'em-202611243938276076-00bc760ee8', '全国首个“人工智能产业保险共同体”成立', '11月23日，“深圳创投日”四周年暨2026香蜜湖财富管理周开幕大会在深圳举办。记者从会上获悉，深圳福田区13家财险机构已共同发起成立全国首个“人工智能产业保险共同体”，致力于破解大模型产业链“不敢保、不能保”难题。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:30:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9a37acbb85ea01f9', '100001', 'news-category-finance-flash', 'em-202611243938272711-1684096d6f', '黑色家电板块短线走高 四川长虹涨停', '黑色家电板块短线走高，四川长虹涨停，创维数字、九联科技、高斯贝尔、兆驰股份、四川九洲等跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:29:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7e374a32fe57a255', '100001', 'news-category-finance-flash', 'em-202611243938279275-115ab67461', '减持茅台、增持科技股 有主动ETF从价值切向成长赛道', '经历昨日的反弹后，首批主动ETF的调仓动作分化。18只产品的前十大重仓股来看，贵州茅台依旧是第一大重仓股，但被减持，持有ETF数量减少1只。主要是均衡量化主动ETF天弘呈现从价值切向成长风格的情况，贵州茅台在该ETF中清仓退出，片仔癀、工商银行等个股被减持；中微公司、中际旭创、宁德时代等被增持。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:28:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5ec5e825d8206e6e', '100001', 'news-category-finance-flash', 'em-202611243938271355-6f9b263ef6', '广州：延长“卖旧买新”专项补贴申领条件中居民个人购买新建商品住宅并完成网签的时间', '广州市住房和城乡建设局发布优化商品住房“卖旧买新”专项补贴政策的通知。延长“卖旧买新”专项补贴申领条件中居民个人购买新建商品住宅并完成网签的时间。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:27:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-34cda14d137d7621', '100001', 'news-category-finance-flash', 'em-202611243938271122-2931ada630', '智元与蓝思科技达成战略合作', '近日，智元创新与蓝思科技达成战略合作。据智元创新介绍，其与蓝思科技的合作，主要聚焦手机MMI、ANT、CAM、CAMCV等测试环节。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:27:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6cc83e88722e9aed', '100001', 'news-category-finance-flash', 'em-202611243938271018-b7dab887a4', '美国BIS芯片新规落地，国产自主可控机遇备受关注，科创芯片ETF博时(588990)跟踪指数强势涨超5%', '截至2026年11月24日早盘，科创芯片ETF博时(588990)跟踪指数上证科创板芯片指数(000685)强势上涨5.34%，成分股芯源微上涨12.41%，华虹宏力上涨12.34%，盛合晶微上涨11.48%，盛科通信，燕东微等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:26:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a6761c051a192ea0', '100001', 'news-category-finance-flash', 'em-202611243938270078-7093051a16', '澳新银行预测澳央行明年6月启动降息', '澳新银行（ANZ）24日发布澳大利亚经济研究报告。报告预测，澳大利亚储备银行（央行）将于2027年6月启动降息，随后于同年8月再次降息25个基点，将现金利率降至4.35%。2028年2月，澳央行可能进一步降息25个基点，使现金利率降至4.10%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:26:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c83b6a2ba6ca7397', '100001', 'news-category-finance-flash', 'em-202611243938268978-de47be2444', '豆包旗下AI个人助理“小豆”开启公测', '11月24日，豆包旗下AI个人助理产品“小豆”正式开启公测。公测期间，小豆采用邀请制开放，用户凭邀请码即可开启体验，并获赠一定量免费额度。未来，小豆上的能力与体验也将逐步在豆包App上线。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:25:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0761d65a2bd6ab64', '100001', 'news-category-finance-flash', 'em-202611243938267587-8da01b200e', '江苏交控增持南京银行，持股比例升至15.09%', '11月23日，南京银行（601009.SH）公告称，基于对南京银行长期投资价值的高度认可和对未来持续稳定发展的信心，大股东江苏交通控股有限公司自2026年7月18日起至2026年11月20日期间以自有资金通过上海证券交易所交易系统以集中竞价交易方式增持南京银行股份。增持完成后，江苏交控对南京银行持股比例由15%增加至15.09%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:23:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d51d10b21c344ca8', '100001', 'news-category-finance-flash', 'em-202611243938267631-6e2961ada3', '华为终端：鸿蒙终端设备数突破1亿', '华为终端官微11月24日宣布，鸿蒙终端设备数突破1亿。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:23:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-961ea808962463bb', '100001', 'news-category-finance-flash', 'em-202611243938268833-21df05184d', '美国企业对特定流媒体设备及其组件提起337调查申请', '据商务部消息，2026年11月10日，美国TruesightCommunications,LLC根据《美国1930年关税法》第337节规定向美国国际贸易委员会提出申请，指控对美出口、在美进口及销售的特定流媒体设备及其组件侵犯其专利权，请求发起337调查并发布有限排除令和禁止令。中国6家企业涉案。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:22:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-46f86d260cd70243', '100001', 'news-category-finance-flash', 'em-202611243938267751-d3942905ac', '南向资金净买入额达50亿港元', '截至目前，南向资金净买入额达50亿港元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:22:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6a804520e4b9902f', '100001', 'news-category-finance-flash', 'em-202611243938264742-e331c9c3cf', '英伟达股价惊人飙涨 欧洲做空杠杆基金损失超90%！', '英伟达管理层的惊人反转，使英伟达做空杠杆ETF迎来崩盘式暴跌。GraniteShares 3倍做空英伟达每日ETP（3SNV）和Leverage Shares 3倍做空英伟达ETP（NV3S） 均于英国时间周一下午2点30分左右停止交易，其中3SNV下跌92.1%，NV3S下跌91.4%，之后于下午晚些时候恢复交易。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:21:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-33707a3dc8d87aa0', '100001', 'news-category-finance-flash', 'em-202611243938267429-4076306745', '黄仁勋回归，海外市场情绪回暖，科创创业人工智能ETF国联安（158040）早盘涨超4%', '11月23日，英伟达董事会一致决议恢复黄仁勋CEO及董事职务，针对其开展的独立调查仍将继续推进，公司同时增设首席合规官岗位。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:19:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9c2a46e081d6ac70', '100001', 'news-category-finance-flash', 'em-202611243938264970-ee823c70b3', 'AI“大到不能倒”？黄仁勋回归触发史诗级买盘 野村提醒风险犹存！', '野村证券分析师CharlieMcElligott表示，美国总统唐纳德·特朗普“促成”英伟达恢复CEO黄仁勋职务的决定，引发了一场大规模的、情绪驱动的股市上涨，因为这证明了人工智能和相关股票“大到不能倒”。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:19:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7ef2dc168098978d', '100001', 'news-category-finance-flash', 'em-202611243938264313-1b22c48b28', '智平方郭彦东担任咸亨国际首席科学家顾问', '11月24日，咸亨国际披露，公司已于11月21日聘请智平方创始人、CEO郭彦东博士担任公司首席科学家顾问；同时，智平方聘请咸亨国际董事长王来兴担任公司首席战略顾问。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:15:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5e2c45c3d04d808', '100001', 'news-category-finance-flash', 'em-202611243938266217-4bd2de1349', '算力链情绪快速修复，具身智能再迎催化，科创创业人工智能ETF永赢盘中涨超4%！', '11月24日，A股AI产业链走强。相关ETF方面，科创创业人工智能ETF永赢（159141）盘中涨超4%，成分股慧博云通涨超11%，云天励飞涨超8%，协创数据、星宸科技、中际旭创、凌云光等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:15:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4b9396192a21d967', '100001', 'news-category-finance-flash', 'em-202611243938264564-4afdb1c5e7', '军工板块表现活跃 晨曦航空涨超10%', '军工板块表现活跃，晨曦航空涨超10%，北方长龙、建设工业、航天彩虹、中航成飞跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:15:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-06c42c2041493ab1', '100001', 'news-category-finance-flash', 'em-202611243938264863-800e946642', '黄仁勋回归英伟达算力情绪逆转 创业板算力ETF易方达+5.37%', '10时6分快照显示，创业板算力ETF易方达（158050）上涨5.37%，最新价报0.647元，今日以0.653元高开，较昨收0.614元上涨0.039元，开盘后维持强势运行，盘中最高触及0.663元、最低下探0.646元，成交额约2.04亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:13:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-41cb4bcca768d424', '100001', 'news-category-finance-flash', 'em-202611243938263062-5466c232ca', '纽约联储主席：抗通胀工作尚未完成，不排除连续加息', '11月24日消息，纽约联储主席约翰·威廉姆斯（JohnWilliams）表示，尽管美国经济依然强劲，但通胀仍持续处于过高水平，美联储在确保通胀及时、持续地回到2%的目标水平方面仍有工作要做。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:13:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-61524adc38ff5673', '100001', 'news-category-finance-flash', 'em-202611243938265654-cf511f8ada', '创业板拟引入做市商制度，政策组合拳释放稳市场积极信号，创业板50ETF万家标的指数盘中涨超4%', '2026年11月24日早盘，A股三大指数全线高开，截至09:44，创业板50指数(399673)强势上涨3.30%，成分股胜宏科技上涨12.95%，罗博特科上涨11.86%，天孚通信上涨10.76%，光库科技，中际旭创等个股跟涨。流动性方面，创业板50ETF万家盘中换手1.57%，成交145.55万元。拉长时间看，截至11月23日，创业板50ETF万家近1周日均成交855.37万元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:13:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c617a10c43c36ed6', '100001', 'news-category-finance-flash', 'em-202611243938264619-05d284582b', '黄仁勋复职，AI产业链叙事修复，中际旭创拟大手笔回购，人工智能ETF万家标的指数早盘涨3.7%', '11月23日晚间，英伟达恢复黄仁勋的总裁、首席执行官及董事职务。受此影响，隔夜美三大股指大幅收涨，英伟达暴涨超31%。美股科技股及AI硬件板块大涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:13:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c5e4229344bb0471', '100001', 'news-category-finance-flash', 'em-202611243938266063-3d11166b20', '黄仁勋回归英伟达全球AI情绪逆转 创业板人工智能ETF易方达涨4.23%', '11月24日10时6分快照显示，创业板人工智能ETF易方达（158031）上涨4.23%，最新价报0.64元，较昨收0.614元高开于0.654元，盘中最高触及0.655元、最低回探0.633元，成交额约1440.6万元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:13:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ea3ee7f20aa47ab2', '100001', 'news-category-finance-flash', 'em-202611243938263469-4c45d88797', '半导体板块震荡拉升 华虹宏力涨超10%', '半导体板块震荡拉升，和林微纳20%涨停，华虹宏力、盛科通信、燕东微、伟测科技等涨超10%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2b000ceeed6ae76b', '100001', 'news-category-finance-flash', 'em-202611243938263210-a466af7683', '人形机器人跳空高开！物理AI缘何再度走强？', '11月24日早盘，三大指数系数高开，机器人ETF招商（560770）延续反弹，标的指数冲高涨近3%！权重股拓普集团、大族激光涨超4%，三花智控涨超2%，绿的谐波、中控技术涨近4%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:12:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c39e02fe26c178c1', '100001', 'news-category-finance-flash', 'em-202611243938264466-3f2b24d5b3', '黄仁勋回归带动成长反弹 成长ETF易方达+4.58%', '11月24日早盘10时6分，成长ETF易方达（159259）日内涨幅+4.58%，报0.844元，较昨日收盘价0.807元高开于0.863元，盘中最高上探至0.866元、最低回踩0.842元，成交额约3.41亿元，量能明显放大，显示资金参与度提升。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:12:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aec7b5783603b865', '100001', 'news-category-finance-flash', 'em-202611243938262843-1f0b4fd8af', '国产超节点迎来发展机遇窗口，半导体ETF鹏华涨超3%', 'A股半导体产业链强势反弹，消息面上，AI芯片供应链收紧，国产超节点迎发展机遇窗口。业内人士表示，海外流片通道进一步收紧的态势下，国产AI供应链建设势在必行。在制程技术落后于海外先进厂商的情况下，超节点有望弥补单芯片算力短板，并将迎来发展的机遇窗口。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:11:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ea34cf2638522b45', '100001', 'news-category-finance-flash', 'em-202611243938262698-9818eba8a9', '亿优威光完成约5000万元Pre-A轮融资', '11月24日，据光源资本消息，国内激光产生等离子体（LPP）极紫外（EUV）光源企业深圳亿优威光科技有限公司完成约5000万元Pre-A轮融资首批交割。由祥峰投资领投，民银国际跟投，光源资本担任独家财务顾问。本轮资金将用于EUV光源技术持续迭代、人才团队扩充、战略客户产品导入。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:11:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-94aaf04d69d62192', '100001', 'news-category-finance-flash', 'em-202611243938262584-def5786e45', '“小盘双子星”盘中双双涨超3%！聚焦优质基本面，长期超额收益显著', '海外风险偏好修复等因素催化下，11月24日早盘，小微盘延续修复势头。截至发稿，上证指数涨超1%，中证2000涨3.50%、中证1000涨3.08%。相关ETF方面，中证2000增强ETF招商（159552）涨3.31%，中证1000增强ETF招商（159680）涨3.27%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:09:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7e310559875ef8a5', '100001', 'news-category-finance-flash', 'em-202611243938262746-6739323a60', '2026年半导体材料价格全线上行，行业迎国产替代关键窗口期，科创新材料ETF博时(588010)跟踪指数强势涨超4%', '截至2026年11月24日早盘，科创新材料ETF博时(588010)跟踪指数上证科创板新材料指数(000689)强势上涨4.46%，成分股上纬新材上涨10.39%，联瑞新材上涨8.74%，三孚新科上涨8.22%，德邦科技，安集科技等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:09:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-700650bae31813ca', '100001', 'news-category-finance-flash', 'em-202611243938260949-910e7ef704', '有色·钴概念震荡走高 腾远钴业、寒锐钴业涨超10%', '有色·钴概念盘中震荡走高，腾远钴业、寒锐钴业涨超10%，华友钴业、格林美、盛屯矿业等跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:08:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-83c78d35566cf350', '100001', 'news-category-finance-flash', 'em-202611243938261457-43a29e141b', 'AI算力产业链卷土重来，科创100ETF鹏华涨超3%', '半导体、算力硬件早盘走强，消息面上，黄仁勋复职带动美股周一大涨，隔夜费城半导体指数大涨14%，创2025年以来最大单日涨幅；英伟达暴涨超31%，报165.05美元/股，单日市值增加创纪录的9520亿美元，催化AI算力产业链行情。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:08:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fe698755edef7b28', '100001', 'news-category-finance-flash', 'em-202611243938261144-f60923a701', '万里扬CD400-4E320完成样车装配标定', '据万里扬消息，近日，万里扬重卡新能源双电机动力总成CD400-4E320取得关键进展，顺利完成四家行业TOP10主机客户的样车装配及标定工作。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:08:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d7ee3f9493f3daaa', '100001', 'news-category-finance-flash', 'em-202611243938261016-70685b420f', '半导体设备板块震荡走强 全筑股份6天4板', '半导体设备板块盘中震荡走强，全筑股份6天4板，此前和林微纳、百傲化学涨停，华兴源创、芯源微、微导纳米、菲沃泰等涨幅靠前。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:07:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a3eca0d1afe6dfef', '100001', 'news-category-finance-flash', 'em-202611243938258375-a6533d5b15', '科创 200 指数涨超 4% 领涨宽基，科创 200ETF 东财跟涨3.67%，把握科创板硬科技弹性修复机会', '今日早盘科创板强势拉升，截至10:00，科创200指数上涨4.44%，涨幅领跑主要宽基；科创100、科创综指、科创50分别上涨3.98%、4.01%、3.78%。截至发稿，科创200ETF东财（589330）现价0.650元，涨幅3.67%，成交额338万元，交投活跃。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:07:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-11fc3411f5191200', '100001', 'news-category-finance-flash', 'em-202611243938259053-0dec0d13a6', '英伟达飙涨超31%带动科技股走强，科创芯片设计ETF国联安(588780)跟踪指数涨超4%', '截至2026年11月24日09:31，科创芯片设计ETF国联安(588780)跟踪指数上证科创板芯片设计主题指数(950162)强势上涨4.07%。科创芯片设计ETF国联安盘中换手0.75%，成交575.87万元。成分股聚辰股份上涨9.63%，思瑞浦上涨8.46%，普冉股份上涨8.35%，新相微，澜起科技等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:06:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0b619b7100fb1de3', '100001', 'news-category-finance-flash', 'em-202611243938258671-4b81ffc0d1', '“AI行情”回归？长川科技、中微公司大反弹！半导体设备ETF招商连续4日净流入', '11月24日，A股科技方向呈现大面积反弹，半导体链集体上涨！北方华创、中微公司、寒武纪、拓荆科技、华海清科、长川科技纷纷反弹，半导体设备ETF招商（561980）标的指数涨近5%！截至11月23日，该ETF连续4日吸金近1亿！标的指数中证半导近3年累涨144%，大幅领先半导体材料设备（113%）、科创芯片（119%）等同类指数。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:05:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dbb5a3c7833cbf4f', '100001', 'news-category-finance-flash', 'em-202611243938257140-9094f0b757', '中消协提示：口腔、生殖健康医疗消费纠纷多发，警惕诱导消费和过度医疗', '据中国消费者协会，有媒体报道，陕西宝鸡一名63岁心梗老人因牙疼到当地一家民营口腔医院就医，被拔除全口12颗牙、种植10颗牙，不仅刷光手机内18800元，还欠费6200元，引发社会关注。从全国消协智慧315平台接收的医疗服务相关投诉情况看，口腔、生殖健康类投诉较多，消费者反映较为集中的问题包括夸大病情、治疗效果不及预期以及过度医疗等。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:05:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d8da5a81d91fa0b7', '100001', 'news-category-finance-flash', 'em-202611243938258441-9e8149e564', '领益智造：任命子公司立敏达核心管理团队 布局算力液冷供应', '领益智造官微消息，11月23日，领益智造完成子公司立敏达核心管理团队的任命，派驻集团核心商务运营干部与原有团队共同组建立敏达核心管理团队，推动立敏达深耕海外、国内算力液冷核心供应链。10月份，立敏达作为NVIDIAMGX生态合作伙伴参加了2026OCPGlobalSummit。在NVIDIAAIFactoryMGXEcosystem展示墙上，立敏达展出了InnerManifold分水器及新一代ZQD快拆连接器等液冷核心产品。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:05:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-26230d91ce477729', '100001', 'news-category-finance-flash', 'em-202611243938256350-ec6273163c', '润邦股份：旗下KOCH Solutions与Viscaria签署新项目合同', '据润邦股份消息，近日，润邦股份旗下KOCHSolutions与Viscaria签署新项目合同，将为其位于挪威的纳尔维克港项目提供物料搬运和输送成套系统。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:04:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f997695706878514', '100001', 'news-category-finance-flash', 'em-202611243938254860-32cd125c2c', '开盘半小时两市放量超1800亿 预计全天成交超2.1万亿', '开盘半小时，沪深两市成交额突破6400亿，较上一日此时放量超1800亿，预计全天成交金额超2.1万亿。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:01:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0b8dbb394d185af6', '100001', 'news-category-finance-flash', 'em-202611243938253894-18623b727b', '黄仁勋回归引爆AI行情，英伟达市值单日增长近万亿，人工智能ETF华富(515980)标的指数盘中一度涨超4%', '消息面，黄仁勋回归引爆美股空头回补，纳指大涨6.5%，英伟达暴涨31%，芯片指数飙涨14%；黄金反弹近3%，WTI原油期货跌超4%。黄仁勋重掌帅印，英伟达股价暴涨31%，市值单日增长近万亿。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:00:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4f561bb54423e051', '100001', 'news-category-finance-flash', 'em-202611243938253682-fb64ede371', '三星电子计划扩大第九代垂直NAND闪存(V9)产能，科创半导体设备ETF鹏华涨超4%', '消息面上，三星电子计划升级位于西安的半导体工厂，扩大第九代垂直NAND闪存(V9)产能。这类芯片用于人工智能(AI)数据中心的企业级固态硬盘。三星计划将西安第二工厂(X2)的V9产能从目前每月约1万片300毫米硅晶圆提高至约5万片。', 'published', NULL, FALSE, 100, 1, '2026-11-24T02:00:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a4564d17a400c816', '100001', 'news-category-finance-flash', 'em-202611243938253387-47f2a51df1', '海信集团、中远海运集团签署新一轮战略合作', '据海信集团消息，11月23日，中国远洋海运集团与海信集团再次签署新一轮战略合作协议，进一步升级战略合作伙伴关系，加强供应链、产业链融合发展。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:59:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7d07634b39df2dea', '100001', 'news-category-finance-flash', 'em-202611243938253481-acd1112cea', '上海浦东新区：支持安全可控建设和运营数字人民币跨境、离岸和区块链基础设施', '《上海市浦东新区促进离岸金融业务发展若干规定（草案）》公开征求意见。其中提到，支持依托数字人民币国际运营中心，在安全可控前提下建设和运营数字人民币跨境、离岸和区块链基础设施，稳妥推进与境外金融基础设施的互联互通。支持数字人民币在离岸业务中的应用和场景拓展，提升离岸业务支付清算效率。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:59:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b64b1a21839b60fb', '100001', 'news-category-finance-flash', 'em-202611243938250863-7d98e80e61', '华为算力概念异动拉升 华胜天成8天4板', '华为算力概念异动拉升，华胜天成走出8天4板，真视通、拓维信息、四川长虹、常山北明、星华新材、软通动力等冲高。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:57:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d82ba83f2e7e63b5', '100001', 'news-category-finance-flash', 'em-202611243938250963-175b861703', '章鱼动力回应：确认完成数亿元新融资', '11月24日，就融资进展消息方面，章鱼动力独家回应界面新闻称，年内已再次完成数亿元人民币融资。新增投资方包括芯动能投资、美的资本等投资机构与产业资本；早期股东线性资本、小米集团、PangaCapital持续多轮加注。融资将主要用于灵巧手高端制造产线构建和具身模型的研发投入，加速“脑-手-数据”的软硬件一体化设计（Co-Design），以及“智能-部署-数据”的自进化生产力飞轮构建。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:57:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-179d41681c7feb87', '100001', 'news-category-finance-flash', 'em-202611243938251273-fdae6b588d', '山东：到2030年初步建成清洁低碳安全高效的新型能源体系', '据大众日报，11月23日下午，山东省新闻办举行“开局起步‘十五五’”主题系列新闻发布会，解读《山东省新型能源体系建设“十五五”规划》。《规划》共设置能源保障、绿色转型、降碳提效、创新发展、惠民利民5大类18项可量化、可落地的指标，总体目标是，到2030年初步建成清洁低碳安全高效的新型能源体系。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:57:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-45bc532cec97ca5b', '100001', 'news-category-finance-flash', 'em-202611243938253018-f086e331ca', '光模块龙头大幅反弹！云计算ETF永赢盘中涨超4%', '11月24日，云计算ETF永赢（517230）开盘大涨，盘中涨超4%。截至9:52，中证沪港深云计算产业指数前十大成分股中新易盛、中际旭创、润泽科技涨幅领先。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:55:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8024f115b5df67c2', '100001', 'news-category-finance-flash', 'em-202611243938249449-a1d2d16ee0', '润邦股份旗下KOCH Solutions获Viscaria挪威纳尔维克港新订单', '11月24日，据润邦股份消息，近日，润邦股份旗下KOCHSolutions成功与Viscaria签署新项目合同，将为其位于挪威的纳尔维克港项目提供物料搬运和输送成套系统。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:55:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9f51d8789f47aec2', '100001', 'news-category-finance-flash', 'em-202611243938248449-5ed5377c01', '黄仁勋复职提振市场情绪，AI产业链集体走高，科创芯片设计ETF鹏华、科创芯片ETF鹏华均涨超4%', '消息面上，英伟达黄仁勋复职提振市场情绪，AI产业链集体走高。国内方面，有龙头公司在2026年第三季度业绩说明会表示，公司目前在手订单充沛，正在与多家国内半导体产业伙伴进行合作，打造基于国产供应链的云端AI芯片产品。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:52:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1f452abbef45e213', '100001', 'news-category-finance-flash', 'em-202611243938248015-240d2e28c7', '黄仁勋回归引爆AI行情、电池板块联动走强——创业板电池ETF永赢（158081）开盘涨超2.68%', '今日A股创业板指高开3.88%，创业板电池ETF永赢（158081）涨超2.68%（数据来源：Wind），电池ETF永赢（158019）涨超2.21%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:51:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f4109b07dfad473f', '100001', 'news-category-finance-flash', 'em-202611243938249396-6f69ead01d', '多只双创宽基ETF涨超3%', '多只双创宽基ETF上涨。科创50ETF易方达、科创50ETF广发、科创100ETF国泰、科创100增强ETF易方达等多只科创ETF涨超3%，创业板ETF广发、创业板ETF华夏、创业板ETF汇添富等多只创业板ETF涨超3%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:51:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e0515909ea6828a6', '100001', 'news-category-finance-flash', 'em-202611243938247597-2c1d90dd6d', '金饰克价涨回1100元', '国内黄金饰品价格对比显示，多家黄金珠宝品牌公布的境内足金首饰价格较昨日有所上调，老庙黄金报价1098元/克，较昨日涨10元；周大福报价1103元/克，较昨日涨12元；老凤祥报价1100元/克，较昨日涨12元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:49:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c3b421ae79ca3620', '100001', 'news-category-finance-flash', 'em-202611243938246515-f6fde88490', '黄仁勋复职英伟达CEO，芯片板块爆发！芯片 ETF 东财上涨3.04%', '截至今日9:45，芯片板块开盘大幅上涨，芯片ETF东财（159599）紧密跟踪中证芯片产业指数，截至发稿，上涨3.04%，最新报价2.1，成交额突破6100万元。跟踪指数成分股中，盛科通信-U、天岳先进、芯原股份、珂玛科技、澜起科技等跟涨超6%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:48:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b15375893ca6a5f7', '100001', 'news-category-finance-flash', 'em-202611243938247353-170d28dbbc', '黄仁勋回归英伟达！科创芯片设计ETF永赢盘中涨超5%', '11月24日，上证科创板芯片设计主题指数开盘走强，盘中涨超5%。截至9:43，指数前十大成分股中思瑞浦、芯原股份、澜起科技、佰维存储涨幅领先。A股光模块、光芯片等概念表现亮眼。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:47:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d8f2a4111d1d189b', '100001', 'news-category-finance-flash', 'em-202611243938246073-d838ccf21b', '富佳股份等成立动力科技公司，含AI业务', '企查查APP显示，近日，合肥界面动力科技有限公司成立，经营范围包含：人工智能应用软件开发；电子产品销售；自然科学研究和试验发展；工程和技术研究和试验发展等。企查查股权穿透显示，该公司由富佳股份（603219）等共同持股。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:45:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-697f6be1b816f8d5', '100001', 'news-category-finance-flash', 'em-202611243938246326-feaeaf2c6f', '港股光通信股走强 罗博特科涨近20%', '截至发稿，罗博特科(03757.HK)涨19.83%，剑桥科技(06166.HK)涨17.19%，东山精密(02384.HK)涨11.19%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:44:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0d8875f62e243b30', '100001', 'news-category-finance-flash', 'em-202611243938246159-97d3c2db97', '天数智芯、比依股份等成立智算私募投资基金', '企查查APP显示，近日，上海盛启智算私募投资基金合伙企业（有限合伙）成立，经营范围包含：以私募基金从事股权投资、投资管理、资产管理等活动。企查查股权穿透显示，该企业由天数智芯（09903.HK）、比依股份（603215）、联动科技（301369）等共同出资。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:44:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-70fbe9ff46512e51', '100001', 'news-category-finance-flash', 'em-202611243938245022-c51563a448', 'AI漫剧概念表现活跃 上海电影2连板', 'AI漫剧概念表现活跃，上海电影、浙文影业、横店影视走出2连板，幸福蓝海、掌阅科技、中国电影、引力传媒跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:44:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-57fcac2dbb899b85', '100001', 'news-category-finance-flash', 'em-202611243938246971-01c0a017e1', '药明生物美国基地迈入商业化生产！CXO高景气助力港股医疗ETF永赢开盘涨超2.4%', '场内ETF方面，截至11月20日，港股医疗ETF永赢（159366）规模8.53亿元，涨超2%，10月20日至11月20日日均成交额约3.52亿元，流动性佳。该ETF紧密跟踪中证港股通医疗主题指数，覆盖CXO、创新药、医疗服务及AI医疗等港股医疗核心方向。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:43:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-de0a51843bb250a5', '100001', 'news-category-finance-flash', 'em-202611243938243321-63bd8f468a', '港股PCB概念股走强 鼎泰高科涨超19%', '截至发稿，鼎泰高科(01377.HK)涨19.60%，胜宏科技(02476.HK)涨17.19%，景旺电子(03228.HK)涨12.51%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:42:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-74184c491bd03a2d', '100001', 'news-category-finance-flash', 'em-202611243938244529-72fbd4774c', '欧摩威推出车载远程控制网络解决方案', '11月24日，欧摩威集团推出车载远程控制网络解决方案（AutomotiveRCNet）。据介绍，这是一项专为软件定义汽车（SDV）设计的开放式网络概念，可在不同整车架构中实现端到端面向服务的通信，并将中央计算平台、区域控制器、I/O盒、传感器和执行器纳入统一的组网框架。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:42:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-885138eaf9d8de8c', '100001', 'news-category-finance-flash', 'em-202611243938242455-f8b8440f59', '液冷服务器概念震荡拉升 冰轮环境等多股涨停', '液冷服务器概念震荡拉升，冰轮环境、飞龙股份、金富科技、豪尔赛等涨停，同星科技、同飞股份、申菱环境、强瑞技术涨超10%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:40:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-94d65731de251344', '100001', 'news-category-finance-flash', 'em-202611243938242725-e79b41ea81', '资金扫货中证1000ETF 昨日净流入最多', '昨日股市反弹之际，资金继续流入股票ETF。Wind数据显示，11月23日，股票ETF净流入182.18亿元，上周一以来连续净流入6个交易日。中证1000ETF南方昨日净流入最多，单天流入34.62亿元，该ETF已连续5个交易日吸金，规模创新高至603.08亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:40:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ce925f08c1d5d85e', '100001', 'news-category-finance-flash', 'em-202611243938240734-9b14197ae6', '算力租赁概念震荡反弹 奥尼电子20cm涨停', '算力租赁概念震荡反弹，奥尼电子20cm涨停，行云科技涨超10%，协创数据、蜂助手、迈信林、中创环保等跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:39:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7031254c242d0f4e', '100001', 'news-category-finance-flash', 'em-202611243938244470-cc6a23750e', '国瓷材料：拟发可转债募资不超10亿元加码牙科陶瓷与覆铜板用球硅材料', '国瓷材料(300285.SZ)11月23日披露向不特定对象发行可转债预案，计划募资总额不超过10亿元，该事项尚需股东大会、深交所审核及证监会注册后方可实施。其中4亿元投向年产3000吨牙科用陶瓷基材料产业化项目，3亿元投向年产5000吨特种覆铜板用高性能球硅粉体材料产业化项目，剩余3亿元用于补充流动资金。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:39:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6194205dfc36ef23', '100001', 'news-category-finance-flash', 'em-202611243938240128-c4687587f8', '零售概念表现活跃 杭州解百2连板', '零售概念表现活跃，杭州解百2连板，中央商场、茂业商业、浙江东日、宁波中百、徐家汇跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:38:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-79d44d6bb0d8f273', '100001', 'news-category-finance-flash', 'em-202611243938240360-78141541d3', '国家统计局：11月中旬生猪价格环比上涨3.4%', '国家统计局公布2026年11月中旬流通领域重要生产资料市场价格变动情况，据对全国流通领域9大类50种重要生产资料市场价格的监测显示，2026年11月中旬与11月上旬相比，11种产品价格上涨，38种下降，1种持平。其中生猪（外三元）价格为9元/千克，环比上涨3.4%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:37:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c17911500650a983', '100001', 'news-category-finance-flash', 'em-202611243938239070-aa6d3bb187', '创业板指涨逾4% 上涨个股近5000只', '指数走强，创业板指拉升涨逾4%，沪指涨1.13%，深成指涨2.47%。算力硬件、半导体芯片、机器人等方向涨幅居前，沪深京三市上涨个股近5000只。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:36:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6691825a8e82f4c7', '100001', 'news-category-finance-flash', 'em-202611243938239272-fd05d5a042', '西子洁能签约浙石化120万吨/年丙烷脱氢（PDH）余热回收器项目', '近日，西子洁能中标浙石化120万吨/年丙烷脱氢（PDH）余热回收器项目并完成签约。资料显示，西子洁能为项目提供配套余热回收器核心装备，依托在PDH赛道沉淀多年的设计、制造及工程实践经验，采用适配石化复杂工况及超高烟气流速的高效换热结构方案，保障设备换热效率与长周期稳定运行。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:36:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-94dd6916a6fef603', '100001', 'news-category-finance-flash', 'em-202611243938237569-646872445e', '猪肉概念反复活跃 金新农8天5板', '猪肉概念反复活跃，金新农走出8天5板，京基智农、天域生物、罗牛山、天邦食品跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:35:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0c875bd705fa0cb9', '100001', 'news-category-finance-flash', 'em-202611243938238651-923073c647', '王力行将出任华兴资本集团副董事长', '11月24日，华兴资本集团董事会主席许彦清在《致华兴朋友们的一封信》中宣布，王力行将出任华兴资本集团副董事长，并继续担任执行委员会成员。未来他将继续专注于投资银行业务，深耕客户关系，做好客户资源对接与长期维护，并在公司治理层面发挥更大价值，推动治理体系更加规范、更加完善，共襄集团战略与业务方向的重大决策。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:34:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef2f60006328d302', '100001', 'news-category-finance-flash', 'em-202611243938237861-93360b0c37', '港股存储芯片股走强 澜起科技涨近12%', '截至发稿，澜起科技(06809.HK)涨11.61%，兆易创新(03986.HK)涨8.79%，江波龙(09976.HK)涨7.97%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:34:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cb1f849ea5ab1ba3', '100001', 'news-category-finance-flash', 'em-202611243938236015-685ea551cc', '半夏投资李蓓：已做多A股宽基指数', '11月24日，半夏投资创始人李蓓发文表示，上周开始持续卖出宽基指数put，上周五和本周一持续买入宽基指数股指。“我当然是不知道黄仁勋能回归的，做多股指的动作完全基于自己的框架。”她写道。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:33:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a5f6a829f22770b9', '100001', 'news-category-finance-flash', 'em-202611243938235597-8c1d6da759', '人形机器人概念反复活跃 锋龙股份2连板', '人形机器人概念反复活跃，锋龙股份2连板，福莱新材、中大力德、上纬新材、五洲新春跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:31:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4057d4e5da1ee446', '100001', 'news-category-finance-flash', 'em-202611243938236251-dec2d9e5dd', '工业富联开盘涨停', '工业富联开盘涨停，集合竞价阶段成交6亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:31:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-813e392cb9530613', '100001', 'news-category-finance-flash', 'em-202611243938235765-5510d639b1', '隆扬电子：HVLP5铜箔产品正配合客户需求测试验证中，尚未有批量化订单', '隆扬电子在互动平台表示，公司主营业务相关材料订单、客户需求及排产整体正常。公司HVLP5铜箔产品目前正配合客户需求测试验证中，尚未有批量化订单。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:29:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8f5cf41d814076b0', '100001', 'news-category-finance-flash', 'em-202611243938234879-abbf9f014f', '440亿美元，最大GPU租赁融资案出炉 云计算50ETF东方红（562110）标的指数今日开盘上涨', '近日，阿波罗全球管理公司与高盛发布公告称，已完成约440亿美元优先及次级票据的定价，资金将用于购买GPU及相关设备，再出租给SpaceX使用。据悉，这批资金将用于采购英伟达下一代VeraRubin芯片，支持SpaceX地面算力扩张。阿波罗全球管理公司报告测算：按照当前公布的计划，2026年至2028年全球AI基础设施累计资本开支可能达到约3.5万亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:27:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a8fb5fb90c4431d9', '100001', 'news-category-finance-flash', 'em-202611243938234458-b73f107352', '算力硬件股大幅高开 中际旭创等多股涨超10%', '算力硬件股大幅高开，东山精密、青山纸业、剑桥科技一字涨停，天孚通信、中际旭创、罗博特科、联特科技、源杰科技等多股涨超10%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:27:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5e364bbd8fd06b44', '100001', 'news-category-finance-flash', 'em-202611243938232369-ef23f787ee', '中际旭创、剑桥科技暴涨 港股光通信板块高开', '11月24日，港股光通信板块高开，中际旭创(03308.HK)、剑桥科技(06166.HK)均开涨15%，东山精密(02384.HK)涨近15%，汇聚科技(01729.HK)、长飞光纤光缆(06869.HK)、曦智科技-P(01879.HK)等个股跟涨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:25:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-82633ba15e5c6bf9', '100001', 'news-category-finance-flash', 'em-202611243938232192-a4f2621543', 'A股主要指数集体高开 创业板指上涨3.88% 科创50指数上涨3.25%', 'A股主要指数集体高开，沪指上涨0.82%，创业板指上涨3.88%，科创50指数上涨3.25%。算力硬件、半导体芯片等方向涨幅居前。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:25:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5d474fea95c86c25', '100001', 'news-category-finance-flash', 'em-202611243938234780-db7aa16efc', '港股物理AI股走强 迅策涨超8%', '截至发稿，迅策(03317.HK)涨8.48%，海清智元(01392.HK)涨7.50%，五一视界(06651.HK)涨7.29%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:25:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-15880f2742d23875', '100001', 'news-category-finance-flash', 'em-202611243938232866-a583f615d0', '华为维感G1动态血糖仪正式发布', '11月24日，华为首款独立血糖监测产品——华为维感G1动态血糖仪正式发布，监测准确度MARD值7.06%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:24:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1da7fb4d5ef163fc', '100001', 'news-category-finance-flash', 'em-202611243938225744-3c5b8ccbd2', '摩根士丹利：华友钴业、格林美和洛阳钼业料将受益于钴价上涨', '11月24日，摩根士丹利认为，刚果(金)暂停钴出口料将推高钴价，华友钴业、格林美和洛阳钼业等中国生产商将从中受益。“华友钴业满负荷运转时，按权益计算的钴年产能可达1.2万吨，新的Pomalaa项目达到全部产能时，还将新增每年8,800吨产能，不过产能利用率也取决于镍价和生产成本，”Chris Jiang等分析师在报告中写道。格林美满负荷生产时，年产能可达6,000吨。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:22:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-44d7d7715308add3', '100001', 'news-category-finance-flash', 'em-202611243938220511-d7686ba564', '香港恒生指数开盘涨1.09% 恒生科技指数涨2.05%', '香港恒生指数开盘涨1.09%，恒生科技指数涨2.05%，智谱、MiniMax涨超14%，联想控股涨超7%，蓝思科技涨超5%，阿里巴巴涨超4%，中芯国际、快手、比亚迪电子涨超3%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:21:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c5219ba9811402a8', '100001', 'news-category-finance-flash', 'em-202611243938230531-81d9ae5d38', '央行今日进行5160亿元人民币隔夜逆回购操作', '央行今日进行5160亿元人民币隔夜逆回购操作，操作利率为1.25%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:21:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6620a351bdb3546a', '100001', 'news-category-finance-flash', 'em-202611243938212990-ae594f586a', '特朗普祝贺黄仁勋复职，白宫跟帖、马斯克转发', '当地时间23日，特朗普在社交媒体上发文称赞英伟达（NVDA.US）董事会所做出让黄仁勋复职决定，白宫转发了这一推文并引用了特朗普原话：“英伟达董事会作出了正确且恰当的决定，让黄仁勋重返首席执行官职位......祝贺黄仁勋、英伟达董事会、美国人民——乃至全世界”。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:20:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-329509a6c5b06dc1', '100001', 'news-category-finance-flash', 'em-202611243938228546-d0dc504b36', '开勒股份：通过收购福建威泰思光电，正式进入光电行业赛道', '开勒股份在投资者关系活动中表示，通过收购福建威泰思光电有限公司，公司正式进入光电行业赛道。威泰思光电在光学精密制造领域有深厚的技术积累和客户卡位，下游覆盖半导体、光通信、机器视觉和生物医药等四个行业赛道。公司未来将以威泰思光电为主体，横向拓宽光学元件品类和下游应用，纵向向模组、组件等高附加值环节延伸，持续整合行业资源。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:20:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cc947d7227abf001', '100001', 'news-category-finance-flash', 'em-202611243938191693-2306996736', '人民币兑美元中间价报6.7111 上调9点', '人民币兑美元中间价报6.7111，上调9点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:16:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-00c513def611eef4', '100001', 'news-category-finance-flash', 'em-202611243938166022-c4dd98fbf2', '特朗普将自己的“遇刺成名照”魔改成黄仁勋 称这场风波对黄仁勋或是好事', '11月24日，据国是直通车援引《华盛顿邮报》报道，美国总统特朗普于当地时间周一在“真实社交”平台发布了一则梗图，这张图片改编自2024年宾夕法尼亚州巴特勒市枪击事件后的经典照片——原图拍摄于枪击发生片刻之后，图中的特朗普被替换为刚刚官复原职的英伟达首席执行官黄仁勋。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:14:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6171b85953acac7e', '100001', 'news-category-finance-flash', 'em-202611243938178086-5118c7ca6c', '穿越者：完成穿越者壹号亚轨道载人飞船逃逸舱静力试验', '11月24日，北京穿越者载人航天科技有限公司宣布，已于近日完成穿越者壹号（CYZ1）亚轨道载人飞船逃逸舱静力试验。本次试验以逃逸舱承力主结构为对象，依据逃逸飞行工况载荷谱对舱体施加模拟推力、弯矩、剪力载荷以及强制位移，分级加载至设计载荷，并完成极限加载。结果表明，在极限考核载荷条件下，逃逸舱结构强度、刚度与稳定性满足设计要求，关键传力部位承载状态及变形处于允许范围内。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:13:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ce4f604ec5d0d252', '100001', 'news-category-finance-flash', 'em-202611243938181092-ea6311931f', '慈文传媒：微短剧《铁血信使》投资规模较小且收入占比较小', '慈文传媒在互动平台表示，公司微短剧《铁血信使》投资规模较小，截至目前及预计未来，其产生的归属于公司的收入在公司整体营业收入中占比较小，不会对公司经营业绩产生重大影响。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:12:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cf76f36603d3fa64', '100001', 'news-category-finance-flash', 'em-202611243938156994-5141b8b4cf', '日经225指数涨幅扩大至5%', '日经225指数涨幅扩大至5%，报59261.78点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:11:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b227773e30502828', '100001', 'news-category-finance-flash', 'em-202611243938158418-f0e9056905', '华为推出首款血糖监测产品', '11月24日，华为正式推出首款独立血糖监测产品华为维感G1持续葡萄糖监测系统。据介绍，该产品监测准确度MARD值7.06%（该数值越小测量结果越准）。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:11:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0a727117af7d2322', '100001', 'news-category-finance-flash', 'em-202611243938140266-045bf24a84', '美媒起底黄仁勋复职内幕：特朗普史无前例的干预？', '北京时间11月24日，英伟达公司董事会周一突然改变态度，出人意料地宣布恢复黄仁勋(Jensen Huang)的CEO职务。《纽约时报》、彭博社等美国媒体披露了背后的内幕。据两名知情人士透露，在特朗普启动了持续数日的幕后斡旋，为英伟达董事会提供保证，确认黄仁勋没有面临刑事指控，也不构成国家安全风险后，黄仁勋重新被任命为英伟达CEO。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:10:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d81e12fbea946af7', '100001', 'news-category-finance-flash', 'em-202611243938141756-7c7dc45ce9', '日本东证指数上涨3%', '日本东证指数上涨3%，报3,784.46点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:09:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-35c683c4a170bf5a', '100001', 'news-category-finance-flash', 'em-202611243938151533-4f877489a8', '11月23日ETF资金整体净申购103.68亿元', '2026年11月23日，ETF资金整体净申购103.68亿元，股票型净申购158.16亿元，宽基型净申购177.35亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:09:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4f7d38b385fd57a2', '100001', 'news-category-finance-flash', 'em-202611243938148678-34ee443011', '11月23日股票型ETF份额变动前三', '2026年11月23日，股票型ETF份额增加前三：华夏上证科创板50成份ETF+15.42亿份、南方中证1000ETF+15.00亿份、华夏上证科创板半导体材料设备主题ETF+14.16亿份。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:09:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f06c9768261cd17a', '100001', 'news-category-finance-flash', 'em-202611243938149893-6a9bd8a404', 'ETF两市融资融券余额1220.16亿元 增加17.05亿元', '截至11月23日，ETF两市融资融券余额1220.16亿元，较上个交易日增加17.05亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:09:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9df4a9b0902cd317', '100001', 'news-category-finance-flash', 'em-202611243938133774-16ca259d4c', '徐工集团、交银投资等成立工程机械产业基金', '企查查显示，近日，江苏徐工交融工程机械产业基金合伙企业（有限合伙）成立，经营范围包含以私募基金从事股权投资、投资管理、资产管理等活动。企查查股权穿透显示，该企业由徐州工程机械集团有限公司全资子公司徐工集团产业投资发展（徐州）有限公司、交银金融资产投资有限公司等共同出资。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:07:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cf29410ed0c9c269', '100001', 'news-category-finance-flash', 'em-202611243938133991-64e9ff88e5', '神舟二十四号具备执行发射任务条件，优先采用自主快速交会对接策略', '今天（11月24日）上午，神舟二十四号载人飞行任务新闻发布会在酒泉卫星发射中心召开。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:06:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e032cba422cb182c', '100001', 'news-category-finance-flash', 'em-202611233937568545-dacb51e76d', '三季度险资在加仓还是减仓？行业数据给出答案', '金融监管总局最新发布的三季度保险公司资金运用情况表数据显示，保险资金三季度末的核心权益资产（股票+基金）投资余额约6.5万亿元，环比增加1435亿元，投资占比（人身险+财产险公司口径，下同）环比微增0.03个百分点。1435亿元的余额增加值均由股票贡献，三季末险资的股票投资余额环比增加1464亿元至4.25万亿元，投资占比环比增加0.15个百分点至10.56%，再创新高。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:06:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-da343774a29a73a8', '100001', 'news-category-finance-flash', 'em-202611243938133854-e19333369e', '杭州挂牌两宗涉宅用地，起始总价约25.24亿元', '11月24日，杭州市规划和自然资源局发布杭州市国有建设用地使用权挂牌出让公告，将采用挂牌方式出让两宗地块，起始总价约25.24亿元，地块用途均为住宅（设配套公建）用地，将于2026年12月14日正式挂牌出让。此次出让的两宗地块分别位于拱墅区和钱塘区，地块实行自由竞价，按照价高者得的原则确定竞得人。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:06:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fa61c721d603d5ba', '100001', 'news-category-finance-flash', 'em-202611243938125596-0e61fa15d8', '物理AI企业章鱼动力完成数亿元新融资，小米集团多轮加注、美的资本入局', '11月24日记者获悉，章鱼动力年内再次完成数亿元人民币融资。新增投资方包括芯动能投资、美的资本等知名投资机构与产业资本；早期股东线性资本、小米集团、PangaCapital持续多轮加注。融资将主要用于灵巧手高端制造产线构建和具身模型的研发投入，进一步加速“脑-手-数据”的软硬件一体化设计（Co-Design），以及“智能-部署-数据”的自进化生产力飞轮构建。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:04:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aa87837b918ae5d8', '100001', 'news-category-finance-flash', 'em-202611243938128147-514f5ea696', '济民健康成立微电子公司 含集成电路芯片业务', '企查查APP显示，近日，济瀚微电子（浙江）有限公司成立，经营范围包含集成电路销售；集成电路设计；集成电路芯片设计及服务；半导体器件专用设备销售等，企查查股权穿透显示，该公司由济民健康全资持股。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:04:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-91694c7d91c0bc6c', '100001', 'news-category-finance-flash', 'em-202611243938129631-487ce96db2', '招商基金首席李湛：黄仁勋复职，修复A股科技板块风险偏好', '招商基金研究部首席经济学家李湛24日对第一财经记者表示，黄仁勋复职，短期消除了全球AI产业链最大的管理层不确定性，直接提振了美股科技情绪，也同步修复了A股科技板块的风险偏好。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:04:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7f7eceb3df4edc15', '100001', 'news-category-finance-flash', 'em-202611243938113386-80cbe730b2', '韩国综指涨幅扩大至7%', '韩国综指涨幅扩大至7%，现报5037.91点。个股方面，SK海力士涨超10%，三星电子涨超7%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:03:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-083a0f2659a1124b', '100001', 'news-category-finance-flash', 'em-202611243938110382-1227e362e1', '神舟二十四号瞄准北京时间明日08时18分发射', '今天（11月24日）上午，神舟二十四号载人飞行任务新闻发布会在酒泉卫星发射中心召开。发言人介绍，经研究决定，瞄准北京时间11月25日08时18分发射神舟二十四号载人飞船。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:03:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-740323bb1e00374b', '100001', 'news-category-finance-flash', 'em-202611243938108950-290c5535b1', '鸿蒙操作系统终端设备数突破1亿台', '华为终端有限公司24日宣布，搭载鸿蒙操作系统HarmonyOS 5、6、7的手机、平板和电脑设备数量已突破1亿台。目前鸿蒙操作系统可获取的应用和服务超过46万项，注册开发者超过1200万人。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:02:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0dc1c3d1ed3bbd29', '100001', 'news-category-finance-flash', 'em-202611243938126920-e9838630d7', '粤桂股份：电子级硫酸刚出产品 正在验证过程中', '粤桂股份(000833)11月24日在互动平台表示，公司密切关注电池技术的发展趋势与方向；公司电子级硫酸刚出产品，正在验证过程中；10万吨精制湿法磷酸工业方向可供给下游磷酸铁，同时可供下游农业方向。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:02:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e08fb47f64ab2089', '100001', 'news-category-finance-flash', 'em-202611243938116514-22cca43782', '江苏省国投集团成立私募基金管理公司', '企查查APP显示，近日，江苏省国有资本投资运营集团私募基金管理有限公司成立，经营范围包含以私募基金从事股权投资、投资管理、资产管理等活动。企查查股权穿透显示，该公司由江苏省国有资本投资运营集团有限公司全资持股。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:01:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-184ad57a86242271', '100001', 'news-category-finance-flash', 'em-202611243938104532-1273c121a8', '英伟达发布黄仁勋回归照片', '当地时间11月23日，英伟达在社媒平台发布黄仁勋回归照片。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:01:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-df0f7e7c81bf0df7', '100001', 'news-category-finance-flash', 'em-202611243938118916-b0cddd231a', '国机精工：金刚石散热产品向GPU类客户送样验证工作已开展', '有投资者在互动平台向国机精工提问：公司金刚石散热产品是否向GPU类客户送样？国机精工回复，上述送样验证工作已开展，最近，公司以金刚石散热产品入围某芯片散热方案企业供应商，后续有望实现批量供货。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:01:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fd190783d6aec283', '100001', 'news-category-finance-flash', 'em-202611243938101134-60da592851', '台交所加权股价指数上涨8.5%', '台交所加权股价指数上涨8.5%至39,943.51点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:00:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-95967fd2bcfe31b3', '100001', 'news-category-finance-flash', 'em-202611243938094649-aa4de6f685', '富时中国A50指数期货开盘上涨1.22%', '富时中国A50指数期货开盘上涨1.22%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:00:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b2d667a72e8192a9', '100001', 'news-category-finance-flash', 'em-202611243938085328-1f670f7ed2', '国内商品期货早盘开盘 主力合约多数上涨', '国内商品期货早盘开盘，主力合约多数上涨。涨幅方面，沪银涨近6%，沪锡涨超4%，碳酸锂、沪金、欧线集运、钯、沪铜等涨超2%，苹果、多晶硅涨近2%，铂、橡胶、鸡蛋、沪锌、纯碱等涨超1%；跌幅方面，沥青、低硫燃油跌超3%，燃油跌近3%，原油跌超2%，丁二烯胶跌近2%，聚丙烯、PTA、瓶片、塑料、对二甲苯等跌超1%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T01:00:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-55c9dcbaf0b86c31', '100001', 'news-category-finance-flash', 'em-202611243937729275-57ed8e60cf', '黄仁勋回归英伟达 中国企业更应抓紧自主创新', '中国的优势在工程师红利、丰富的制造生态，更在于广阔的市场。芯片产业的发展，也遵循“用进废退”的道理。黄仁勋的去留风波，凸显出全球半导体产业链的动荡。在一个变乱交织的世界里，中国人工智能可以与中国芯片产业携手并进，共同闯出一片天地。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:58:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d14368612a06fd33', '100001', 'news-category-finance-flash', 'em-202611243938069513-c030c94e23', 'MSCI亚太指数上涨2%', 'MSCI亚太指数上涨2%至238.26点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:55:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b5813abe046fdb95', '100001', 'news-category-finance-flash', 'em-202611243938068332-11080dacd3', '中星微IPO辅导进入验收程序', '证监会披露平台显示，中星微技术股份有限公司及辅导券商银河证券向广东证监局提交了《辅导工作完成报告》，公司拟申报科创板IPO。其IPO辅导状态变更为辅导验收。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:55:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-56034e789862f269', '100001', 'news-category-finance-flash', 'em-202611243938068085-cec66a579f', 'AI需求激增致PCB短缺 韩国中型厂商开始扩产', '受人工智能拉动半导体需求激增影响，PCB出现供应紧张局面。继三星电机、LG Innotek等韩国大型企业之后，当地多家中型PCB厂商也启动大规模扩产。据业内人士透露，大德电子、Isu Petasis、Simtek、TLB、韩国电路、海星DS、BH七家企业今年公布新增投资规模合计达2.8万亿韩元。其中，大德电子的投资额最大，该公司宣布将投资1.325万亿韩元用于设施建设。这七家公司计划从今年年底到2030年陆续扩建生产设施。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:54:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-efd7d4aaa2bfa8be', '100001', 'news-category-finance-flash', 'em-202611243938065879-c2d08a1213', '中信证券：Token工厂从算力到Token重构AI基础设施的投资价值', '中信证券指出，Token工厂以模型部署和推理优化为核心，是连接算力、模型与应用的关键基础设施。随着AI应用由单轮问答向Coding、Agent及多模态工作流演进，Token消耗量进入指数级增长阶段，相较于训练侧对算力规模的集中投入，推理侧更关注算力资源的持续运营及单位算力成本的有效Token产出。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:53:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-09e08a1216a61785', '100001', 'news-category-finance-flash', 'em-202611243938062043-20fe582246', '蜂助手：公司的算力合同不涉及H200芯片', '蜂助手在互动平台表示，公司的算力合同不涉及H200芯片。算力服务合同约定的技术验收标准以合同中《服务单》及配套技术协议为准，合同中明确约定对应GPU型号、相关性能指标等验收标准。服务器方面，公司正在履行协议的各项约定，协议违约责任均有明确约定和保障机制，同时，部分国内厂商的产品已纳入公司供应链体系。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:53:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-93aefec1d3a9c71e', '100001', 'news-category-finance-flash', 'em-202611243938030550-6548b3fb46', '天府文旅：西岭雪山景区内已有部分娱雪区域开放使用', '天府文旅在互动平台表示，公司西岭雪山景区鸳鸯池索道已完成改造并投入运营，改造后实现双索道并行，运力由原来的2000人/小时提升至4000人/小时，新索道配备360°全景透明“盲盒轿厢”，可有效减少游客排队时间、提升旺季客流承载能力。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:51:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-355c62d3e9e5380b', '100001', 'news-category-finance-flash', 'em-202611243938063073-1b07f247e5', '神宇股份：铜价下跌对产品成本有一定正面影响', '神宇股份在互动平台表示，铜价格的下跌对公司产品成本有一定的正面影响，但公司产品成本还需结合其他原材料价格及工费情况等综合判断；公司目前生产经营一切正常。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:51:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-65a3e34b4d80a354', '100001', 'news-category-finance-flash', 'em-202611233937571648-5d0cca6270', '最高7亿元增持！中国能建控股股东也要出手“护盘”了', '11月23日晚间，中国能建发布公告，控股股东中国能源建设集团有限公司（以下简称中国能建集团）拟在未来12个月内通过集中竞价方式增持公司A股股份，增持总金额不低于4亿元、不超过7亿元。本次增持不设定价格区间，资金来源为中国能建集团的自有资金及自筹资金。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:50:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9c2e6d612cd578b7', '100001', 'news-category-finance-flash', 'em-202611233937597615-eb0de05bd4', '建业新生活不再姓“胡”？外资控股的物业企业名单越来越长', '日前，建业新生活发布公告，控股股东胡葆森通过全资平台创怡有限公司，将20%债转股股份抵给淡马锡系私募信贷基金SeaTown Private Credit Master Fund II，并与担保代理另行约定授出33%股份的认购期权。若33%的期权全数行使，胡葆森持股将从65.28%退至12.28%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:49:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b68ba85ff9c2773d', '100001', 'news-category-finance-flash', 'em-202611243938024687-d9acf2a41b', '两市融资余额减少89.84亿元', '截至11月23日，上交所融资余额报11189.33亿元，较前一交易日减少18.35亿元；深交所融资余额报10158.74亿元，较前一交易日减少71.49亿元；两市合计21348.07亿元，较前一交易日减少89.84亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:47:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-591ff75c371afd81', '100001', 'news-category-finance-flash', 'em-202611233937625676-8300b19954', '上海地铁涨价 平均每人次票价提高0.9元', '上海地铁自2005年来首次涨价。11月23日，上海市发展改革委公开了《关于优化上海市轨道交通票价机制的复函》，上海申通地铁集团同步发布了最新票价及配套优惠措施。这意味着上海地铁票价优化方案最终敲定。按照安排，新的轨道交通票价机制将于2026年12月1日起正式执行。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:47:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-697c75b76ecf3ec7', '100001', 'news-category-finance-flash', 'em-202611233937615671-858b91d85f', '创业板做市商制度渐行渐近 A股“竞价+做市”交易版图加速成形', '市场人士分析指出，市场调整阶段，竞价交易模式下买卖盘容易失衡，可能加剧股价波动。而做市商的持续双边报价义务，能够在不同市况下为市场提供相对稳定的流动性供给与交易对手方。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:46:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3f2870c8060ae182', '100001', 'news-category-finance-flash', 'em-202611243937784635-d861ea02b2', '闲鱼不急 转转抢跑：谁能成为二手经济“国内第一股”？', '转转要上市的消息，突然传了出来。近日，据报道，二手交易平台转转的运营主体北京转转精神科技有限公司，已以保密形式申请赴港上市，拟募资最高约5亿美元，最快可能于2027年完成上市。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:44:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8bd8fc2e668cfa09', '100001', 'news-category-finance-flash', 'em-202611243937969911-3bd9aebcae', '950亿横店集团，投了梁文锋', '一家老牌影视集团，坐上DeepSeek牌桌。11月下旬，梁文锋设立的持股平台“杭州程砚”完成股权变更，新进31家出资方，其中，横店资本持有程砚1.43%份额，与兆易创新同处一档。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:43:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-96d55b397191f853', '100001', 'news-category-finance-flash', 'em-202611243938021360-f5f47d7068', '东华能源：碳纤维生产流程已全线贯通', '东华能源在互动平台表示，目前碳纤维生产流程已全线贯通，正常出丝，现阶段主要目标是实现产能提升。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:40:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7df2d7ab962f9c2b', '100001', 'news-category-finance-flash', 'em-202611243938018239-aad0662f83', '美股工业控制与医疗健康方向表现亮眼 哪些A股有望共享景气传导？', '截至收盘美股市场共有77只股票创下阶段新高，按市值排序并剔除20日日均成交额在1亿美元以下的小微盘股，有22个具备流动性的核心标的值得关注，其中短线资金流向较显著的方向是工业机械与部件、保健护理服务与其他专门REIT。在指数强劲反弹的交易日里，资金同时向航空航天工业控制与医疗健康服务两条主线聚集。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:40:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2923a86f3b169581', '100001', 'news-category-finance-flash', 'em-202611243938019650-0b2bcb94cf', '中信建投：重视物理AI板块性行情', '中信建投研报指出，马斯克预计1-2个月内演示Optimus非预编程任务能力，把握物理AI板块行情。GPT-6惊艳效果有望加速产业核心具身大脑发展，Apple、OpenAI、Meta入局，Tesla推进量产，进一步明确产业趋势。OpenAI对独立机器人团队进行架构重构，中信建投判断主要系通用模型在机器人控制上展现出较强潜力，中长期看AI大模型提升机器人智能化水平的趋势明确。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:38:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ccede575494543b3', '100001', 'news-category-finance-flash', 'em-202611233937658516-fba05a1ff6', '光伏产能过剩 马斯克看好的“太空光伏”成新出口？', '在近日召开的第九届光伏与储能产业大会上，太空光伏成为热门话题。多位行业人士表示，太空场景对低成本、长寿命、高可靠性电源需求明确，为部分地面产能提供了可能的出口。但地面产品不能直接用于太空，有效在轨验证和降本仍是商业化前提，同时还存在在轨验证、抗辐照封装、太阳翼集成等挑战。太空光伏能否成为地面过剩产能的真实消纳场景，仍要看产业链协同突破的进度。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:38:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-610e7b86f7242908', '100001', 'news-category-finance-flash', 'em-202611233937511512-9cf84dccc2', '美算力管制影响几何？燧原总经理：基于国产供应链打造芯片', '燧原科技董事、总经理、首席运营官张亚林谈到了美国商务部工业与安全局（BIS）新规对晶圆代工的影响，其表示，“公司目前按计划正常开展生产经营，并正在与多家国内半导体产业伙伴进行合作，打造基于国产供应链的云端AI芯片产品，构建稳定的供应链体系，支撑公司业务发展。”', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:37:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-858bdd8dedf366b1', '100001', 'news-category-finance-flash', 'em-202611233937629828-582948f79b', '北京商报侃股：分散持仓要避免布局同一赛道', '分散持仓是投资者常用的风险控制手段，目的是通过买入多只个股降低单一持股风险。但部分投资者持仓股票高度集中在同一个赛道，看似买了很多只，实际上底层资产的涨跌逻辑高度趋同，很难起到分散风险的效果。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:35:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7756386118a7c9d8', '100001', 'news-category-finance-flash', 'em-202611233937629495-6487dcffd4', '“AI攻克黎曼猜想”不必慌', '恐慌大可不必。过往，人类征服黎曼猜想最大的难度，在于计算难以穷尽，找不到严密覆盖所有情况的通式推导。如今，人类充当向导，AI去探路解题成为新的可行路径。人类数学家与AI模型的配合将成为典型模式。在这个模式之下，AI不会取代数学家，但会帮助数学家、配合数学家。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:33:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b5c4e68e3c1662b0', '100001', 'news-category-finance-flash', 'em-202611243938017780-c3dac20556', '中金公司：2027年有望迎来小批量装车的产业催化、产业进展提速', '中金公司研报认为，新技术看好钠电和固态电池产业化持续推进。固态电池板块历经2026年调整、估值充分消化，中金公司预计2027年有望迎来小批量装车的产业催化、产业进展提速；钠电池在头部电池厂引领下，产业链有望迎来1到10规模化放量，适配储能、启停、低速交通等多元应用场景。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:32:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c59f590f93241dfb', '100001', 'news-category-finance-flash', 'em-202611243938016012-49966d01f1', '日本11月制造业PMI初值为53.7 前值为53.3', '日本11月制造业PMI初值为53.7，前值为53.3。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:30:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7a28450de9819e52', '100001', 'news-category-finance-flash', 'em-202611243938015440-98fb509ee5', '日经225指数涨幅扩大至4%', '日经225指数涨幅扩大至4%，现报58680.6点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:30:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-97835541d9bda52f', '100001', 'news-category-finance-flash', 'em-202611243938015686-7115290838', '俄美柴油协议执行受阻 尚无俄罗斯柴油运抵美国', '今年10月，俄罗斯和美国就俄向美国及全球市场提供柴油达成一致。但时至今日，俄罗斯柴油都没有进入到美国市场。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:29:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-417207098635c5ad', '100001', 'news-category-finance-flash', 'em-202611243938015169-1f0eba191a', '中信证券：《GTA VI》首发创纪录，互动影游与春节档催化接续', '中信证券研报指出，本周《GTAVI》首发刷新全球娱乐产品销售纪录，头部内容的付费潜力进一步得到验证，互动影游与影视院线催化接续。游戏方面，《GTAVI》全球首日零售销售额达37.9亿美元，约为前作首日的4.7倍，凸显成熟IP与全球发行能力对高投入项目的支撑。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:28:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4c26b577b1d4cbae', '100001', 'news-category-finance-flash', 'em-202611243938015071-9199e48c09', '接着奏乐接着舞！黄仁勋回归助力美元继续冲高', '近来，美元似乎总能在全球金融市场上“立于不败之地”。在过去几周的AI抛售潮中，美元成为了不少业内人士首选的避险资产之一。而当本周一英伟达首席执行官黄仁勋“王者归来”时，美元依然成为了一大受益资产，美元指数隔夜进一步刷新了2025年3月以来的最高位……', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:27:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-85a68982a7cf2133', '100001', 'news-category-finance-flash', 'em-202611243937992949-3a545f6f45', '端侧AI催化窗口密集来临 产业链厂商有望迎估值与业绩的双重重估', '近日，洛图科技（RUNTO）数据显示，2026年第三季度，中国智能眼镜市场（包含带显示的AR眼镜、不带显示的音频眼镜和拍摄眼镜三大品类）的全渠道零售量为54.4万台，同比增长14.3%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:26:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-750b4e73caeb87e9', '100001', 'news-category-finance-flash', 'em-202611243937929651-8e5952b4f9', '我国腔内影像领域实现世界首创性突破 AI+医疗器械彰显竞争力', '一套可同步完成冠脉腔内结构成像与血流功能评估的“三合一腔内影像系统”11月22日在哈尔滨医科大学附属第二医院正式发布，这是全球首款集成三类核心评估能力的原创技术成果，标志着我国在腔内影像及功能学指导精准冠状动脉介入治疗领域实现世界首创性突破。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:25:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a0f06d2c2f26ca56', '100001', 'news-category-finance-flash', 'em-202611243937889433-062a20403c', '三星2027至2029年存储产能已近售罄 算力基建对存储需求有望延续', '有知情人士透露，三星电子2027年至2029年的存储产能已近售罄，部分客户正推动将长约延至2031年。主要存储厂商目前仅能满足客户约60%至70%的需求。报道称，苹果此前是唯一一家未与三星签署DRAM长约的大型科技公司，过去长期凭借议价能力坚持短期合同，并在每次续约时压低单价，如今主动寻求长约，说明议价的天平已向供应商倾斜。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:25:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4ed58345d48bb9be', '100001', 'news-category-finance-flash', 'em-202611243938013845-7eae6a35f6', '现货白银日内涨幅扩大至1%', '现货白银日内涨幅扩大至1%，报43.58美元/盎司。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:24:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f209fd5ddfe6b475', '100001', 'news-category-finance-flash', 'em-202611243938013660-cba639bc47', '华兴资本控股：任命葛小波为首席执行官', '华兴资本控股在港交所公告，董事会宣布，自2026年11月24日起，葛小波获委任为本公司首席执行官及本公司执行委员会成员，而王力行不再担任本公司首席执行官，并获委任为董事会副主席。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:23:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-65685fb67ff7e9b4', '100001', 'news-category-finance-flash', 'em-202611243938012662-9e3913eb81', '中信证券：看好国内原料药产业的结构性投资机会', '中信证券研报指出，我国是全球主要的原料药生产国和出口国，原料药品种众多，不同产品的供需格局和价格周期存在明显差异。2026年以来，原料药及中间体中大部分品种价格仍处低位。兽用原料药指数处于磨底探底阶段，不同品种价格表现分化，其中氟苯尼考和盐酸多西环素有所修复。综合来看，后续建议重点关注价格触底回升、供给格局改善的品种，看好国内原料药产业的结构性投资机会。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:22:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-34e5c8c726760241', '100001', 'news-category-finance-flash', 'em-202611243938005462-158c8ec6e2', '11月24日投资避雷针：上交所向5连板盛剑科技下发监管工作函', '公司方面重点关注包括：1）上交所向5连板盛剑科技下发监管工作函；2）20CM涨停两连板凡拓数创公告，数据采集业务暂未形成营收；海外市场重点关注包括：1）WTI原油期货结算价跌3.88%，布伦特原油期货结算价跌3.46%；2）高盛预计2028年存储芯片价格或跌两成。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:21:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-208346594aafe4cb', '100001', 'news-category-finance-flash', 'em-202611243938012351-ca08791ba7', '中信证券：原材料价格回落，白电盈利修复可期', '中信证券研报指出，近期铜铝及塑料价格回落，白电成本压力边际缓解，其中铜价下降更利好空调，塑料降价对冰洗毛利率提振更显著。受业务结构及原有盈利水平影响，部分家电企业毛利率弹性相对更高。中信证券认为，后续降本红利的留存取决于需求和竞争格局，在需求改善时二线品牌修复弹性更大，需求偏弱时一线龙头盈利更稳健，建议观察后续行业价格情况。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:20:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4cd405732e210b27', '100001', 'news-category-finance-flash', 'em-202611233937512128-3d339739be', '影石宣布云台相机涨价', '11月23日晚间，影石发布公告称，受半导体、存储等关键零部件价格上行以及供应链综合成本抬升影响，影石将对Luna云台系列产品的建议零售价进行调整。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:20:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef044feb56cedeb1', '100001', 'news-category-finance-flash', 'em-202611243938011216-8d6b6753f7', '芯爱科技启动上市辅导', '11月24日，证监会网站披露，芯爱科技（南京）股份有限公司拟首次公开发行股票并上市，已聘请国泰海通作为其首次公开发行股票的辅导机构。辅导备案信息显示，公司无控股股东。公司官网显示，芯爱科技提供从研发、设计、生产到测试等全方位IC基板服务，涵盖BT及ABF基板，适用产品包括Coreless、ETS、FCCSP、FCBGA(BT)及FCBGA(ABF)。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:18:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-eb30e163e46600ca', '100001', 'news-category-finance-flash', 'em-202611243938011368-bb4b11d43d', '中金公司：27年锂电需求不悲观，供给仍存结构性约束', '中金公司研报表示，展望27年，锂电需求不悲观、产业链供需仍然存在结构性约束，部分材料环节基本面有望维持稳健，电池环节伴随与下游客户税费分摊机制达成、盈利亦有望逐步迎来修复。当前板块估值已较充分计入27年基本面悲观预期、具备较高性价比。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:18:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8f754af266d316c2', '100001', 'news-category-finance-flash', 'em-202611233937329465-34b1944113', '携程梁建章称未来五年2亿国际游客来中国 将带动上万亿元旅游消费', '梁建章的判断依据包括：“智能时代只有不容易被自动化的、满足精神需求的行业才会得到增长，因为其价格是稳定甚至上升的，旅游业就是这样一个重资产的提供精神体验的行业”；“旅行业需要把人从一个地方运到另一个地方，不可能被AI或者机器人取代”；“未来AI能够替代人的很多工作，人到底干什么？其中很大一部分人会去旅游”。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:16:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a0f206f02a8e3f5a', '100001', 'news-category-finance-flash', 'em-202611243938011167-557cdf35c5', '中信证券：美股23×5交易开启 开拓券商全球服务新机遇', '中信证券研报称，美股拟新增7小时夜盘，夏令时与A股H股分别重叠4小时、5.5小时，夜盘流动性和交易成本有望改善。美股延长交易后夜盘成交将集中在部分美股高市值明星标的，港股科技与可选消费行业面临较强资金分流压力，金融和公用事业行业防御性较强，A股直接分流有限。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:16:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d237496999761000', '100001', 'news-category-finance-flash', 'em-202611243938009825-1815bc2188', '财政部副部长廖岷出席金融稳定理事会全体会议', '据财政部网站，2026年11月16日至17日，金融稳定理事会（FSB）在瑞士巴塞尔举行全体会议暨新兴市场与发展中经济体论坛，会议围绕全球金融脆弱性、人工智能应用对金融体系影响、危机应对等议题进行了讨论。财政部副部长廖岷出席会议并发言。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:14:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5802a53a697199f9', '100001', 'news-category-finance-flash', 'em-202611243937778662-334c0b7758', '瑞银王宗豪：回调后中国股票风险回报改善 银行是全球“独一无二的风险分散板块”', '11月23日，在瑞银“聚焦中国行业”系列媒体分享会上，瑞银中国股票策略研究主管王宗豪表示，2026年中国股市的表现主要受估值下挫影响，实际EPS仍在增长。经历调整，目前MSCI中国的估值处于历史相对低位，一些板块已涌现出明显价值。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:14:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-539111af4d5df6f0', '100001', 'news-category-finance-flash', 'em-202611243937996929-c7950d5572', '日经225指数涨幅扩大至3%', '日经225指数涨幅扩大至3%，现报58177.09点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:10:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2220c41e495fc546', '100001', 'news-category-finance-flash', 'em-202611243937766867-1fc1a007cd', '精准对接银发市场需求', '近期，不少地方推出适老化产品展销、老年文旅专场等活动，以切实消费举措提升爱老敬老的民生温度。此前印发的《扩大消费“十五五”规划》提出，推动银发经济高质量发展。银发经济是顺应人口发展规律、破解老龄化挑战的重要战略选择，其出发点和落脚点是精准对接全社会的养老需求，增进人民群众福祉。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:08:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e9ac72cc63030fb8', '100001', 'news-category-finance-flash', 'em-202611243937973477-cbe4a8fad8', '韩国交易所启动SIDECAR机制 暂停KOSPI程序化买盘', '韩国交易所启动SIDECAR机制，暂停KOSPI程序化买盘。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:07:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7999520e39a5c5b5', '100001', 'news-category-finance-flash', 'em-202611243937767343-842fd7ce3d', '平价羽绒服是新趋势吗', '天气转凉，关于羽绒服的讨论热了起来。一边是北京大学等定制款羽绒服刷屏社交平台，上架即被学生、校友抢到断货；一边是99元至599元不等的超市羽绒服成为不少年轻人冬季采购的新选择。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:06:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0dae7399f6fa6096', '100001', 'news-category-finance-flash', 'em-202611243937977156-b8ea7bd1ee', '利比亚多方谴责乌克兰在利沿海发动袭击', '利比亚多方23日谴责乌克兰针对利东部城市班加西港口及附近海域船只发动的袭击，要求追究相关责任，并采取措施维护国家主权。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:05:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e4ade4dfa72f9e93', '100001', 'news-category-finance-flash', 'em-202611243937765473-9932b02d18', '无人配送车驶入规模化路口', '在城市街巷或乡村邮路上，外形方正、没有驾驶舱的无人配送车越来越常见。中国物流与采购联合会2026年上半年调研报告显示，全国无人配送车保有量已突破5.5万台，较2025年同期接近翻番。今年3月，深圳还率先向无人配送车开放夜间路权，释放政策红利。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:05:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6dec282621227e3d', '100001', 'news-category-finance-flash', 'em-202611243938002395-5422e17298', '华尔街因黄仁勋回归“炸开了锅”：上调评级和目标价 同时警告风险犹在！', '周一，英伟达董事会一致同意黄仁勋回归并担任总裁、首席执行官及董事，英伟达股价收涨31.48%，录得2003年5月以来最大单日涨幅，也是其上市以来第三大单日涨幅。伯恩斯坦分析师Stacy Rasgon迅速上调了英伟达的评级，尽管华尔街不少分析师认为正在进行的调查仍将对该公司构成挥之不去的阴影。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:04:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c90bf6157a305ee4', '100001', 'news-category-finance-flash', 'em-202611243937969567-770cbe987f', '韩国KOSPI指数盘初涨幅迅速扩大至6% SK海力士涨9.8%', '韩国KOSPI指数盘初涨幅迅速扩大至6%，三星电子涨8.2%，SK海力士涨9.8%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:02:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-245f57e650c68dd1', '100001', 'news-category-finance-flash', 'em-202611243937969766-1d33ae9238', '新加坡将2026年GDP增长预期上调至“约6%”', '新加坡将2026年GDP增长预期上调至“约6%”。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:01:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-47e73336fe2cc488', '100001', 'news-category-finance-flash', 'em-202611243937970236-ef5666faca', '神舟二十四号载人飞行任务新闻发布会将于今天上午召开', '据中国载人航天工程办公室介绍，空间站应用与发展阶段飞行任务总指挥部定于北京时间11月24日上午9时，在酒泉卫星发射中心召开神舟二十四号载人飞行任务新闻发布会，通报此次任务有关情况。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:01:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7afe5bf945962084', '100001', 'news-category-finance-flash', 'em-202611243937969132-a7c934156c', '日韩股市集体高开 韩国KOSPI指数盘初涨3.8%', '韩国KOSPI指数盘初涨3.8%。三星电子涨9%，SK海力士涨10.5%。日经225指数高开1.02%，报57009.99点。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:01:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-31bee591828b32f8', '100001', 'news-category-finance-flash', 'em-202611243937969446-dab5b9730e', '新加坡第三季度GDP同比增长6.1% 预估5.6%', '新加坡第三季度GDP同比增长6.1%，预估5.6%。', 'published', NULL, FALSE, 100, 1, '2026-11-24T00:00:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d3627e864435c9c0', '100001', 'news-category-finance-flash', 'em-202611243937765715-bb58c1e510', '日本经济结构性减速趋势难逆', '上周，日本经济季度数据出现负增长，且明显低于市场预期。数据起伏主要是受到短期因素扰动，但也反映出日本经济面临潜在增速下滑、通胀反噬消费等多重压力，逆转日本经济结构性减速的趋势并非易事。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:59:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-070a698dd4b78bbc', '100001', 'news-category-finance-flash', 'em-202611243937765849-e4c68e8a84', '谷子消费回归“为快乐买单”', '一枚动漫角色徽章，曾经在二手市场被炒到天价，如今却被混在一堆周边产品里，按斤称重甩卖。近来，多地谷子店集中闭店，曾经人声鼎沸的二次元主题街区纷纷降温。这一系列变化表明，谷子经济正从“炒身份”的狂热，回归“买喜欢”的消费原点。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:58:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a85af4db84f92980', '100001', 'news-category-finance-flash', 'em-202611243937765952-05c91fddf3', '经济日报金观平：为什么总有人刻意看空中国经济', '看待中国经济，既要正视困难，也不要被片面的悲观论调带偏。不可否认，内外环境复杂多变，矛盾挑战客观存在，人们感受到的压力真实而具体。困难挑战年年有，但这些年来中国经济就是在爬坡过坎、攻坚克难中发展壮大的。对于发展中的难题、前进路上的坎，我们不能回避，要敢于正视、迎难而上。同时更要看到，中国经济有韧性、有潜力，眼下的一些困难，是经济转型中的阵痛，是发展阶段绕不开的规律性挑战。客观分析经济形势，发挥好自身优势和潜力，适时适度出台务实管用政策，完全能克服各种困难挑战，推动经济持续向好。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:56:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7543f1247c4d39be', '100001', 'news-category-finance-flash', 'em-202611243937968858-25996886b6', '国泰海通：增量稳市举措接续推出 三重筑底看好券商', '国泰海通发布研报称，11月22日，沪深北三大交易所以及中国结算密集出台政策，涵盖调整融资保证金比例、创业板引入做市商制度以及一揽子降费政策。政策、业绩、估值三重筑底，继续看好券商板块', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:56:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b454b45039f7e5a4', '100001', 'news-category-finance-flash', 'em-202611243937945988-4a7a7cc601', 'R星为《GTA6》推送首个更新 涉及游戏崩溃、自动存档修复', '当地时间11月23日，RockstarGames为《侠盗猎车手6》（GTA6）推送发售后的首个更新，覆盖PS5与XboxSeriesX|S平台，共7项修复，包括多项导致游戏崩溃问题、自动存档异常、推动剧情/解锁任务的电话无法触发、通缉等级无法消除等，其中存档与任务电话两项此前可导致玩家卡关。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:55:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fc2339f1a5ef09e2', '100001', 'news-category-finance-flash', 'em-202611243937747485-2f838560f3', '新业态用电量增速领先 高载能行业连续三个月负增长', '国家能源局11月23日发布数据显示，10月，全社会用电量8709亿千瓦时，同比增长1.6%，较9月份回升0.4个百分点。记者注意到，10月高技术及装备制造业用电量同比增长6.5%，充换电服务业、互联网数据服务用电量增速分别达到59.4%、34.7%，而四大高载能行业用电量连续三个月负增长。这“一升一降”折射出我国经济转型的成效。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:54:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2aa8125d8f65eed8', '100001', 'news-category-finance-flash', 'em-202611243937747151-2ff46ca88b', '生物药集采改革加速转向价值竞争', '近日，全国药品联盟集中带量采购（单克隆抗体类）发布第1号公告，正式启动信息申报工作。这是国内规模最大的单抗类生物药联盟集采，纳入7个单抗品种、合计15个品规，全部是临床刚需、使用体量较大的重磅药物。业内专家指出，这标志着集采改革从胰岛素这一相对单纯的生物药，迈入单抗这一高度复杂生物药的“深水区”。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:51:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fbe21df5e616776a', '100001', 'news-category-finance-flash', 'em-202611243937897144-52e597b853', '日经225指数期货早盘上涨2%', '日经225指数期货早盘上涨2%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:49:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b80ad80041151950', '100001', 'news-category-finance-flash', 'em-202611243937902426-76a04bfde3', '乐高计划斥资近10亿欧元在葡萄牙建厂', '乐高当地时间11月23日宣布，计划在葡萄牙埃斯塔雷雅投资约10亿欧元，建设其在欧洲的第四座工厂，以满足欧洲、中东和非洲地区不断增长的市场需求。乐高表示，新工厂将采用公司最先进的自动化技术，预计于2030年投产，全面运营后将创造1000多个就业岗位。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:47:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6e3dcf656cd7ce36', '100001', 'news-category-finance-flash', 'em-202611243937884947-41ff0c6245', '特朗普推动黄仁勋回归 所持英伟达股票价值最高上涨1亿元', '北京时间11月24日，据《金融时报》报道，当地时间周一，随着黄仁勋意外被恢复英伟达CEO职务的消息传出，英伟达股价飙升。美国总统特朗普持有的英伟达股票价值最高上涨1500万美元(约合1亿元人民币)。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:47:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c66df2558cdc9c30', '100001', 'news-category-finance-flash', 'em-202611243937886294-32927722a8', '三星电子2027至2029年存储产能据悉大部分已被锁定 部分客户寻求将长约延至2031年', '据报道，知情人士透露，三星电子2027年至2029年的存储产能已近售罄，部分客户正推动将长约延至2031年。主要存储厂商目前仅能满足客户约60%至70%的需求。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:47:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-63c46cd03d0d457a', '100001', 'news-category-finance-flash', 'em-202611243937734779-a6f9a53dd5', '刚性需求强 政策支持加码 技术迭代加速 多公司深耕康养机器人赛道', '11月23日，国家发展改革委等四部门对外发布《“一老一小”服务体系建设实施方案》。《实施方案》提出，鼓励发展适合养老场景的人工智能体、服务机器人、智能穿戴设备、外骨骼等新产品。北京艾文智略投资管理有限公司首席投资官曹辙在接受《证券日报》记者采访时表示，在老龄化刚性需求较强、政策支持加码，以及AI智能体技术迭代共振的背景下，产业链上市公司正加速新品研发与机构端试点布局。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:46:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5c5564e1796fcb98', '100001', 'news-category-finance-flash', 'em-202611243937734833-506240be95', '具身智能数据国标研制启动 上市公司抢滩数据应用', '据国家数据局网站11月22日消息，具身智能数据国家标准研制正式启动，“十五五”期间将陆续形成20余项专项国家标准，同步开展标准试点验证，未来将支撑人形机器人、特种作业机器人、工业协作机械臂等多类应用场景落地。值得关注的是，今年以来，已有上市公司聚焦具身智能训练需求，围绕数据采集设备、场景数据供给等环节开展布局。未来，在政策支持下，相关部署有望提速。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:45:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dc9d49ab26f7c2d2', '100001', 'news-category-finance-flash', 'em-202611243937736073-1f2e49f9f5', '头部企业引领生态 应用场景多点开花城市超级智能体强力铺开', '城市超级智能体是具备感知、认知、决策、执行与自主演进能力的智能主体框架。国家数据发展研究院与华为技术有限公司联合发布的《AICITY城市智能体前瞻研究报告》，将城市超级智能体定位为AI（人工智能）城市演进后的高阶形态，并指出城市将从“数据驱动”向“城市超级智能体”跨越式升级。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:44:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-69ec9da58dfadd65', '100001', 'news-category-finance-flash', 'em-202611243937735743-f10fa98613', '高端PCB产业链企业优化策略稳供扩能', '11月23日，PCB（印制电路板）板块走强，东方财富PCB指数上涨4.62%。相关公司股价的强势表现，缘于AI（人工智能）算力、高速光互连带来的需求重构，叠加上游基材供应紧张，高端PCB供需矛盾持续发酵。近日，全球电子协会发布行业预警，PCB短缺已经从上游材料端蔓延至成品交付环节，汽车、通信等多领域客户普遍面临交期拉长的局面。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:42:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fe6779b5252a69ed', '100001', 'news-category-finance-flash', 'em-202611243937846613-867b3ddfd3', '涂鸦智能第三季度总收入同比增长约19.5%', '11月24日，涂鸦智能在港交所公告，2026年第三季度总收入为9860万美元，同比增长约19.5%；整体毛利率为45.8%，同比下降2.5个百分点；净利润为1850万美元（2025年第三季度：1500万美元）。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:41:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fa586149f1ae4a4c', '100001', 'news-category-finance-flash', 'em-202611243937833889-2b1fbbd0c9', 'Anthropic CEO达里奥 · 阿莫代伊出售337.8万股股票 IPO当天套现约2.8亿美元', '当地时间 11 月 23 日，美国证券交易委员会（SEC）披露的 Form 4 文件显示，Anthropic CEO 达里奥 · 阿莫代伊（Dario Amodei）于 IPO 上市当天出售了 3,378,378 股 Class A 普通股，成交价格为每股 83 美元（即 IPO 发行价）。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:39:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b4aefa1d7f107184', '100001', 'news-category-finance-flash', 'em-202611243937841243-6b601a4194', '中信建投2027年港股展望：弱美元受益者', '中信建投研报指出，港股过去表现相对较弱，底层原因是港股深刻演绎全球宏观负贝塔。资金外流、美债高利率、企业低盈利，过去持续压制港股。更重要的是，过去全球股市掀起一轮AI“硬科技”交易浪潮，港股硬科技含量低，表现相对偏弱。展望2027年，全球宏观主线正在起变化，未来或见到美元摸顶之后回落。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:39:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-26f8a015a537aac7', '100001', 'news-category-finance-flash', 'em-202611243937785847-2cc4c6f9e8', '港股IPO料稳中有进 商业化落地能力被看重', '港股IPO和再融资一直是市场关注的焦点。港交所最新数据显示，2026年前十个月，共有121家企业在港上市，首次公开招股（IPO）集资总额达到4039亿港元，较2025年同期大增84%。此外，进入11月，多家生物医药、医疗器械港股公司发布再融资公告。多位受访人士认为，硬科技公司依然会是港股IPO市场的主线，这既是由产业升级的长期趋势决定的，也与港交所拥抱新经济资产的战略方向契合。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:38:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5bd0b6175b96bb28', '100001', 'news-category-finance-flash', 'em-202611243937837891-653b0d99db', '三星据悉拟扩大西安工厂先进NAND闪存产能 供应AI数据中心', '据报道，三星电子计划升级位于西安的半导体工厂，扩大第九代垂直NAND闪存(V9)产能。这类芯片用于人工智能(AI)数据中心的企业级固态硬盘。三星计划将西安第二工厂(X2)的V9产能从目前每月约1万片300毫米硅晶圆提高至约5万片。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:37:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aff6b0b74526987c', '100001', 'news-category-finance-flash', 'em-202611243937787152-20431c135f', '脑机接口加速临床转化 赛道迈向产业化攻坚期', '日前，2026脑机接口大会在北京市昌平区举办。大会集中发布15项国内脑机接口标志性成果、《脑机接口创新发展研究报告（2026）》，同步启动两大公共服务平台、落地一批重点产业项目。昌平作为脑机接口创新策源地，其科研、临床、资本协同的产业生态，也是国内脑机接口产业发展的一个缩影。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:37:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-55982d39de7c2515', '100001', 'news-category-finance-flash', 'em-202611243937838630-172ce09813', '中信建投：国产算力供需共振 AI安全需求持续升级', '中信建投研报指出，近日BIS新规将管制延伸至云端算力与制造服务，海外算力、代工、封测三通道同步收紧，国内客户采购加速转向本土。国产供应链已基本闭环：寒武纪、沐曦实现全链条国产，长鑫HBM3完成头部云厂商适配、2027年规模化，供给瓶颈有望逐步缓解。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:37:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z')
