INSERT INTO news_item (
    id, tenant_id, category_id, slug, title, summary, status, author_name,
    featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
    ('news-item-81cfe28e23e11bbe', '100001', 'news-category-finance-flash', 'em-202611243937835691-96296624e2', '中信建投：仍然看好2027年锂电增速', '中信建投研报指出，预计2026年全球锂电池需求约3147GWh，同比增长38.9%；展望2027年，中信建投认为明年全球锂电池需求80%以上可能达到4081GWh，对应同比29.0%增速，且有望进一步达到4196GWh，对应同比32.7%增速。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:37:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4357fc73b46c30ef', '100001', 'news-category-finance-flash', 'em-202611243937786820-e372657a35', '真金白银稳市护盘 多家上市公司实施股份回购', '近期，A股密集披露回购相关公告。除多份正式回购方案出炉外，也有不少公司董事长或实控人提议进行回购。与此同时，多家公司披露获得金融机构的回购专项贷款承诺函。从回购意向到资金支持，它们已成为11月以来A股回购落地节奏加快的缩影。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:36:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-34b00275f91fe956', '100001', 'news-category-finance-flash', 'em-202611243937787825-9af1672d03', '一纸承诺函“贷”动超200亿元回购增持潮', '“这段时间我们重新梳理、排查了辖区内的上市公司客户，积极接洽客户及其主要股东在股票回购、增持方面的需求，尽可能简化业务流程，匹配客户的用款节奏。”一家股份行深圳分行相关业务负责人告诉中国证券报记者。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:35:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-58a28be9960a9ee5', '100001', 'news-category-finance-flash', 'em-202611243937813323-21f6b188ca', 'A股限售股解禁一览：8.89亿元市值限售股今日解禁', '数据显示，周二（11月24日），共有7家公司限售股解禁，合计解禁量为5050.99万股，按最新收盘价计算，合计解禁市值为8.89亿元。从解禁市值来看，英特科技、炬光科技、杰克科技解禁市值居前，解禁市值分别为6.0亿元、1.42亿元、9391.16万元。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:34:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-763b57883d5d0f4e', '100001', 'news-category-finance-flash', 'em-202611243937797869-0d89bcd44c', '默茨：与俄罗斯谈判 欧洲准备好了', '德国总理默茨11月23日在柏林表示，欧洲已做好与俄罗斯谈判的准备，乌克兰问题顾问级别的和平谈判近期可能在阿联酋首都阿布扎比再次举行，由乌克兰、俄罗斯、欧洲和美国参加。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:33:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-770ea233a56c46b8', '100001', 'news-category-finance-flash', 'em-202611243937743354-f8e665b1ba', '港股回购“多点开花” 结构性变化释放积极信号', '近期，港股上市公司积极回购股份。从多个维度的数据来看，年内港股市场的股份回购行为正在发生一些结构性变化，其中部分变化透露出的积极信号值得重视。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:31:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bcc8af5d6ed4e494', '100001', 'news-category-finance-flash', 'em-202611243937741838-90c0adf8b5', '“北上追雪”热情高 滑雪装备市场迎销售旺季', '近日记者实地探访迪卡侬北京公益西桥店。随着雪季到来，滑雪装备集中陈列在门店进门显眼位置，雪板、雪服、护目镜、头盔、护具等品类齐全，不少顾客驻足翻看、咨询产品，既有新手挑选入门装备，也有爱好者比对升级款。门店同时提供雪具租赁服务，面向初次体验、不想一次性购置全套装备的滑雪人群。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:30:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bb172f913c8bf4f1', '100001', 'news-category-finance-flash', 'em-202611243937742630-01c2608266', '银行理财净值回调引关注 机构密集发声稳预期', '11月以来，股债市场同步震荡，压力沿底层资产传导至银行理财净值，部分中低风险产品亦出现回撤。面对投资者的担心，多家理财公司密集发声，解释调整原因并引导理性持有。记者据公开信息不完全统计，截至11月23日，已有招银理财、兴银理财、工银理财等十余家理财公司发布安抚投资者内容，并解释净值回撤原因。展望后市，短期赎回扰动如何演化、低利率下收益从何而来，成为行业新考题。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:29:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6cf2f2c9c6b4af80', '100001', 'news-category-finance-flash', 'em-202611243937794618-f6320dcba2', '数百名员工欢呼，黄仁勋重返英伟达：感谢给我第二次机会', '当地时间11月23日，在离开英伟达11天后，黄仁勋重新回到位于美国加州圣克拉拉的公司总部，受到员工的热烈欢迎。多段由英伟达员工发布的现场视频显示，数百名员工聚集在总部大厅，有人站在楼梯和楼上走廊的栏杆旁，鼓掌、欢呼，齐声高喊“Jensen！”当天，黄仁勋没有穿标志性的黑色皮衣。他向员工鞠躬致歉，承认自己犯下了严重的错误，并为给员工带来的动荡表示歉意。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:29:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a94fd2ed5699777e', '100001', 'news-category-finance-flash', 'em-202611243937741953-50ac0fabd7', '11月以来逾40家公司更换董秘 兼职边界收紧', '据记者统计，11月1日至22日，沪深A股有79家公司披露董秘人事公告。其中，67家披露聘任或续聘安排（26家继续由原董秘任职，41家披露新任董秘），12家暂由董事长承接职责。分板块来看，主板集中了59家，创业板、科创板各有11家、9家。从公告内容看，这一轮调整的背后原因多样化，既有监管规则推动职责拆分，也有董事会换届带动集中聘任；从董秘的履历来看，证券事务代表及具备投行、财务、法律背景的人选正加快接棒。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:28:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-656c81245251a526', '100001', 'news-category-finance-flash', 'em-202611243937743040-a861a1e49b', '稳市举措齐发力 券商板块配置价值凸显', '国泰海通证券金融研究组金融研究主管刘欣琦认为，当前，政策、业绩、估值三重筑底。其中，资本市场工具加码，夯实政策底；市场修复利好券商核心业务线提升，叠加低利率带来头部券商泛财富管理、国际业务的盈利确定性；同时，板块整体低配低估，继续利好券商板块。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:27:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-262f01b006b67094', '100001', 'news-category-finance-flash', 'em-202611243937742119-b5d5a553aa', '油轮新造船订单大增121% 全球造船业景气度上行', '英国造船和海运动态分析机构克拉克森近期发布数据显示，截至11月13日，今年以来油轮新造船订单已达到707艘，同比增长121%，散货船订单为655艘，同比增长27%。此外集装箱船订单为742艘，同比保持平稳。克拉克森新船价格指数温和上行，从3月的182点持续上涨到10月的187.2点。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:25:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-83d3634031355389', '100001', 'news-category-finance-flash', 'em-202611243937794384-b9a3ca675d', '亚马逊宣布收购Decart技术与团队', '当地时间11月23日，亚马逊宣布已签署协议，收购Decart优化栈（DecartOptimizationStack，DOS）的专有技术，并吸纳DecartAI联合创始人迪恩·莱特斯多夫（DeanLeitersdorf）、摩西·沙莱夫（MosheShalev）、奥里安·莱特斯多夫（OrianLeitersdorf），以及该团队的AI研究员与工程师加入亚马逊。本次交易的完成尚需满足常规交割条件，包括获得监管审批。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:24:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5b133f5615aacad', '100001', 'news-category-finance-flash', 'em-202611243937742260-b9dc7c9451', '前端白菜价后端开盲盒 Token中转站生意需引入“公平秤”', '近期，“API中转”“Token代理”等关键词，已在部分电商平台上被全面屏蔽。然而，这门生意并未销声匿迹，商家们迅速换上“算力代充”“模型体验卡”“大模型资源包”等词汇，或使用拼音、谐音规避检测，将交易转入私域社群。以低价为诱饵，这门生意至今是个不透明的黑盒：计费规则暗藏猫腻、用量不透明、模型真伪难辨、充值后被封号、“挂羊头卖狗肉”等纠纷时有发生，核心代码与商业对话数据更是在毫无保障的第三方服务器中“裸奔”。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:23:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2e33f1bb2299bbd0', '100001', 'news-category-finance-flash', 'em-202611243937792572-27ce85ef06', '黄仁勋回归，OpenAI CEO发声', '当地时间11月23日，英伟达宣布恢复黄仁勋作为公司总裁兼CEO及董事会成员职务后，OpenAICEO山姆·奥尔特曼发文“Jensen!（黄仁勋英文名）”但评论区有网友并不买账，他们称“黄落魄的时候你并没有支持他”“总是有人等到风险降至零才开始欢呼”。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:22:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9969b108a28ac0c2', '100001', 'news-category-finance-flash', 'em-202611243937742940-abfebe03b8', '海上发射母港竞速扩容 商业航天高频发射能力加快形成', '今年7月，全球运力最大的固体火箭引力一号在上海东部海域完成海上发射。近期，中科宇航力箭一号运载火箭也有望迎来两次海上发射任务。记者了解到，上海、江苏、广东等沿海经济高地已相继注册成立海上发射运营企业，筹划依托各自资源开启海上发射母港建设——沿海省份开始“抢火箭”，一场由地方国资、央企、民营商业火箭企业多方参与的赛道竞速就此拉开。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:20:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cc8648bed854b8ea', '100001', 'news-category-finance-flash', 'em-202611233937616389-30be1b1a31', '多家机构聚焦北交所市场 中长期配置价值受关注', '经历一年有余的调整，北交所市场近期引起机构投资者密切关注。多家机构人士日前对记者表示，当前板块在政策预期、估值水平与市场情绪三方面已有边际改善迹象，中长期配置价值凸显。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:19:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-210bc6bb6a3ebeb9', '100001', 'news-category-finance-flash', 'em-202611243937740841-03f221db76', '回购升温、外资回补、“北水”提速 三路增量资金近期稳步入场港股', '“展望后市，随着人民币资产重估推进，外资对中国股票配置将逐步抬升，持续向基准中性水平修复。港股流动性约束比较强的阶段大概率已经过去。”光大证券首席资产配置分析师王开在接受上海证券报记者采访时表示，上市公司回购、南向定价权增强、外资回补三大因素共振，2027年港股有望进入流动性与估值双升的窗口期。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:16:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-650cbd230fbe692a', '100001', 'news-category-finance-flash', 'em-202611243937743958-b89cd56825', '监管部门部署两融逆周期调节措施落实细节', '融资融券逆周期调节措施将于11月30日正式实施。记者从业内获悉，为确保相关工作平稳有序开展，引导投资者理性投资，切实有效防范风险，监管部门向证券公司下发了《关于落实融资融券逆周期调节措施、提升风险管控有效性有关工作的通知》，围绕政策实施、风险统筹、行为管理、预期引导四方面作出部署。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:15:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ec9ca22dae8a161e', '100001', 'news-category-finance-flash', 'em-202611243937790084-711f7ab4ab', '法企425亿欧元投资“选择法国” 重点涉能源领域', '第二届面向本国企业的“选择法国”峰会11月23日在巴黎国际大学城举行。本届峰会汇集200多家法国企业，共展示273个投资项目，投资总额达425亿欧元。其中81个项目为首次公布，涉及投资金额149亿欧元，重点涉及能源、环境、人工智能、航空航天和医疗健康等领域。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:15:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-678da90b0782350b', '100001', 'news-category-finance-flash', 'em-202611243937741679-1a4f01de6d', '创新药：同步辐射光源点亮研发之路', '一束光，如何赋能创新药研发？在上海同步辐射光源，当高强度的X射线穿透蛋白质晶体，留下的衍射信号经过计算分析，便能倒推蛋白质的三维结构，为药物分子设计与优化提供关键依据。从看清生命分子的微观结构，到支撑创新药研发的日常流程，同步辐射光源正从科研利器走向产业一线，成为创新药企探索新靶点、开发新药物的重要基础设施。随着人工智能加速融入药物研发，这束光也正在打开新的应用空间。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c91e789af97d5bb', '100001', 'news-category-finance-flash', 'em-202611243937788277-dcac086bd5', '美媒：英伟达董事会短时间敲定黄仁勋回归 临时CEO等管理层不知情', '北京时间11月24日，据彭博社报道，知情人士透露，英伟达董事会出人意料地决定恢复黄仁勋(Jensen Huang)的CEO职务，但这一决定并未事先征求公司高层领导的意见。英伟达高管直到最后一刻才获知这一计划。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:11:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-44f773c374ffb827', '100001', 'news-category-finance-flash', 'em-202611243937788671-8c0ff0c085', '三星盘前上涨9% SK海力士上涨12%', '三星盘前上涨9%，SK海力士上涨12%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:11:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9ce9ec1e82c25cde', '100001', 'news-category-finance-flash', 'em-202611243937787068-c9217ae405', '黄仁勋回来了 英伟达一天涨出一个“摩根大通” 半导体指数狂飙14%', '当地时间11月23日，美三大股指大幅收涨，道琼斯指数涨3.01%，标普500指数涨4.74%，纳斯达克综合指数涨6.51%。黄仁勋复职带动AI相关股票普涨，费城半导体指数大涨14%，创2025年以来单日涨幅纪录。英伟达暴涨超31%，报165.05美元/股，单日市值增加创纪录的9520亿美元，市值重返全球第二位，总市值超3.98万亿。美光科技涨19%，英特尔涨超16%，台积电涨14%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:09:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-02cda58306a753ce', '100001', 'news-category-finance-flash', 'em-202611243937786244-d18464db0a', '台积电侯永清：AI成长趋势不变 未见客户调整订单或出货', '11月23日，台积电资深副总经理侯永清在一场座谈活动中表示，AI成长是大趋势，半导体技术则是推动AI成长不可或缺的必要条件。针对短期事件影响，目前没看到客户针对订单、出货有任何调整，甚至针对长期需求，目前看到需求依旧强劲，未有减弱趋势。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:06:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-303fb0400bc4ff9f', '100001', 'news-category-finance-flash', 'em-202611243937786578-7511b4b834', '黄仁勋回归难挡Anthropic跌势', '当地时间11月23日，黄仁勋回归英伟达掌舵的消息一度提振美股科技板块情绪，纳指相关AI、芯片标的出现脉冲反弹，但刚上市不久的AI独角兽Anthropic未能跟随回暖，全天维持弱势震荡。从分时盘面看，Anthropic当日开盘冲高后快速回落，日内反复震荡，最低下探至84.61美元附近，接近83美元的发行价。最终收报87.64美元，下跌1.43%，总市值11586亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:05:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b803db4d78259c29', '100001', 'news-category-finance-flash', 'em-202611243937783729-074122d89f', '美股股指期货高开 纳指期货涨0.15%', '美股股指期货高开，其中纳指期货涨0.15%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T23:00:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d5715acf90034fb0', '100001', 'news-category-finance-flash', 'em-202611243937783918-0b41795e06', '美联储威廉姆斯：如有需要不会排除连续加息的可能性', '美联储威廉姆斯称，如有需要，不会排除连续加息的可能性。数据将决定利率行动的时机和步伐。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:57:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8abd08f224bd20be', '100001', 'news-category-finance-flash', 'em-202611243937780292-170ab99ded', '德国总理：欧洲已做好准备与俄罗斯谈判', '德国总理默茨23日在柏林表示，欧洲已做好与俄罗斯谈判的准备，乌克兰问题顾问级别的和平谈判近期可能在阿联酋首都阿布扎比再次举行，由乌克兰、俄罗斯、欧洲和美国参加。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:45:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b62517bac23c1dbb', '100001', 'news-category-finance-flash', 'em-202611243937781589-3c03fd5ef9', '稳市场稳预期 政策“组合拳”精准发力 融资保证金比例下限调降 沪深交易所推出新一批降费措施', '沪深北交易所发布《关于调整融资保证金比例等相关安排的通知》，将融资保证金比例下限从100%降低至80%；深交所就《创业板股票做市交易业务细则》公开征求意见；沪深交易所发布《关于进一步减免相关费用的通知》，推出新一批降费措施；中国结算发布《关于暂免收取部分债券登记结算费用的通知》……11月22日，有关部门发布的一揽子政策，传递出稳市场稳预期的最新信号。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:44:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3318df3738871a59', '100001', 'news-category-finance-flash', 'em-202611243937779657-84d3312494', 'AI安全需求爆发！网安最大并购之一落地 多股明年业绩改善(名单)', '11月23日，CrowdStrike拟以439亿美元全股票收购Zscaler，为网安行业最大交易之一。机构预测，23只网络安全概念股明年业绩得到改善。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:42:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6751d05bdd52c03b', '100001', 'news-category-finance-flash', 'em-202611243937778517-ada6f432db', 'Anthropic首席执行官Amodei以每股83美元的价格出售340万股股票', 'Anthropic首席执行官Amodei以每股83美元的价格出售340万股股票。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:41:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b23bd3b56afbb5ef', '100001', 'news-category-finance-flash', 'em-202611243937740952-9d032f0338', '原煤产量稳步爬坡 煤企四季度业绩改善可期', '当前，北方地区已全面开启冬季供暖。山西省统计局数据显示，10月山西原煤产量达到8297.1万吨，较9月增加414万吨左右，增幅约为5%。此前，山西原煤产量于6月至9月出现明显回落，同比降幅超过30%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:31:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1b9e4a3e1c374fa9', '100001', 'news-category-finance-flash', 'em-202611243937741211-b890786d46', 'AI芯片供应链收紧 国产超节点迎发展机遇窗口', '近日，三星开始穿透严查代工的传闻流出。上海证券报记者向国内晶圆代工厂、芯片设计公司等多方求证获悉，该传闻并不准确，但传闻背后，是美国商务部工业和安全局（BIS）于11月16日出台新规带来的滥用出口管制。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:21:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5ebc5c6837096495', '100001', 'news-category-finance-flash', 'em-202611243937775047-d4d67c6675', '巴西石油公司PetroBras将支付156亿雷亚尔额外股息', '巴西石油公司PetroBras将支付156亿雷亚尔额外股息。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:20:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0dd19bb9511eaa4f', '100001', 'news-category-finance-flash', 'em-202611243937774627-a955dbc3a4', 'SharkNinja将纳入标普500指数', 'SharkNinja将纳入标普500指数。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:19:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5d532f343a3401c', '100001', 'news-category-finance-flash', 'em-202611243937743688-1dc9800f81', '频现增持信号 产业资本“纠偏”REITs定价', '公募REITs市场近期正释放积极信号。11月以来，汇添富、博时、南方等多家基金公司密集披露公告，旗下REITs的原始权益人拟逆势增持份额。部分业内人士认为，本轮产业资本的“增持潮”是二级市场回调背景下的定价纠偏，叠加锁仓承诺、集团层面参与等安排，信号“含金量”在提升。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:18:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-53c3a0ffee58541d', '100001', 'news-category-finance-flash', 'em-202611243937744191-d127d72ddf', '新增专项债发行接近尾声 增量资金有望加速到位', '今年新增专项债发行接近尾声。上海证券报记者梳理专项债券信息网披露数据发现，截至目前，2026年全国地方政府债累计发行规模达到9.98万亿元。其中，新增专项债已发行约4.13万亿元，发行进度为93%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:16:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-719499a46154164d', '100001', 'news-category-finance-flash', 'em-202611243937772746-310c6fcd62', '周二你需要知道的隔夜全球要闻：黄仁勋复职英伟达暴涨超31%；黄仁勋下周将赴美参议院公开作证；富国上调美国大盘股评级至“最看好”', '1、美三大股指大幅收涨，道琼斯指数涨3.01%，标普500指数涨4.74%，纳斯达克综合指数涨6.51%。标普500指数和纳指均创2025年4月8日以来最大单日涨幅。纳斯达克中国金龙指数收涨2.44%。2、黄仁勋复职带动AI相关股票普涨，费城半导体指数大涨14%，创2025年以来最大单日涨幅。英伟达暴涨超31%，报165.05美元/股，单日市值增加创纪录的9520亿美元。美光科技涨19%，英特尔涨超16%，台积电涨14%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:08:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-815135775b146fec', '100001', 'news-category-finance-flash', 'em-202611243937772219-6e39aeebdd', '美联储12月加息25个基点的概率为95.9%', '据CME“美联储观察”：美联储12月加息25个基点的概率为95.9%，加息50个基点的概率为4.1%。美联储到明年1月加息25个基点的概率33.2%，累计加息50个基点的概率为64.2%，累计加息75个基点的概率为2.7%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T22:07:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f1256e4e3419d311', '100001', 'news-category-finance-flash', 'em-202611243937763895-09a945bc12', '日内阁成员持续曝出丑闻 高市政府执政压力逐渐增大', '近日，日本文部科学大臣关芳弘因邀请政府部门工作人员出席政治筹款活动等问题而持续受到质疑，执政党和在野党内要求他辞职的呼声不断扩大。', 'published', NULL, FALSE, 100, 1, '2026-11-23T21:55:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d5172ae73a673a16', '100001', 'news-category-finance-flash', 'em-202611243937762329-2679f5377b', '美股生物制药公司Kymera Therapeutics将出售15亿美元的普通股', '美股生物制药公司KymeraTherapeutics将出售15亿美元的普通股。', 'published', NULL, FALSE, 100, 1, '2026-11-23T21:47:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2725b31859b1a804', '100001', 'news-category-finance-flash', 'em-202611243937760615-c22d337ccc', '消息人士表示 美联储监察机构调查理事鲍曼与美国银行客户的晚餐一事', '消息人士表示，美联储监察机构调查理事鲍曼与美国银行客户的晚餐一事。', 'published', NULL, FALSE, 100, 1, '2026-11-23T21:29:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f8c4b81db544dd95', '100001', 'news-category-finance-flash', 'em-202611243937759617-50a3e438de', '纽约联储主席威廉姆斯表示10月以来的数据、联邦公开市场委员会（FOMC）显示通胀仍然过高', '纽约联储主席威廉姆斯表示10月以来的数据、联邦公开市场委员会（FOMC）显示通胀仍然过高，预计2027年通胀将接近2%，失业率将降至约4%。', 'published', NULL, FALSE, 100, 1, '2026-11-23T21:25:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e9b69f5e3edf9f2b', '100001', 'news-category-finance-flash', 'em-202611243937759049-4900f29f5e', '比利时首相：分歧难消 政府仍未能就预算问题达成一致', '比利时王宫方面23日表示，当天，比利时首相德韦弗向国王菲利普汇报了预算谈判的最新情况。因分歧依旧，联合政府各政党仍未能就预算问题达成一致。', 'published', NULL, FALSE, 100, 1, '2026-11-23T21:23:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
