INSERT INTO news_item (
    id, tenant_id, category_id, slug, title, summary, status, author_name,
    featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
    ('news-item-6d0a2f42eb730d3b', '100001', 'news-category-finance-flash', 'em-202611223936893269-5f62bb6e3d', '启迪设计：股票将被实施其他风险警示 11月23日停牌一天', '启迪设计(300500.SZ)公告称，公司收到证监会江苏监管局《行政处罚事先告知书》，因原子公司虚增利润等事项，股票将被实施其他风险警示。公司股票于11月23日停牌一天，11月24日复牌并变更为“ST启设”，日涨跌幅限制仍为20%。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:35:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-15561efd1db36358', '100001', 'news-category-finance-flash', 'em-202611223936893119-f3331f4e0a', '天阳科技：因涉嫌信息披露违法违规 证监会决定对公司立案', '天阳科技(300872.SZ)公告称，公司于2026年11月20日收到证监会出具的《立案告知书》。因涉嫌信息披露违法违规，证监会决定对公司立案。立案调查期间，公司将积极配合调查并履行信息披露义务。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:34:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b7254cb90358c421', '100001', 'news-category-finance-flash', 'em-202611223936893086-d2372f4cd7', '金科股份：因涉嫌信息披露违法违规 控股股东及合伙人遭证监会立案', '金科股份(000656.SZ)公告称，公司控股股东京渝星筑、京渝星璨因涉嫌信息披露违法违规，收到证监会立案告知书；其合伙人北京天娇绿苑房地产开发有限公司亦被立案。公司表示，本次立案不涉及上市公司，生产经营正常，将配合调查并履行信披义务。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:33:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5f83ff194533fa35', '100001', 'news-category-finance-flash', 'em-202611223936892922-c9d9a30489', 'ST洲际：因涉嫌信息披露违法违规 证监会决定对公司立案', 'ST洲际(600759.SH)公告称，公司于2026年11月20日收到证监会下发的《立案告知书》，因涉嫌信息披露违法违规，证监会决定对公司立案。公司表示将积极配合调查，目前生产经营活动正常，该事项不会对生产经营产生重大影响。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:32:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4662dfa318d07595', '100001', 'news-category-finance-flash', 'em-202611223936892719-f685c9b91d', '印度总理莫迪呼吁减少购买黄金', '印度总理莫迪21日在北方邦首府勒克瑙出席活动时表示，印度民众听从他此前减少购买黄金的建议，如今金价大幅下跌，许多人因此避免了损失。莫迪回忆，他曾呼吁国民，若非必要，请一年内不要购买黄金。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:27:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-05b46e7d33d1f350', '100001', 'news-category-finance-flash', 'em-202611223936892196-e1d4f5453d', '阿富汗首都发生枪战 警方称打死3名武装分子', '雷克萨斯中国宣布，ES纯电版正式上市，全系标配宁德时代三元锂离子电芯，ES 350e长续航版综合工况续航707公里，售价33.99万元起；ES 500e高性能版零百加速5.5秒，售价35.99万元起。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:19:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9e3f0de95fca966b', '100001', 'news-category-finance-flash', 'em-202611223936891310-b767b74c17', '瑞士联邦副主席兼外长卡西斯将访华', '据外交部网站，外交部发言人宣布：应中共中央政治局委员、外交部长王毅邀请，瑞士联邦副主席兼外长卡西斯将于11月23日至24日访华并举行中瑞第五轮外长级战略对话。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:02:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-379e142ea48fb2c7', '100001', 'news-category-finance-flash', 'em-202611223936891254-df2d2e6b53', '周末要闻汇总：两部门出手 打击编造传播涉资本市场谣言行为', '沪深北交易所降低融资保证金比例下限至80%；沪深交易所、中国结算推出一揽子降费措施；深交所拟在创业板引入做市商制度；两部门公布4起典型案例，打击编造传播涉资本市场谣言行为；美方拟禁止中国电信运营商直接获取美国互联网电话号码资源，商务部回应；恒生指数公司宣布季检结果，恒生科技指数纳入20只股票；台湾金管会宣布稳定股市措施；特朗普称寻求与伊朗达成一项永久性协议；韩国财政部表示已准备好立即部署市场稳定基金；美股全线下挫，纳指跌超5%，费城半导体指数重挫近11%；报道称SEC正在调查英伟达的会计操作，英伟达跌逾14%。', 'published', NULL, FALSE, 100, 1, '2026-11-22T07:00:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7cca1afe7617297d', '100001', 'news-category-finance-flash', 'em-202611223936890886-98fe0d8bc5', '云南能投：实施积极、持续、稳定的分红政策，推动公司价值的更好实现', '云南能投在投资者关系活动中表示，公司紧紧围绕上市公司市值管理相关工作要求，聚焦公司价值创造、传播、实现各个环节。一是坚定不移做强做优做大绿色能源核心主业，加快推动盐业转型升级；二是高度重视股东回报，实施积极、持续、稳定的分红政策，现金分红水平逐年提高；与此同时，持续提升信息披露质量，加强投资者关系管理，推动公司价值的更好实现。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:55:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-192a1121debe6c8d', '100001', 'news-category-finance-flash', 'em-202611223936890921-0a793bd437', '云南能投：正有序有力推进昆明安宁350MW压缩空气储能示范项目建设', '云南能投在投资者关系活动中表示，公司锚定绿色能源发展战略，紧抓战略机遇，聚焦风电、光伏等绿色能源的投资、开发、建设和运营管理，积极拓展新型储能等新能源新赛道。新型储能方面，公司目前正有序有力推进昆明安宁350MW压缩空气储能示范项目建设。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:51:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1525d952242736d0', '100001', 'news-category-finance-flash', 'em-202611223936890417-f2718d96f6', '伊朗革命卫队公开新型导弹发射装置', '当地时间11月21日，伊朗国家电视台发布的一段视频显示，伊朗伊斯兰革命卫队总司令瓦希迪等高级官员日前现身革命卫队的一个地下导弹基地。视频中，伊朗伊斯兰革命卫队新研发的一种双联装导弹发射装置首次亮相。报道称，这种导弹发射装置能够同时携带并发射两枚液体燃料导弹。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:41:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-480ba46ae834bec0', '100001', 'news-category-finance-flash', 'em-202611223936889478-7906159219', '曹德旺：将继续把福耀玻璃美国工厂办好', '福耀玻璃工业集团创始人曹德旺20日在福耀玻璃美国有限公司（FGA）投产十周年庆典上表示，他将像爱护自己的生命一样爱护福耀玻璃在美国俄亥俄州的工厂，继续把企业办好。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:20:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ecbf1dbb2ea0931a', '100001', 'news-category-finance-flash', 'em-202611223936889013-f4d17cb9b2', '秘鲁卡鲁阿马约东北偏北15公里处发生5.0级地震', '据美国地质调查局消息，秘鲁卡鲁阿马约东北偏北15公里处发生5.0级地震。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:08:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-402cea993183850d', '100001', 'news-category-finance-flash', 'em-202611223936888694-2330c121fd', '袁记食品通过港交所聆讯', '11月22日记者了解到，袁记食品集团股份有限公司更新聆讯后资料集。数据显示，2023年—2025年，袁记食品营业收入分别为20.26亿元、25.61亿元、27.95亿元。2026年前五个月，其营业收入为13.06亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:05:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-60b9246c84b201bd', '100001', 'news-category-finance-flash', 'em-202611223936888819-c173df4bdc', 'PCB供应预警！常规材料或短缺至2027年上半年', '“印刷电路板日益短缺，正威胁下一波人工智能与电子行业的增长浪潮。”近日，总部位于美国的全球电子协会（Global Electronics Association）发布PCB供应预警报告。报告显示，从上游的玻纤布、树脂到下游的成品电路板，PCB供应链各环节均出现供不应求。尽管亚洲PCB产能仍在扩大，玻纤布、树脂、铜箔和生产设备的供应瓶颈，仍制约着成品板交付。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:04:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6d4d9746b4aa42c3', '100001', 'news-category-finance-flash', 'em-202611223936888920-37925e74c7', '陈茂波：香港可在世界湾区合作中作出独特贡献', '香港特区政府财政司司长陈茂波11月22日发表网志表示，香港在世界湾区合作中具有独特价值，可以作出更积极贡献。在近日于深圳举行的2026年亚太经合组织(APEC)工商领导人峰会上，中方提出支持成立世界湾区经济合作联盟，深化各湾区交流互动，探索亚太经济合作新路径。陈茂波表示，香港作为粤港澳大湾区的重要一员，亦以“中国香港”名义参与APEC，与其他经济体有着广泛且长期的联系。香港熟悉国际市场的规则和商业文化，也在大湾区的跨境商贸、金融、创科和专业服务合作方面，累积了丰富经验。', 'published', NULL, FALSE, 100, 1, '2026-11-22T06:02:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7755686badba2b48', '100001', 'news-category-finance-flash', 'em-202611223936888172-fe293ce760', '脑虎科技陶虎：量产是脑机接口的必经之路', '11月21日，“脑智芯联机遇昌平”2026脑机接口大会期间，脑虎科技创始人、CEO兼首席科学家陶虎在接受新京报贝壳财经采访时表示，量产是脑机接口的必经之路，作为国家未来产业之一，脑机接口的产业目标是将脑机接口培育成能够大范围使用、大范围获益的产品和行业，量产是脑机接口毋庸置疑的方向。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:53:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-701d9f58d668dae1', '100001', 'news-category-finance-flash', 'em-202611223936887785-e67a47e761', '巨型IPO之后美股大跌 历史现象又一次复现？', '类似现象在历史上多次出现。以本世纪为例，2000年4月27日，AT&T Wireless以约106亿美元募资成为当时美国最大IPO，但纳指早在当年3月见顶5132.52点，随后两年纳指最大跌幅近八成，互联网泡沫破灭。2007年6月22日，以房产领域投资见长的私募巨头黑石以约41亿美元募资成为当年美国最大IPO之一，当年10月标普500见顶，并在此后约1年半的时间累计下跌近60%。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:51:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-671db6a5345b6c8a', '100001', 'news-category-finance-flash', 'em-202611223936886863-2087ec0e68', '十大券商发声 坚定看好市场长期走势', '本周以来，A股市场出现一定幅度的调整，投资者情绪受到一定扰动。各大券商分析师普遍认为，短期波动更多是外部因素冲击下的情绪放大，而非基本面恶化；从中长期看，上市公司盈利改善、增量资金入市、政策持续发力以及AI产业趋势延续等多重积极因素正在积聚，A股长期向好的基础并未改变，当前的调整为中长期资金提供了布局窗口。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:24:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7dbd9aca8e214307', '100001', 'news-category-finance-flash', 'em-202611223936886762-566392ff4d', '刘烈宏赴江西省调研数据要素市场化配置改革工作推进情况', '人民财讯11月22日电，近日，国家数据局党组书记、局长刘烈宏带队赴江西省南昌市，实地调研江西省数字产业集团有限公司、华润江中药业股份有限公司、江西一脉阳光集团股份有限公司、江西时刻互动科技股份有限公司，并召开数字中国建设调研座谈会，深入了解地方推进数据要素市场化配置改革的问题和意见建议。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:22:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0508898ef8222559', '100001', 'news-category-finance-flash', 'em-202611223936885472-d83295f726', '英特尔、SpaceX还是另起炉灶？围绕黄仁勋“下一站” 市场上猜测四起', '英伟达前CEO黄仁勋接下来的去向，目前已成为华尔街和硅谷的热议话题之一。这位AI行业大佬的未来去向不仅关乎他个人，更关乎全球AI算力格局的走向。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:15:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b16581a588e46c62', '100001', 'news-category-finance-flash', 'em-202611223936886191-1bc268ca05', '战事影响能源供应 伊朗实施限电措施', '据伊朗官方媒体报道，由于中东地区战事导致伊朗关键基础设施受损、加剧该国能源危机，伊朗定于22日起实施轮流断电措施。伊朗国家电力公司负责人穆罕默德·拉达德21日告诉伊朗国家电视台，鉴于伊朗当下能源供应状况，电力部门不得不从22日起实施配电限制措施，方案为每两天停电约两小时，或每日最长停电两小时，具体停电时长因地而异。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:15:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-18f9da47ac76656c', '100001', 'news-category-finance-flash', 'em-202611223936884649-a8f452db93', '马斯克最新警告：人工智能行业明年可能面临严重的资金短缺 可能需要数千亿美元额外资金投入', '马斯克称，让如此大规模的算力设备通电、冷却并实现稳定运行，极其困难。人工智能行业明年可能面临严重的资金短缺。如果全行业从支付算力成本到设备能够稳定创收的时间累计推迟数月，仅营运资金就可能需要额外投入数千亿美元，马斯克反问这些资金将从何而来。', 'published', NULL, FALSE, 100, 1, '2026-11-22T05:01:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c03c289302fd582a', '100001', 'news-category-finance-flash', 'em-202611223936882096-f4a7d0f52c', '第二艘国产大型邮轮“爱达·花城号”正式开启商业首航', '第二艘国产大型邮轮“爱达·花城号”今天搭载3800余名宾客，从广州南沙国际邮轮母港出发，前往中国香港、越南顺化（真美），正式开启6天5晚的商业首航，标志着国产大型邮轮向规模化运营迈出坚实一步。2027年，“爱达·花城号”将以广州为母港运营50余个国际邮轮航次，兼顾短途休闲与中长线深度探索。', 'published', NULL, FALSE, 100, 1, '2026-11-22T04:34:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c3950eafc4fce9e1', '100001', 'news-category-finance-flash', 'em-202611223936880690-e7ff503305', '信用风波冲击债市！后市怎么走？机构这样看', '近期，受点状信用风险事件、资金面边际收敛以及国债免税政策预期变化等多重因素交织影响，国内债券市场出现一轮明显波动，理财赎回、债基被动卖券的负反馈一度发酵，十年期国债收益率出现阶段性上行。多位机构人士接受记者采访时表示，本轮调整属于阶段性扰动，债市中期运行逻辑并未发生改变，展望后市，利率债大概率维持区间震荡格局，但仍需关注财政供给、监管政策等潜在变量。', 'published', NULL, FALSE, 100, 1, '2026-11-22T04:33:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-89a046eeafc95a72', '100001', 'news-category-finance-flash', 'em-202611223936880444-e05e715d17', '美联储突传大消息！美股回吐2026年全部涨幅 加息或有变数？', '美联储加息，或有变数？美银首席投资策略师Michael Hartnett在最新一期《Flow Show》周报中指出，阻止美联储继续加息的最快方式，是让美国股市回吐2026年的全部涨幅。这一目标位对应标普500指数6845点，而该指数上周五收于6910点，距离触发仅剩65点、约1%的空间。', 'published', NULL, FALSE, 100, 1, '2026-11-22T04:20:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2d8c4889bb7dca0e', '100001', 'news-category-finance-flash', 'em-202611223936880523-8811deb7ec', '美国俄亥俄州发生枪击事件 3死1伤', '美国当地警方证实，美国俄亥俄州克利夫兰南部郊区21日发生枪击事件，有人在一个婴儿送礼会活动上开枪，造成3人死亡、1人受伤。警方接到报警称，克利夫兰郊区帕尔马镇有两名持枪人员，警方已确认并控制了两名持枪者。', 'published', NULL, FALSE, 100, 1, '2026-11-22T04:14:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-44eaa951a446c555', '100001', 'news-category-finance-flash', 'em-202611223936880354-85d6d565af', '金价暴跌 莫迪开心：像我这样的普通人劝大家少买黄金 印度人就真的少买了 听我话的人钱保住了', '据印度新德里电视台报道，印度总理莫迪21日在北方邦首府勒克瑙出席活动时表示，印度民众听从他此前减少购买黄金的建议，如今金价大幅下跌，许多人因此避免了损失。', 'published', NULL, FALSE, 100, 1, '2026-11-22T04:12:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a12144b469df7f16', '100001', 'news-category-finance-flash', 'em-202611223936880216-006d128416', '片仔癀总经理首秀道歉背后：不是需求没了 是渠道泡沫破了', '前不久，漳州片仔癀药业股份有限公司2026年第一次临时股东大会在福建漳州召开。履新不久的总经理施艺雄首次面对股东，开口第一句是道歉：“今年的业绩不够理想，一些股东压力很大，我们管理层压力也很大。”他没有把问题全部推给外部环境，而是列了“三个不够”：投放节奏不够精细、产品结构不够均衡、机制活力不够充足。', 'published', NULL, FALSE, 100, 1, '2026-11-22T04:06:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1f02de027852d203', '100001', 'news-category-finance-flash', 'em-202611223936880186-6650bbd8b0', 'AI新方法或有助优化败血症急诊救治流程', '英国伦敦国王学院日前发布消息说，该校研究人员开发出一种新方法，可通过分析败血症患者的就诊记录，找出对人工智能（AI）模型预测影响较大的环节，有望帮助医院查找败血症急诊救治延误的可能原因。研究人员说，这一方法还可纳入医护人员的专业判断，有望帮助医院确定应优先改进哪些环节。相关成果已在电气电子工程师学会国际数据挖掘会议上报告。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:59:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-afd2b324577e7f20', '100001', 'news-category-finance-flash', 'em-202611223936880078-31cd346dc1', '青藏铁路西格段扣停列车恢复运行 线路区间全面巡检', '从国铁青藏集团公司了解到，受昨晚（21日）青海省海西州地震影响扣停的部分青藏铁路列车，经铁路部门巡检确认线路设备完好，今天已限速恢复运行。青海省海西州德令哈市5.6级地震，波及青藏铁路西宁至格尔木段部分区间。地震发生后，铁路部门紧急扣停途经列车，并启动应急预案，封锁区间、进行设备全面巡检，同时准备了充足的食品、饮用水等应急物资，保障旅客需求。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:48:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a9330b542c32cf58', '100001', 'news-category-finance-flash', 'em-202611223936879550-0e60e7d045', '小鹏汇天首款全尺寸全倾转电动飞行汽车倾转过渡试飞成功', '11月22日，小鹏汇天宣布，全尺寸全倾转电动飞行汽车A868倾转过渡试飞成功。“倾转过渡成功”是指飞行汽车能够从垂直起降状态完整转换为高速平飞状态，这也是这款飞行汽车自去年11月完成首次起降试飞以来，正式从起降验证迈向全倾转等飞行能力。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:35:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-afcc8fdbd9dbf50f', '100001', 'news-category-finance-flash', 'em-202611223936879781-87e7497fa5', '重整之后，金科股份买下第一张“AI入场券”', '11月20日，金科股份（000656.SZ）重新站回1元面值之上。此前两个交易日，该股先后上涨6.90%、9.68%。市场本轮反弹，与其1.5亿至3亿元回购方案落地，以及近期落子AI算力运营的布局相关联。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:31:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-340fc6272b34117c', '100001', 'news-category-finance-flash', 'em-202611223936879138-f865c1ac8e', '下周A股28家公司限售股解禁：蓝特光学、炬光科技等热门股在列 多只价格曾翻倍', '数据显示，下周（11月23日至27日），A股共有28家上市公司限售股解禁，合计解禁数量约7.32亿股。其中，有10只个股解禁数量均超过1000万股。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:30:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-13ded1fd725942a2', '100001', 'news-category-finance-flash', 'em-202611223936878927-547c9dae40', '极氪法务部辟谣“召回”短信：系冒名诈骗', '11月22日，极氪法务部发布关于防范冒用极氪名义发布虚假召回信息的声明：我们注意到，近日有不法分子冒用极氪名义，向车主发送虚假召回短信。该类短信以车辆“存在安全隐患”、“逾期取消质保” 等表述制造紧迫感，同时附带非官方虚假网站链接，诱导车主跳转至仿冒页面、输入手机号及验证码登录后联系所谓 “客服” 办理召回手续，很可能造成用户的个人信息泄露和财产损失。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:29:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d83ceb032e546597', '100001', 'news-category-finance-flash', 'em-202611223936878680-834359c255', '韩国高考AI作弊事件发酵 教育部长引咎辞职', '当地时间22日，韩国教育部长官崔教振辞去职务，为韩国2027年度大学修学能力考试（韩国高考）期间防范高科技作弊措施不足引发混乱而承担责任。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:22:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7a8c651a57d7d5c1', '100001', 'news-category-finance-flash', 'em-202611223936878518-cf7866db8d', '郎平获国际排联最高荣誉“排球勋章”', '国际排联官网消息，当地时间11月21日，在多米尼加共和国举行的国际排联第40届代表大会上，中国排球名宿郎平与另外四位国际排球界杰出人士共同荣获国际排联最高荣誉——“排球勋章”。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:20:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cc032dd81862ee9e', '100001', 'news-category-finance-flash', 'em-202611223936877167-20072ab0bd', '同名同姓引误读 搜狐张朝阳辟谣“被出具警示函”', '北京证监局近日披露的一份对“张朝阳”采取出具警示函措施的决定在网络传播，部分舆论将该“张朝阳”与搜狐创始人、董事局主席兼首席执行官张朝阳关联。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:04:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-59efedaed099f581', '100001', 'news-category-finance-flash', 'em-202611223936876949-274df0ca8d', '中国石油天然气集团有限公司党组成员、副总经理谢军接受审查调查', '中国石油天然气集团有限公司党组成员、副总经理谢军涉嫌严重违纪违法，目前正接受中央纪委国家监委纪律审查和监察调查。', 'published', NULL, FALSE, 100, 1, '2026-11-22T03:00:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d0cf5869ac1a223d', '100001', 'news-category-finance-flash', 'em-202611223936876063-0d9c54e99a', '“张朝阳被证监会出具警示函” 搜狐创始人张朝阳：不是我 AI区别不了同名同姓的人', '针对“张朝阳被证监会出具警示函”的消息，搜狐创始人张朝阳公开回应：“搞错了吧，此张朝阳不是我。”张朝阳还提到，自己并没有收到警示函，也没有从事证券咨询业。他随后还略带调侃地补充道：“看来AI还是不行，区别不了同名同姓的人。”', 'published', NULL, FALSE, 100, 1, '2026-11-22T02:48:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f1090bb79e0c9364', '100001', 'news-category-finance-flash', 'em-202611223936875812-f481948235', '黄金连连溃败 逼近3500美元关口！华尔街齐呼：已跌入超卖区域', '在刚刚过去的一周，国际金价遭遇剧烈杀跌，3800、3700、3600美元关口接连失守，逼近具有重要心理意义的3500美元关口。上周五，美国黄金期货下跌4%，收报每盎司3539美元；现货黄金下跌2.41%，收报每盎司3538.11美元，盘中最低触及3502美元，单周跌幅达8.9%，创下3月20日当周以来最大单周跌幅。', 'published', NULL, FALSE, 100, 1, '2026-11-22T02:40:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cc3ddc04abb83ee4', '100001', 'news-category-finance-flash', 'em-202611223936875745-45625e3ff8', '困扰数学界167年的黎曼猜想被AI辅助证明？丘成桐回应', '北京时间11月21日晚间，著名数学家、清华大学求真书院院长、菲尔兹奖得主丘成桐对该事件发表看法称：“这是一个伟大的贡献，也可以讲震动了全世界，表示数学进入了一个新的纪元。”同时丘成桐强调，数学要向前迈进一大步，一个重要问题是往什么方向走，需要提出新的方案。希望年轻学者，尤其中国年轻数学家，能在此基础上发展出一套自己的理论，这对中国学者也是很好的机会。', 'published', NULL, FALSE, 100, 1, '2026-11-22T02:39:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-db32b5b9e4a1ec94', '100001', 'news-category-finance-flash', 'em-202611223936874946-6067177f87', '全球股市都在跌 下周A股会不一样吗？回测结果来了', '刚过去的交易周（11月16日至20日），A股市场与全球股市共振下跌。全球股市一周累计跌超8%，中国股市总体跌了2.4%，不过在周期制造、科技、医药方向的跌幅也不小。', 'published', NULL, FALSE, 100, 1, '2026-11-22T02:17:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-20af02853bd7b395', '100001', 'news-category-finance-flash', 'em-202611223936874337-22dcce1625', '亚马逊用接近75亿美元收购以色列AI 芯片初创公司 目标是对付英伟达', '据英国《金融时报》中文网22日报道，亚马逊接近达成75亿美元收购AI初创公司Decart的交易，此举凸显科技巨头增强AI能力的强烈意愿。', 'published', NULL, FALSE, 100, 1, '2026-11-22T02:07:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cfed83bd7bb3ce7a', '100001', 'news-category-finance-flash', 'em-202611223936874484-62d845cd7b', '伊朗打击美基地博弈再度升温', '据驻伊朗记者观察，随着伊朗当地时间11月21日晚对巴林境内美军基地实施打击，伊美博弈再度升温，危机走向牵动中东全局。一段时间以来，已经有多艘油轮在霍尔木兹海峡发生触雷起火，此外据伊朗统计，自美以伊40天战争后，伊朗已经陆续击落了数十架美军各型号无人机。伊朗舆论认为，卡塔尔和阿曼等国家做出了许多外交斡旋努力，海湾国家可以在缓和紧张局势方面发挥作用，但他们无法让美国解除对伊制裁，也无法确保伊朗在谈判桌上做出让步，因此，面对当前伊美“非战非和”的局面，双方必须重新审视各自的战略目标。', 'published', NULL, FALSE, 100, 1, '2026-11-22T02:06:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2a3712fa4698ea21', '100001', 'news-category-finance-flash', 'em-202611223936873915-3b666b249b', '脑机接口报告：全球企业增至1175家 中国三大城市群集聚190余家', '2026脑机接口大会发布《脑机接口创新发展研究报告（2026）》。《报告》指出，脑机接口产业在2026年取得了新进展，全球企业数量从原有的800多家增长到了1175家，市场变现主要来自两个领域：一是科研，二是医疗。目前中国脑机接口产业集聚在三大城市群，分别为京津冀、长三角和粤港澳。这三大城市群，分布着190多家脑机接口企业，占全国的77.4%。前五大省市分别为广东省、北京市、上海市、江苏省和浙江省。产业的下一个趋势是产业整合分化与治理监管并行，同质化发展会逐渐走向专业深耕与分工。', 'published', NULL, FALSE, 100, 1, '2026-11-22T01:52:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ddee8bd572df254e', '100001', 'news-category-finance-flash', 'em-202611223936872933-e2f7438a5c', '法国连续第6个周六举行示威活动', '法国巴黎等多地民众21日举行新的示威游行。这是法国自10月17日抗议酿成严重骚乱以来，连续第6个周六举行示威活动，但规模创新低。（新华社）', 'published', NULL, FALSE, 100, 1, '2026-11-22T01:25:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dc5575f7847e676f', '100001', 'news-category-finance-flash', 'em-202611223936872328-412979a8c7', '江南华南降水发展 新一股冷空气明起携大风降温来袭', '今天（11月22日）进入小雪节气，随着暖湿气流增强，南方降水发展，江南、华南部分地区有中雨。明天，新一股冷空气将登场，中东部将先后出现4℃至8℃的降温，其中东北气温起伏较大，公众需关注气温变化，及时添衣保暖，谨防感冒。', 'published', NULL, FALSE, 100, 1, '2026-11-22T01:15:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-45030b514aaeb102', '100001', 'news-category-finance-flash', 'em-202611223936871619-6b227da1af', '航行警告：东海部分海域进行军事训练活动', '据中国海事局网站消息，宁波海事局发布航行警告，11月22日12时至16时，东海部分海域进行军事训练活动，禁止驶入。', 'published', NULL, FALSE, 100, 1, '2026-11-22T01:06:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2194e02fbd567149', '100001', 'news-category-finance-flash', 'em-202611223936871775-5114d5cf16', '江苏省省长刘小涛会见香港航商总会主席赵式庆', '据新华日报，11月19日下午，江苏省省长刘小涛在南京会见香港航商总会主席、华光海运董事长赵式庆。', 'published', NULL, FALSE, 100, 1, '2026-11-22T01:06:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-46364e5d774d0a0c', '100001', 'news-category-finance-flash', 'em-202611223936871552-fa0d2461f3', '特斯拉在美推出FSDv 15', '特斯拉宣布在美国市场推出FSDv15，目前已向早期体验计划（EAP）成员推送首批版本。官方宣称，本次更新对安全关键场景的处理能力提升了25倍。本次更新还带来了“TeslaRealityView”全新可视化界面，车机屏幕上可显示摄像头画面叠加FSD行驶规划，支持全屏显示、地图或分屏视图，也可以选择使用安静模式。', 'published', NULL, FALSE, 100, 1, '2026-11-22T01:04:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9405b0d54fe72d56', '100001', 'news-category-finance-flash', 'em-202611223936870690-f64d058dc2', '回归路变窄 美媒：黄仁勋还有五招重掌英伟达', '北京时间11月22日，据《商业内幕》报道，黄仁勋(Jensen Huang)重返英伟达CEO职位的道路可能正在变窄，但他仍有办法为回归而战。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:56:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-143cacd179c7a99e', '100001', 'news-category-finance-flash', 'em-202611223936870515-82f9231dfe', 'Claude宣称攻克黎曼猜想数小时后，斯坦福数学家公布纯人类证明', '北京时间11月22日，据科技媒体The Decoder报道，围绕数学界最著名的未解难题之一——黎曼猜想，一场人工智能与人类数学家的“证明竞赛”正在上演。Anthropic数学家莱文特·阿尔佩格（Levent Alpge）宣布，他与Claude合作找到了广义黎曼猜想的证明。仅数小时后，斯坦福大学研究人员也公开了一份完全由人类独立完成的竞争性证明草稿。 不过，两项成果目前均有待数学界进一步验证。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:54:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b1df45a4344e81df', '100001', 'news-category-finance-flash', 'em-202611223936870248-71886592b8', '中国诚通总经理郭祥玉赴成渝地区开展工作调研', '中国诚通消息，11月19日至21日，集团党委副书记、总经理郭祥玉带队赴成渝地区开展工作调研。11月19日，郭祥玉带队调研成都瑞雪丰泰精密电子公司和成都电气公司，详细了解超高精度射频类、太赫兹类及激光通信精密零组件产品制造流程、核心技术及市场应用情况、高端工业节能透平装备研发制造等情况。11月20日，郭祥玉带队赴重庆与中国长安汽车党委书记、董事长朱华荣，党委常委、总会计师王锟就加强多领域合作座谈交流，并调研中国长安汽车天枢智能实验室，深入了解首个央企自研智能驾驶辅助解决方案——长安天枢领航及中国长安汽车在智能化、未来产业领域的发展成果。在渝期间，郭祥玉还带队会见了重庆市科技局党委书记、局长方磊，双方围绕强化资本赋能、推动科技创新与产业创新深度融合进行交流。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:46:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-97e98a3f5e6ff33b', '100001', 'news-category-finance-flash', 'em-202611223936869982-120e6ceef1', '美军欲在艾奥瓦州引爆有毒化学物质引争议', '美国一个联邦巡回上诉法院19日要求美国陆军暂停推进在艾奥瓦州引爆68桶有毒含铅化合物的计划。当地民众和环保组织担忧，引爆可能对环境造成不可逆转的影响，要求法院阻止引爆。由于这一计划引发争议，美国陆军已把引爆日期从20日推迟至23日。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:44:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5c739149a530c023', '100001', 'news-category-finance-flash', 'em-202611223936868237-b564638abb', '数学界百年难题被AI攻克？马斯克称成果令人震撼', '北京时间11月22日，特斯拉CEO埃隆·马斯克（Elon Musk）在社交平台X发文，谈及人工智能证明数学界著名难题“黎曼猜想”的意义，并将这一成果称为超级智能取得的又一项令人震撼的成就。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:20:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-72436108624ad9c7', '100001', 'news-category-finance-flash', 'em-202611223936867724-13dd91367a', '纽约时报：硅谷还在为AI狂欢 华尔街却开始担心一个问题', '《纽约时报》报道，人工智能公司Anthropic本周创下史上最大规模IPO纪录，但上市后的股价表现却让投资者感受到AI热潮背后的风险。Anthropic上市所引发的市场波动，正在凸显硅谷与华尔街之间日益扩大的分歧：科技公司坚信人工智能将重塑全球经济，但投资者越来越担心，支撑这场技术革命的巨额投入，究竟何时才能转化为可持续的利润。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:18:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8bdc9f2f08f429ad', '100001', 'news-category-finance-flash', 'em-202611223936867855-ab736ae3f0', '上海电气与中国重燃签署合资合作框架协议', '11月20日，2026年重型燃气轮机现代产业链共链行动大会暨产业化推进会在上海临港召开。会上，国家电投集团中国重燃集中推介300兆瓦自主重型燃机产品，并与上海电气签署合资合作框架协议，同时与上海汽轮机厂签署产业链党建联建共建协议。大会发布首批重型燃气轮机现代产业链“场景＋平台”，公布自主重型燃气轮机研制需求。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:15:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-70b3fc8d54e2819a', '100001', 'news-category-finance-flash', 'em-202611223936867913-64b4a3d003', '近一周机构调研个股120多只 多股最新滚动市盈率低至个位数', '近一周（11月14日至20日）机构调研个股有120多只，微导纳米调研机构数最多。', 'published', NULL, FALSE, 100, 1, '2026-11-22T00:14:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f60639bdc8699302', '100001', 'news-category-finance-flash', 'em-202611223936867093-e1d7c7bcba', '加拿大正式加入北约创新基金', '加拿大国防部长戴维·麦金蒂当地时间21日宣布，加拿大正式加入北约创新基金，成为第25个加入该基金的北约成员国，也是北美地区首个加入该基金的成员国。', 'published', NULL, FALSE, 100, 1, '2026-11-21T23:44:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5dc2e71b8c289a81', '100001', 'news-category-finance-flash', 'em-202611223936865989-eb9ecaeef5', '美股遭遇恐慌性抛售 多家华尔街机构认为或只是牛市调整', '尽管近日市场遭遇猛烈抛售，但多家华尔街机构认为，当前下跌可能只是牛市中的一次调整，尚未构成基本面持续恶化的明确信号。', 'published', NULL, FALSE, 100, 1, '2026-11-21T23:25:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2fe3cfece8e999e3', '100001', 'news-category-finance-flash', 'em-202611223936859929-bb46299e17', '中国文旅在伦敦世界旅游交易会受青睐', '2026年伦敦世界旅游交易会日前在伦敦展览中心举行，来自180多个国家和地区的4000余家参展商齐聚一堂，展示旅游产品，对接合作资源，寻找新的市场机遇。中国展区以“中国旅游：文塑旅彰，智创未来，绿色共生”为主题亮相，整体设计融合东方美学与现代活力，成为本届交易会最亮眼的展区之一。', 'published', NULL, FALSE, 100, 1, '2026-11-21T22:59:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9fd945b73bcd3647', '100001', 'news-category-finance-flash', 'em-202611223936865236-f64a36e711', '阿尔及利亚国防部称击毙两名涉嫌贩毒的摩洛哥公民', '阿尔及尔消息：阿尔及利亚国防部21日表示，阿尔及利亚边防人员20日在该国西部边境附近击毙两名涉嫌参与毒品走私的摩洛哥公民。阿国防部在一份声明中表示，两名嫌疑人无视边防人员警告，试图向阿尔及利亚走私超过50公斤的大麻制品。阿国防部还通报称，在另一次行动中，阿军方捣毁一个涉嫌从摩洛哥走私大麻制品的犯罪网络，一周内查获近1.9吨毒品并逮捕17名嫌疑人，还查获数十辆车和大笔现金。', 'published', NULL, FALSE, 100, 1, '2026-11-21T22:49:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-69163c3de5e08b27', '100001', 'news-category-finance-flash', 'em-202611223936864714-c8b3325bc1', '特朗普拟联手民主党 将信用卡利率上限设为10%', '当地时间周六，美国总统特朗普表示，愿与即将掌控国会两院的民主党合作，推动将信用卡利率上限设为10%，以兑现其2024年竞选承诺。他称，信用卡公司“已经赚了很多钱”。民主党参议员沃伦随后回应称：“让我们限制信用卡利率，为美国民众省钱。”沃伦预计将出任下一届参议院银行委员会主席。特朗普今年1月曾提出这一计划，但遭到银行业强烈反对，共和党控制的国会也未积极推动。', 'published', NULL, FALSE, 100, 1, '2026-11-21T22:29:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e23b3f434b496fdb', '100001', 'news-category-finance-flash', 'em-202611223936863164-856c17a23e', '也门政府军称继续打击胡塞武装目标', '当地时间21日晚间，也门政府军表示，政府军在代号为“也门黎明”的军事行动中，继续打击胡塞武装目标。过去24小时内，政府军共实施816次军事行动，造成149名胡塞武装人员死伤。', 'published', NULL, FALSE, 100, 1, '2026-11-21T22:20:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b0dc09d185025875', '100001', 'news-category-finance-flash', 'em-202611223936860046-3708d564b8', '异地存款收紧保障储户权益', '近期，多地民营银行发布个人存款业务属地化整改公告，暂停异地新增存款。10月份，天津金城银行发布《关于个人存款业务属地化调整的公告》，逐步暂停向非天津客户新增销售个人存款产品。9月份，无锡锡商银行也对个人存款业务属地化进行调整，明确个人存款业务仅限江苏省内本地客户办理。据不完全统计，截至目前，全国19家民营银行中，10余家已实施个人存款属地化整改。', 'published', NULL, FALSE, 100, 1, '2026-11-21T21:59:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bcf739fc2254443b', '100001', 'news-category-finance-flash', 'em-202611223936860314-0e91ce6c0d', '稳步扩大金融市场双向开放', '前段时间，中国人民银行召开外资金融机构座谈会，听取外资金融机构意见建议，研究进一步优化营商环境、推动金融业高水平对外开放有关工作。本次座谈会释放出清晰信号：中国将继续推动金融高水平开放，持续完善政策供给，稳步扩大金融市场双向开放，不断优化跨境支付服务，更加便利人民币国际使用。', 'published', NULL, FALSE, 100, 1, '2026-11-21T21:46:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ce3f52dfd9a7e645', '100001', 'news-category-finance-flash', 'em-202611213936851119-aa65e18505', '又一百万吨长协落子 中国从最大天然气买家转向国际能源“协调者”', '今年以来，地缘局势持续扰动全球能源市场。依托国内充足的天然气供给底盘与多元进口保障体系，中国正在从全球最大天然气进口国，转变为国际能源资源再平衡的重要协调者。', 'published', NULL, FALSE, 100, 1, '2026-11-21T21:20:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0ac39737f424b9c8', '100001', 'news-category-finance-flash', 'em-202611223936859297-8a394f07a5', '刚果（金）本轮埃博拉疫情死亡病例超5600例', '当地时间11月21日，刚果（金）卫生部门最新数据显示，截至目前，该国本轮埃博拉疫情已累计报告确诊病例11613例，其中5678人死亡，总病死率为48.9%。目前已有3148名患者康复出院，1743人仍在接受治疗或隔离，密切接触者追踪率为82.6%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T21:00:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9f82f539503ecfb4', '100001', 'news-category-finance-flash', 'em-202611213936854914-92e3112c64', '多家银行发债按下“暂停键”', '10月末以来，债券市场持续调整，部分商业银行的发债计划也按下了“暂停键”。截至11月20日，工商银行、浦发银行、兴业银行、郑州银行、张家港农商行、湖北银行均发布公告推迟了债券发行。', 'published', NULL, FALSE, 100, 1, '2026-11-21T20:40:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e8609dd28bc302f0', '100001', 'news-category-finance-flash', 'em-202611223936859045-914a98c6a0', '伊朗方面称美军“爱国者”导弹击中巴林平民区', '当地时间21日晚，伊朗方面消息称，一枚从美国第五舰队军事基地发射、原定用于拦截任务的“爱国者”导弹，坠落在了巴林的一处居民区。', 'published', NULL, FALSE, 100, 1, '2026-11-21T20:21:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d042f768d546f0e2', '100001', 'news-category-finance-flash', 'em-202611223936859191-c08814fcb5', '伊朗副外长证实调解方卡塔尔代表团访问德黑兰', '据伊朗伊斯兰共和国通讯社21日报道，伊朗外交部负责法律和国际事务的副部长加里巴巴迪当天证实，卡塔尔代表团20日晚访问德黑兰，与伊方举行了约两小时会谈。伊朗正与包括卡塔尔在内的调解方保持接触，探讨能否再次推动外交途径解决与美国之间的冲突问题。', 'published', NULL, FALSE, 100, 1, '2026-11-21T20:10:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-62fa5bb1f90b5f53', '100001', 'news-category-finance-flash', 'em-202611223936858262-56e8167de0', '沙特主导的多国联军称拦截并摧毁一架来袭无人机', '当地时间21日，沙特主导的多国联军发言人在社交平台上发文表示，联军已拦截并摧毁一架由也门胡塞武装向沙特利雅得地区发射的无人机。', 'published', NULL, FALSE, 100, 1, '2026-11-21T19:55:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e4d168add628301b', '100001', 'news-category-finance-flash', 'em-202611223936858367-54a9cf9b5a', '伊朗伊斯兰革命卫队对巴林美军基地进行打击', '伊朗方面当地时间21日晚消息称，伊朗伊斯兰革命卫队对位于巴林的两处美军军事基地发动打击。此外，巴林内政部当天也发布消息称，巴林境内一处民用设施遭遇伊朗袭击。袭击导致该处设施起火，目前民防部门正在组织救火行动。', 'published', NULL, FALSE, 100, 1, '2026-11-21T19:42:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-92b01cfd01894ace', '100001', 'news-category-finance-flash', 'em-202611223936858484-a1fd7b6c6e', '墨西哥军方抓获一名被美国联邦调查局通缉的毒枭', '当地时间11月21日，墨西哥国防部宣布，该国特种部队20日晚在锡那罗亚州成功抓获绰号“矮子伊西德罗”的毒枭福斯托·伊西德罗·梅萨-弗洛雷斯。此人被列为美国联邦调查局十大通缉要犯之一，美方曾悬赏500万美元征集线索。', 'published', NULL, FALSE, 100, 1, '2026-11-21T19:20:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f1f52cdfd755c5e6', '100001', 'news-category-finance-flash', 'em-202611223936858120-a6cba2e042', '伊朗霍尔木兹甘省锡里克附近海面传出爆炸声', '当地时间21日，伊朗方面消息称，位于霍尔木兹甘省东部的锡里克居民报告，几分钟前听到从海面方向传来巨大的爆炸声。', 'published', NULL, FALSE, 100, 1, '2026-11-21T19:00:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bdbf953ce572da2f', '100001', 'news-category-finance-flash', 'em-202611223936858093-2e00a173c8', 'Anthropic创纪录IPO：亚马逊和谷歌成最大赢家', '本周，人工智能（AI）公司Anthropic创纪录的首次公开募股（IPO）让多家硅谷风险投资机构及科技巨头获得了巨额账面回报。其中，亚马逊和谷歌成为持股价值规模最大的机构投资者。按照11月20日收盘价计算，两家公司所持Anthropic股份合计价值约3300亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T18:40:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-889fc0499965bc98', '100001', 'news-category-finance-flash', 'em-202611223936857969-16c566cbe9', '2026中国电影节在哥伦比亚开幕', '2026中国电影节20日在哥伦比亚首都波哥大开幕，200余名各界嘉宾出席开幕式，并观看开场电影《给阿嬷的情书》。', 'published', NULL, FALSE, 100, 1, '2026-11-21T18:20:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bfad82d39cde7df8', '100001', 'news-category-finance-flash', 'em-202611213936854115-8f56a0d08e', '《GTA VI》火了 游戏主机也涨疯了！PS5 Pro一年涨价超一倍', '近日，《侠盗猎车手》系列新作《GTA VI》重磅回归，市场热度再创新高。游戏发售首日全球零售额达到37.9亿美元，创下娱乐行业历史最高首发纪录。正式发售前，预售销量已达3250万份。然而，对于准备购买游戏主机的玩家来说，迎接他们的可能不只有新游戏，还有越来越贵的游戏主机。', 'published', NULL, FALSE, 100, 1, '2026-11-21T18:00:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b3a39601d3c80dbe', '100001', 'news-category-finance-flash', 'em-202611223936857888-1dabbed285', '北约秘书长：将捍卫波兰“每一寸领土”', '北约秘书长吕特21日就波兰方面通报的领空遭侵犯事件表示，北约将捍卫波兰的“每一寸领土”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T17:40:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cee12d9133d0cd0f', '100001', 'news-category-finance-flash', 'em-202611223936857732-d7003baf26', '也门荷台达传出爆炸声', '当地时间21日晚，总台报道员在也门荷台达市听到爆炸声，该地区疑似遭沙特主导的多国联军空袭，但具体遭袭地点尚不明确。', 'published', NULL, FALSE, 100, 1, '2026-11-21T17:20:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a26bcca8a316afed', '100001', 'news-category-finance-flash', 'em-202611213936855553-6cc789a56b', '华为推出星芒 AI手机的故事怎么落地？', '11月20日，华为子品牌星芒手机发布。此时行业环境并不轻松：存储芯片已占手机BOM的49%，厂商一边涨价、一边收缩产品线；华为却逆势新开一条子品牌线，试水AI手机。记者从华为方面获悉，星芒共享麒麟芯片、鸿蒙操作系统等核心技术底座，聚焦原创设计、前沿技术与全新AI交互，并承担技术试验田角色。这意味着，星芒并非简单加入走量竞争，而是以差异化定位承接华为的前沿探索。', 'published', NULL, FALSE, 100, 1, '2026-11-21T17:00:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-799a2f73d2ed63b8', '100001', 'news-category-finance-flash', 'em-202611223936857611-ad3c45576e', '伊朗副外长称与卡塔尔代表团在德黑兰举行磋商', '当地时间21日，伊朗副外长加里巴巴迪表示，一个卡塔尔代表团于20日晚抵达伊朗首都德黑兰，双方进行了两个小时的磋商。', 'published', NULL, FALSE, 100, 1, '2026-11-21T16:40:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c9ecc9b84db7cd4c', '100001', 'news-category-finance-flash', 'em-202611213936856371-252464d9fa', '167年数学难题被攻克？90后数学家联手AI 最新公布', '人工智能（AI）向探索科研级数学问题深处不断迈进。美国时间2026年11月20日，Anthropic数学家莱文特·阿尔波格（Levent Alpge）宣称与AI合作证明了167年未解的黎曼猜想，但超25万页证明仅以代码公开，引发学界震动与争议。', 'published', NULL, FALSE, 100, 1, '2026-11-21T16:20:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ab3e8509b7329335', '100001', 'news-category-finance-flash', 'em-202611213936559175-121c467763', '宽基ETF频现巨量成交 本轮资金流入逾6700亿元', '在震荡调整的市场行情中，大量资金借道ETF积极入市。11月20日，多只宽基ETF成交金额超过百亿元，部分ETF成交额创历史纪录。从本轮资金流向看，9月28日以来，股票型ETF资金净流入已超过6700亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T16:09:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0c5a728372bf61de', '100001', 'news-category-finance-flash', 'em-202611203936446945-530e3b6dab', '小微盘股指数集体走出“七连跌” ETF资金流向为何分化', '数据显示，近两周以来跟踪中证1000、中证2000等小微盘指数的ETF整体呈资金净流出态势，34只产品近两周资金合计净流出70.35亿元。一些受访人士认为，本轮下跌与部分由于小微盘股前期积累了一定的涨幅同时缺乏基本面支撑，也与近期市场成交量、两融余额持续萎缩等因素有关。', 'published', NULL, FALSE, 100, 1, '2026-11-21T16:06:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ba47ce4868d61f67', '100001', 'news-category-finance-flash', 'em-202611213936855865-8e75bade6c', '“半个月几乎打光子弹”！多家券商公告 控股股东“超速”增持', '近日，多家券商发布增持回购的进展情况。国联民生的控股股东，原计划用5个月时间增持国联民生，结果半个月左右，就几乎打光了增持的资金额度。中泰证券，原计划用1年的时间回购股份，最新情况是仅2个月左右就顶格完成了回购。国金证券称，券商板块PB跌至1.03倍，约十年3%分位数，位于破净边缘；PE跌至12倍，位于十年1%分位数，板块配置性价比高。', 'published', NULL, FALSE, 100, 1, '2026-11-21T16:00:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-30ca643961a1999e', '100001', 'news-category-finance-flash', 'em-202611213936856797-fccf96806c', '特朗普称没有考虑伊朗政权更迭', '美国总统特朗普在美国福克斯新闻频道21日播出的采访节目中说，没有考虑伊朗政权更迭。', 'published', NULL, FALSE, 100, 1, '2026-11-21T15:45:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c82004da813de5e7', '100001', 'news-category-finance-flash', 'em-202611213936856463-455e080847', '伊朗称在波斯湾北部拦截一架敌方侦察无人机', '当地时间21日，伊朗伊斯兰革命卫队宣布，不久前，卫队航空航天部队的防空系统成功拦截并击落了一架侵入伊朗领空的敌方侦察无人机。伊朗伊斯兰革命卫队表示，此次行动发生在波斯湾北部，即布什尔沿海水域。伊朗防空部队通过精准有效的火力完成了此次拦截。任何对伊朗领空的侵犯都是绝对不可接受的。', 'published', NULL, FALSE, 100, 1, '2026-11-21T15:36:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-238ffeb7b8baf55d', '100001', 'news-category-finance-flash', 'em-202611213936855242-eca7988f3e', '特朗普：将与伊朗达成一项永久性协议', '美国总统特朗普在美国福克斯新闻频道21日播出的采访节目中说，将与伊朗达成一项永久性协议。', 'published', NULL, FALSE, 100, 1, '2026-11-21T15:19:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ee76356b4d989c45', '100001', 'news-category-finance-flash', 'em-202611213936854814-4667d333ea', '芬兰称俄罗斯一货船在芬兰湾遭袭起火 俄方发文证实', '芬兰国防部21日发布公告说，芬兰边防军当天上午在芬兰湾东部国际水域监测到一艘俄罗斯货船船体受损并起火，疑遭无人机袭击。俄罗斯列宁格勒州州长随后发文证实一艘俄罗斯货船在该水域遭无人机袭击。', 'published', NULL, FALSE, 100, 1, '2026-11-21T15:12:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ad8316f3f9623c1c', '100001', 'news-category-finance-flash', 'em-202611213936854227-b7da444e6a', '美军中央司令部：伊朗击伤美军F-16战机说法不实', '美军中央司令部21日发表声明说，伊朗伊斯兰革命卫队称其20日击伤一架美军F-16战机并迫使其紧急降落的说法不实。', 'published', NULL, FALSE, 100, 1, '2026-11-21T14:57:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9124ead6ad76afb6', '100001', 'news-category-finance-flash', 'em-202611213936853681-93c28ba350', '卡塔尔代表团抵伊朗磋商两小时', '当地时间11月21日，伊朗副外长加里巴巴迪表示，一个卡塔尔代表团20日晚抵达伊朗首都德黑兰，双方进行了两个小时的磋商。', 'published', NULL, FALSE, 100, 1, '2026-11-21T14:39:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6475a6e37f504eee', '100001', 'news-category-finance-flash', 'em-202611213936853298-cfb4a5d9f6', '秘鲁胡宁省6.7级地震已造成8人受伤', '据秘鲁国家民防研究所今天（11月21日）最新通报，秘鲁胡宁省6.7级地震已造成8人受伤，128户房屋受到影响，另有4户房屋被毁。此次地震波及范围较广，秘鲁首都利马等地均有震感。（CCTV国际时讯）', 'published', NULL, FALSE, 100, 1, '2026-11-21T14:28:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fea3b858c44cc74d', '100001', 'news-category-finance-flash', 'em-202611213936852329-174340f272', '亚投行将在香港设立办公室', '中华人民共和国政府与亚洲基础设施投资银行（亚投行）21日在香港签署《中华人民共和国政府与亚洲基础设施投资银行关于在中华人民共和国香港特别行政区设立办公室的协定》，为亚投行在香港开设办公室奠定基础。中华人民共和国政府与亚投行分别由财政部部长蓝佛安和亚投行行长邹加怡代表签署协定。该协定确定亚投行于香港设立办公室，并为特权、豁免与其他有助成立办公室的事宜制定原则。', 'published', NULL, FALSE, 100, 1, '2026-11-21T14:24:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-81acabc08fb6321d', '100001', 'news-category-finance-flash', 'em-202611213936852284-7966cffd7e', '受地震影响 途经青藏铁路西格段部分列车晚点运行', '记者从国铁青藏公司了解到，今天（21日）18时45分，青海省海西州德令哈市发生5.6级地震，地震波及青藏铁路西宁至格尔木段部分区段，铁路部门紧急扣停途经列车，部分列车晚点运行。目前铁路部门已启动应急预案，对封锁区间进行设备全面巡检并准备充足的食品、饮用水等应急物资，保障旅客需求。', 'published', NULL, FALSE, 100, 1, '2026-11-21T14:23:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1a8283c6f77a29de', '100001', 'news-category-finance-flash', 'em-202611213936851955-2f265a28a5', '以军袭击加沙城一辆汽车 致3死多伤', '据巴勒斯坦方面当地时间21日消息，以色列军方战机当天中午袭击了加沙地带加沙城西南部的一辆汽车，造成3名巴勒斯坦人死亡、另有数人受伤。', 'published', NULL, FALSE, 100, 1, '2026-11-21T14:06:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d5e0fe3b4faa1b73', '100001', 'news-category-finance-flash', 'em-202611213936850943-2c24dd411e', '青海德令哈5.6级地震 救援人员已抵震中未发现人员伤亡', '青海省海西蒙古族藏族自治州德令哈市发生5.6级地震，震源深度10公里，震中位于北纬37.14度，东经96.62度，震中距德令哈市约70公里。', 'published', NULL, FALSE, 100, 1, '2026-11-21T13:56:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fa6ea75625acf23f', '100001', 'news-category-finance-flash', 'em-202611213936848634-bc0e468806', '韩国悬赏重金查处高考作弊者', '韩国总统李在明21日说，今年韩国大学修学能力考试即高考中，作弊行为的举报者可获得1亿韩元（约合7.4万美元）奖金。', 'published', NULL, FALSE, 100, 1, '2026-11-21T13:41:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8595ef6daf5e1351', '100001', 'news-category-finance-flash', 'em-202611213936846972-479aa4b26d', '伊朗称击中一架F-16战机', '据伊朗媒体21日报道，伊朗军队防空系统20日在波斯湾上空拦截并击中一架F-16战机，该战机受损，在某机场紧急降落。', 'published', NULL, FALSE, 100, 1, '2026-11-21T13:34:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fe55b2510dae6520', '100001', 'news-category-finance-flash', 'em-202611213936845370-ef32d1ca41', '数万家智能工厂背后 AI到底改变了什么？', '“过去靠看风口亮度、听异响、摸水温来判断炉况，现在，我们给高炉装上了‘透视眼’。”南钢人工智能研究院院长李瑾彦说，高炉周边布设了上千个传感器，实时采集温度、压力、图像等多维数据，铁水一级品率提升了10个百分点，217个产品和技术达到国际领先水平。印象中“傻大黑粗”的钢铁企业，依靠“智改数转网联”，实现了从依赖个人经验的“手工作坊式”操作，到依靠数据算法的标准化、精准化生产的转变。', 'published', NULL, FALSE, 100, 1, '2026-11-21T13:25:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e89f2b5bf064d11d', '100001', 'news-category-finance-flash', 'em-202611213936842937-4aaf0f0000', '泽连斯基会见英国国防大臣 讨论乌防空能力建设', '当地时间11月21日，乌克兰总统泽连斯基在基辅会见到访的英国国防大臣斯特里廷。双方重点就乌防空能力建设、“爱国者”防空系统所用拦截弹供应、联合武器生产、远程打击能力等议题进行磋商。', 'published', NULL, FALSE, 100, 1, '2026-11-21T13:06:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-59c9568ae8f9baef', '100001', 'news-category-finance-flash', 'em-202611213936843092-49adeaf95d', '美国火车盗窃团伙落网 案值逾2000万美元', '11月21日消息，美国司法部说，日前抓获一个专门盗窃货运列车的团伙。该团伙共有14人，年龄从21岁至38岁不等。2024年2月至2026年8月期间，这一团伙在加州南部持续作案，盗窃至少36趟货运列车，失窃货物总值约2250万美元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T13:02:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b8bb0179af8178c9', '100001', 'news-category-finance-flash', 'em-202611213936842490-a555480d11', '欧盟再对乌提供10亿欧元军事支持', '欧盟理事会11月20日通过两项决定，批准通过欧洲和平基金再向乌克兰提供10亿欧元军事支持，用于为乌克兰武装部队采购军事装备。这批装备包括无人机、防空装备、弹药、电子战设备和雷达系统等，计划于2027年底前交付。', 'published', NULL, FALSE, 100, 1, '2026-11-21T12:36:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-39b49b8b16dcc42a', '100001', 'news-category-finance-flash', 'em-202611213936841243-be5a041007', '公司产品会否提价？光威复材回复', '有投资者在互动平台向光威复材提问：“中复神鹰于8月份开始对全系列产品提价5%～10％，请问贵公司会同步提价吗？”光威复材回复：公司产品价格依据具体产品、应用领域、合同约定、市场供需、产品成本等因素确定，公司会密切关注市场状况变化，及时合理调整市场策略积极应对市场环境变化。', 'published', NULL, FALSE, 100, 1, '2026-11-21T12:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5befc8c7c8844fbf', '100001', 'news-category-finance-flash', 'em-202611213936857159-d0d7ae850e', '台湾金管会宣布稳定股市措施', '11月21日消息，中国台湾地区金管会宣布进一步稳定市场的措施，实施全面禁止卖空以稳定市场，上市柜个股最低融券保证金成数由130%升为150%。“国安基金”表示已进场买入股票。', 'published', NULL, FALSE, 100, 1, '2026-11-21T12:05:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-10d1a1c1b91e11cf', '100001', 'news-category-finance-flash', 'em-202611213936840844-640e131e35', '泽连斯基称乌欧美俄四方会谈时间取决于美方协调', '当地时间11月21日，乌克兰总统泽连斯基在会晤英国国防大臣斯特里廷时表示，下一轮乌克兰、美国、欧洲、俄罗斯四方会谈的举办时间与形式，取决于美方和各方就会议议程协调一致的进度。他称，“美方会尽力推动会谈尽快举行，但预计俄方可能采取行动拖延会议”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T12:00:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ea907482d08653a9', '100001', 'news-category-finance-flash', 'em-202611213936836510-f460274bf6', '青海德令哈发生5.6级地震 初步排查未发现人员伤亡和房屋倒塌事件', '11月21日，德令哈市融媒体中心发布情况通报：11月21日18时45分在青海海西州德令哈市发生5.6级地震，震源深度10公里，震中位于北纬37.14度，东经96.62度。', 'published', NULL, FALSE, 100, 1, '2026-11-21T11:40:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b9dc8e0f26113ecb', '100001', 'news-category-finance-flash', 'em-202611213936833814-d4e504979f', '唐人神：生猪出栏规划会结合市场行情等因素动态优化', '唐人神在投资者关系活动中表示，公司将积极响应国家生猪产能调控相关政策导向，在现有产能下做好自身生产经营，公司生猪出栏规划会结合市场行情、生物安全、现金流等因素动态优化，持续夯实生产稳定性、聚焦提质增效。', 'published', NULL, FALSE, 100, 1, '2026-11-21T10:57:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-12ee02a6277f1555', '100001', 'news-category-finance-flash', 'em-202611213936833194-3ffc01c004', '俄方称克里米亚大桥铁路运输已全面恢复', '总台记者11月21日从俄罗斯方面获悉，俄罗斯副总理尼基京称，克里米亚大桥铁路运输已全面恢复。', 'published', NULL, FALSE, 100, 1, '2026-11-21T10:52:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6dcc7d27ce2bdb9b', '100001', 'news-category-finance-flash', 'em-202611213936832560-cc581561a7', '青海海西州德令哈市附近发生5.7级左右地震', '中国地震台网自动测定：11月21日18时45分在青海海西州德令哈市附近（北纬37.14度，东经96.59度）发生5.7级左右地震，最终结果以正式速报为准。', 'published', NULL, FALSE, 100, 1, '2026-11-21T10:49:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c479e7493460caaa', '100001', 'news-category-finance-flash', 'em-202611213936832424-f3dbdabcc9', '特朗普批美联储利率太高 美联储主席陷两难', '当地时间20日，美国总统特朗普再度批评美联储，称当前利率水平过高，美联储的决策带有“政治属性”。不过，他说自己的这一表态并不是在责怪美联储主席凯文·沃什。', 'published', NULL, FALSE, 100, 1, '2026-11-21T10:47:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b8a58e82cd1b8d42', '100001', 'news-category-finance-flash', 'em-202611213936831961-bd3f50acea', '伊朗革命卫队称击落第19架美军MQ-1型无人机', '伊朗伊斯兰革命卫队11月21日在社交媒体上说，革命卫队当天在格什姆岛上空击落一架美军MQ-1型无人机。这是伊方击落的第19架美军该型无人机。', 'published', NULL, FALSE, 100, 1, '2026-11-21T10:32:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-995c33108e43fa47', '100001', 'news-category-finance-flash', 'em-202611213936831055-5835a68fb6', '国科微亮相世界计算大会 展示新一代端侧AI NPU', '据国科微消息，11月19日，2026世界计算大会在长沙开幕。国科微以“构建端侧AI芯引擎”为主题亮相，集中展示全系端侧AI芯片、AI算法及端侧应用成果。', 'published', NULL, FALSE, 100, 1, '2026-11-21T10:18:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f536158835ee7a13', '100001', 'news-category-finance-flash', 'em-202611213936830581-b299457060', '两艘油轮接连在驶出霍尔木兹海峡时遇袭', '根据英国海上贸易行动办公室21日发布的通报，两艘油轮当天接连在驶出霍尔木兹海峡时被不明抛射物击中。', 'published', NULL, FALSE, 100, 1, '2026-11-21T09:57:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-854d3ca1931ea725', '100001', 'news-category-finance-flash', 'em-202611213936830029-2b2cf54b48', '印尼马鲁古省附近海域发生7.2级地震', '据印尼气象、气候和地球物理局发布的报告，当地时间11月21日16时42分，印尼马鲁古省东北43公里海域发生7.2级地震，震源深度125公里。', 'published', NULL, FALSE, 100, 1, '2026-11-21T09:55:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d150a73bc279ab19', '100001', 'news-category-finance-flash', 'em-202611213936829549-e80533e2c7', '重庆发布86项低空产业发展机会清单 总投资约289亿元', '11月21日下午，重庆国际人才交流大会·超大城市低空综合治理产业人才发展大会在重庆举行。大会发布低空产业发展机会清单86项，预计总投资约289亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T09:52:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ba0724f8ef9d1a0c', '100001', 'news-category-finance-flash', 'em-202611213936828363-f998858d6b', '长高电气：四季度交付速度有一定回升', '长高电气(002452)近日接受机构调研时表示，从公司旗下几家主要输变电设备子公司的发货排产计划，结合10月、11月实际交付情况来看，四季度交付速度有一定回升，前期部分延后交付的订单开始陆续安排交付或排产。', 'published', NULL, FALSE, 100, 1, '2026-11-21T09:24:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1c615234cb316de1', '100001', 'news-category-finance-flash', 'em-202611213936827317-dc224b4f25', '国家数据局：积极拓展词元服务应用场景 健全词元计量计费、质量测评等标准规范', '2026年11月20日，国家数据局党组书记、局长刘烈宏出席在湖南长沙举办的2026世界计算大会开幕式并致辞。', 'published', NULL, FALSE, 100, 1, '2026-11-21T08:45:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b92339a9790f5fbc', '100001', 'news-category-finance-flash', 'em-202611213936825789-8d6ca11e0d', '国家电网公司自主研制首套静止全功率发生器投运', '据国家电网消息，11月20日，国家电网有限公司自主研制的世界首套35千伏/30兆伏安IGBT串联型静止全功率发生器（SPG），经过短路试验后168小时试运行，在陕西延安330千伏方河变电站正式投运。', 'published', NULL, FALSE, 100, 1, '2026-11-21T08:23:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6697ed066b179f89', '100001', 'news-category-finance-flash', 'em-202611213936825459-3130d4d38e', '长高电气：中低压产品毛利率预计在第四季度将有所修复', '11月21日，长高电气在投资者关系活动中表示，前三季度公司综合毛利率40.88%，同比提升1.47个百分点。高压类产品毛利率稳中有升，中低压产品毛利率同比出现较大幅度下降。', 'published', NULL, FALSE, 100, 1, '2026-11-21T08:21:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b101945f07d3a03e', '100001', 'news-category-finance-flash', 'em-202611213936825378-524e1151f8', '蓝佛安出席亚洲基础设施投资银行香港办公室协定签署仪式', '11月21日，亚洲基础设施投资银行香港办公室协定签署仪式在香港举行。财政部部长蓝佛安出席并代表中国政府与亚投行行长邹加怡共同签署协定。', 'published', NULL, FALSE, 100, 1, '2026-11-21T08:19:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f69bfa43ee12aaec', '100001', 'news-category-finance-flash', 'em-202611213936822536-83d48f4806', '又有美法官叫停华盛顿“凯旋门”项目动工', '美国一名联邦地区法官20日发布禁令，在诉讼审理期间阻止特朗普政府在首都华盛顿动工建造“凯旋门”。此前，已有另一名联邦地区法官针对该项目发布临时限制令并延长至12月3日。', 'published', NULL, FALSE, 100, 1, '2026-11-21T08:10:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0fd4f94ead82cb87', '100001', 'news-category-finance-flash', 'em-202611213936821035-31bbceaf8e', '中国通号：国内首款4.9GHz无蜂窝基站获证商用', '据中国通号消息，中国通号所属低空公司自主研发的4.9GHz无蜂窝移动通信基站，正式取得工业和信息化部颁发的电信设备进网许可证，成为国内首款获证的4.9GHz无蜂窝移动通信基站。', 'published', NULL, FALSE, 100, 1, '2026-11-21T08:01:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c9a72fcb898b7b2d', '100001', 'news-category-finance-flash', 'em-202611213936820971-44088bbe1e', '伊朗外长：伊方仍愿通过外交途径解决与美国的争端', '据《伊朗报》21日报道，伊朗外交部长阿拉格齐近日在接受该报专访时表示，伊朗仍希望通过外交途径解决与美国之间的争端。只要伊朗的要求在谈判中得到满足，“霍尔木兹海峡就会开放”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:56:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-16d410c4f031ab78', '100001', 'news-category-finance-flash', 'em-202611213936820885-f4f4445316', '国产120kV冷冻透射电子显微镜发布', '11月21日，国产120kV冷冻透射电子显微镜TH-F120C在广州发布，这是我国推进高端科学仪器自主可控的一项突破，将为科研人员提供解析生物大分子结构、研究先进材料微观特性的重要工具。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:54:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7d6c9907130b7c12', '100001', 'news-category-finance-flash', 'em-202611213936820711-37be600021', '南水北调“天河”大模型完成升级', '今天（21日）记者从中国南水北调集团了解到，全新升级的南水北调“天河”大模型V2发布。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:49:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c085f8f4989e787b', '100001', 'news-category-finance-flash', 'em-202611213936820552-71c460026c', '中国驻沙特使馆再次提醒在沙特中资机构和中国公民注意安全', '11月21日，中国驻沙特大使馆发文表示，近来，沙特首都利雅得等多地频繁遭导弹和无人机袭击。据媒体报道，部分袭击造成人员伤亡，有机场、建筑物、能源电力设施等受损，局部地区出现短时停水电断网等情况。多地学校继续线上授课，部分当地机构和企业人员居家办公。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:45:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4bfa6986a3dbe325', '100001', 'news-category-finance-flash', 'em-202611213936820343-6103c1aefc', '享界V8开启全国大规模交付', '11月21日，鸿蒙智行享界MPV车型享界V8全国18城同步开启大规模交付，该车昨日正式上市，全系搭载华为乾崑智驾ADS5，标配800V高压纯电/增程双平台，售价31.98万元起。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:39:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6d00d5f096ded2c8', '100001', 'news-category-finance-flash', 'em-202611213936820424-3f805a782d', '刘洪建、杨承新与中国中铁任鸿鹏一行座谈', '据“昆明发布”，11月20日，昆明市委书记刘洪建，市委副书记、市长杨承新与中国中铁股份有限公司党委常委、副总裁任鸿鹏一行座谈。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:39:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8b5284e74a3c8f5f', '100001', 'news-category-finance-flash', 'em-202611213936819970-4b44696082', '伊朗外交部长：浓缩铀不会被运出伊朗境外', '伊朗外交部长阿拉格齐当地时间今天（11月21日）在社交媒体发文表示，伊斯兰堡谅解备忘录已经失去了实际意义，伊朗提出的两日计划或许将为达成协议铺平道路。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:34:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-445bfeade6dcbc13', '100001', 'news-category-finance-flash', 'em-202611213936819887-d88ac22d9a', '中国铜业100亿元小公募债申报获上交所受理', '上交所公司债券项目信息平台显示，中国铜业有限公司100亿元小公募债项目状态更新为“已受理”，受理日期为2026年11月20日。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:32:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a93840d78e2044eb', '100001', 'news-category-finance-flash', 'em-202611213936819297-3d030155c7', '上海电气：与马来西亚国家能源公司深化东南亚市场绿色低碳合作', '上海电气消息，11月20日下午，上海电气集团党委副书记、总裁朱兆开与到访的马来西亚国家能源公司（TenagaNasionalBerhad，简称“TNB”）总裁兼首席执行官沙姆苏勒·本·艾哈迈德举行会谈，双方围绕东南亚市场机遇、绿色低碳产业发展、深化全方位合作深入交流。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:14:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c4f92eb3291ce4d', '100001', 'news-category-finance-flash', 'em-202611213936819048-0be4c1d6c3', '上海电气与上海电力深化战略对接', '据上海电气消息，11月20日下午，上海电气集团党委书记、董事长吴磊拜访上海电力股份有限公司（简称“上海电力”），与上海电力党委书记、董事长黄晨举行会谈，围绕深化产业协同、加快能源绿色低碳转型、服务新型电力系统建设等议题深入交流。', 'published', NULL, FALSE, 100, 1, '2026-11-21T07:00:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d7e52d1a4d6509ce', '100001', 'news-category-finance-flash', 'em-202611213936819159-0babfe6362', '《GTA6》带动PS5价格持续上涨，Pro版本涨至1.6万元', '《侠盗猎车手6》（GTA6）带动PS5价格持续上涨。目前PS5Pro的价格仍在进一步走高。截至发稿，天猫自营国行PS5Pro数字版报价11499元，港版报价15999元。得物App上，国行数字版报价8899元，港版报价12056元。多个平台的报价相比《GTA6》发售当天，普遍上涨1000至2000元。也就是说，想在自己家里用上能增强GTA6画面的PS5Pro，实际支出普遍在8000元以上，港版现货甚至涨至1.6万元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:59:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c9ab50e1d5b40c8c', '100001', 'news-category-finance-flash', 'em-202611213936818528-f76278191f', '西安举行光子产业投资对接会', '11月20日，第11期中科创星·硬科技冠军营（西安站）暨光子产业投资对接会在陕西西安举行。本次活动以“汇光成炬星耀新程”为主题，汇聚来自光子、新材料、生物医药、航空航天等前沿领域的70位全国硬科技企业创业者，搭建政府部门、本地链主龙头、科研中试平台、投资机构与科创企业多方对接的平台。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:57:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-941a0e2d6413a285', '100001', 'news-category-finance-flash', 'em-202611213936818681-9c893d00d3', '上海电气与上海电力深化战略对接', '据上海电气消息，11月20日下午，上海电气集团党委书记、董事长吴磊拜访上海电力股份有限公司（简称“上海电力”），与上海电力党委书记、董事长黄晨举行会谈，围绕深化产业协同、加快能源绿色低碳转型、服务新型电力系统建设等议题深入交流。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:56:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-80702b7ea0b4f3a2', '100001', 'news-category-finance-flash', 'em-202611213936817847-24809fc41e', '韩国总统李在明访问蔚山SK人工智能数据中心，称速度是全球竞争的关键', '11月21日首尔经济报消息，韩国总统李在明视察蔚山SK AI数据中心施工现场。李在明指出全球竞争中速度至关重要，“速度关乎生死存亡”。他希望该项目成功实施能发挥示范作用，吸引全球AI企业追加投资，并强调AI数据中心是支撑实体AI的核心基础设施，“AI高速公路”将为国家迈向AI时代铺平道路。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:49:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-19445bcedaabfe87', '100001', 'news-category-finance-flash', 'em-202611213936816872-594fbb54a5', '新指数ETF产品密集上报 覆盖半导体、算力与航运等领域', '11月20日，证监会网站显示，多家基金管理人上报科创创业半导体ETF、沪深港算力ETF、中证航运ETF三条新指数ETF产品。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:39:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7fb2ce5007c9a535', '100001', 'news-category-finance-flash', 'em-202611213936816963-761136d6ca', '中信建投食品饮料2027年投资策略：周期底部范式重构 红利守正成长出奇', '中信建投证券发布食品饮料2027年投资策略报告称，食饮选股新范式：优先选择自由现金流稳定、分红率与股息率可验证、位居行业龙头且格局稳定、管理层有明确的股东回报动作（回购注销、承诺分红）的公司。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:36:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-58ec1568c6d27c8c', '100001', 'news-category-finance-flash', 'em-202611213936816689-18c8b3754f', '商业银行总资产突破500万亿元！金融监管总局最新发布！', '11月20日，金融监管总局发布最新监管指标数据显示，商业银行净息差继续呈现筑底态势。截至今年三季度末，行业净息差为1.41%，较上季度末略有回升；自2025年一季度以来，净息差已连续多个季度保持在1.4%附近。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:30:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d8d567c8b3b8bc79', '100001', 'news-category-finance-flash', 'em-202611213936816771-22268bc4ce', '人力资源服务方向国家人工智能应用中试基地在渝揭牌', '在21日举行的重庆国际人才交流大会开幕式上，国家人工智能应用中试基地（人力资源服务方向）正式揭牌，将推动人力资源服务行业数智化转型升级。据介绍，该基地规划建设1套算力底座、1个行业大模型、27个高质量数据集、1套运营服务体系，通过“技术研发—场景验证—成果转化”全周期赋能，打通人力资源服务业人工智能落地“最后一公里”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:29:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-17188344924ceec7', '100001', 'news-category-finance-flash', 'em-202611213936815839-ea0c8b27d9', '黄仁勋要重新创业？一则“预测”搅动硅谷', '黄仁勋要重新创业了？过去几天，这则传闻在硅谷持续发酵。引爆点并非来自英伟达（NVDA.US）官方，也非黄仁勋本人，而是Semafor记者Rohan Goswami在节目中的一番个人预测。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:20:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-50a7496beaea0b73', '100001', 'news-category-finance-flash', 'em-202611213936816036-dcba43ac61', '托普云农发布智能（AI）虫情测报灯9.0', '据托普云农消息，11月21日，第四十届中国植保信息交流暨农药械交易会在成都开幕，托普云农智能（AI）虫情测报灯9.0在现场首发亮相。作为新一代智能测报装备，一台9.0测报灯集成虫情测报站、气象站、无人机自动巡检站、作物长势分析、AI算法识别与智能大脑六大模块，并创新性内嵌农业AI智能体“问稷”，一台设备同时具备地面测报、环境感知、低空巡检与智能分析能力。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:20:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7f8db686555ff51c', '100001', 'news-category-finance-flash', 'em-202611213936814623-fec0f77ba7', '造船短期产能紧俏订单基本排至2030年 绿色转型受成本与国际规则掣肘', '记者近日采访获悉，不少业内人士认为，短时间内船厂船位仍处于稀缺状态，头部船厂基本排期至2030年，产能变化带来的影响仍需关注2028年后订单需求情况。此外，MEPC 85会议召开在即，IMO净零排放框架或仍难通过，对船舶绿色转型节奏、路径有所影响，但绿色船舶的溢价依然存在。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:10:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1421520a1ce30566', '100001', 'news-category-finance-flash', 'em-202611213936812946-bbade4451d', '突然集体拉升！两则好消息传来', '周五恐慌性抛售过后，市场情绪出现修复迹象。盘后，英伟达、英特尔、超威半导体（AMD）、应用材料、Coherent、CoreWeave、NEBIUS等涨超3%；美光科技、Arm、博通、高通、闪迪、康宁、希捷科技、迈威尔科技、甲骨文等涨超2%。大型科技股方面，特斯拉、亚马逊、微软、Meta、谷歌、SpaceX等涨超1%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T06:01:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-322b56b05e7f1e6a', '100001', 'news-category-finance-flash', 'em-202611213936812896-d82f23db8c', '沙特主导的多国联军称拦截并摧毁3枚弹道导弹', '当地时间11月21日，沙特主导的多国联军发言人表示，联军防空部队拦截并摧毁了也门胡塞武装向沙特首都利雅得发射的3枚弹道导弹。当天凌晨，沙特首都利雅得居民收到经由手机程序发布的防空警报。联军方面表示，防空部队还拦截并摧毁了胡塞武装向沙特南部地区发射的一架无人机。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:55:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-de60f80b9c2e4119', '100001', 'news-category-finance-flash', 'em-202611213936812021-aa44a518a4', '重磅预警！高盛“恐慌指数”逼近最大值：美股下周恐还有一波大规模抛售', '据高盛集团交易员称，随着美国股市周五暴跌，高盛集团的“恐慌指数”攀升至接近最高水平，这表明未来一周将出现另一波大规模抛售。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:50:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-66b1c44e65fd7850', '100001', 'news-category-finance-flash', 'em-202611213936811662-7306b4c4cf', '受理加速两日三家！香雪制药、瑞和股份、西安旅游启动重整 年内总计6单获受理', '11月19日，香雪制药公告，法院裁定受理债权人对公司的重整申请；11月20日，瑞和股份、西安旅游双双公告，法院裁定受理公司重整。至此，2026年年内，共有6家公司重整获受理。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:48:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7433234536994cd7', '100001', 'news-category-finance-flash', 'em-202611213936811990-c6b2fd8eea', '合肥市委书记覃卫国与迈瑞医疗董事长李西廷举行工作会谈并见证签约', '据合肥日报，11月20日下午，合肥市委书记覃卫国与迈瑞医疗董事长李西廷一行举行工作会谈。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:44:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ce91996c5afe5889', '100001', 'news-category-finance-flash', 'em-202611213936810927-500bddfe5d', '达里奥2010年曾拒绝马斯克招揽 2016年加入OpenAI后又出走创立Anthropic', '据《华尔街日报》今日报道，Anthropic CEO 达里奥 · 阿莫代伊（Dario Amodei）早在 2010 年就曾通过熟人结识埃隆 · 马斯克并受邀参观 SpaceX 办公室。据称，马斯克当时还向他发出了工作邀请，但达里奥最终选择拒绝。他认为自己的专业能力更适合计算生物学，而不是火箭工程。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:38:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-73cc7714901fea9e', '100001', 'news-category-finance-flash', 'em-202611213936810316-d4be3ad893', '美新科技：子公司星曜宇航已启动4米级舱段生产', '11月20日，美新科技在接待机构调研时表示，子公司四川星曜宇航航天科技有限公司成立于2026年2月，是一家专注于商业航天运载火箭全箭结构件的专业化企业。公司构建了火箭结构件集产品研发、工艺设计、精密加工、特种焊接、试验验证及批量交付于一体的全链条研制体系，可形成从设计输入、工艺实现到批产交付的闭环能力，力争成为是国内商业航天产业链的重要配套制造商。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:35:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dff54f87f24d9c0c', '100001', 'news-category-finance-flash', 'em-202611213936807957-545b2ab01d', '涉嫌违规！顺丰速运、八马茶业被暂停全军采购参与资格', '11月21日，军队采购网发布军队采购暂停名单，顺丰速运有限公司、八马茶业股份有限公司因涉嫌违规，被暂停参加全军物资、工程和服务采购活动，处理部门为军委后勤保障部采购服务中心，处理日期为11月19日。公告未披露具体违规事由与暂停期限。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:34:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-60aae6abf747aecd', '100001', 'news-category-finance-flash', 'em-202611213936809736-a7a714dee1', '黄仁勋没有的“护身符”：Anthropic 创始人手握 50.1% 投票权建立“反夺权”机制', '科技媒体 Business Insider 昨日（11 月 20 日）报道，AI 公司 Anthropic 在上市后通过特殊股权设计，让包括 CEO 达里奥 · 阿莫代伊（Dario Amodei）在内的 7 位联合创始人共同掌握 50.1% 的股东投票权。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:33:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-53b7f442f85b480e', '100001', 'news-category-finance-flash', 'em-202611213936809377-8f14334213', '银轮股份：大型板换产线预计12月正式投产', '银轮股份11月21日在互动平台表示，公司大型板换产线预计12月份正式投产。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:31:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-986e80704ca42826', '100001', 'news-category-finance-flash', 'em-202611213936809078-4c218ba225', '中信重工与汇川技术发布国产工业操作系统与中大型PLC深度适配联合行动', '据中信重工消息，近日，在上海举办的2026年工业操作系统大会召开期间有色矿山行业工业操作系统创新应用论坛成功举办，在论坛上中信重工与汇川技术共同发布国产工业操作系统与中大型PLC深度适配联合行动。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:29:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3715b8e043187eee', '100001', 'news-category-finance-flash', 'em-202611213936808026-90b0c300aa', '宜涪高铁大石坝隧道顺利贯通', '记者从长江沿岸铁路集团重庆有限公司获悉，11月21日，沿江高铁宜昌至涪陵段重庆段大石坝隧道顺利贯通，这是宜涪高铁重庆段首座贯通的中长隧道，为全线按期通车奠定了坚实基础。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:26:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9935c8464be55ed5', '100001', 'news-category-finance-flash', 'em-202611213936807635-17f2ed9a81', '中国银联与Visa深化三大领域合作', '中国银联与Visa近日宣布，双方将秉持开放合作、互利共赢、安全可控、合规稳健的原则，在三大领域展开深度合作，包括两大全球支付网络“一点对接”互联互通的网络对网络合作，共同优化境外人士来华支付服务，以及AI时代的智能支付。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:20:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a37f22922c0300b2', '100001', 'news-category-finance-flash', 'em-202611213936807219-65d608b6ae', '国铁集团与中国石油“总对总”战略合作对接活动举办', '据国铁集团消息，11月19日至20日，中国国家铁路集团有限公司与中国石油天然气集团有限公司“总对总”战略合作专场对接活动在兰州举行。中国石油总部部门、专业公司及油气田、炼化、成品油销售、装备制造等41家相关企业，与国铁集团有关部门，18个铁路局集团公司、3个专业运输公司近200人共同参加活动。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:12:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c590d82b111d9c2a', '100001', 'news-category-finance-flash', 'em-202611213936805855-17507b8755', '魏建军考察胖东来 此前于东来购买310辆坦克700奖励员工', '11月21日清晨，长城汽车董事长魏建军在个人社交账号发布视频，宣布当天赴许昌考察学习胖东来。按行程，他将先后参观正在建设中的胖东来“梦之城”、天使购物中心，并走进胖东来物流中心和中央厨房，与于东来及管理团队进行深度交流。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:07:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b3f058398f9d2635', '100001', 'news-category-finance-flash', 'em-202611213936805745-b3da239c47', '英伟达被查！', '据外媒11月20日报道，美国证券交易委员会（SEC）正在对英伟达潜在会计问题展开调查。这一消息进一步加剧英伟达投资者的担忧情绪，英伟达股价当天跌超14%，报125.5美元，较10月高点243.4美元跌超48%，接近腰斩。', 'published', NULL, FALSE, 100, 1, '2026-11-21T05:04:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2431bcf8d27b5916', '100001', 'news-category-finance-flash', 'em-202611213936805394-179acbbaf6', '第三季度财报里的AI：钱花出去了 收入跟上了吗？', '11月17日至19日，京东、腾讯、快手、拼多多、阿里巴巴相继交出2026年第三季度财报。若以更能反映主营业务经营趋势的经调整净利润（Non-GAAP）口径来看，本季度阿里巴巴经调整净利润同比增长92%，京东非公认会计准则净利润增长44%，拼多多经调整净利润微降约1.2%，腾讯调整后净利润下滑6%，快手经调整净利润下滑84%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:59:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-911ad117c91369a2', '100001', 'news-category-finance-flash', 'em-202611213936804748-9aab519a92', '沐曦股份曦云C系列GPU率先完成腾讯混元Hy4 Day 0适配', '据沐曦股份消息，11月20日，腾讯混元正式开源Hy4。沐曦股份旗下曦云C系列GPU率先完成Hy4的Day0适配。目前，Hy4在曦云C系列GPU平台上实现高吞吐、低延迟的稳定运行，并在复杂任务与长序列场景下保持优异表现。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:49:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f547d3accce03001', '100001', 'news-category-finance-flash', 'em-202611213936804098-0669f28f88', '金价会跌破3500吗？专家：活下来比猜对金价何时见底更重要', '银河期货贵金属研究员袁正认为，贵金属在美国就业数据恶化、通胀数据走弱等宏观指标信号出现之前，预计仍将对紧缩宏观环境进行交易，明年一季度后或成为观察窗口期。袁正指出，对于普通投资者而言，今年贵金属定价重返宏观货币政策定价逻辑后，在当前黄金的运行格局中，活下来远比猜对更重要，仓位管理决定了投资者能否跨越波动、等到趋势重新明朗的那一刻。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:38:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cf13c20fcf33dbe8', '100001', 'news-category-finance-flash', 'em-202611213936804282-3f897adbb4', '亿纬锂能刘金成：锂电池消费税落地后会有相当一部分企业退出市场', '在今日进行的第十一届动力电池应用国际峰会上，亿纬锂能董事长刘金成表示，锂电消费税落地后，会有相当一部分企业将退出市场。他援引统计数据称，在铅酸电池增收10%消费税后，行业内90%的铅酸企业退出。以此类推，三年之内，锂电池行业中相当一部分企业也将不得不退出市场，这也会给行业发展带来不确定性，2027年一季度将是行业的过渡期。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:36:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-358d9fb8e0e202f0', '100001', 'news-category-finance-flash', 'em-202611213936804134-832f1bd8e7', '赣锋锂电肖海燕：海外上游合规成本系统性上升 锂资源行业进入“政策定价”时代', '在今日进行的第十一届动力电池应用国际峰会上，赣锋锂电总裁肖海燕表示，全球锂资源多元化分布，面对资源国“锁矿”的情形，行业已经进入“政策定价”时代，成本曲线受制于政策曲线。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:36:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cd647b4c81bc91c9', '100001', 'news-category-finance-flash', 'em-202611213936804358-094b91d45f', '中信证券：AI巨头融资布局“东进”，亚太本币信用市场迎来新格局', '11月21日，中信证券最新研报指出，海外AI科技巨头多币种融资版图正在加速拓展，2026年11月19日，巨头之一的Alphabet首度发行港元债及新加坡元债，标志AI科技巨头对亚太本币信用市场布局的进一步深化。除融资成本与渠道多元化的考量外，近年来亚太本币信用市场在持续扩容，长期融资承接能力不断提升，随着跨境融资配套基础设施日益完善，为科技巨头加速布局亚太市场提供了有力支撑。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:35:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6689c9a11f79d7a2', '100001', 'news-category-finance-flash', 'em-202611213936803816-c05b3e81f2', '中信证券：预计全国性机制电价政策有望在2027年推出', '11月21日，中信证券最新研报指出，随着沿海电价重回上涨，核电的周期性电价下降风险已经消除；火电容量电价推出后，核电面临结构性电价下降冲击，通过政策保障以应对该冲击极具必要性和可行性。考虑试点省市运行效果良好，中信证券预计全国性机制电价政策有望在2027年推出；2027~2028年，预计机制电价推出将提振核电公司业绩幅度约4%-6%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:33:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-33b706e4deb4045a', '100001', 'news-category-finance-flash', 'em-202611213936803375-73c1d36c55', '高股息指数防“虚胖”：上证红利、中证红利等将引入可投资权重上限', '11月20日，中证指数有限公司官网发布多则公告，对上证红利指数及中证红利低波动指数等偏红利、高股息指数的编制方案进行修订。其中最明显的变化，就是引入流动性约束。权重上限规则调整为“单个样本权重不超过10%及其可投资权重上限，其中可投资权重上限为该样本在指数中总市值占比8倍、近3个月日均成交额占比4倍的孰低值”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:31:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-adf404d42b4339fc', '100001', 'news-category-finance-flash', 'em-202611213936803293-838a5dffe5', '短剧和AI冲击游戏？网易管理层：游戏核心竞争力不受影响', '在网易第三季度财报电话会议上，管理层被问及短剧和AI对游戏行业的影响。管理层表示，尽管短剧在短期内吸引了较高的用户关注度，但游戏基于“控制与反馈”的核心玩法依然具备不可替代的优势。AI技术将为游戏行业带来更广阔的想象空间，让过去难以实现的创意玩法（如互动影游）成为可能，推动游戏内容向更多元、更高质量的方向创新发展。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:25:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dfe28c6308624f76', '100001', 'news-category-finance-flash', 'em-202611213936803118-3d9a0ca53e', '黄金跌破3550美元！分析师：或承压至明年', '专家认为，对于贵金属市场而言，后续核心变量仍是中东局势。若美伊、红海方向持续扰动，黄金大概率承压至明年中旬。不过过程中仍存在不确定性。2027年民主党正式接管国会后，特朗普施政可能受阻，这将会给多头留出一定发挥空间。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:19:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c3438454f55fdfe7', '100001', 'news-category-finance-flash', 'em-202611213936799341-64d6b7c406', '比特币跌至两年多低点 风险资产抛售加剧下行压力', '比特币日内下跌6%，跌破56000美元，创2024年9月以来新低。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:07:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7abc1e3c69aec380', '100001', 'news-category-finance-flash', 'em-202611213936799281-33ffc058b0', '东方港湾：中国股市值得更强信心', '深圳东方港湾投资管理股份有限公司表示，以长期价值投资理念来看今天的中国股市，我们应该给予更多的信心。这份信心，既来自于中国经济长期的发展态势，和中国企业的全球竞争力不断提高，也来自上市公司正在切实发生的变化：科技与先进制造在盈利中的分量加重，企业在全球市场打开了成长空间，股东获得的现金回报也在增加。此时此刻，评估中国股市的投资价值，应当充分看到这些进步。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:06:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c6981db3a34d0588', '100001', 'news-category-finance-flash', 'em-202611213936798920-bcfaad2cbe', '多地上演“豪宅热”：上海再现“日光盘” 杭州有项目连签亿元大单 专家称“市场尚未筑底”', '近期，一出出“豪宅大戏”正在全国多个城市上演。在上海，有高端项目认购率超600%，开盘再现“日光”盛况；在杭州，有叠墅项目首开一周签下三笔亿元级大单；在深圳，有顶层公寓入市，备案单价突破43万元/m2，刷新深圳住宅备案单价纪录。不过，整体来看，重点城市高端住宅成交仍呈下行趋势。', 'published', NULL, FALSE, 100, 1, '2026-11-21T04:02:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a4ce24a709bcb286', '100001', 'news-category-finance-flash', 'em-202611213936798811-e9b4ba06af', '阿根廷政府批准该国规模最大投资项目', '阿根廷政府11月20日宣布批准将一个液化天然气项目纳入大型投资激励计划。阿根廷经济部长路易斯·卡普托在社交媒体上说，这是该国历史上规模最大的投资项目，到2050年累计投资额将达约507亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:57:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7545cf594e7bfd07', '100001', 'news-category-finance-flash', 'em-202611213936798760-cb62b508cb', '元气森林唐彬森：今年外星人电解质水与好自在产品线均实现双位数增长', '11月20日，元气森林2026年度全国经销商大会在珠海举行。元气森林创始人唐彬森在主题演讲中表示，2026年是公司“做减法、实现增长”的一年。他介绍，外星人电解质水与好自在两条产品线均实现双位数增长。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:53:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8c273eb7036c8322', '100001', 'news-category-finance-flash', 'em-202611213936798685-1ddfe5e646', '国家发展改革委召开视频会议调度督促政府投资资金支付使用和项目储备工作', '11月20日，国家发展改革委召开政府投资资金支付使用和项目储备工作视频会议，委党组成员、副主任岳修虎同志出席并讲话。会议通报了各地政府投资资金支付使用和重大项目储备工作情况，浙江、河南、广东、黑龙江、安徽、陕西等6省发展改革委负责同志作了交流发言。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:49:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3a3476a72c51c87d', '100001', 'news-category-finance-flash', 'em-202611213936798456-daf18e2f20', '比特币跌破57000美元', '比特币跌破57000美元，日内跌超4%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:38:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aa9e495e0ecc393a', '100001', 'news-category-finance-flash', 'em-202611213936798343-9e96e5da64', '俄称乌克兰加入北约完全不可接受', '据俄新社报道，俄罗斯外交部副部长里亚布科夫11月20日表示，乌克兰加入北约对俄方而言“完全不可接受”，为乌方谋求“准成员国”地位或寻找某种“创造性解决方案”也不会被俄方接受。里亚布科夫表示，鉴于欧盟“日益咄咄逼人”的姿态、鲜明的反俄路线以及持续军事化，俄方认为，欧盟与北约之间“没有多大差别”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:35:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0c4c0e5ecaf65220', '100001', 'news-category-finance-flash', 'em-202611213936798275-674726fed2', '源杰科技独家直投芯钬量子A++轮融资', '11月20日晚，上海芯钬量子科技有限公司宣布完成A++轮融资，由源杰科技独家直投。此前，公司天使轮、A轮及A+轮分别由慧眼资本、京东方显智链和交银资本投资。本轮融资后，芯钬量子将围绕工业AI与多物理场仿真能力的深度融合持续加大投入。芯钬量子表示，未来还将探索量子计算、超导、光子芯片、自旋电子及拓扑物态等前沿领域的应用需求。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:35:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3ce6bc5ea0ba5d76', '100001', 'news-category-finance-flash', 'em-202611213936799917-24df9fc1a0', '华为星芒品牌总经理回应O1 PRO定价争议：努力贴近4999', '11月21日凌晨，华为OSTA星芒品牌总经理刘赫公布O1PRO首销进展：16G版本已在全平台售罄，远超预期，12G版本仅部分门店和平台合作伙伴有现货，目前正在全力以赴协调产能和版本生产弹性。针对定价争议，刘赫回应称：“星芒要便宜还是星芒要创新，我们选择创新优先。”他也表示，在努力贴近4999这个国补后的价格，这一点导致其高配备货过于谨慎。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:28:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-564e2dc5ef2df926', '100001', 'news-category-finance-flash', 'em-202611213936797338-48b51c4a87', '产业规模破万亿元！高铁直达、夜场升级 冰雪消费提前升温', '新一轮冰雪季开启，我国冰雪消费呈现出不少新变化：秋假带动亲子冰雪游提前升温，南方游客持续涌入北方雪场，冰雪产业规模突破万亿元。冰雪游正从季节性运动体验，向亲子研学、休闲度假和综合消费延伸，为冬季文旅市场注入新活力。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:23:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3ca92f002f3fdb38', '100001', 'news-category-finance-flash', 'em-202611213936794355-2564d049c7', '美国今年麻疹确诊病例已超5800例', '美国疾病控制和预防中心20日公布的最新数据显示，截至19日，美国今年累计报告麻疹确诊病例5838例，且病例数持续上升。数据显示，今年以来，美国47个州和地区共报告5820例麻疹病例，另有18例为赴美国际访客。目前，已有646名患者住院治疗，约占确诊病例总数的11%。约96%的确诊病例未接种过麻疹疫苗或接种情况不明。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:16:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2aec61ebb81d896d', '100001', 'news-category-finance-flash', 'em-202611213936793646-392465a2bd', '中际旭创：光模块行业需求仍然强劲 订单能见度延伸至2028年', '中际旭创股份有限公司近期披露，当前行业需求依然强劲，公司主要客户订单已基本覆盖2027年全年，目前已有至少一家重点客户给出2028年明确需求指引，且需求强劲，其他客户的需求指引仍在持续收集中，预计公司800G、1.6T产品订单需求仍将保持快速增长。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:14:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8f33f6aa88352a5a', '100001', 'news-category-finance-flash', 'em-202611213936793192-dd6b5c0b7a', '美财长称仍居住在军事基地', '美国财政部长贝森特20日称，他依然面临来自伊朗方面的安全“威胁”，因此目前仍居住在军事基地里。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:04:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d152a1ccfd133d7d', '100001', 'news-category-finance-flash', 'em-202611213936793396-873a87a33a', '伊朗称击落第58架美军“死神”无人机', '伊朗伊斯兰革命卫队公共关系部门11月21日在社交媒体上说，一架美军MQ-9型“死神”无人机当天在霍尔木兹海峡上空被伊斯兰革命卫队新型防空系统拦截并击落。这是伊方击落的第58架美军“死神”无人机。根据所搭载的传感器和武器不同类型，一架MQ-9型“死神”无人机的造价在3000万美元至5000万美元之间。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:01:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-56f18d139ed112a4', '100001', 'news-category-finance-flash', 'em-202611213936793282-3c04ac7bb5', '2026脑机接口十五项标志性成果发布', '今日，在2026脑机接口大会上，十五项脑机接口标志性创新成果对外发布，主要包括芯智达“北脑一号”智能脑机系统、中电云脑非侵入式高精度脑电采集计算芯片、品驰医疗植入式脑机接口神经刺激器、阶梯医疗无线植入式超柔性脑机接口系统、神舞科技ND系列多模态信号采集系统等。这批成果集中展现国内在侵入式设备、脑电芯片、信号采集、医疗康复及工业安全等方向的最新进展。', 'published', NULL, FALSE, 100, 1, '2026-11-21T03:01:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-286a5e5d43ab19c1', '100001', 'news-category-finance-flash', 'em-202611213936792957-d369391a06', '市值一夜蒸发近5000亿美元！英伟达遭遇重挫 黄仁勋回归变数加大', '美股11月20日，英伟达暴跌14.01%，市值3.03万亿美元，一夜蒸发4928亿美元市值，市值回到一年多以前的水平。英伟达已连跌7天，累计跌去27.74%。对比10月6日的股价高点，在45天时间内，英伟达则已累计跌去47.53%，股价几近腰斩。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:59:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-127476b637401cbc', '100001', 'news-category-finance-flash', 'em-202611213936792898-b51e681401', '美媒：美防长限制美加防务合作', '据美国《华盛顿邮报》20日援引部分不具名官员的话报道，美国国防部长赫格塞思已对美国同加拿大的防务关系施加了新的限制。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:47:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f45b5de70e6a526f', '100001', 'news-category-finance-flash', 'em-202611213936792782-faa16ac4ef', '美货运“龙”飞船脱离空间站启程返回地球', '美国太空探索技术公司货运“龙”飞船11月20日脱离国际空间站，携大量科研样本和设备等启程返回地球。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:43:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f6d8d04af6a60732', '100001', 'news-category-finance-flash', 'em-202611213936792690-e6af732a86', '人民日报：唱空中国经济者终会落空', '今年以来，一些境外媒体和机构围绕中国经济频频发难。一会儿渲染所谓“通缩陷阱”，断言中国经济增长难以为继；一会儿炒作“中国冲击2.0”，声称中国制造威胁全球产业。说辞换了一茬又一茬，唯有悲观的结论像是提前写好了一般。可惜，中国经济的发展，从来不由这些唱空者说了算。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:42:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a91a377cdb8b192e', '100001', 'news-category-finance-flash', 'em-202611213936792226-c0c6d92d9c', '小米从小鹏挖来了欧洲汽车业务负责人', '小米汽车在欧洲搭建的本地团队，又补上一名关键负责人。界面新闻从知情人士处获悉，前小鹏汽车西欧及南欧董事总经理强顺强已于今年9月加入小米汽车，出任国际业务部欧洲区董事总经理（Managing Director of Europe），常驻德国。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:39:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-67dcf15753893cd6', '100001', 'news-category-finance-flash', 'em-202611213936792546-f2b57e7c50', '开普云签约新疆喀什政务大模型项目', '据开普云消息，近日，开普云签约新疆喀什地区数字政府“一网通办·政务大模型”建设项目。项目围绕数字政府智能化建设需求，依托大模型、智能体及数据智能分析等技术，建设政务AI助手、经济数据分析预警、援疆项目管理三大AI应用平台，为政务办公、经济运行分析及援疆项目管理等业务提供智能化支撑。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:37:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-321324dfa98ec008', '100001', 'news-category-finance-flash', 'em-202611213936792075-2b985b70b9', '软银孙正义曾探讨以1万亿美元收购SK海力士', '据知情人士透露，软银董事长孙正义近期接洽华尔街机构，商议融资推进一笔规模达万亿级美元的收购，目标是存储芯片巨头SK海力士，但软银发言人表示，孙正义现已不再积极推进该交易。软银发言人称：“软银会考察大量机会，这笔交易目前已不再纳入积极评估范围。”SK海力士暂未回应置评请求。软银此前重仓OpenAI，资产负债表已经承压，目前尚不清楚其该如何筹措这笔收购资金。也没有迹象表明华尔街机构愿意为软银提供这笔融资。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:33:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c5219dca04258643', '100001', 'news-category-finance-flash', 'em-202611213936791229-0ddfc2291a', '美国FBI正在调查刑事信息数据库遭入侵事件', '据报道，美国FBI正在调查刑事信息数据库遭入侵事件。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:29:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-acbc02aad17d7d8f', '100001', 'news-category-finance-flash', 'em-202611213936790750-858303426a', '2026新西兰—中国商品博览会开幕', '20日，2026新西兰—中国商品博览会在新西兰最大城市奥克兰开幕，展会共持续三天。本次博览会总共设有13个行业展区，涉及食品饮料、轻工纺织、数字电子、光伏储能、文化旅游、电子商务等领域，同时展示中国非物质文化遗产相关产品和技艺。活动现场还举办了“出口中国”新西兰专场活动和中国—新西兰经贸企业对接活动。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:27:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8f4fb909bbedf96e', '100001', 'news-category-finance-flash', 'em-202611213936790462-750575f00d', '特朗普公开场合再次力挺黄仁勋：英伟达应该接受道歉 让他回来工作', '当地时间11月20日，特朗普在白宫记者会上再次公开支持英伟达前首席执行官黄仁勋回归。据《华尔街日报》发布的一段视频，特朗普在记者会上说：“他是个好人。他做过一些错误决定，但他确实是个非常有才华的人。”', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:27:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-903d732deeddd854', '100001', 'news-category-finance-flash', 'em-202611213936790176-f10a702e4e', 'RingConn推出限量版第三代智能戒指', '11月20日，智能戒指品牌RingConn宣布，公司与华纳兄弟全球消费品事业部达成合作，推出至尊魔戒（TheOneRing）。该产品为RingConn第三代智能戒指，设计灵感来源于《指环王》系列电影。该限量版戒指售价399美元，各地区实际售价会有所差异。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:22:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3b4aaa1619f9b9ec', '100001', 'news-category-finance-flash', 'em-202611213936789695-6469155765', '珠海冠宇徐延铭：锂电行业面临专利内忧外患 呼吁停止内部阻击式诉讼、抱团一致对外', '11月21日，珠海冠宇董事长徐延铭在第十一届动力电池应用国际峰会(CBIS2026)的企业家高层论坛上指出，国内锂电行业专利压力凸显，海外多家企业及专利池持续发起专利挑战；同时国内同业专利诉讼频发，不少诉讼瞄准IPO、招标节点形成阻击。他建议行业减少内部诉讼，将协商调解常态化，停止内卷，抱团出海共同应对海外知识产权风险。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:22:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5325e6199cfcfcfb', '100001', 'news-category-finance-flash', 'em-202611213936789127-dbb881c2ac', '美总统特使与卡塔尔高官讨论美伊斡旋工作', '当地时间20日获悉，两位知情人士表示，美国总统特朗普特使威特科夫和特朗普的女婿库什纳19日在柏林与卡塔尔高级官员举行会晤，就美国与伊朗之间的斡旋工作进行讨论。卡塔尔首相兼外交大臣穆罕默德及其特使出席。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:18:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-40642848f6fa44fe', '100001', 'news-category-finance-flash', 'em-202611213936788733-47bffe2fba', '蔚来ES9地平线鎏金特别版正式上市', '11月21日，蔚来宣布，蔚来ES9地平线鎏金特别版正式上市，售价63.8万元起；采用BaaS电池租用方式购买，售价53万元起。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:15:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7659c0feb5896ee8', '100001', 'news-category-finance-flash', 'em-202611213936788639-fdeb701343', '金饰克价继续下跌 老凤祥单日跌34元', '11月21日，国内黄金饰品价格对比显示，多家黄金珠宝品牌公布的境内足金首饰价格较昨日有所下调，老凤祥报价1056元/克，较昨日跌34元；老庙黄金报价1065元/克，较昨日跌23元；周大福报价1068元/克，较昨日跌20元；周六福报价1063元/克，较昨日跌25元。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:09:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-32c19afca19a71d1', '100001', 'news-category-finance-flash', 'em-202611213936787724-6aaed4d35f', '集邦咨询：需求降温，11月电视、显示器及笔电面板价格或全面持平', 'TrendForce集邦咨询公布了11月面板价格：2026年11月，电视、显示器、笔电面板价格与前月一致。电视面板方面，进入11月，电视面板逐步转入淡季循环，需求转弱，预计第四季主要电视品牌的采购动能将季减6%左右。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:07:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f29d7db7bdb04ea6', '100001', 'news-category-finance-flash', 'em-202611213936787480-1f571b7e1a', '美媒曝光黄仁勋被董事会罢免的主要原因', '北京时间11月21日，据《连线》杂志报道，黄仁勋(Jensen Huang)因婚外情风波而被英伟达免职。然而，据两名了解英伟达董事长及其他董事私下讨论情况的人士透露，最终促使董事会采取行动的，是与黄仁勋“不够坦诚”和“撒谎”相关的“多个问题”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:02:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-88d559f2e6ecca6d', '100001', 'news-category-finance-flash', 'em-202611213936787524-541883c8ce', '中国石化资本联合组建易消盾公司，上市首批锂电池专用灭火器', '据中国石化资本消息，11月19日，由中国石化资本、广西石油、青岛安工院联合组建的中石化易消盾科技（广西）有限公司在广西南宁东部产业新城六景园区揭牌成立，同步上市首批锂电池专用灭火器。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:02:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a97e3b70e96512f4', '100001', 'news-category-finance-flash', 'em-202611213936787347-b49ba3d1e8', '特朗普称将对海外建AI数据中心的美企征收“巨额税款” 美国不能重蹈芯片产业覆辙', '美国总统特朗普当地时间11月20日在白宫新闻发布会上突然提出，美国将对在海外建设数据中心的美国企业征收“巨额税款”（tremendous tax），以推动AI基础设施投资留在美国境内。他称，美国此前在芯片产业发展中犯下的错误不能再次发生。', 'published', NULL, FALSE, 100, 1, '2026-11-21T02:00:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dd230e084a5e7312', '100001', 'news-category-finance-flash', 'em-202611213936787090-273742a95f', '重大突破！量子计算机“高速内存”全球首次真机实现', '浙江大学西溪校区物理学院超导量子计算实验室内，形似巨型金属圆筒的稀释制冷机内部，一枚由浙江大学微纳加工中心制备、指甲盖大小的超导量子芯片躺在最低温区的混合室上，四周密布着铝线和微波同轴线缆。这枚芯片名为“天目2号”，此前在这里完成了一项重大突破——QRAM（量子随机存储器）的全球首次真机实现，这项成果相当于给量子计算机装上了“高速内存”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:55:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4c889d7598c99c10', '100001', 'news-category-finance-flash', 'em-202611213936785674-0eba5d541d', '警报！美元冲击波强势来袭！影响有多大？', '11月中旬以来，美元指数持续走强。美银全球研究投资策略师Michael Hartnett在近期面向客户的评论中警告，美元若按这个节奏继续飙升，终将变成一颗“破坏球”；高盛外汇策略团队则认为，美元短期仍有上行空间，2027年才会迎来实质性逆转。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:53:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c8532b31085b7d36', '100001', 'news-category-finance-flash', 'em-202611213936786077-5e76991e0d', '“像赌一把全押” 腾讯姚顺雨领衔混元开源后的一场深夜问答', '11月21日凌晨，北京时间刚过零点，腾讯首席AI科学家姚顺雨带着混元团队出现在海外社交媒体社区，做了一场文字AMA（公开问答）。问题来自全球开发者，回答前后持续两个多小时。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:50:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d8b13c658662401e', '100001', 'news-category-finance-flash', 'em-202611213936785782-c13b98fa9c', 'Anthropic研究员预测2027年底AI在几乎所有领域超越顶尖专家', '11 月 15 日在接受 Palisade Research 采访时，Anthropic 公司技术团队成员 Tao Lin 预测到 2027 年年底，在编程、电影制作等几乎所有领域，人工智能（AI）在发展大约还有 1.3 年后，可以媲美或超过世界顶尖人类专家的水平。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:45:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f55ad633f299fbf6', '100001', 'news-category-finance-flash', 'em-202611213936785467-9834392505', '北京理工大学机械与车辆学院教授孙逢春：2035年汽车基本实现纯电驱动', '在2026中国汽车充换电生态大会上，北京理工大学机械与车辆学院教授孙逢春指出，发展以纯电驱动为主的新能源汽车，核心是破解三大命题：我国原油对外依存度达75.6%，能源安全压力突出；交通领域碳排放体量巨大，若不推进电动化，交通碳中和难以落地；同时市场端已经形成倒逼，商用车电动化趋势不可逆转，预判2035年国内汽车将基本实现电动化、纯电驱动。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:43:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ac957da026edf230', '100001', 'news-category-finance-flash', 'em-202611213936785866-cec2c83ebc', '俄称爱沙尼亚关闭与俄边境口岸是制造新的“铁幕”', '俄罗斯外交部发言人扎哈罗娃11月20日表示，爱沙尼亚决定从12月1日起关闭与俄罗斯之间边境口岸的决定将对爱沙尼亚经济和社会造成负面后果。她还说，爱沙尼亚此举是在制造新的“铁幕”，俄方将采取必要的政治和外交措施来确保本国利益不受损害。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:42:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1d3b77efb1b71588', '100001', 'news-category-finance-flash', 'em-202611213936785346-0cce137e13', '郭明錤：谷歌预计将调整TPU 8t与8i系列2027年出货比重', '11月20日晚，天风国际证券分析师郭明錤发布最新产业调查显示，谷歌下修2027年、由博通设计的TPU8i系列共约100万颗（以单价较高的8iMax/Whalefish为主）。此下修约占2027年TPU8i系列出货量约20%。本次调查也指出，谷歌预计增加2027年由联发科设计的TPU8t系列出货，但细节尚未确定。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:38:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-97753761a1ca9a14', '100001', 'news-category-finance-flash', 'em-202611213936785262-83f6eac32f', '丹麦驱逐俄罗斯武官，俄表示将“适当回应”', '丹麦外交大臣拉斯穆森11月20日宣布，丹麦决定驱逐俄罗斯驻丹麦国防武官，要求其在7日内离境。俄外交部当天表示，俄将对丹麦驱逐其武官一事“作出适当回应”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:36:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2188243aec486238', '100001', 'news-category-finance-flash', 'em-202611213936785190-c8289b7fa6', '逆势加仓！阿布达比投资局继续买入两只个股', '晶盛机电(300316)最新公告显示，截至11月16日，合格境外机构投资者（QFII）“阿布达比投资局－自有资金”持有1468.57万股，占总股本的比例为1.12%。睿创微纳(688002)的公告也显示，截至11月16日，“阿布达比投资局－自有资金”持有581.38万股，占公司总股本比例1.25%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:36:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-97843a5476b1a02e', '100001', 'news-category-finance-flash', 'em-202611213936784875-605c360001', '我国“5G+工业互联网”项目达2.7万个 已覆盖全部41个工业大类', '记者从工业和信息化部了解到，目前我国5G应用已融入全部97个国民经济大类，工业互联网已覆盖全部41个工业大类。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:32:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e88fe7c67bd9d508', '100001', 'news-category-finance-flash', 'em-202611213936784764-265f1f20d4', '福建漳州核电4号机组三台蒸汽发生器全部吊装就位', '11月20日，华龙一号再传捷报，中核集团旗下中国核电投资控股的漳州核电4号机组三台蒸汽发生器全部精准吊装就位。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:32:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1b4f34210303583e', '100001', 'news-category-finance-flash', 'em-202611213936784410-013d7f5799', '辽宁义县推进小规模、薄弱学校合并办学：多所小学、中学撤并', '近日，辽宁省锦州市义县教育局发布《关于撤销并重新组建学校的公告》。公告称，此次撤销并重新组建学校是为“适应区域学龄人口变动、城乡发展规划和优质均衡教育发展要求，进一步优化县域教育布局，整合办学资源，推进小规模、薄弱学校合并办学，全面提升区域基础教育办学质量、办学效益和治理水平”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:28:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c7cb66589b7169e2', '100001', 'news-category-finance-flash', 'em-202611213936782679-051bfe6740', '加密货币市场大幅走低 超29万人被爆仓', '一觉醒来，比特币大跌！昨日晚间至今日凌晨，比特币开启加速下跌模式，陆续跌破61000美元、60000美元、59000美元、58000美元等多个关口，一度跌至2024年9月以来的最低水平。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:25:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a20c9c5926e82883', '100001', 'news-category-finance-flash', 'em-202611213936782490-189c006a6c', '新疆最大热电联产项目建成投产', '据中国能源建设集团有限公司消息，11月20日20时50分，中国能建华东院设计、建筑集团承建的喀什华电2×66万千瓦热电联产项目7号机组通过168小时满负荷试运行，标志着新疆最大热电联产项目全面建成投产。该项目位于新疆喀什市，是国家“两个联营”一体化重点项目、新疆电力发展规划重点工程。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:15:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0e7af97a85d97d8b', '100001', 'news-category-finance-flash', 'em-202611203936234665-3722fe5470', '现房销售改革后 地方政府为了卖地既“费心”又“贴心”', '11月19日，北京朝阳区驼房营地块顺利成交，西地块由中建智地+太古联合竞得，东地块由金隅+懋源联合竞得，成交价分别为49.05亿元、40.74亿元，溢价率分别为9%、7.2%。而这宗地能顺利卖出去，背后藏着地方政府满满的“求生欲”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:14:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-84d2f8c9b0a765d6', '100001', 'news-category-finance-flash', 'em-202611203936379822-5e10246b49', '从“多放几天假”到“淡季造峰器” 秋假激活亲子出游消费窗口', '秋假正从“多放几天假”变成文旅消费的“淡季造峰器”。随着多地开启秋假，近期迎来出游高峰。记者了解到，随着多地进入今年秋假高峰期，铁路部门在多地增开了列车班次。例如11月17日至23日，上铁集团增开去往北京、南昌、福州、深圳等多个方向旅客列车17对。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:13:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6d26f9d3ddf51818', '100001', 'news-category-finance-flash', 'em-202611213936782128-258e4184c5', '黄仁勋20年前诉讼被翻出：被指辱骂恐吓员工 律师因提担忧遭解雇', '彭博社报道，根据2007年在加州提起的一桩诉讼中的指控，大约20年前，两位英伟达员工就已对时任CEO黄仁勋(Jensen Huang)对待员工的方式提出不满，其中包括他威胁员工，并发表露骨性言论。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:11:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-144e8439ec015bd4', '100001', 'news-category-finance-flash', 'em-202611213936782092-1a0bb2f3ff', '宁德时代在土耳其首个宁家服务体验中心开业', '11月19日，宁德时代在土耳其的首个宁家服务体验中心正式开业。该设施是土耳其首个专业电池仓维修中心及销售服务一体化枢纽。宁家服务体验中心位于伊斯坦布尔，由宁德时代与Ascendum集团旗下AscendumTürkiye合作推出。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:10:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ca05aabe94fcdd46', '100001', 'news-category-finance-flash', 'em-202611203936388329-ad1f9a5ab6', '广州珠光系近6亿元债权包流拍 低调富豪兄弟的地产困局浮出水面', '11月20日午间，广州资产管理有限公司挂牌的两笔珠光系债权包以流拍告终。两笔共计近6亿元债权，相关抵押物包括广州市海珠区的江景大平层、从化区的养老别墅，以及商铺等，合计198套住宅及64套商铺，起拍价3.49亿元，仅与债权本金相当。', 'published', NULL, FALSE, 100, 1, '2026-11-21T01:09:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9a82450e03512606', '100001', 'news-category-finance-flash', 'em-202611203936156769-c84014058a', '智元机器人开始“做”手机了', '记者获悉，近日，智元创新（AGIBOT）与国内智能终端全产业链精密制造龙头蓝思科技达成合作，在手机测试产线部署智元精灵G2机器人，数十台机器人同时进行测试工位自动上下料、测试设备交互等工作，聚焦手机MMI、ANT、CAM、CAMCV等测试环节，打造3C手机测试场景标准化样板。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:59:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d658b145fb379ea4', '100001', 'news-category-finance-flash', 'em-202611203936513944-debe852723', '年内多只量化私募基金业绩受挫 头部机构押注大模型自主挖掘因子技术引发业内热议', '北京量化投资管理有限公司总经理窦长民向记者透露，一家头部量化机构在内部交流会上提到：公司通过大模型全程自主挖掘、零人工介入的另类因子，已实盘跑赢基准超18个月，与传统因子相关性不足0.2。这一说法也被认为打破了过去量化因子平均6个月就衰减失效的“行业铁律”。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:55:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-686694a952b9b7fe', '100001', 'news-category-finance-flash', 'em-202611203936515650-2b3affdd72', '商业航天“国家队”加速拓市场 中国商火超3亿元中标空天院火箭发射项目', '中国政府采购网11月18日公告，中国科学院空天信息创新研究院（空天院）“03-06卫星运载火箭及发射场服务项目”完成招标，中国航天科技集团商业火箭有限公司以3.177亿元中标，综合评审得分92.58分。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:53:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-123815a01e32dbd3', '100001', 'news-category-finance-flash', 'em-202611203936287395-1ff707c8cd', 'DeepSeek千亿元融资落地背后：一群浙江实业企业悄然上牌桌', '9月下旬以来，传化智联、老板电器、雅戈尔、健盛集团等多家浙股上市公司披露了一份不甚引人瞩目的投资公告。尽管各家公司出资金额不同，但他们都将资金共同投向了一只名为横店柏晖创业投资（杭州）合伙企业（有限合伙）的私募基金。这只总规模为16.5亿元的私募基金，投资方向为高成长性科技产业项目。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:52:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c0c5594f3d850cf1', '100001', 'news-category-finance-flash', 'em-202611203936491270-6eed181e7c', '卡莱特股价三日涨逾70%背后：算力子公司上半年“零收入” 公司曾称其为“第二增长曲线”', '11月20日，卡莱特股价收跌8.11%，终止了连续涨停的势头。今年上半年，卡莱特宣布成为“昇腾APN钻石部件伙伴”，近期因华为算力“昇腾”概念火热，这家LED（发光二极管）显示控制厂商也成为市场关注度最高的标的之一。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:49:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-47eb425be50f6084', '100001', 'news-category-finance-flash', 'em-202611203936500951-66aa24fdf0', '英国对中国割草机器人启动反倾销调查 国内割草机龙头大叶股份将如何应对？', '11月20日晚间，国内割草机龙头之一的大叶股份发布公告称，英国贸易救济局于2026年11月18日应企业申请，对原产于中国的割草机器人正式发起反倾销调查。面对外部贸易环境变化，颇具此类经验的大叶股份表示，将调整境外生产基地的生产结构，并通过此前全资收购的德国子公司及奥地利生产基地承接欧洲当地的研发与生产制造。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:47:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-26e3f50b3691e5b0', '100001', 'news-category-finance-flash', 'em-202611213936779787-05ec510b61', '甲骨文称已筹集履行与OpenAI合同所需全部资金，预计2029财年自由现金流超300亿美元', '当地时间11月20日，甲骨文表示，已筹集履行与OpenAI基础设施合同所需的全部资金，本月早些时候完成最后一轮融资后，成为本轮投资周期中首家完成全部资金筹措的超大规模云服务商。公司称，相关融资方案已落实，后续与供应商的讨论仅涉及额外融资选择，不影响合同履行。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:47:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7834a0e43e74cc65', '100001', 'news-category-finance-flash', 'em-202611213936779087-1628d1f270', '美股大跌 纳指年内涨幅悉数回吐', '美国股市三大指数20日大幅下跌。其中，纳斯达克综合指数单日跌幅超过5%，年内涨幅悉数回吐。本周以来，纳指成分股市值蒸发逾4万亿美元，该指数今年以来的累计涨幅已全部抹去。与此同时，道指和标普500指数较各自历史收盘高点均下跌超过10%，进入技术性回调区间。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:46:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-609f3e15782d040f', '100001', 'news-category-finance-flash', 'em-202611203936247862-794eec082c', '专访格力电器CMO朱磊：AI算力增长 制冷正成为关键基础设施', '近日，格力电器（珠海）CMO朱磊表示，全球气候治理当前面临的关键问题，不是缺少标准，而是如何推动标准落地。制造企业需要通过技术创新和产品应用，将节能标准转化为实际减排成效。朱磊介绍，格力此次带来了面向人工智能数据中心的高效制冷解决方案。在相关项目中，格力的液冷同源一体化解决方案已将PUE降至1.1。此外，格力还在探索数据中心余热利用，将低品位废热提升至70摄氏度，用于居民供暖等场景。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:43:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0124bb304f31505e', '100001', 'news-category-finance-flash', 'em-202611213936778966-57098db059', '上海航交所：本周三大船型运价小幅下跌 干散货租金指数止涨回落', '据上海航运交易所，本周，国际干散货运输市场三大船型运价不同程度下跌，远东干散货租金指数小幅回落。分船型来看，海岬型船太平洋市场运输需求前少后多，运价先抑后扬；远程矿航线市场较安静，船用燃油价格下行，运价微跌。巴拿马型船市场，下半周煤炭运输需求转弱，日租金稳中有跌。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:42:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ff004d459a2427da', '100001', 'news-category-finance-flash', 'em-202611213936599455-048258f9c5', '深圳3D打印龙头 帮张雪造机车配件', '小到齿科导板、文创潮玩，大到汽车部件、航空发动机等，其设备都能打印出来。2026年，金石三维的收入预计超10亿元。在记者采访时，江泽星表示，很多行业的关键部件，未来3D打印都有机会代替传统制造。当下正针对一些小品类、小批量的行业，尝试产品量产。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:40:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4fe0e4df5f47ed3c', '100001', 'news-category-finance-flash', 'em-202611213936777222-306bb492eb', '宗馥莉48小时调整247人', '11月19日，记者从知情人士获悉，娃哈哈集团董事长许思敏已正式辞职。当日晚，记者多次拨打许本人电话，均无人接听，发送求证短信，至发稿也未获回复。有报道称，其在48小时内，合计调整247人的职务。宗馥莉正用一套高度效率导向的逻辑，来改造一个靠“人情”运转30多年的体系。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:36:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3c5cf145364ad4e7', '100001', 'news-category-finance-flash', 'em-202611213936778087-ab71686fc1', '零跑汽车回应“A10后备厢被几箱啤酒压穿底”：系下层独立储物盒受损 非底板或整车承载结构损坏', '11月20日晚，针对网传零跑A10后备厢被几箱啤酒压穿底一事，@零跑汽车发布《关于零跑A10后备厢储物盒的情况说明》称，近日关注到网络上流传的零跑A10后备厢下层储物盒受损的相关视频。公司高度重视，第一时间联系用户并对车辆进行了检测。经核实，本次受损部件为后备厢盖板下方的独立储物盒，系装载物品超过其设计承重上限所致，并非后备厢底板或整车承载结构受损。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:29:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2ee84eaaa083cb6e', '100001', 'news-category-finance-flash', 'em-202611203936313439-3caefb9835', '1到10月白酒累计产量下跌超4% 行业去库存到了关键期？', '白酒渠道去库存同时，酒厂的产量也在同步下降。近日，国家统计局发布的酒类产量数据显示，1至10月，规上白酒企业（折65度，商品量）产量累计259.2万千升，同比下降4.3%。其中10月（折65度，商品量）产量23.9万千升，同比下降8.1%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:27:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-00b60e3e4622d03c', '100001', 'news-category-finance-flash', 'em-202611213936777867-50cadab046', '第100家央企“满月”答卷：数据要素改革“实体操盘”提速', '10月20日揭牌，11月20日满月。短短一个月，国家数据集团有限公司完成了从“亮相”到“起步”的切换：国务院国资委监管央企名录扩容至100家，数据要素市场化改革从制度设计迈入实体化运营，治理架构、股东协同、雄安场景、全国数据市场、AI供给五条线同步铺开。这家备受瞩目的新央企，轮廓日渐清晰。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:26:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d71c0bf61126b004', '100001', 'news-category-finance-flash', 'em-202611203936172352-a0a7e8b276', '全球股市“黑色星期五” A股如何更抗跌？多家机构这样说', '全球股市遭遇“黑色星期五”。11月20日，亚太股市深度调整，日经225指数、韩国KOSPI指数双双跌超5%，A股同样飘绿，但跌幅明显低于其他主要市场——上证指数跌1.23%，深证成指、创业板指跌超3%，上证50微涨0.45%。记者采访了十余家机构，梳理出本轮调整的核心逻辑：外围流动性扰动是主因，A股基本面未变、估值更低，中长期投资价值反而在下跌中进一步凸显。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:20:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-94498f02df608472', '100001', 'news-category-finance-flash', 'em-202611203936460169-5dce643ace', '超200条变更公告、多位“扛旗者”出走 广发基金怎么了？', '一年变更公告超200条、多位“扛旗者”接连出走——广发基金的投研阵容正在经历大洗牌？记者梳理发现，今年以来，广发基金旗下基金经理频繁变动，年内发布有关基金经理变更公告达222条，超过2023年-2025年三年的总和。与此同时，年内多位“扛旗者”离场，广发基金到底怎么了？', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:18:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6c51ac3f3b30579c', '100001', 'news-category-finance-flash', 'em-202611213936777396-d2934c3d35', '英伟达创金融危机来最长连跌：累跌46% 市值掉了一个亚马逊', '北京时间11月21日，据CNBC报道，英伟达股价周五暴跌14%，连续第七个交易日下跌。随着投资者对黄仁勋(Jensen Huang)卸任后的公司前景日益担忧，英伟达股价持续承压。该股已连续第七周收跌，为2008年金融危机以来最长的连续周跌势。在此期间，英伟达股价累计下跌46%，公司市值缩水约2.6万亿美元，相当于一个亚马逊公司。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:16:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0630658a335517e2', '100001', 'news-category-finance-flash', 'em-202611203936533747-228dc7f2f6', '黄金急跌一周多重关口失守 类似行情历史上出现过三轮', '一向被视作资产“避风港”的黄金，与风险资产同步下挫。对此，多位业内人士表示，本轮金价暴跌并非黄金长期投资逻辑崩塌，而是美联储货币政策重新定价、跨资产流动性挤兑、技术破位引发多头减仓多重因素共振。历史多轮急跌证明，流动性紧张阶段黄金常因高流动性被优先抛售，不等于避险属性失效。面对剧烈波动，专家提醒普通投资者摒弃抄底冲动，结合自身投资目标理性控仓。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:13:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-24c46d62d6836b86', '100001', 'news-category-finance-flash', 'em-202611213936587394-1181ec0ffb', '“闭门造车”造不出新消费', '今年的“双11”榜单上，一批成立不足5年的新品牌闯入各行业销量前10名，最快创牌仅一年便跻身头部，成为今年消费市场一道亮眼风景。182个新锐品牌站上行业前排的背后，不只是流量红利的偶然眷顾，更是一套由用户、产业集群、数字平台共同编织的“共创”新机制，为我们观察供给侧变革、读懂消费升级打开了微观窗口。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:10:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-016362638003c841', '100001', 'news-category-finance-flash', 'em-202611213936586544-583fc602bf', '把电池产业优势转化为竞争力', '工信部等7部门联合印发的《新型电池产业发展“十五五”规划》，作为电池领域首份国家级专项规划，为新型电池产业发展提供了遵循和方向指引。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:09:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d21f36c8a1ee5cf1', '100001', 'news-category-finance-flash', 'em-202611213936776597-d4af42f457', '黄金一周大跌近9% 考验3500美元关口', '当地时间11月20日，国际金价再度大跌，现货黄金盘中一度跌近3.5%，考验3500美元关口，最低报3502美元/盎司，最终收盘时报3537.87美元/盎司，跌幅2.47%，本周跌超346美元，跌幅达8.91%。国际银价同样遭遇大幅下跌，现货白银跌3.84%，报41.22美元/盎司，本周跌幅达15.42%。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:06:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0b7f30eeecd08c7f', '100001', 'news-category-finance-flash', 'em-202611213936586872-95beed41c7', '“温差”待消弭 信心不可失', '今年以来，我国经济顶压前行，继续保持总体平稳、向新向优发展态势，展现出强大韧性和活力。不过，与宏观数据相比，不少微观个体的直接感受，依然存在“温差”。正视这种“温差”，不是否定宏观数据的真实性，而是为了更准确地理解经济转型期的结构性矛盾，打通政策落地的“最后一公里”，让经济增长红利能够更均衡地传递到每个经营主体、每位普通人身上。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:06:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dabef49cb3611ba4', '100001', 'news-category-finance-flash', 'em-202611213936776080-64ab06f8fc', '缅甸总统府介绍新政府施政及未来规划', '缅甸总统府20日举行新闻发布会。缅甸总统府副部长兼总统发言人凯凯索介绍了新政府执政半年来的施政情况，以及新政府从2026至2030年五年发展路线图。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:05:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ee4364e8fadcac47', '100001', 'news-category-finance-flash', 'em-202611203936464050-359595416a', '对接企业需求 银行股票回购增持专项贷款提速', '股票回购增持再贷款政策加码落地半个月，银行端投放热情持续升温。11月2日，央行会同金融监管总局、证监会等部门召开股票回购增持再贷款座谈会，宣布加力实施该政策、对政策“升级扩围”；11月4日，政策正式落地——再贷款利率下调0.25个百分点至1%，工具由阶段性安排转为长期制度性安排，支持对象扩至21家全国性银行和5家系统重要性城商行。', 'published', NULL, FALSE, 100, 1, '2026-11-21T00:01:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z')
