INSERT INTO news_item (
    id, tenant_id, category_id, slug, title, summary, status, author_name,
    featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
    ('news-item-3514d34df552eebc', '100001', 'news-category-finance-flash', 'em-202611203935644877-67860f2b23', 'Anthropic上市当天遭抗议 离职研究员呼吁必须关闭这项AI技术', '北京时间11月20日，据美媒《旧金山标准报》（The San Francisco Standard）报道，Anthropic前研究员雅各布·考克森（Jacob Coxon）在该公司IPO当天现身旧金山总部外，向现场抗议者公开呼吁，禁止人工智能系统进行递归自我改进（Recursive Self-Improvement，简称RSI）。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:57:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c95e216b4cc63ecf', '100001', 'news-category-finance-flash', 'em-202611203935658457-d7d03ee109', '金融街证券：董事长祝艳辉接受调查并被实施留置措施', '金融街证券（01476.HK）发布内幕消息公告，根据中华人民共和国北京市西城区监察委员会的通知，公司董事长祝艳辉目前正接受调查并被实施留置措施。于公告刊发时，公司未收到任何需要协助调查或提供任何资料的要求，本集团的业务运营正常。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:56:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c9b53ff7ac7a24a4', '100001', 'news-category-finance-flash', 'em-202611203935633426-0e62921d51', '中信证券：房地产相关权益资产价值可能在2027年见底向上', '中信证券研报称，预计2027年房价将在更广阔的范围止跌回升，房地产市场的各个细分领域都将走向精细化运营，并为消费者带来更多的价值。房地产相关权益资产价值可能在2027年见底向上。核心资产持有和开发混业的地产企业持续的折价可能逐渐消失。看好减值计提充分、产品力出色的开发企业，也看好市占率不断提升的运营和服务龙头。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:55:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a28660a573d41bc4', '100001', 'news-category-finance-flash', 'em-202611203935447484-9c10356a31', '向居住全周期场景延伸 多地优化公积金提取政策', '11月以来，广州、武汉、海南等多地密集出台公积金优化细则。公积金提取场景从传统购房还贷，向租房安居、家装提质、物业缴费、老旧小区更新、适老化改造等居住全周期场景延伸。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:55:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-73c2289877ff40f9', '100001', 'news-category-finance-flash', 'em-202611203935446787-561c2b4183', '一块F1赛车电池背后的亚太“数绿协同”', '两个多星期前，20岁的年轻车手基米·安东内利驾驶搭载中国产电池的赛车，在F1赛场上冲过终点，成为F1历史上最年轻的世界冠军。在11月17日举行的2026年亚太经合组织工商领导人峰会“推动数字化绿色化协同转型”专题研讨上，惠州亿纬锂能股份有限公司董事长刘金成用一个生动的故事，展开了这场对谈。这家企业为夺冠赛车提供电池解决方案。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:54:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c2cb667ee72ada5d', '100001', 'news-category-finance-flash', 'em-202611203935429884-e2bd4b8a91', '冷空气催热“暖经济”御寒商品和暖食茶饮走俏', '近期，全国多地迎来持续降温天气，带动冬季消费需求释放。记者走访多家大型商超、家电卖场以及多个核心商圈了解到，羽绒服、取暖小家电等御寒商品销售升温，火锅、新式茶饮等暖食热饮消费同步增长，业态多元的冬日“暖经济”正为实体消费增添活力。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:53:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c1b7eb8a2c121063', '100001', 'news-category-finance-flash', 'em-202611203935433393-ca572f36d8', '上市公司数据资产入表迈入精耕细作新阶段', '随着数据要素价值持续显现，A股上市公司数据资产入表（按会计准则将达标数据资源确认为资产并入账）工作稳步推进。数据统计，2026年前三季度共有139家A股上市公司参与数据资产入表工作，入表规模合计34.65亿元，参与企业数量及规模分别同比增长33.03%和16.63%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:52:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d9eb575922b5616c', '100001', 'news-category-finance-flash', 'em-202611203935434311-c23d23d48c', '直接融资比重提升蕴含深层变化', '今年以来，政府债券融资保持高位、企业债券和股票融资同比多增、银行贷款同比少增，共同促成这一结构变化。提高直接融资比重的意义，不仅在于拓宽实体经济融资渠道，更在于改善金融资源配置、优化风险分担机制和债务结构，为我国经济高质量发展积蓄更足的后劲。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:50:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4d83055c53371a50', '100001', 'news-category-finance-flash', 'em-202611203935605360-4c99ed91b8', '国金证券：AI芯片功耗与热点密度持续提升 推动高导热散热材料需求增长', '国金证券研报称，AI芯片功耗与热点密度持续提升，推动高导热散热材料需求增长。金刚石铜与纯金刚石分别切入封装盖板、冷板嵌件及芯片近端散热，制造降本与客户验证推进将逐步打开应用空间。看好订单放量后，具备批量交付能力的企业通过产能利用率提升与工艺降本释放业绩弹性。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:49:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-85d7418c2dd0c20f', '100001', 'news-category-finance-flash', 'em-202611203935592749-f6da8bb479', '中信建投：玻璃基板有望成为封装材料升级重要方向 产业化初期重点把握设备先行机会', '中信建投研报称，AI算力需求推动先进封装向多芯粒、多HBM与大尺寸演进，玻璃基板有望成为封装材料升级的重要方向，产业化初期重点把握设备先行机会。随着单一封装集成的芯粒与HBM数量增加，封装面积、互连密度和供电需求同步提升，玻璃凭借较高刚性、良好平整度和尺寸稳定性，为大尺寸、高密度封装提供新的材料选择，并具备向玻璃中介层及光电共封装拓展的潜力。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:47:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b369e29dbd15f384', '100001', 'news-category-finance-flash', 'em-202611203935435210-40014d7976', '股票ETF月内净流入超2000亿元', '数据显示，截至11月19日，11月份以来，股票型ETF呈现资金净买入状态，月内净流入金额已达2019.49亿元。在一众ETF中，股票型ETF净流入金额居于首位，货币型ETF、跨境ETF月内净流入金额分别为162.59亿元、7.78亿元，商品型ETF、债券型ETF月内则出现不同程度的资金净流出。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:47:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-46654c5254418e4e', '100001', 'news-category-finance-flash', 'em-202611203935584785-3477be84f7', '日经225指数期货早盘下跌3.63%', '日经225指数期货早盘下跌3.63%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:46:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-13b4ce15cf129b5d', '100001', 'news-category-finance-flash', 'em-202611203935436512-a79c562edc', '产业链公司多路径布局风机叶片回收赛道', '记者采访了解到，我国风电自2006年前后进入规模化发展阶段，按20年左右设计寿命推算，早期规模化投运的机组正陆续进入退役窗口。部分项目仅靠回收产物销售难以覆盖投入，退役叶片存在长期堆存等问题，资源化利用水平仍有待提升。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:46:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-69bb575854a5435a', '100001', 'news-category-finance-flash', 'em-202611203935436784-41475ee2c0', '财政政策工具密集落地 为年末稳增长注入动能', '四季度以来，作为更加积极的财政政策的重要抓手，各类债务工具密集落地。地方债方面，数据显示，截至11月19日，今年以来新增专项债发行规模已达到40876亿元，发行进度（全年额度4.4万亿元）达到93%。从资金投向看，投向市政和产业园区基础设施建设、交通基础设施、民生服务、棚户区改造的资金超过五成。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:45:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c95b305602f4c74b', '100001', 'news-category-finance-flash', 'em-202611203935479024-d7a1481fce', '新一批城市试点启动 “5G+工业互联网”加快规模化应用', '11月19日，以“网联万物智兴千业”为主题的2026中国5G+工业互联网大会在湖北省武汉市开幕。工业和信息化部总经济师高东升介绍，我国工业互联网体系化发展走在全球前列。截至目前，我国已建成工业5G专网2.7万个，培育卓越级智能工厂750余家、领航级智能工厂49家，建成5G工厂1260家，具有一定影响力的平台超360家，重点平台工业设备连接数超1亿台（套）。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:43:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-36f40763d098f1e8', '100001', 'news-category-finance-flash', 'em-202611203935550325-8ba5d5bd68', '美联储保罗森称，清晰的沟通有助于货币政策；其重视拥有多种不同的沟通工具', '美联储保罗森称，清晰的沟通有助于货币政策；其重视拥有多种不同的沟通工具。不对货币政策近期走向发表看法。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:42:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1f1c6b950fa3baa5', '100001', 'news-category-finance-flash', 'em-202611203935546091-6c5b12dd94', '现货白银日内跌幅扩大至1%', '现货白银日内跌幅扩大至1%，报42.36美元/盎司。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:42:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8e9437acf16f29d9', '100001', 'news-category-finance-flash', 'em-202611203935479359-b0ffe3f136', '从采购走向共创 车企电池协作开创新范式', '伴随国内电池制造能力整体走向成熟，动力电池的采购关系正在被重新书写。行业逐步跳出传统采购模式，车企把电池纳入自研序列，从标准定义、过程管控到资本绑定，层层向电芯环节延伸。近日，记者实地走访中创新航生产基地小米龙甲电池产线，近距离观察这套由车企主导定义、电池厂商负责落地制造的新型量产体系。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:40:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7f739bf8ea3c975d', '100001', 'news-category-finance-flash', 'em-202611203935526976-e3429b2fdb', '现货黄金向下跌破3600美元', '现货黄金向下跌破3600美元，日内下跌0.72%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:40:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-df5bb6dc1329d8c4', '100001', 'news-category-finance-flash', 'em-202611203935478819-5591d90354', '影视变革一线调研： AI走进片场 传统电影人重新算账', '记者在调研中了解到，AI正在改变影视作品的制作方式，也让创作者重新计算成本与收益。镜头更容易做出来了，故事却仍需细细打磨；一些制作费用省下来了，作品怎样获得市场认可、收入怎样支撑持续创作，仍待探索。传统电影人与年轻团队的合作，正把AI影视的尝试推向技术之外更深的层面。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:38:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-24cffb07546fbd4d', '100001', 'news-category-finance-flash', 'em-202611203935515762-317b8410a9', '苹果相机及照片软件业务负责人离职', '据报道，苹果公司负责相机及照片软件业务的高管已经离职。知名科技记者古尔曼援引知情人士的话称，乔恩·麦考马克（JonMcCormack）已于10月底退休，结束了其在苹果公司超过八年的职业生涯。他此前负责管理iPhone的“相机”和“照片”应用，以及决定用户如何拍摄、查看和编辑照片及视频的底层技术。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:38:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3eb882332ee4c27b', '100001', 'news-category-finance-flash', 'em-202611203935479545-cd2f13f0c3', '行业标准落地 国产化向多工序拓展 半导体材料设备板块触底回升', '近期，半导体材料设备板块震荡回升，产业端也迎来新进展。行业专属质量管理体系标准获批，前期扩产订单陆续转化为收入，国产设备新品加快导入客户产线，零部件企业持续拓展供货。分析人士认为，国内晶圆厂新建产能与存储厂工艺升级同步推进，有望带动设备采购及配套耗材需求增长。国内厂商正从供应单一机型向覆盖多道关键工序拓展，国产化有望加速。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:36:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e71dd678880eedb2', '100001', 'news-category-finance-flash', 'em-202611203935440867-18dc38045d', '淡季叠加成本上升 水泥行业频发涨价函', '11月以来，水泥行业涨价函频发。11月16日，浙江金华、衢州、丽水市场部分主流品牌水泥企业发布通知，计划将P·O42.5散装水泥价格上涨20元/吨。前一日，河南多地水泥企业也陆续发布通知，上调水泥价格。但本轮涨价行情并非由需求端回暖驱动，而是在行业淡季叠加成本抬升的双重压力下，企业无奈被动提价。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:31:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-88359273e3ff8588', '100001', 'news-category-finance-flash', 'em-202611203935484824-0457eff922', '日本10月全国CPI同比增长2.3% 预期2.50%', '日本10月全国CPI同比增长2.3%，预期2.50%，前值2.10%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:31:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f7421658accca4ef', '100001', 'news-category-finance-flash', 'em-202611203935491181-5e2e2665fa', 'A股限售股解禁一览：53.32亿元市值限售股今日解禁', '数据显示，周五（11月20日），共有10家公司限售股解禁，合计解禁量为1.97亿股，按最新收盘价计算，合计解禁市值为53.32亿元。从解禁市值来看，夏厦精密、丹娜生物、并行科技解禁市值居前，解禁市值分别为24.17亿元、9.61亿元、7.12亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:31:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-89a218d63f45aad3', '100001', 'news-category-finance-flash', 'em-202611203935484672-195c461087', '日本10月核心CPI同比增长2.2% 预期2.30%', '日本10月核心CPI同比增长2.2%，预期2.30%，前值2.10%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:30:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-41ad4781414cd099', '100001', 'news-category-finance-flash', 'em-202611203935444240-fe40002eab', '市场情绪逐步平复 明年利率债或维持区间震荡', '近期，受点状信用风险事件、资金面边际收敛以及国债免税政策预期变化等多重因素影响，国内债券市场出现明显波动，理财赎回、债基被动卖券的负反馈一度发酵，10年期国债收益率也出现了阶段性上行。随着市场情绪逐步平复，债市重回企稳态势。多位机构人士表示，本轮行情调整属于阶段性扰动，债市中期运行逻辑并未发生改变。展望后市，利率债大概率维持区间震荡格局，但仍需关注财政供给、监管政策等潜在变量。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:29:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bbb41123a846730f', '100001', 'news-category-finance-flash', 'em-202611203935484518-55081e82d4', '法国巴黎银行上调美联储加息预期 料连续三次加息25个基点', '法国巴黎银行在利率预测中新增美联储明年3月加息的预期，预计继今年12月和明年1月之后，美联储将连续第三次加息25个基点。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:29:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-652bfe5006549a43', '100001', 'news-category-finance-flash', 'em-202611203935441115-5f0a760b20', '脑机接口大会召开 超三十家公司布局相关产业', '脑机接口是我国培育新质生产力、布局未来产业的核心赛道之一。据悉，2026脑机接口大会于11月19日至22日在北京市昌平区举办。大会由中国信息通信研究院联合北京市昌平区举办，将构建“会、赛、展”三位一体体系，聚焦学术交流、成果转化、人才培育、科普推广、区域赋能五大方向，形成“思想引领—人才支撑—产业转化”的创新闭环。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:28:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0123a81a3f0f0707', '100001', 'news-category-finance-flash', 'em-202611203935443784-c766ce28a8', '征收政府债券利息所得税讨论再起 专家称短期不具备落地条件', '近日，中国人民银行在2026年三季度货币政策执行报告中提出，“国内目前对国债利息收入免征所得税，使纳税投资者愿意接受低于应税债券的收益率”，这一表述让市场对于是否征收政府债券利息所得税的讨论进一步升温。多位受访专家指出，相关调整涉及税法修改等法定程序，不同税种、券种调整路径不一致，且需要考量对金融市场的系统性影响，对财政体系的影响也未必正向。未来是否征收、如何征收仍需审慎研究。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:26:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-47c9fbc32bff2277', '100001', 'news-category-finance-flash', 'em-202611203935441551-b894682b99', '瑞银全球投资银行部亚洲区副主席朱正芹：优质公司在港股不缺上市窗口', '瑞银全球投资银行部亚洲区副主席朱正芹表示，短期的市场动荡并不会改变投资人对优质资产的认可，一些国际长线资金已在告别港股IPO几年后回归。“港股市场的深度无需质疑，真正的好公司永远有上市窗口，但投资者的眼光正变得更加挑剔，好赛道和好公司缺一不可——眼下最符合要求的是中国人工智能（AI）相关企业与高端制造企业。”她说。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:25:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-46f31d8ce88a5421', '100001', 'news-category-finance-flash', 'em-202611203935441290-960aad637b', '华住集团股价创新高 连锁酒店龙头集中转向经营效率竞争', '受益于超预期的三季度业绩，华住集团股价日前创历史新高，这是否意味着国内酒店行业会迎来春天？有迹象显示，当前国内酒店行业整体需求依然不强，但华住集团、首旅酒店、锦江酒店、亚朵等龙头纷纷开始变革转型，使得酒店赛道的竞争转向商业模式与经营效率的深层较量。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:24:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-279eda05fecf1a2a', '100001', 'news-category-finance-flash', 'em-202611203935441438-22b58a093c', '与火箭“零距离”接触 航天研学游热起来了', '从全球首次海上网系回收，到国内首次入轨级火箭陆地回收，中国商业航天今年接连取得新突破，航天科普研学热潮也随之掀起。曾经神秘的火箭生产车间和发射现场，如今成为特色研学课堂，越来越多亲子家庭近距离探访大国重器，在沉浸式体验中感受中国航天的力量。航天科普研学热潮背后，从“看一眼”变成“住一晚、吃一顿、玩一圈”的消费链条正在形成。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:23:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-230f1f14f8eddc03', '100001', 'news-category-finance-flash', 'em-202611203935441623-3ea589d3bd', '年末车市“旺季未旺” “看车的人没少，下订的人慢了半拍”', '“看车的人没少，但下订的人慢了半拍。”接受记者采访时，北京来广营地区一家自主品牌4S店销售经理小谷表示，往年客户坐下来先问“还能再便宜多少”，今年问得最多的一句是“年底会不会更便宜”？', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:22:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-38fe4fa929493198', '100001', 'news-category-finance-flash', 'em-202611193935249018-31bae56da3', '半年来最大降幅 海外美债持仓锐减', '美东时间周三，美国财政部发布的国际资本流动报告（TIC）显示，9月海外投资者持有的美国国债总规模环比下降755亿美元，至9.2412万亿美元，创下今年3月以来最大单月降幅。作为头号“债主”，日本9月持有的美国国债规模环比减少52亿美元，降至1.0631万亿美元，创21个月来新低，但仍稳居美国最大海外“债主”之位。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d78e073351fc5ab8', '100001', 'news-category-finance-flash', 'em-202611203935442091-0f2133e660', '词元重塑算力计价标尺 跨界协同破解产业错配难题', '算力的计价方式正在改变，从按卡、按时租赁走向按词元（Token）计量，算力与电力的关系也从简单的“用电”走向协同调度。在11月19日举行的SMM数据要素赋能算力产业发展大会上，来自算力、能源、金融等领域的企业代表和专家，围绕算力定价体系、数据要素价值释放、算电协同机制等话题展开探讨，搭建促进跨界交流与协同创新的平台。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:20:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7156ab82de04951d', '100001', 'news-category-finance-flash', 'em-202611203935442286-1223ab0365', '部分基金经理“抄底”科技股 上市公司回购公告透底机构动向', '进入四季度以来，科技板块再度震荡调整，临近年底，机构是如何操作的？近期上市公司回购公告披露的股东变动信息显示，部分知名基金经理开始“抄底”科技股，外资机构也开始加仓部分标的。在机构看来，A股当前整体估值处于历史偏低分位点，具备较高的安全边际，成长板块依然是获取超额收益的主战场，但要注意投资逻辑的变化。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:18:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f25338d1356feb75', '100001', 'news-category-finance-flash', 'em-202611203935441920-88ec3176a6', '阿里巴巴三季度营收同比增长10% 平头哥三代GPU路线图加速推进', '在阿里巴巴集团首席执行官吴泳铭看来，集团全栈AI能力持续提升商业化水平，推动季度表现强劲——2027财年第二季度，营收为2715.19亿元，同比增长10%；经营利润为291.16亿元，同比增长443%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:16:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5973949389e34c0', '100001', 'news-category-finance-flash', 'em-202611203935443619-d66b4370b0', '中国虚拟电厂发展报告发布 6月底已提前完成2027年调节能力目标', '11月19日，国家能源局关于我国虚拟电厂的首份报告——《中国虚拟电厂发展报告（2026）》正式发布。报告显示：截至2026年6月底，我国已建成并投运的虚拟电厂数量为592个，同比增长78.9%；虚拟电厂最大调节能力达到2042.8万千瓦，同比增长62.7%，提前完成2027年调节能力达到2000万千瓦以上的发展目标。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:15:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ad3855ae7451bf20', '100001', 'news-category-finance-flash', 'em-202611203935442851-978fe28718', '信用债行情延续修复 大行二级资本债领涨', '11月19日上午，信用债市场延续前两个交易日的修复行情。大型银行二级资本债表现突出，部分个券收益率下行4个基点；中低评级信用债走势仍有分化，部分个券收益率继续上行。同期银行间资金面延续宽松，10年期国债活跃券收益率降至1.58%以下。机构认为，资金利率回落为信用债修复提供了支撑。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:13:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-83c1866a00903737', '100001', 'news-category-finance-flash', 'em-202611203935480645-83fab3dbd6', 'Sandisk提交修订公司章程证书 实施8比1普通股正向拆股', 'Sandisk（SNDK）提交修订公司章程证书，实施8比1普通股正向拆股，授权普通股从4.5亿股增至36亿股。修订于美东时间2026年11月19日下午4:01生效，预计11月20日开盘起按拆股后基准交易。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-936ebd37bc9aca49', '100001', 'news-category-finance-flash', 'em-202611203935480151-49ec931297', '朱雀三号“二手”发动机再次完成试车', '飞上太空，还能回来接着用！此前成功回收的朱雀三号火箭，发动机已全部完成再次试车，具备重复使用条件。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:10:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-13e154d3b2b45dc5', '100001', 'news-category-finance-flash', 'em-202611203935443067-f06e2f1aa0', '工业互联网跃迁 算网电协同支撑智能化升级', '11月19日，2026中国5G+工业互联网大会在武汉开幕。工业和信息化部有关负责人在会上介绍，我国已建成工业5G专网2.7万个，培育各行业智能工厂750余家、领航级智能工厂49家，建成5G工厂1260家。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:08:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a4224c5e067694ad', '100001', 'news-category-finance-flash', 'em-202611203935474145-0cb5d14512', '有色大跌 专家谈后市演绎', '美联储最新表态如一记重拳砸向有色金属市场。11月18日，伦铜主力合约盘中一度大跌6.41%，最终收跌4.55%；伦铝主力合约盘中最大跌幅达4.28%；伦锡主力合约盘中最大跌幅为8.21%。铜、铝、锡后市将如何演绎？在11月16日至18日举办的SME 2026上海金属周上，业内分析人士认为，受宏观预期压制，有色金属价格短期承压；品种基本面分化显著，铜、锡中长期供应仍偏紧，铝远期或转向过剩格局。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:06:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-51a24ba780f79c99', '100001', 'news-category-finance-flash', 'em-202611203935477171-76aae4dc53', 'MSCI将于12月1日把Anthropic纳入大盘股指数', 'MSCI将于12月1日把Anthropic纳入大盘股指数。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:04:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1725827e5ab3e8f4', '100001', 'news-category-finance-flash', 'em-202611203935478024-109875972c', '美股股指期货小幅低开 纳指期货跌0.1%', '美股股指期货小幅低开，其中纳指期货跌0.1%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T23:01:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-290e4e409533f3de', '100001', 'news-category-finance-flash', 'em-202611203935472845-1e61d3288c', '据报道：英伟达接近以逾5亿美元收购一家扩散式AI开发商Inception', '据报道，英伟达接近以逾5亿美元收购一家扩散式AI开发商Inception。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:46:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b447a8f90d965324', '100001', 'news-category-finance-flash', 'em-202611203935472952-b3a68931f6', '史上最大IPO落地！Anthropic筹得813亿美元 股价首日收涨17%', '北京时间周五（11月20日）凌晨00:48，Anthropic在纳斯达克全球精选市场开始交易，股票代码为“ANT”，发行价为83美元，超过了70至78美元的推介区间。开盘后5分钟，Anthropic一度涨至日内高点115.10美元，涨幅最大时接近39%，市值短暂突破2万亿美元关口，一度成为全球第六大上市公司。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:45:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-66b393ad4fedb4e4', '100001', 'news-category-finance-flash', 'em-202611203935472786-35214a5927', '普京：克里米亚大桥遭袭后 俄方不会再讨论海上停火', '俄罗斯总统普京19日表示，在克里米亚大桥遭袭后，俄方不会就海上停火或停止攻击能源设施与有关方面进行谈判。据俄罗斯总统网站19日发布的消息，在回应记者关于克里米亚大桥近日多次遭袭及受损情况的提问时，普京表示，克里米亚大桥是民用设施，俄方从未通过该桥运输军事装备和弹药，也没有通过该桥运输石油及石油制品。普京说，俄方此前曾评估与有关方面就海上停火及停止攻击能源设施举行谈判的可能性，但克里米亚大桥再次遭袭后，俄方不会就此进行谈判。他表示，俄方将作出回应，且力度将比乌方对克里米亚大桥的攻击更大。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:44:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4826a111ae39af41', '100001', 'news-category-finance-flash', 'em-202611203935472274-68c11bf95c', '欧盟批准匈牙利54亿欧元国防贷款计划', '欧盟理事会19日批准匈牙利修订后的国防投资计划，同意通过欧盟“欧洲安全行动”框架向匈牙利提供最高54亿欧元贷款。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:39:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-095eb99c4ca2dcaf', '100001', 'news-category-finance-flash', 'em-202611193935362065-eba1f9fb49', '阿里云外部经常性收入增长67% 吴泳铭：近两年中国市场算力尤为紧缺', '阿里巴巴集团19日发布2027财年第二季度（截至2026年9月30日的季度）财报。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:34:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a8a6ee526642b581', '100001', 'news-category-finance-flash', 'em-202611203935444585-b59f50a6fa', '量身定制融资方案 银行加码支持“六张网”建设', '政策层面引导金融资源向“六张网”建设领域集聚，银行业也加码布局，为相关项目量身定制融资方案。业内人士普遍认为，银行支持“六张网”建设，既有利于稳定基建投资、扩大有效需求，也有助于优化金融资源配置，为银行业提供优化资产结构、培育新的信贷增长点等机遇。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:22:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-628e9a5131aced98', '100001', 'news-category-finance-flash', 'em-202611193935355084-55f1843bc4', '赣锋锂业拟最高4亿元回购A股“护盘” 股价较年内高点回撤超60%', '在股价持续震荡走低之际，锂矿龙头正式端出了回购方案。赣锋锂业（SZ002460，股价34.20元，市值717.07亿元）披露公告称，公司拟使用自有资金或自筹资金，以集中竞价方式回购部分A股股份，回购资金总额在2亿元至4亿元之间，用于维护公司价值及股东权益。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:19:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7b318eb8f5b261d7', '100001', 'news-category-finance-flash', 'em-202611203935468265-c5093c274e', '据报道：美国白宫国家网络总监肖恩·凯恩克罗斯即将离职', '据报道，美国白宫国家网络总监肖恩·凯恩克罗斯（Sean Cairncross）即将离职。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:18:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aac7685e104adcdc', '100001', 'news-category-finance-flash', 'em-202611193935317437-07ac4cee64', 'DeepSeek1050亿元融资落定！梁文锋“挑”投资人：腾讯、宁德时代挤进第一梯队', '《每日经济新闻》记者获悉，DeepSeek第二轮融资有了最新进展。天眼查显示，11月17日，DeepSeek的工商主体杭州深度求索人工智能基础技术研究有限公司完成投资人变更，新增杭州程砚企业管理咨询合伙企业（有限合伙，以下简称杭州程砚），注册资本金也由此前的1644.7496万元增加至1991.8707万元。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:12:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4c10a2d5ce4814cf', '100001', 'news-category-finance-flash', 'em-202611203935465374-9760253680', '周五你需要知道的隔夜全球要闻', '周五你需要知道的隔夜全球要闻：Anthropic上市首秀收涨17%；交易员押注欧美三大央行利率将在数年内保持高位。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:05:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-918052c2fefe536f', '100001', 'news-category-finance-flash', 'em-202611203935465435-3f490415df', '美联储12月加息25个基点的概率为96.4%', '11月20日，据CME“美联储观察”：美联储12月加息25个基点的概率为96.4%，加息50个基点的概率为3.6%。美联储到明年1月累计加息25个基点的概率30%，累计加息50个基点的概率为67.5%，累计加息75个基点的概率为2.5%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T22:05:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-112975ae27c7854f', '100001', 'news-category-finance-flash', 'em-202611193935404897-d1365fdb02', '长鑫科技回购方案再生变！新增护盘式回购上限30亿元 注销上限增至40亿元', '11月19日，科创板存储龙头长鑫科技（688825.SH）披露《关于调整以集中竞价交易方式回购公司股份方案的公告》，明确本次股份回购中15亿—30亿元的部分将用于维护公司价值及股东权益（即“护盘式回购”），相关股份在回购完成后予以注销并减少注册资本。按方案安排，该部分回购自股东会审议通过本次方案之日起即可实施，实施期限为3个月。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:57:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-65df952088219a4a', '100001', 'news-category-finance-flash', 'em-202611193935355975-57582c1486', '福特官宣“正式进入电池业务” 底层技术来自中国合作伙伴', '美国本土汽车产量最高的车企福特确认，其位于密歇根州的电池工厂已开始发运首批磷酸铁锂（LFP）方形电芯。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:53:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-08bf13d8ef1fa0b3', '100001', 'news-category-finance-flash', 'em-202611203935461160-4e4e3a1723', '现货白银短线跳水 跌幅扩大至5%', '现货黄金价格跌2.75%，报3622.39美元/盎司；现货白银价格跌5.02%，报42.77美元/盎司。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:49:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d22dcbdc2f1d5329', '100001', 'news-category-finance-flash', 'em-202611203935460150-5a0ff53415', '美国行业协会拉响警报：全球PCB短缺危机正在蔓延 供应紧张局面或持续至2028年年中', '总部位于美国的全球电子协会（Global Electronics Association）在预警报告中指出，全球电子产业正面临印刷电路板（PCB）的严重短缺。这种零部件几乎存在于所有含有电子元件的消费产品中，其供应缺口可能对全球经济造成广泛影响。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:45:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-82b1d7190f1f3d0c', '100001', 'news-category-finance-flash', 'em-202611193935415640-4179ba3036', '六家公募上报 新的ETF产品有何来头?', '公募ETF（交易型开放式指数基金）再度上新。近日，《国际金融报》记者获悉，已有六家公募基金公司上报中证A500成长ETF，相关申请均获监管受理。该产品跟踪中证A500成长指数，截至10月30日，指数权重集中在电子、有色金属、通信三大行业。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:40:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7a078a7dbe4e6347', '100001', 'news-category-finance-flash', 'em-202611203935442328-9684b58f5c', '锂企“试水”金属锂 加码固态电池材料', '固态电池还在路上，锂企在材料端已有所行动。近日，天齐锂业年产1000吨高能锂电材料电池级金属锂项目在重庆市铜梁区竣工。项目投产后，天齐锂业金属锂总产能将提升至1600吨/年。记者从天齐锂业获悉，目前产品已面向下游头部电池及高端合金客户送样验证。不只是天齐锂业。赣锋锂业青海装置正在试车，盛新锂能超薄锂带已批量供货，贝特瑞、中一科技也从负极和箔材两头向金属锂延伸。作为固态电池负极潜在的重要材料，金属锂正被逐渐推向“前排”。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:36:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7a78544a4cc9d855', '100001', 'news-category-finance-flash', 'em-202611203935457444-e170753b60', '现货黄金价格跌超2% 失守3650美元', '现货黄金价格跌2.18%，报3643.38美元/盎司；现货白银价格跌3.55%，报43.43美元/盎司。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:26:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c0d43adb8e3f0133', '100001', 'news-category-finance-flash', 'em-202611203935424713-a909106368', 'Anthropic上市首日收涨17% 市值一度达到1.5万亿美元', '人工智能公司Anthropic（ANT）今日正式登陆纳斯达克，发行价为83美元/股，开盘报111.5美元，较发行价上涨34%。按开盘价计算，公司市值约为1.5万亿美元。本次IPO发行9.8亿股，发行总额约813.4亿美元，其中公司发行9.5635亿股，老股东出售2364.86万股。截至收盘，公司报97.17美元/股，较发行价上涨17.1%，市值达1.27万亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:22:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f58cdc7501c73881', '100001', 'news-category-finance-flash', 'em-202611203935456649-a5e925f17f', 'MSCI将于12月1日将ANTHROPIC纳入大盘股指数', 'MSCI将于12月1日把Anthropic纳入大盘股指数。富时罗素表示，Anthropic将被快速纳入富时全球股票指数系列。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:21:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-618c1359d2a01477', '100001', 'news-category-finance-flash', 'em-202611203935455568-efdb9a8f40', '普京：克里米亚大桥遭袭后 不再讨论海上停火', '俄罗斯总统普京19日表示，在克里米亚大桥遭袭后，俄方不会就海上停火或停止攻击能源设施与有关方面进行谈判。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:17:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c3ab39b305945894', '100001', 'news-category-finance-flash', 'em-202611203935455434-dde2da3e0b', '富时A50期指连续夜盘收跌1.12% 报12553点', '富时A50期指连续夜盘收跌1.12%，报12553点。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:16:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-75363c08c36df382', '100001', 'news-category-finance-flash', 'em-202611203935455342-909b5f957d', '日用消费品巨头宝洁计划到2030年裁减20%至30%的全球制造岗位', '日用消费品巨头宝洁计划到2030年裁减20%至30%的全球制造岗位。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:13:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-73a94ebe96aa73c2', '100001', 'news-category-finance-flash', 'em-202611203935453672-6c7c9ffc0e', '美三大股指高开低走均跌超2% Anthropic首秀市值站上1.27万亿美元', '美三大股指集体收跌。道琼斯指数跌2.19%，标普500指数跌2.02%，纳斯达克综合指数跌2.25%。Anthropic纳斯达克首秀，较发行价上涨17.1%，报97.17美元/股，市值达1.27万亿美元。AMD重挫近8%，做空机构Hunterbrook警告称其采用了与英伟达类似的“循环交易”。受此拖累，芯片股高开低走，英伟达跌超3%，美光科技跌超2%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:00:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2fae81efd5a4cc2d', '100001', 'news-category-finance-flash', 'em-202611193935389929-79f995f05a', '又跌了！国内金价失守800元/克 后市怎么走？', '金价跌势仍在延续。11月19日，国际金价再度震荡下探。伦敦金现在前一交易日跌破3800美元/盎司整数关口的基础上，再度失守3700美元/盎司关口，刷新年内低点。', 'published', NULL, FALSE, 100, 1, '2026-11-19T21:00:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0243b51eb6a98734', '100001', 'news-category-finance-flash', 'em-202611203935452776-85bf793e7d', '法巴银行强化美联储加息预期 现预计将连续三次加息', '法国巴黎银行（BNPParibas）在其预测中增加了一次3月的美联储加息，预计在12月和1月行动之后，将迎来连续第三次25个基点的加息。', 'published', NULL, FALSE, 100, 1, '2026-11-19T20:51:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fc85ad21c12a43b9', '100001', 'news-category-finance-flash', 'em-202611203935451985-4271680183', '比特币跌至四个月来新低', '比特币跌至四个月来新低，最新下跌0.6%，至61,876.23美元。', 'published', NULL, FALSE, 100, 1, '2026-11-19T20:39:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-889edb8d7ae0c152', '100001', 'news-category-finance-flash', 'em-202611203935450160-fb99e532d1', '美联储古尔斯比称：人工智能数据中心建设加剧通胀', '美联储古尔斯比称，人工智能数据中心建设加剧通胀。', 'published', NULL, FALSE, 100, 1, '2026-11-19T20:31:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1c3e1af0621f5cf8', '100001', 'news-category-finance-flash', 'em-202611203935443451-aa118047fa', '基金净值透露调仓方向 机构探寻下阶段确定性', '11月以来，海外市场波动及事件性因素扰动，A股科技板块震荡未止，机构投资者近期的调仓动作也随之浮出水面。数据显示：截至11月19日收盘，光模块、PCB两大市场热点板块本月以来跌幅均在10%上下，但区间振幅均超过25%；与此同时，以中芯国际、华虹宏力、寒武纪为代表的国产半导体产业链个股纷纷上涨，长江半导体设备指数上涨19.8%，区间振幅高达29.70%。', 'published', NULL, FALSE, 100, 1, '2026-11-19T20:30:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d90c6ff3f24d729d', '100001', 'news-category-finance-flash', 'em-202611203935449768-7ead4947ec', '英伟达与微软将加速计算从Azure扩展至Windows PC', '英伟达表示，正在与微软扩展全栈合作。旗下VeraRubinNVL72系统现已在微软Azure数据中心运行，使企业能够在云端和本地WindowsPC上定制AI模型并部署应用。', 'published', NULL, FALSE, 100, 1, '2026-11-19T20:17:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b7954b128126ff87', '100001', 'news-category-finance-flash', 'em-202611203935449023-f927ba6cb5', '特斯拉表示：将Cybercab扩展至美国达拉斯', '特斯拉表示，将Cybercab扩展至美国达拉斯。', 'published', NULL, FALSE, 100, 1, '2026-11-19T20:05:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
