INSERT INTO news_item (
    id, tenant_id, category_id, slug, title, summary, status, author_name,
    featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
    ('news-item-6c2b47c85d263451', '100001', 'news-category-finance-flash', 'em-202611163931555638-8ac01294ad', '中信建投：注意估值风格切换的年末行情特征', '中信建投研报认为，注意估值风格切换的年末行情特征。年底往往是最容易发生估值和风格切换的时点，随着10月底三季报披露完成，投资者普遍会将视点聚焦至次年的景气行业，低估值、盈利确定性强的板块在年末的胜率通常更高。目前机构仓位仍较为集中，补涨的赔率来自“低配+低拥挤”；另一方面，关注跨年主题行情。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:41:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-80bdae30b5103b80', '100001', 'news-category-finance-flash', 'em-202611163931555428-f54ecdaea3', '三星电子拟在美为SpaceX“星链”生产芯片', '据报道，三星电子将在美国得州奥斯汀工厂为SpaceX的“星链”卫星生产STM32V8微控制器（MCU），这种高性能MCU采用三星与意法半导体共同开发的18纳米全耗尽绝缘体上硅（FD-SOI）工艺。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:40:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5898bbade17429c0', '100001', 'news-category-finance-flash', 'em-202611163931554446-3e72778e4d', '黄仁勋已同意到国会作证 日期尚未确定', '北京时间11月16日，据彭博社报道，美国共和党众议员约翰·穆勒纳尔(John Moolenaar)透露，黄仁勋(Jensen Huang)已同意在闭门听证会上向议员作证，说明他与一位女商人之间的关系。几天前，黄仁勋因婚外情风波辞去了英伟达CEO。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:39:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5592fbda3857278f', '100001', 'news-category-finance-flash', 'em-202611163931533791-e6e5b7c1cb', '一轮调整超九成产品浮亏 FOF拿什么证明“专业”', '7月以来A股市场大幅震荡，截至11月13日，680余只公募FOF平均下跌7.77%，更有37只回撤幅度超过偏股基金指数同期26.71%的跌幅；取得正收益的FOF占比不足一成，收益上限也未超过3.5%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:38:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e7556a83571f6de0', '100001', 'news-category-finance-flash', 'em-202611163931532443-2474ca50be', '北交所开市五周年：三维协同发力 深耕中小企业资本主阵地', '2026年11月15日，北京证券交易所迎来开市五周年。设立五年来，北交所锚定服务创新型中小企业主阵地定位，与新三板一体化发展，在融资端构建多元工具体系、在投资端激活市场流动性、在生态端凝聚多方共育合力，市场功能持续完善，服务实体经济质效稳步提升，已成为我国多层次资本市场支持中小企业创新发展的重要平台。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:37:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6addb0f83eaf5a3f', '100001', 'news-category-finance-flash', 'em-202611163931554292-20efa57058', '佛得角现任总统若泽·马里亚·内韦斯宣布赢得大选', '佛得角现任总统若泽·马里亚·内韦斯当地时间15日在新闻发布会上宣布，其已赢得大选。15日当天，佛得角举行总统选举，包括现任总统若泽·马里亚·内韦斯在内的6名候选人角逐下届总统。选举投票于当地时间15日早上8时开始，选民在1300多个投票站进行投票。根据佛得角选举法，总统由选民直选产生，获逾半数选票的候选人赢得选举，任期5年。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:36:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ff2b773bf75a69b0', '100001', 'news-category-finance-flash', 'em-202611163931554068-7db4ab7f9f', '监管严查！带客户境外调研去了赌场 国盛和国联民生证券被处罚', '11月6日，江西证监局披露，国盛证券存在为公募基金管理人承担境外调研期间门票、调研中介等费用的情形，违反了相关规定，江西证监局决定对国盛证券采取出具警示函的行政监管措施，并记入证券期货市场诚信档案。这场境外调研违规风波起于今年一季度，据财新报道，3月份，有券商组织买方机构赴美国参加活动期间，将部分公募基金人员带往拉斯维加斯，而当地当时并无展会，相关人员实际上是去了赌场，且存在违规行为的券商不止一家。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:34:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5d6e79b3a79b4b9a', '100001', 'news-category-finance-flash', 'em-202611163931533416-34ebc146bb', '现房新政多地“开花” 房企主动适配新规则', '商品住房销售制度改革的落地速度，比市场预想更快。据中指研究院的统计，截至11月13日，“8·28新政”后已有25个省市落地实施细则，不管是现房销售、资金监管还是土拍规则，各地细则中都有不少“新提法”。其中，现房销售备受市场关注，市场一线也在发生变化。当买房不再像“开盲盒”时，购房者对“确定性”居住空间的需求更高，也考验着房企主动适配新规则的能力。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:32:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e5094ab84a6de57c', '100001', 'news-category-finance-flash', 'em-202611163931553571-b326484929', 'A股限售股解禁一览：28.84亿元市值限售股今日解禁', '数据显示，周一（11月16日），共有14家公司限售股解禁，合计解禁量为2.4亿股，按最新收盘价计算，合计解禁市值为28.84亿元。从解禁市值来看，隆平高科、直真科技、光弘科技解禁市值居前，解禁市值分别为11.92亿元、6.43亿元、6.01亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:32:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-93d0b0d6822d48ed', '100001', 'news-category-finance-flash', 'em-202611163931533253-84331c609d', 'A500家族再添新丁 头部公募集体上报成长风格ETF', '宽基指数的风格细分布局又迈出关键一步。11月13日，易方达基金、华夏基金、国泰基金、广发基金、招商基金、博时基金等头部公募扎堆上报中证A500成长ETF，申报材料已获证监会接收。这一批新产品，是市场在中证A500这一基础宽基指数之上，专门为成长风格打造的指数工具，补齐了A500系列的成长拼图。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:31:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a097ac3fa9a5bca1', '100001', 'news-category-finance-flash', 'em-202611163931553447-e08969809a', '全长277.6公里 我国输送距离最长二氧化碳长输管道投运', '记者今天从中国石油获悉，吉林石化——吉林油田二氧化碳长输管道工程建成投运。这是目前我国输送距离最长、管径最大、设计压力最高、输送规模最大的二氧化碳长输管道。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:30:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6311700d50ebbe12', '100001', 'news-category-finance-flash', 'em-202611163931532147-7bf7bfc095', '花旗集团董事长兼CEO范洁恩：补齐在华证券业务版图 竞争对手要“打起精神”了', '“我们的竞争对手要‘打起精神’了。”说出这句话时，花旗集团董事长兼首席执行官（CEO）范洁恩（JaneFraser）眼神中流露着自信而坚定的锐气。作为华尔街大型银行史上首位女性掌门人，范洁恩终于等来了一张翘盼五年的关键牌照。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:29:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0a72d36b20131b0a', '100001', 'news-category-finance-flash', 'em-202611163931553086-4ae118b936', '英媒曝黄仁勋考虑重返英伟达 其硅谷盟友正组建游说团向英伟达董事会施压 要求恢复其职务', '据英国《金融时报》11月15日消息，黄仁勋正考虑重返英伟达担任首席执行官。与此同时，其硅谷盟友正向英伟达董事会施压，要求恢复其职务。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:28:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5cb070fc6ab70f94', '100001', 'news-category-finance-flash', 'em-202611163931533350-9f8b610e34', '证监会：深化市场稳定长效机制研究 防范异常波动', '近日，证监会主席吴清在首届中国资本市场学术年会上表示，推进资本市场改革发展稳定，有很多重大理论和实践问题需要抓紧深化研究，进一步深化市场稳定长效机制研究，有效防范市场异常波动。深化市场微观结构研究，深入研究改善预期引导机制，减少“羊群效应”“短期化”交易等带来的市场波动，深入研究评估量化交易、股份减持等制度规则的优化和公平合理的监管安排，切实保护好投资者合法权益。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:26:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6454ef9447ce87ad', '100001', 'news-category-finance-flash', 'em-202611163931532790-b1026ec36b', 'A股“远通系”魅影浮现：进出九家上市公司 总持仓超百亿', '云天化第三季度末的前十大股东明细显示，赵志超位列第三大股东，重庆鑫远通酒店管理有限公司位列第四大股东，北京大地远通（集团）有限公司位列第七大股东，河北远通矿业有限公司位列第九大股东。以上四个股东合计持股6500万股，占云天化总股本的3.57%。按照云天化11月13日收盘价26.17元/股计算，该等股权市值合计约17.01亿元。这些账户向上穿透均互为关联方，指向赵志超及其控股的大地远通。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:25:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9cd370205ddb1a41', '100001', 'news-category-finance-flash', 'em-202611163931530715-d8d5f4c156', '让耐心成为可计量的信心', '北交所市场讨论最多的词是“耐心”。企业需要耐心研发，机构需要耐心定价，地方需要耐心培育。但耐心不能只靠倡导维持，它需要制度承接、成本分担和预期管理。如果以开市五周年为重新出发的起点，北交所而今迈步从头越，真正要完成的，是把各方的耐心转化为可预期、可兑现的信心。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:22:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-53c310a9fca8cd61', '100001', 'news-category-finance-flash', 'em-202611163931529487-572c5d68f5', '坚持看好港股优质资产 公募加码结构性布局', '今年以来，港股在亚太主要市场中表现相对偏弱，恒生科技指数调整幅度较深。业内人士表示，伴随市场持续消化前期高估值与交易拥挤度，近期部分具备基本面支撑的优质资产逐步显现估值吸引力。后续投资机会或更多集中在内需修复、创新药出海、互联网应用、现金流稳定的高股息资产等结构性方向。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:20:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ebe169e539792dbf', '100001', 'news-category-finance-flash', 'em-202611163931529130-e692639f47', '性价比显现 私募乐观看待A股配置价值', '11月报告显示，近六成受访私募基金经理对后续行情预期较为积极，预计加仓或维持仓位水平不变的占比超过90%。而且，10月下旬百亿级私募仓位便有所提升，显示私募在市场调整中捡拾筹码。业内人士表示，经过前期调整，A股和港股有不少标的显现性价比，可逐步加大布局力度。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:19:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b714a141a966e356', '100001', 'news-category-finance-flash', 'em-202611163931529868-35cfd176d0', '科技板块调整提升投资赔率 私募积极寻找反弹机会', '近期，A股市场有所调整，前期表现强势的科技成长板块出现波动。随着部分热门赛道估值回落，市场风险收益比逐步发生变化，一些私募机构开始重新审视科技板块的布局价值，积极寻找调整后的反弹机会。受访机构认为，部分优质科技资产经过前期调整，投资赔率有所改善，但反弹行情的持续性仍需要产业基本面和企业盈利能力的支撑。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:18:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-484c0045e4b4ef9f', '100001', 'news-category-finance-flash', 'em-202611163931527616-616ea85989', '51个一类新药纳入新版医保目录 多家上市公司产品迎商业化新机遇', '记者获悉，新版国家医保目录新增107种药品，其中51个一类新药，新增数量再创历史新高。12种药品新增纳入商保创新药目录，包括全球首个实体瘤CAR-T、中国首个血友病基因治疗药物等重大创新药品。多家上市公司产品进入双目录，相关产品有望借助医保、商保支付支持，进一步扩大患者覆盖面，为商业化增长打开空间。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:16:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8542e9547dd82677', '100001', 'news-category-finance-flash', 'em-202611163931529667-b0a6296733', '保持恒定的投资风格至关重要', '基金经理当然可以根据市场变化调整持仓，但在净值大幅下跌的情况下，这就可能事关基金投资风格漂移问题。如果调仓是基于对投资标的价值边界的审慎重估，尚可理解；如果是在持续下跌的压力下，转身去追涨其他方向，那就陷入了追涨杀跌的境地。这种在低点做出的方向性切换，一旦市场风格回摆，就会形成“卖在底部，买在顶部”的双重损耗。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:15:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-49bb1fc32b888259', '100001', 'news-category-finance-flash', 'em-202611163931529062-40c7ea8aae', '估值回调释放配置空间 机构看好亚洲科技股长期投资价值', '经过一轮调整，亚洲科技资产的投资价值正重新进入全球资金视野。在市场交易拥挤度明显回落的背景下，多家外资机构认为，亚洲核心科技板块性价比持续抬升，有望成为全球资本布局人工智能长期主线的重要方向。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:12:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6ea1bcbaf8736a7a', '100001', 'news-category-finance-flash', 'em-202611163931551245-b691bc973a', '伊朗称打击在巴林的美军基地是“回应美国侵略”', '伊朗外交部发言人巴加埃15日在例行记者会上表示，伊朗打击在巴林的美军基地是“回应美国侵略”。他同时表示，伊朗不会放弃和平利用核能的权利，伊美之间目前没有就核问题细节进行任何讨论。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:12:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0bcc8d25191eeab1', '100001', 'news-category-finance-flash', 'em-202611163931527722-e95c5ed5a1', '物理AI贡献阿尔法 机构科技投资调仓进行时', '科技投资如何从“叙事”到“落地”？物理AI正试图解答这个问题。“简单来说，物理AI就是让AI从处理数字信息，进一步走向感知和作用于真实世界。它要看懂周围环境，理解任务目标，再把判断转化为具体动作。人形机器人是其中一种载体，但物理AI的应用并不限于人形机器人。”中欧基金制造组研究员卢文杰说。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:10:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c17a52b7d02a865f', '100001', 'news-category-finance-flash', 'em-202611163931551461-954736a5b3', '奥克斯电气：认购建行、农行及浦发银行理财产品及结构性存款 累计涉资62.38亿元', '奥克斯电气（02580.HK）发布须予披露交易公告，公司通过全资附属公司认购中国建设银行、中国农业银行及浦发银行的理财产品及结构性存款。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:10:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-34a61f8c617bb2dd', '100001', 'news-category-finance-flash', 'em-202611163931551113-3e034b479e', '英伟达风波冲击全球算力格局 国产算力有望迎来重估契机', '从一封道歉信到官宣辞任，短短数日，英伟达创始人黄仁勋的个人风波已经演变为一场席卷全球AI产业链的巨震。记者采访了解到，多家基金及相关机构认为，此次风波冲击的并非全球AI产业的长期需求，而是英伟达作为全球AI芯片龙头的确定性溢价。随着全球算力竞争格局加速重塑，产业链有望从“一枝独秀”走向“百花齐放”，国产算力也有望迎来重估契机。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:09:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8eab46d26d3e6ef2', '100001', 'news-category-finance-flash', 'em-202611163931551375-01928f15e0', '云顶新耀：维适平及依嘉首次纳入2026年新版国家医保药品目录', '云顶新耀（01952.HK）发布自愿公告，公司维适平（精氨酸艾曲莫德片）及依嘉（注射用盐酸依拉环素）通过国家医保谈判，首次纳入新版《国家基本医疗保险、工伤保险和生育保险药品目录(2026年)》，新版目录将于2027年1月1日起正式生效。同时，耐赋康（布地奈德肠溶胶囊）继续保留在国家医保药品目录。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:09:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ea8fc32300951eb1', '100001', 'news-category-finance-flash', 'em-202611163931550029-abdd290e6a', '伊朗外交部：伊拥有和平利用核能的权利', '伊朗外交部发言人巴加埃在15日的新闻发布会上表示，伊朗拒绝接受德国有关伊朗停止铀浓缩活动的要求。他说，伊朗作为《不扩散核武器条约》缔约国，拥有和平利用核能的权利。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:06:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3f9ff2eb06b1ccb8', '100001', 'news-category-finance-flash', 'em-202611163931550218-3b69bfca6f', '美股股指期货小幅高开 其中纳指期货涨0.25%', '美股股指期货小幅高开，其中纳指期货涨0.25%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T23:01:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3431139e1375af55', '100001', 'news-category-finance-flash', 'em-202611163931550956-880660d4b6', '也门胡塞武装单方面释放600名被扣押人员', '萨那消息：也门胡塞武装15日宣布，在红十字国际委员会支持下，该组织当天在也门首都萨那单方面释放600名与也门冲突有关的被扣押人员。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:59:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fa8ef49b80e2045a', '100001', 'news-category-finance-flash', 'em-202611163931549761-bcfe17f393', '华东最长工业供热干线主体管道建设完成 全长42.35公里', '从国家能源集团获悉，华东最长工业供热干线工程——国能浙江舟山定海环岛工业集中供热项目已完成全线架空管道敷设，标志着该项目主体管道建设完成。项目依托舟山本岛规模最大热源点——国能浙江舟山电厂2台660兆瓦超超临界火电机组，建设全长42.35公里的供热管线，最大供热能力达每小时464吨，是目前华东地区干线最长的工业供热工程。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:59:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b2d63342dae1c9ba', '100001', 'news-category-finance-flash', 'em-202611163931549594-4ee8595a21', '美航空运输预计16日全面恢复 空管老旧问题再受关注', '美国交通部长达菲当地时间15日表示，美国航空运输预计当天逐步恢复正常，受飞机和机组人员不在预定执勤位置影响，可能到16日才能全面恢复。此前13日，美国联邦航空管理局因大规模通信故障发布全国航班停飞令，持续近5小时，影响持续至今。美方称，目前没有迹象表明事件系网络攻击，根本原因仍在调查。此次事件再次暴露美国空管系统设备老旧、投资不足等问题，美国政府呼吁国会追加拨款，全面升级空管通信网络。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:56:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bf5a206788def28d', '100001', 'news-category-finance-flash', 'em-202611163931527537-d64210f292', '红利基金今年以来 分红金额近百亿元', '今年以来，红利基金分红金额和次数均为历史同期新高。Wind数据显示，截至11月11日，全市场213只红利基金今年以来累计分红1156次，同比增加76.49%；分红金额93.97亿元，同比增加61.43%。另有数据显示，截至6月底，红利基金持有人户数合计1385.83万。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:50:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-31edc73fd91700d6', '100001', 'news-category-finance-flash', 'em-202611163931546013-6203f40c79', 'AI交易颠簸！资金回流红利 13只银行股股息率站上5%(名单)', '美东时间11月14日，美联储在金融稳定报告中警示AI杠杆风险，美股资金转向防御与红利板块。国内10年期国债收益率仍在1.6%附近，红利资产的比价优势尚未削弱。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:38:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-506b1ab4c726a41e', '100001', 'news-category-finance-flash', 'em-202611163931545564-5c439888d9', '胡塞武装称向沙特利雅得发射弹道导弹', '也门胡塞武装11月15日发表声明称，胡塞武装当天使用弹道导弹打击了沙特首都利雅得的哈立德国王国际机场和一座金融中心，另外还使用无人机袭击了沙特东西向输油管道的两座泵站。胡塞武装称这次袭击泵站行动成功实现了预定目标。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:30:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b19fc88d20f7dcd7', '100001', 'news-category-finance-flash', 'em-202611163931544452-b834978bda', '北交所上市公司 “真金白银”回报股东', '开市五年来，北交所上市公司回报投资者的“账本”日渐厚重。记者通过Wind统计发现，截至2026年11月15日，311家北交所上市公司参与分红，累计现金分红约290亿元，分红覆盖面逐年扩大。同时，增持回购也成为北交所公司传递价值信号、稳定市场预期的重要抓手，今年以来，北交所公司累计披露增持计划26家次、回购股份方案38家次，一个以“真金白银”为底色的投资者回报生态，正在这个服务创新型中小企业的主阵地上加速形成。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:16:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-370502ae38ee5c3d', '100001', 'news-category-finance-flash', 'em-202611163931541918-7bf0019fa6', 'CME“美联储观察”：美联储12月加息25个基点的概率为95%', '据CME“美联储观察”：美联储12月加息25个基点的概率为95%，加息50个基点的概率为5%。美联储到明年1月累计加息25个基点的概率25.2%，累计加息50个基点的概率为71.1%，累计加息75个基点的概率为3.7%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:05:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c118727baf799fd', '100001', 'news-category-finance-flash', 'em-202611163931540628-fda2c42a89', '高盛将港股评级上调至超配', '高盛将港股评级上调至超配。', 'published', NULL, FALSE, 100, 1, '2026-11-15T22:01:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-35a168e0c3275e43', '100001', 'news-category-finance-flash', 'em-202611163931540190-0dcb073668', '据报道 白宫或将对五角大楼前首席战略家提起刑事诉讼', '据报道，白宫或将对五角大楼前首席战略家提起刑事诉讼。', 'published', NULL, FALSE, 100, 1, '2026-11-15T21:47:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-22afcd72b103b7dc', '100001', 'news-category-finance-flash', 'em-202611163931532264-c2d9ad6dec', '专精特新赛道成色渐显 北证市场进入功能提升新阶段', '2026年11月15日，北京证券交易所迎来开市五周年。五年前鸣锣开市时，北交所仅有81家上市公司、总市值不足3000亿元；如今上市公司已达355家，总市值约8000亿元。五年间，这片聚焦创新型中小企业的资本市场沃土，不仅完成了规模上的立柱架梁，更跑出了一批实实在在的牛股。', 'published', NULL, FALSE, 100, 1, '2026-11-15T21:40:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-acf43535a05da35c', '100001', 'news-category-finance-flash', 'em-202611163931539287-9b3f9e1b23', '美“火神”火箭未能将亚马逊卫星送入预定轨道', '美国联合发射联盟公司的“火神”运载火箭15日首次执行亚马逊低地轨道卫星发射任务，但升空约10分钟后出现异常，未能将搭载的40颗宽带通信卫星送入预定轨道。据联合发射联盟公司介绍，“火神”运载火箭于美国东部时间当天12时40分许（北京时间16日1时40分许）从佛罗里达州卡纳维拉尔角太空军基地发射升空。', 'published', NULL, FALSE, 100, 1, '2026-11-15T21:25:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-985aaa39340cb547', '100001', 'news-category-finance-flash', 'em-202611163931537912-160135e066', '爱尔兰提出欧盟碳市场改革折中方案 以推动分歧重重的谈判', '爱尔兰在一份文件中提议，允许欧盟提前使用国际碳信用额度，并放宽免费排放配额规则，旨在为改革其旗舰气候政策的谈判注入动力。爱尔兰政府希望引入一个从2031-35年的试点阶段，在此期间，受欧盟碳排放交易体系（ETS）覆盖的企业，可使用高完整性的进口碳信用来满足其部分履约义务。这项改革提案在欧盟各国政府间引发了分歧：部分国家支持更严格的排放规则和更快的清洁能源转型，而另一些国家则担忧摆脱化石燃料的成本。', 'published', NULL, FALSE, 100, 1, '2026-11-15T21:06:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0ce51d4d83f76e15', '100001', 'news-category-finance-flash', 'em-202611163931537569-ed7eddcee6', '据报道 三星将在美国为SpaceX生产卫星芯片', '据报道，三星将在美国为SpaceX生产卫星芯片。', 'published', NULL, FALSE, 100, 1, '2026-11-15T20:53:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-43200fce2fc10ae5', '100001', 'news-category-finance-flash', 'em-202611163931532810-752c5baf6c', '打通不动产投融资循环链条 公募REITs蓄力万亿市场', '从首批9只产品破冰到如今近百只产品挂牌、总市值逾2400亿元，公募REITs（不动产投资信托基金）过往五年多完成了从“个案试点”到“常态化发行”的跨越。在此过程中，基金公司以管理人身份统筹各方，贯穿从资产筛选、产品发行到持续运营的全链条，畅通实体资产投融资循环，助力基础设施建设与实体经济提质增效，成为“公募力量”赋能实体经济的又一有力注脚。面对超百万亿元的基础设施存量资产，公募REITs的发展空间远未见顶。如何引入更多长期资金、扩大优质资产供给、提升二级市场定价效率，是迈向更高质量发展的新课题。', 'published', NULL, FALSE, 100, 1, '2026-11-15T20:44:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7bb1b3005538805e', '100001', 'news-category-finance-flash', 'em-202611163931536780-6827046860', '伊朗海军称一艘油轮在霍尔木兹海峡以东触雷后起火', '伊朗海军称一艘油轮在霍尔木兹海峡以东触雷后起火。', 'published', NULL, FALSE, 100, 1, '2026-11-15T20:24:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b34c70e8a761f55d', '100001', 'news-category-finance-flash', 'em-202611163931532525-e29f6d15c5', '物理AI产业与行情共振 公募抢抓第二波投资红利', '行情与产业共振之下，物理AI的产业叙事正在被市场重新定价。自2026年10月下旬起，沉寂已久的A股机器人板块迎来一波强势行情，多只核心标的轮番走强。Wind物理AI指数近一个月逆势上行，区间涨幅达25.73%；成份股内部行情分化显著，一个月内十余只个股涨幅超47%，上纬新材股价接近翻倍，宇树科技涨幅也达65.76%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T20:07:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6b62a51c8aa42097', '100001', 'news-category-finance-flash', 'em-202611163931534892-e6aa8d1d7c', '堪萨斯城联储主席表示 当前利率没有任何限制性', '堪萨斯城联储主席表示，当前利率没有任何限制性。', 'published', NULL, FALSE, 100, 1, '2026-11-15T19:47:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9ab64a2a56eec7ae', '100001', 'news-category-finance-flash', 'em-202611163931532683-483b645f6d', '英伟达风波冲击全球算力格局 基金研判AI投资新变量', '从一封道歉信到官宣辞任，短短数日，英伟达创始人黄仁勋的个人风波已经演变为一场席卷全球AI产业链的巨震。多家基金及相关机构认为，此次风波冲击的并非全球AI产业的长期需求，而是英伟达作为全球AI芯片龙头的确定性溢价。随着全球算力竞争格局加速重塑，产业链有望从“一枝独秀”走向“百花齐放”，国产算力也有望迎来重估契机。', 'published', NULL, FALSE, 100, 1, '2026-11-15T19:43:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a980e1b84434c7ac', '100001', 'news-category-finance-flash', 'em-202611163931534612-d429be71eb', '以军称“精准打击”哈马斯 加沙医院数十人死伤', '据巴勒斯坦通讯社11月12日报道，以色列军队当天对加沙地带南部城市汗尤尼斯的一家医院发动空袭，造成至少6人死亡、超过20人受伤。以方同日发表声明称，对该医院内的巴勒斯坦伊斯兰抵抗运动（哈马斯）高级别武装人员发动“精准打击”，目标包括哈马斯汗尤尼斯旅指挥官穆罕默德·阿布·伊斯梅尔等人。', 'published', NULL, FALSE, 100, 1, '2026-11-15T19:34:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-51bbdfbebcdffa34', '100001', 'news-category-finance-flash', 'em-202611163931534196-e9b8e647e8', '投行Phillip Securities将Palantir评级上调至买入', '投行PhillipSecurities将Palantir评级上调至买入，目标价248美元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T19:14:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2390d011da9ef64a', '100001', 'news-category-finance-flash', 'em-202611163931534516-e6ea91c7ce', '阿富汗兴都库什山区域发生5.1级地震', '据欧洲-地中海地震中心初步监测，当地时间15日22时18分，阿富汗兴都库什山区域发生5.1级地震，震源深度100公里。阿富汗首都喀布尔有震感。', 'published', NULL, FALSE, 100, 1, '2026-11-15T19:06:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e91397583bf0d6d1', '100001', 'news-category-finance-flash', 'em-202611163931534470-d993f105f9', '堪萨斯城联储主席称 若撇开能源价格 通胀仍将运行在3%', '堪萨斯城联储主席称，若撇开能源价格，通胀仍将运行在3%。美联储在通胀方面还有一些工作要做。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:46:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3b475b8628e70496', '100001', 'news-category-finance-flash', 'em-202611163931534359-ad8df6b9ca', '也门胡塞武装称用两枚弹道导弹袭击了沙特利雅得的哈立德国王机场和金融中心', '也门胡塞武装称用两枚弹道导弹袭击了沙特利雅得的哈立德国王机场和金融中心。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:35:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-063aca357dd04308', '100001', 'news-category-finance-flash', 'em-202611163931534256-5fdb0aab6c', '美能源勘探巨头Diamondback将以约50亿美元从Double Eagle收购资产组合', '美能源勘探巨头Diamondback将以约50亿美元从DoubleEagle收购资产组合。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:33:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-03a4e336a47ac5ae', '100001', 'news-category-finance-flash', 'em-202611163931534043-7d1f0ef9b8', '日本民众举行集会 反对高市政权扩军修宪', '当地时间15日晚，部分日本民众在东京新宿车站前举行集会，反对高市政权扩军修宪。集会参加者表示，近期高市政权讨论修改“安保三文件”，进一步增加防卫费支出，推动修改日本和平宪法等相关动向令人担忧，日本绝不能再次走上战争的道路。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:21:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f80727ef6c430117', '100001', 'news-category-finance-flash', 'em-202611163931533958-ab2056bbc0', '伊朗外交部：打击在巴林的美军基地是“回应侵略”', '伊朗外交部发言人巴加埃15日就地区局势、伊美关系等举行新闻发布会。巴加埃表示，伊朗当天打击在巴林的美军基地是“回应美国侵略”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:15:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-758da88cfa45391e', '100001', 'news-category-finance-flash', 'em-202611163931532356-8bb8bbf81d', '港交所今日推出离岸人民币债券指数', '继今年8月推出5年期人民币国债期货之后，11月16日，香港交易所正式推出离岸人民币债券指数。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:15:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-298a325ab86e8364', '100001', 'news-category-finance-flash', 'em-202611163931527831-ccdfab314a', '掘金中国资产 海外资金看多信号密集显现', '全球市场波动之下，海外资金对中国资产的看多信号正在密集显现：最新披露的三季度13F持仓文件显示，巴克莱、花旗、富达投资等机构对多家头部中概互联网企业进行了明显加仓；华尔街知名投资人迈克尔·巴里更是持续买入京东看涨期权和比亚迪股票。', 'published', NULL, FALSE, 100, 1, '2026-11-15T18:03:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-191f5d304339313a', '100001', 'news-category-finance-flash', 'em-202611163931531923-dbf23676a4', '据沙特方面报道 也门亚丁以西传出两声爆炸', '据沙特方面报道，也门亚丁以西传出两声爆炸。', 'published', NULL, FALSE, 100, 1, '2026-11-15T17:49:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-66444245eee85599', '100001', 'news-category-finance-flash', 'em-202611163931528193-437340aa48', '从双11看消费新趋势', '各大平台的双11购物狂欢节已全部收官，与往年相比，电商大促的竞争范式正在发生转变。', 'published', NULL, FALSE, 100, 1, '2026-11-15T17:44:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d65ed8c6303b07fb', '100001', 'news-category-finance-flash', 'em-202611163931527951-e46334eec4', '175家险企前三季度平均综合投资收益率为2.28%', '随着险企三季度偿付能力报告陆续披露，保险机构前三季度投资“成绩单”随之揭晓。《证券日报》记者统计发现，截至目前，已有175家保险机构披露了前三季度年化财务投资收益率和年化综合投资收益率。175家保险机构前三季度平均财务投资收益率为1.87%，平均综合投资收益率为2.28%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T17:30:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-84c111830e435fbe', '100001', 'news-category-finance-flash', 'em-202611153931487554-268da5d209', '房贷贴息未显著拉动住户中长贷 居民去杠杆持续', '中国人民银行发布的10月金融数据显示，当月住户贷款减少4300亿元、同比多减696亿元，居民短贷、中长贷双双走弱。与此同时，国家金融与发展实验室（NIFD）发布的最新宏观杠杆率报告显示，居民部门杠杆率从2024年一季度的62.3%下降至2026年三季度的56.4%，累计去杠杆幅度接近6个百分点。', 'published', NULL, FALSE, 100, 1, '2026-11-15T17:12:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e664100ab6db1d5f', '100001', 'news-category-finance-flash', 'em-202611163931529392-92ff881184', '证监会：进一步深化市场稳定长效机制研究 有效防范市场异常波动', '11月14日，中国证监会主席吴清在2026中国资本市场学术年会开幕式上详细阐述了新“国九条”出台以来资本市场发生的深刻变化，深入分析了大变局下资本市场的机遇挑战，并就深化资本市场重大理论和实践问题研究作出部署。他提出了六个需要进一步深化研究的方向，包括：中国资本市场发展特点规律研究、市场稳定长效机制研究、制度包容性适应性研究、人工智能与资本市场双向赋能研究、市场微观结构研究、资本市场参与全球金融治理研究，并强调需要系统构建稳的机制、稳的力量、稳的生态，有效防范市场异常波动。', 'published', NULL, FALSE, 100, 1, '2026-11-15T17:01:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fc7f02d32451f5a5', '100001', 'news-category-finance-flash', 'em-202611163931526066-fd82bbf484', '中国人民银行上调金融机构外汇存款准备金率至6%', '11月15日，中国人民银行上调金融机构外汇存款准备金率正式生效，外汇存款准备金率由现行的4%提高到6%。这是中国人民银行时隔近5年再度上调外汇存款准备金率。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:55:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9bd5c70750ed7025', '100001', 'news-category-finance-flash', 'em-202611163931527359-76e9af23eb', '数据显示：马来西亚11月1-15日棕榈油出口预计为794,717吨 下降1.0%', '数据显示，马来西亚11月1-15日棕榈油出口预计为794,717吨，下降1.0%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:55:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dff8ab9e5bf298fc', '100001', 'news-category-finance-flash', 'em-202611163931526555-08a045027c', '以色列10月CPI同比上涨1.1% 为2021年4月以来最低水平', '以色列10月CPI同比上涨1.1%，为2021年4月以来最低水平；环比下降0.1%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:40:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-456519ec5067878e', '100001', 'news-category-finance-flash', 'em-202611153931510227-c5776dd9fd', '全球航运界人士“维港对话” 聚焦中外合作新空间', '由香港航商总会主办的“维港对话”15日在港举行，60多位中外航运和经贸企业以及智库代表围绕航运政策、香港国际航运中心定位、贸易格局变化及绿色转型等议题深入交流。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:32:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c2fb4378b7ed6e59', '100001', 'news-category-finance-flash', 'em-202611153931487453-fb76e49753', '股债波动影响投资 居民“存款搬家”放缓', '央行日前披露的最新金融数据显示，今年前10个月，居民部门累计新增存款8.47万亿元，贷款减少1.46万亿元。整体来看，居民部门去杠杆与“存款搬家”仍在同步进行。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:28:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c6d6da2d1c9e7785', '100001', 'news-category-finance-flash', 'em-202611153931505281-96ecb98dfc', '“三重门”改变并购江湖 A股“卖壳”交易难了', '近一年来，A股“卖壳”江湖正悄然变天：资本运作层面，一边是早前流行的表决权委托操作方式被“束之高阁”，一边是锁价定增难以为继全面让位市价发行，再加上董事高管减持规则硬性约束，三条规则相互咬合，让前几年看似红火的卖壳交易，变得难上加难。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:27:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2fa112362cd2a681', '100001', 'news-category-finance-flash', 'em-202611153931506472-67af768a07', '集体拉升！霍尔木兹海峡传出重磅消息！', '北京时间15日晚间，加密货币市场集体拉升。比特币价格回升至6.56万美元，24小时内跌幅收窄至1.5%；此前比特币一度大跌近8%，下探至6.2万美元附近。BNB跌幅大幅收窄至1.73%，此前跌超9%；以太坊、Solana跌幅均收窄至3%以内，此前均跌超10%。与此同时，暗盘市场中部分AI硬件股亦有所拉升。消息面上，据新华社援引伊朗塔斯尼姆通讯社15日报道，伊朗议会国家安全与外交政策委员会发言人卡什卡维说，该委员会已完成霍尔木兹海峡相关方案的专业审议，就有关通行航道“与两个沿岸国家达成协议”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:21:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-76bb4e65f5dfe926', '100001', 'news-category-finance-flash', 'em-202611153931489260-0f069fadb3', '高端显卡价格跳水？记者实探深圳华强北', '近日，有报道称，近期高端显卡价格剧烈波动，部分型号产品售价从10月的1.8万元降至1.4万元。11月15日，中国证券报记者在深圳华强北实探时，有商户表示，目前显卡售价高昂，今年8月开始显卡价格涨幅显著，进入11月价格稍有回落。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:20:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-36da1a3233b154d6', '100001', 'news-category-finance-flash', 'em-202611153931484383-47331894d3', '优必选与沐曦股份合资芯片公司获5亿元融资 对标英伟达胜算几何？', '“人形机器人公司+芯片公司”的合作再次得到了市场关注。根据优必选方面的消息，近日，由优必选与沐曦股份联合发起成立的具身智能端侧芯片公司曦选创智完成了5亿元天使轮融资，投后估值达到40亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:16:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-57f19d1cbd7e33f7', '100001', 'news-category-finance-flash', 'em-202611163931525478-4fbff88833', '胡塞武装称沙特联军24小时内75次袭击也门多地', '也门胡塞武装当地时间15日晚发表声明称，过去24小时内，沙特主导的联军对也门萨达省、塔伊兹省、拉赫季省、焦夫省和马里卜省发动了75次空袭和导弹袭击。声明还称，自也门新一轮军事升级以来，沙特主导的联军累计进行的空袭和导弹袭击次数已达5095次。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:16:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a7283c13fcaf6483', '100001', 'news-category-finance-flash', 'em-202611153931504344-c231a300af', '央行发布10月金融统计数据 专家：贷款“降速提质”仍是新常态', '11月13日，中国人民银行发布的10月金融统计数据显示，今年前10个月我国人民币贷款增加11.42万亿元，贷款规模保持合理增长。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:15:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5950bfecd5df68e', '100001', 'news-category-finance-flash', 'em-202611153931483669-7083e56492', '新版医保药品目录有哪些变化？', '11月14日，2026年《国家基本医疗保险、生育保险和工伤保险药品目录》（以下简称医保药品目录）以及《商业健康保险创新药品目录》（以下简称商保创新药目录）正式公布。据悉，新版医保药品目录新增107种药品，其中51个1类新药，创新药新增数量创下历史新高。此次调整后，2026年版国家医保药品目录药品总数达到3331个。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:15:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c090b2c2a65a93f', '100001', 'news-category-finance-flash', 'em-202611163931525342-543cf96900', '美联储估算：当前用于数据中心建设的远期租赁与兜底担保规模已达约3万亿美元', '美联储报告显示，截至今年10月，美国超大规模云厂商建设数据中心的相关债务发行规模已经突破6800亿美元，较2023年全年1300亿美元的规模增长四倍。美联储估算，当前用于数据中心建设的远期租赁与兜底担保规模已经达到约3万亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:14:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7f098ad76e44903d', '100001', 'news-category-finance-flash', 'em-202611153931522691-8891672181', '管理层收购迎新进展 科创新材实控人将变更 公司前三季业绩大增、经营现金流转负', '日前，北交所上市公司科创新材（920580）发布公司控制权拟发生变更和权益变动的进展公告。2026年11月13日，蔚文绪、马军强、杨占坡、蔚文举以及于春生收到北交所出具的关于公司协议转让申请的确认函，北交所对本次协议转让的申请已完成审核并予以确认。本次交易完成后，公司实际控制人将变更为于春生。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:13:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef09a86605068bf1', '100001', 'news-category-finance-flash', 'em-202611153931484544-d1aef01ee8', '股价较年内高点下降超六成！天孚通信两日火速回购6550万元', '11月15日晚间，光通信龙头天孚通信披露股份回购进展公告。11月13日，公司通过集中竞价交易方式回购40万股，成交总金额为5095.74万元。自11月9日临时股东会通过回购议案以来，天孚通信在两个交易日内已累计回购50万股。公司累计耗资6550.08万元，已完成最低回购目标金额的六成以上。Wind数据显示，截至11月13日收盘，天孚通信股价较年内高点下降61.57%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:13:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c5bb18f42ecadb0b', '100001', 'news-category-finance-flash', 'em-202611153931486066-594f4843b2', '事关SpaceX订单！金辰股份紧急澄清', '11月15日晚间，金辰股份（603396）发布股票交易风险提示公告，公司表示，截至目前，相关报道事项与公司和SINGULUS SOLAR GmbH 无关，公司与 SINGULUS TECHNOLOGIES AG （简称SINGULUS）及SINGULUS SOLAR GmbH 暂无实质性业务往来，不会对公司当前主营业务及经营业绩构成重大影响。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-68b96af90c980b03', '100001', 'news-category-finance-flash', 'em-202611153931478431-411fd29666', '并表不足3个月 子公司获天价存储订单！游族网络：营收影响有限', '据21财经雷达，11月15日，游族网络（002174.SZ）公告，控股子公司智存合盈（深圳）科技有限公司（下称智存合盈）收到B公司闪存颗粒采购订单，金额14.28亿元（含税），约定11月20日交付。这一订单金额已超过游族网络2026年前三季度10.63亿元的营收。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-28a906d5e5ba24fb', '100001', 'news-category-finance-flash', 'em-202611153931495487-3f62e43ed5', '中国稀土重组预案出炉 拟购买中稀凉山51%股权！股票复牌', '停牌10个交易日后，中国稀土（000831）于11月13日晚披露重组预案和复牌公告。公司拟通过发行股份的方式购买实控人中国稀土集团持有的中稀（凉山）稀土有限公司（下称“中稀凉山”）51%股权，并向不超过35名特定投资者发行股份募集配套资金。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:10:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-14880f946f66b6fd', '100001', 'news-category-finance-flash', 'em-202611153931495383-99c94176f9', '最新医保目录公布 近20家药企连夜官宣', '11月15日晚间，上市药企密集发布公告，披露其药品纳入《国家基本医疗保险、生育保险和工伤保险药品目录》（2026年）（简称“国家医保目录”）的相关情况，涉及品种包括首次纳入、备注信息调整、转入常规目录管理等多种情形。新版医保目录将于2027年1月1日起正式实施。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:10:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4df8b0704c3d1a0b', '100001', 'news-category-finance-flash', 'em-202611153931483033-882933dc8a', '安世跨境争端现追加禁令 罚金最高可达3亿欧元！*ST闻泰明确不认可并将上诉', '11月15日晚间，*ST闻泰披露关于子公司经营管理情况的进展公告。其境外子公司安世半导体控股有限公司（Nexperia Holding B.V. ）与安世半导体有限公司此前向荷兰阿姆斯特丹上诉法院企业法庭提交追加临时措施申请，企业法庭于10月30日开庭审理，11月11日作出临时措施裁定。裁定责令*ST闻泰、裕成控股（*ST闻泰子公司）、安世中国及相关人员尊重并容忍管理人履职，七日内撤回向广东省高级人民法院提交的两项诉求，并不得执行东莞市中级人民法院行为保全裁定中的部分内容。汇总后，就违反上述全部义务及禁令所承担的罚金总额最高不超过3亿欧元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:09:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c476cf49c4a643d0', '100001', 'news-category-finance-flash', 'em-202611153931494479-1f758819a9', '北京发布“住房发展”五年规划 预计2030年人均建筑面积35平米', '根据中指研究院发布的数据，今年前三季度，北京二手房成交套数占新房和二手房总成交的约八成。与此同时，今年北京商品住宅用地弹性指标降至200至240公顷，较上一年再降约21%，已经是连续第四年缩量。存量成交上升、新增用地下降，北京住房市场已然出现拐点。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:09:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e6235e2ce99c5833', '100001', 'news-category-finance-flash', 'em-202611153931495088-e83792deec', '通胀和就业都在飙升 美国通胀开始扩散', '12月美联储议息会议不是加不加息的问题，而是加多少的问题，有人预测这次加息是50个基点。受10月物价和就业火爆的影响，美国十年期国债收益率从前期的高调下落到11月5日的4.834%再次涨超5%，短债表现尤为明显，美国短期国债收益率连续四个交易日大幅攀升，2年期收益率升至4.862%，累计涨幅38.8个基点，创2022年6月以来最大四日涨幅。市场普遍预期，12月加息基本已成定局，1月再度加息的概率则高达75%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:06:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fc0343c200ebb206', '100001', 'news-category-finance-flash', 'em-202611153931482918-47dfb92aa5', '涉嫌内幕交易 南卫股份实控人被刑拘！股价已提前跌停', '据21财经雷达，11月15日，南卫股份（603880.SH）一纸公告将一桩三年前的旧案重新拉回公众视野。公司当日收到实控人李平家属通知，李平因2023年在公开市场的减持行为，被公安机关以涉嫌内幕交易罪刑事拘留，案件正在调查中。此时，距江苏证监局就其内幕交易行为作出罚没合计4710.67万元的行政处罚，刚过去一年。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:03:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-658e3856566717c7', '100001', 'news-category-finance-flash', 'em-202611153931497897-3188554f31', 'BLG夺冠带火影院凌晨场！影院为何抢着做电竞生意？', '11月15日凌晨3点，全国多地电影院迎来了一批特殊的观众。为了观看远在美国纽约举行的《英雄联盟》S16全球总决赛，不少电竞迷提前抢购了69元起的影院观赛票。最终，中国赛区BilibiliGaming战队（以下简称BLG战队）战胜韩国赛区GEN战队。作为BLG的母公司，B站随即宣布向用户免费赠送7天大会员，领取页面一度因访问热度过高，提示用户稍后再试。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:02:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-20c2adfef8e062a3', '100001', 'news-category-finance-flash', 'em-202611153931482477-1a113251e5', '最高溢价96.1%！三地土拍现高溢价 分化之下释放什么信号？', '11月13日，武汉、南京、义乌三地土拍同日高溢价成交，最高溢价率96.1%。不过，整体市场并未同步升温，11月1日至12日，300城宅地平均溢价率仅1.87%，武汉、成都、苏州、南京、合肥等地多数地块仍以底价成交。受访业内人士认为，近期土地市场延续低温运行态势，房企愿意加价的对象高度集中于低密、小体量、低总价地块。展望年末，核心城市优质地块仍有望获得企业关注，但整体市场热度预计维持低位，不同城市、不同板块及不同出让条件地块的成交表现将进一步分化。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:02:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6e8084ed1e3a2eb6', '100001', 'news-category-finance-flash', 'em-202611153931482273-6a25e9d0f4', '监管靴子落地！万亿场外衍生品业务迎来规范化新阶段', '监管靴子落地，万亿场外衍生品业务迎来规范化新阶段。11月16日，由证监会发布的《衍生品交易监督管理办法（试行）》（下称《办法》）正式施行。这是证监会监管的衍生品行业首部部门规章。此前曾三次公开征求意见。据悉，截至2023年底，券商场外衍生品业务存续规模超2万亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:02:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e8eb863e1a76b843', '100001', 'news-category-finance-flash', 'em-202611153931504966-7f72a268af', '十大券商策略：市场仍处反弹格局中 把握国产替代窗口', '中信证券：小微盘缓慢的出清过程可能刚刚开始；招商证券：先守后攻，静待花开；中信建投：进二退一，把握年底修复；中国银河证券：市场向下的风险已经有所收敛；申万宏源：反弹窗口仍在延续。', 'published', NULL, FALSE, 100, 1, '2026-11-15T16:01:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-002bc9230a98e179', '100001', 'news-category-finance-flash', 'em-202611153931523755-0a545bfc94', '俄外长：欧盟不考虑俄利益“绝对行不通”', '据俄罗斯媒体15日报道，俄外长拉夫罗夫日前表示，欧盟在解决乌克兰问题方案上如不考虑俄利益，将“绝对行不通”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:57:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cee4686c4e0a6e25', '100001', 'news-category-finance-flash', 'em-202611153931522193-cf2c3ab865', '法国周末示威活动中超过400人被拘捕', '当地时间11月15日，法国内政部和巴黎检察院公布的最新数据显示，在14日举行的全国性示威活动中，共有404人被警方拘捕，其中在巴黎被拘捕的人员为134人。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:46:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d62a3dd49ede56fd', '100001', 'news-category-finance-flash', 'em-202611153931521845-f648b0246a', '天津正式供热 清洁能源占比达98.6%', '记者从天津市城市管理委员会了解到，11月15日天津正式供热，集中供热面积6.29亿平方米。今年天津供暖季清洁能源占比达到98.6%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:42:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-56912fbcc0edd1f2', '100001', 'news-category-finance-flash', 'em-202611153931520813-5f0257be10', '100多家A级旅游景区被摘牌或降级', '不久前，多地文旅主管部门陆续公布A级旅游景区复核结果，一批景区被取消等级、降级或限期整改。据不完全统计，截至2026年9月，至少22个省份的100多家A级旅游景区被摘牌或降级。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:39:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9488e1a36564624c', '100001', 'news-category-finance-flash', 'em-202611153931505358-51d7ada7ed', '单季盈利修复尚待观察 集泰股份接受调研详解公司经营情况', '11月15日，广州集泰化工股份有限公司发布公告称，公司于11月13日开展现场调研交流，多家券商、私募基金、媒体以及个人投资者参与本次活动。在活动中，公司针对市场关注的三季度业绩、盈利持续性、应收账款风险、资产减值等经营问题逐一回应。公司三季度营收同比增长、实现环比扭亏，但前三季度累计依旧亏损。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:32:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ad37f5562f468ec2', '100001', 'news-category-finance-flash', 'em-202611153931519278-a37ad4fb0d', '爱沙尼亚宣布将关闭与俄罗斯的边境口岸', '爱沙尼亚外交部长查赫克纳15日在社交媒体上宣布，爱沙尼亚自12月1日起将关闭所有和俄罗斯之间的边境口岸。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:22:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-10ecc75a2d11e410', '100001', 'news-category-finance-flash', 'em-202611153931517652-c7696024e8', '美财长贝森特表示：下个月美国通胀将大幅下降', '美财长贝森特表示，下个月美国通胀将大幅下降。贝森特对美联储喊话道：“向前看，不要盯着后视镜。”', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:17:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4ebdc195fb2de8d0', '100001', 'news-category-finance-flash', 'em-202611153931517054-12ac58119c', '俄军击中黑海一艘运送货物的乌克兰货船', '俄军击中黑海一艘运送货物的乌克兰货船。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:15:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cb8bbe3f52467ed4', '100001', 'news-category-finance-flash', 'em-202611153931513192-0c078a50ff', '明年起美联储将减少议息频次', '当地时间11月12日，美联储公布了修订后的2027年联邦公开市场委员会（FOMC）会议暂定日程，并作出重大调整——明年10月不再投票决定利率，这意味着明年美联储将少调整一次联邦基金利率。为何要进行会议机制调整？美联储主席沃什给出的答案是，要制定正确的政策，就需要在及时、定期且信息密集的节点上，对近期的经济动态进行评估。但同样重要的是，美联储需要留出专门的时间和空间来进行战略层面的审议，去重新思考那些重大问题，着眼于更长的时间跨度。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:02:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dce946aa78be14ff', '100001', 'news-category-finance-flash', 'em-202611153931514187-46b8d6ee24', '据报道 苹果押注Siri AI应用将成为眼镜产品的主要卖点', '据报道，苹果押注SiriAI应用将成为眼镜产品的主要卖点。', 'published', NULL, FALSE, 100, 1, '2026-11-15T15:01:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1e587489433ce905', '100001', 'news-category-finance-flash', 'em-202611153931512335-fd3f2217c9', '游戏《GTA VI》将于11月19日发售 机构估算预售已超1200万份 前作累计销量接近2.35亿份', '游戏《GTAVI》将于11月19日发售，机构估算预售已超1200万份，前作累计销量接近2.35亿份。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:51:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c83dedaf26d4049c', '100001', 'news-category-finance-flash', 'em-202611153931509143-044f1efa11', '美国交通部长Duffy表示：期待明日能实现航班满负荷运转', '美国交通部长Duffy表示，期待明日能实现航班满负荷运转。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:42:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aae0c3c2469e2ccf', '100001', 'news-category-finance-flash', 'em-202611153931507487-7d0097923a', '动用Token赶进度 基金公司年底上演“合同修订大战”', '今年年底，基金公司比往年更加忙碌。“要先用AI集中修订，买Token已经花了一万多。”这场让基金公司动用AI来赶进度的“大戏”是修订合同。据基金公司人士介绍，此次合同修订涉及面较广，主要包括销售费率调整、业绩比较基准、增设个人养老金Y份额以及增设投顾T类份额等四个方面。经过此轮密集修订，公募产品线将以更清晰的费率结构和更规范的业绩基准进入新的一年。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:41:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ee6504fcdde0e5f6', '100001', 'news-category-finance-flash', 'em-202611153931507323-7d57c1991f', '国家消防救援局：11月30日前完成五类问题自查自改', '11月15日，国家消防救援局发布通告，要求相关社会单位于11月30日前，完成五类严重火灾隐患及消防违法行为自查自改，涵盖通道堵塞、设施瘫痪、违规动火、培训演练缺失、多业态场所管理混乱等情形。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:34:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c8b0528bdb167659', '100001', 'news-category-finance-flash', 'em-202611153931506842-d28a49ff13', '荷兰法庭设最高3亿欧元罚金 *ST闻泰：不接受任何强制出售安世股权安排', 'ST闻泰（600745.SH）与安世半导体相关方的控制权争议有了新动向，荷兰阿姆斯特丹上诉法院企业法庭对前期*ST闻泰两家境外子公司提交的追加临时措施申请作出裁决。*ST闻泰表示，不认可本次裁定，将在法定期限内提起上诉。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:33:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9988a1234f2bda83', '100001', 'news-category-finance-flash', 'em-202611153931505434-3147c0eae2', '美国交通部长称航空出行混乱有望于明日全面恢复正常', '美国交通部长肖恩·达菲（SeanDuffy）表示，美国航空出行受扰情况有望在未来一至两天内结束。他在接受采访时称，航空出行混乱将在“今天结束或明天结束”；其随后表示，航班延误情况预计“今天恢复正常，明天全面恢复正常”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:29:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f51f40adddb7bf16', '100001', 'news-category-finance-flash', 'em-202611153931497628-1a4a985a80', '11月15日晚间公告集锦', '1、ST闻泰：企业法庭就安世境外追加临时措施申请作出裁定，公司拟上诉。2、南卫股份：实控人李平因涉嫌内幕交易罪被刑事拘留。3、游族网络：控股子公司签订14.28亿元闪存颗粒采购合同。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:24:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aff8b7c58a122b38', '100001', 'news-category-finance-flash', 'em-202611153931503510-e1ac87d7e2', '开源盘古模型openPangu-2.1-Pro正式上线华为云', '据华为云消息，11月15日，华为云MaaS模型即服务平台正式上线开源盘古模型openPangu-2.1-Pro。该模型围绕Agent开发、AI编码和推理优化三大方向进行能力升级，在深度研究、鸿蒙系统操控、鸿蒙APP开发、昇腾算子生成及推理链路优化等场景实现增强。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:17:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f67ef59e296e8e97', '100001', 'news-category-finance-flash', 'em-202611153931498427-42ea220482', '吉利星愿两年累销破百万辆 东风日产NX7搭载星火智慧座舱3.0', '近日，吉利汽车方面宣布，星愿自2024年10月上市以来24个月累计销量突破100万辆。东风标致2027款408正式上市，360THP Pro车型售价9.97万元。2027款408搭载第四代360THP全铝双涡道涡轮增压发动机+原装进口爱信第三代6速手自一体变速箱，可以提供127kW的最大功率和255N·m的峰值扭矩。', 'published', NULL, FALSE, 100, 1, '2026-11-15T14:14:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6fd05ba2e7b20270', '100001', 'news-category-finance-flash', 'em-202611153931496731-abd4b8cfec', '复星医药多款药品及新增适应症纳入国家医保目录', '11月15日晚间，复星医药公告称，根据2026年国家医保目录结果，公司及控股子公司多款药品实现首次纳入、备注信息调整，或转入常规目录管理。', 'published', NULL, FALSE, 100, 1, '2026-11-15T13:57:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-51b869d9c9ac8f3a', '100001', 'news-category-finance-flash', 'em-202611153931496633-203141503d', '尚品宅配：联合发布具身智能仿真数据集 与启元成立合资公司推进家用机器人落地', '尚品宅配(300616.SZ)发布投资者关系活动记录表公告，公司于9月联合汤元科技正式发布面向家庭服务具身智能的WorldSimReady-Home仿真数据集。', 'published', NULL, FALSE, 100, 1, '2026-11-15T13:46:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ad9946fa2e3fba63', '100001', 'news-category-finance-flash', 'em-202611153931496197-2cb6246125', '遏制资金利率下行势头 11月6个月期买断式逆回购缩量续做', '新一期买断式逆回购操作将落地。根据人民银行官网日前发布的公告，为保持银行体系流动性充裕，2026年11月16日，人民银行将以固定数量、利率招标、多重价位中标方式开展2000亿元买断式逆回购操作，期限为6个月（180天），到期日为2027年5月15日（遇节假日顺延）。', 'published', NULL, FALSE, 100, 1, '2026-11-15T13:42:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e0b5b7e3e852f21f', '100001', 'news-category-finance-flash', 'em-202611153931493211-3d477cfe56', '下周资本市场大事提醒', '1、11月16日，国家统计局将公布10月社会消费品零售总额、工业增加值、固定资产投资等经济数据。同日，国家统计局公布70城住宅销售价格月度报告。2、11月18日至19日，APEC第三十三次领导人非正式会议将在深圳举行。3、阿里、腾讯、拼多多、京东、百度、网易等中概互联头牌集中发布财报。', 'published', NULL, FALSE, 100, 1, '2026-11-15T13:36:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6586142909bd3cba', '100001', 'news-category-finance-flash', 'em-202611153931491610-8bbad2b448', '研究显示全球冰冻圈正加速退化', '一项最新国际研究显示，全球冰冻圈正加速退化，且部分变化具有不可逆性，可能给地球生态系统和人类社会带来长期风险。冰冻圈包括冰川、冰盖、永久冻土、海冰和积雪，蕴藏着地球约70%的淡水资源，但其规模正在迅速缩小。冰冻圈退化已经对全球的水安全、生态系统、基础设施等造成影响。', 'published', NULL, FALSE, 100, 1, '2026-11-15T13:33:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-db01ab91a93043ef', '100001', 'news-category-finance-flash', 'em-202611153931486430-d4c5972af3', '3连板金辰股份：相关报道事项与公司和SINGULUS SOLAR GmbH无关', '公司关注到近期市场存在关于SINGULUS TECHNOLOGIES AG的相关报道，截至目前，相关报道事项与公司和SINGULUS SOLAR GmbH无关，公司与SINGULUS TECHNOLOGIES AG及 SINGULUS SOLAR GmbH暂无实质性业务往来，不会对公司当前主营业务及经营业绩构成重大影响。', 'published', NULL, FALSE, 100, 1, '2026-11-15T13:31:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c050f6837fac8a19', '100001', 'news-category-finance-flash', 'em-202611153931478971-6d114315d5', '中信建投：市场底大概率确认 超跌修复行情开启', '中信建投研报显示，十月底低点大概率已是本轮市场底，AIAE显示估值偏低，11月是修复起点，但节奏更可能“进二退一”，修复斜率仍受一定约束。', 'published', NULL, FALSE, 100, 1, '2026-11-15T12:54:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4edaf8a603be183c', '100001', 'news-category-finance-flash', 'em-202611153931476671-a60720d120', 'AI应用爆发！主线切换还是资金轮动？基金经理最新解读', '基金经理普遍认为，近期AI应用板块爆发本质上是资金从交易拥挤的算力硬件向低位、有产业催化的应用端进行的高低切换与结构性轮动，而非彻底的主线切换；当前板块整体处于商业化早期至验证期，呈现显著的结构性分化——AI短剧、端侧AI、AI办公等少数方向已跑通变现闭环，进入收入可验证阶段，但多数公司仍处于主题炒作期，估值走在业绩前面，需警惕预期透支与盈利可持续性风险。', 'published', NULL, FALSE, 100, 1, '2026-11-15T12:40:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-959877f4d7c9a8b7', '100001', 'news-category-finance-flash', 'em-202611153931476534-4c0fa6e411', '巴勒斯坦总统呼吁制止以色列袭击', '据巴勒斯坦通讯社11月14日报道，巴勒斯坦总统阿巴斯在巴勒斯坦《独立宣言》发表38周年前夕发表声明，呼吁国际社会制止以色列袭击、定居者暴力、强迫迁移巴勒斯坦人等做法，为巴勒斯坦人民提供保护。', 'published', NULL, FALSE, 100, 1, '2026-11-15T12:26:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-93314fcb6ddf3149', '100001', 'news-category-finance-flash', 'em-202611153931472510-55c607446f', '伊朗：就霍尔木兹海峡航道与两个沿岸国家达成协议', '据伊朗塔斯尼姆通讯社15日报道，伊朗议会国家安全与外交政策委员会发言人卡什卡维说，该委员会已完成霍尔木兹海峡相关方案的专业审议，就有关通行航道“与两个沿岸国家达成协议”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T11:53:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e0ac15e5a930370e', '100001', 'news-category-finance-flash', 'em-202611153931468849-d26992a90a', '带动消费超45.4亿元 第二十五届中国上海国际艺术节闭幕', '11月15日晚，第二十五届中国上海国际艺术节闭幕。从10月17日到11月15日，本届艺术节吸引来自80多个国家和地区的近2万名艺术工作者汇聚申城，呈现了1125场的精彩演出、展览活动，覆盖线上线下观众近1300万人次，整体办节满意率达99.5%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T11:34:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-988342ef99a48f56', '100001', 'news-category-finance-flash', 'em-202611153931466463-be539b84b2', '今年深圳机场口岸出入境人员突破600万人次', '据深圳特区报，深圳边检总站最新数据显示，截至11月13日24时，今年以来深圳机场口岸出入境人员606.4万人次，同比增长5%，较去年提前15天达到600万量级，创历史同期新高，其规模位居全国大型空港第四。', 'published', NULL, FALSE, 100, 1, '2026-11-15T11:16:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3fba200f2bbe8c73', '100001', 'news-category-finance-flash', 'em-202611153931466582-40b24cdbb2', '巴林称遭伊朗无人机袭击 伊朗称“回应美国侵略”', '巴林国防军总司令部15日发表声明说，伊朗继续对巴林发动袭击，巴林防空系统当天拦截并摧毁多架伊朗无人机。伊朗外交部发言人巴加埃同日表示，伊朗打击在巴林的美军基地是“回应美国侵略”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T11:14:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6c06167e0647704c', '100001', 'news-category-finance-flash', 'em-202611153931464282-3c014416dd', '伊朗称法国指其网攻制冷系统没依据', '针对法国指责伊朗应对近期法国超市制冷系统受到网络攻击“负有责任”，伊朗外交部发言人巴加埃今天（11月15日）表示，欧洲国家似乎已经养成了一种习惯，即在提出指控时，完全不觉得有必要提供任何证据或正当理由。', 'published', NULL, FALSE, 100, 1, '2026-11-15T10:56:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a29ae5f8e34fd675', '100001', 'news-category-finance-flash', 'em-202611153931464197-8f1a81783e', '2026年度电影总票房破320亿', '截至11月15日，2026年度电影总票房（含预售）突破320亿元。暂列年度票房榜前五位的均为国产片：《飞驰人生3》《欢迎来龙餐馆》《功夫女足》《八仙！》《给阿嬷的情书》。据测算，今年以来电影全产业链产值近5000亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-15T10:49:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-307d41fa5e496871', '100001', 'news-category-finance-flash', 'em-202611153931464083-6934ef1672', '北交所高新技术企业占比超90% 日均成交额近200亿元', '11月15日，北京证券交易所迎来开市五周年。数据显示，截至11月14日，北交所上市公司达到355家，总市值约8000亿元。其中，国家级专精特新“小巨人”企业占比超过六成，高新技术企业占比超过九成，20家企业已成长为制造业单项冠军。', 'published', NULL, FALSE, 100, 1, '2026-11-15T10:41:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-207fdbed2161cdd1', '100001', 'news-category-finance-flash', 'em-202611153931463818-efc69f8e10', '十大机构论市：反弹窗口仍在延续 如何把握行业配置方向？', '本周沪指下跌0.41%，深证成指下跌1.85%，创业板指下跌1.59%。下周A股将如何运行？我们汇总了各大机构的最新投资策略，供投资者参考。', 'published', NULL, FALSE, 100, 1, '2026-11-15T10:40:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5f36a292cc731381', '100001', 'news-category-finance-flash', 'em-202611153931462561-cb55861e95', '大风降温、大范围雨雪天气轮番登场 多地将有暴雪', '今天（11月15日）至18日，两股冷空气接连影响我国，大风降温和大范围雨雪天气将轮番登场，多地气温将大面积刷新下半年来新低。与此同时，冷空气还会自北向南“清扫”雾和霾。', 'published', NULL, FALSE, 100, 1, '2026-11-15T10:12:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3eabb49dd1ab75a8', '100001', 'news-category-finance-flash', 'em-202611153931461381-ead6c91e51', '伊朗发布打击巴林美军基地视频', '伊朗伊斯兰革命卫队今天（11月15日）发布视频，伊朗无人机打击了位于巴林里法直升机基地的美军防空雷达。巴林国防军今天（11月15日）发布消息称，巴林防空系统当天拦截并摧毁了多个来自伊朗的空中目标。', 'published', NULL, FALSE, 100, 1, '2026-11-15T09:55:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ecaba52dea732323', '100001', 'news-category-finance-flash', 'em-202611153931458525-1fbbb73ef8', '北京15日起正式供热', '据北京市城市管理委员会消息，11月15日起，北京正式达标供热，供热单位要保证居民住宅卧室、起居室的室内温度不低于18摄氏度。全市46支应急抢修队伍已24小时在岗待命，做好准备应对供热突发事件。', 'published', NULL, FALSE, 100, 1, '2026-11-15T09:34:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d57ecadf15c721fb', '100001', 'news-category-finance-flash', 'em-202611153931458059-ac4caba6b6', '美国航空停摆 祸起路由器？', '美国航空大停摆事件的影响持续至15日，当天仍有大量航班被取消。美国交通部长肖恩·达菲14日说，预计航班运行到15日晚可大致恢复正常，但此事再次暴露了美国空管系统设施老化的沉疴。', 'published', NULL, FALSE, 100, 1, '2026-11-15T09:27:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-939123c3799007f0', '100001', 'news-category-finance-flash', 'em-202611153931455748-4a3a59d495', '华北制药：多个产品新纳入2026年国家医保目录', '华北制药(600812)11月15日公告，公司及下属子公司共有240个品种纳入2026年国家医保目录。此次新入选医保目录共有7个品种，分别是奥木替韦单抗注射液、他克莫司胶囊、头孢丙烯片、来特莫韦注射液、罗沙司他胶囊、甲苯磺酸艾多沙班片、那屈肝素钙注射液。', 'published', NULL, FALSE, 100, 1, '2026-11-15T09:14:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dd0e635ab7f945f6', '100001', 'news-category-finance-flash', 'em-202611153931455316-d8f676c108', '京新药业：盐酸卡立哌嗪胶囊等药品纳入国家医保目录', '京新药业(002020)11月15日公告，公司药品盐酸卡立哌嗪胶囊（商标名：京悦达）通过国家医保目录谈判，地达西尼胶囊（商标名：京诺宁）续约成功，纳入《国家基本医疗保险、生育保险和工伤保险药品目录（2026年）》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T09:05:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f4aa5acb2fd2e098', '100001', 'news-category-finance-flash', 'em-202611153931455049-de63383801', '华北制药：240个品种纳入2026年国家医保目录 7个新品种入选', '华北制药(600812.SH)公告称，公司及下属子公司共有240个品种纳入2026年国家医保目录，其中甲类113个、乙类127个。主要产品注射用哌拉西林钠他唑巴坦钠、注射用盐酸去甲万古霉素、阿莫西林胶囊等继续入选。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:59:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-481d7c6da442dd3d', '100001', 'news-category-finance-flash', 'em-202611153931454780-72bdb4239d', '意大利对元宇宙公司巨额罚款', '意大利个人数据保护局11月14日宣布，对美国元宇宙平台公司（Meta）处以8.05亿欧元（约合人民币59亿元）的罚款，原因是该公司在未获用户同意或者未告知用户的情况下，访问安卓系统用户手机中存储的照片和视频。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:45:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6e6c132d8e0807c6', '100001', 'news-category-finance-flash', 'em-202611153931453422-8e48f6c08c', '通化金马：琥珀酸安维吖啶片首次纳入国家医保目录', '通化金马(000766)11月15日公告，公司自主研发、具有完全自主知识产权的化学1类创新药琥珀酸安维吖啶片，首次被纳入《国家基本医疗保险、生育保险和工伤保险药品目录（2026年）》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:34:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9341e82f591cbdc6', '100001', 'news-category-finance-flash', 'em-202611153931453318-5e6123cf62', '游族网络：控股子公司签订14.28亿元闪存颗粒采购合同', '游族网络11月15日公告，智存合盈于2026年11月2日与B公司签订了《采购合同》，约定B公司以订单的形式，向智存合盈采购闪存颗粒产品，合同自双方盖章之日起生效，有效期2年。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:31:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ae4e1277c0f22ca6', '100001', 'news-category-finance-flash', 'em-202611153931453217-5f8cdc173e', '百利天恒：注射用伦康依隆妥单抗纳入国家医保目录', '百利天恒(688506.SH)公告称，公司全资子公司自主研发的全球首创双抗ADC药物注射用伦康依隆妥单抗，上市首年即通过国家医保谈判，成功纳入《国家医保目录(2026版)》，协议有效期自2027年1月1日至2028年12月31日，支付范围限既往经至少二线系统化疗且使用过PD-1/PD-L1抑制剂治疗失败的复发/转移性鼻咽癌成人患者。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:29:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3cd076e4dccfb0ad', '100001', 'news-category-finance-flash', 'em-202611153931453194-3334a36dfa', '创业黑马：拟申请1.33亿元并购贷款并质押标的股权', '11月15日，创业黑马公告称，公司拟向中国民生银行北京分行申请1.33亿元并购贷款，用于先行支付收购北京版信通技术有限公司100%股权的现金对价，贷款期限5年，年利率2.51%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:29:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-805128bbd49fb393', '100001', 'news-category-finance-flash', 'em-202611153931452848-d7b5e57485', '长春高新：控股子公司金蓓欣新纳入国家医保目录', '11月15日，长春高新公告，根据国家医保局、人社部发布的《国家基本医疗保险、生育保险和工伤保险药品目录》，公司控股子公司长春金赛药业有限责任公司自主研发的金蓓欣被新纳入国家医保目录。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:25:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-884aa192ccbe2abc', '100001', 'news-category-finance-flash', 'em-202611153931452740-086d23a87c', '康缘药业：独家品种参蒲颗粒、泻白散颗粒首次纳入国家医保目录', '康缘药业(600557)11月15日公告，公司独家品种参蒲颗粒、泻白散颗粒，首次通过谈判纳入《国家基本医疗保险、生育保险和工伤保险药品目录（2026年）》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:25:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2bc4f60eb6f2e566', '100001', 'news-category-finance-flash', 'em-202611153931451519-15eb9be85c', '微芯生物：产品西格列他钠片续约纳入国家医保目录', '11月15日，微芯生物发布公告，根据国家医保局、人力资源社会保障部关于印发《国家基本医疗保险、生育保险和工伤保险药品目录》以及《商业健康保险创新药品目录》（2026年）的通知【医保发〔2026〕29号】，公司产品西格列他钠片（双洛平）成功续约《国家医保目录》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:09:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bdb5b19ba1dabf02', '100001', 'news-category-finance-flash', 'em-202611153931450993-13c240a6a0', '恒瑞医药：多款药品纳入国家医保目录', '恒瑞医药(600276.SH)公告称，公司部分产品纳入国家医保目录。泽美妥司他片、鲁兹诺雷钠片、恒格列净瑞格列汀二甲双胍缓释片(II)首次纳入；注射用瑞康曲妥珠单抗新增适应症纳入；羟乙磺酸达尔西利片续约并新增适应症；另有脯氨酸恒格列净片等7款药品续约成功。', 'published', NULL, FALSE, 100, 1, '2026-11-15T08:03:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-709e7abd7eb52010', '100001', 'news-category-finance-flash', 'em-202611153931450585-22dce08604', '苑东生物：2类改良型新药氨酚羟考酮缓释片首次纳入国家医保目录', '苑东生物(688513)11月15日公告，公司自主研发的2类改良型新药氨酚羟考酮缓释片通过了医保谈判，首次被纳入《国家基本医疗保险、生育保险和工伤保险药品目录（2026年）》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:59:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3c53363e07ee39aa', '100001', 'news-category-finance-flash', 'em-202611153931425654-fca794cb09', '艾力斯：伏美替尼新增适应症纳入国家医保目录', '艾力斯(688578.SH)公告称，公司产品甲磺酸伏美替尼片EGFR20号外显子插入突变非小细胞肺癌二线治疗适应症被新增纳入国家医保目录，协议有效期为2027年1月1日至2027年12月31日。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:55:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-681f64f467bf592c', '100001', 'news-category-finance-flash', 'em-202611153931425389-3f4e3bb892', '君实生物：拓益新增适应症纳入国家医保目录', '君实生物(688180.SH)公告称，公司产品特瑞普利单抗注射液(商品名：拓益)联合维迪西妥单抗用于HER2表达的局部晚期或转移性尿路上皮癌的适应症，成功纳入《国家基本医疗保险、生育保险和工伤保险药品目录(2026年)》乙类范围，新版目录将于2027年1月1日起实施。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:54:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9bb530e9d6865d1a', '100001', 'news-category-finance-flash', 'em-202611153931425422-5d8d53e238', '复星医药：多款药品新纳入国家医保目录', '复星医药(600196.SH)公告称，根据2026年国家医保目录，公司及控股子公司多款产品获首次纳入、备注信息调整或转入常规目录管理。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:53:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-12ae2cd8a95f6bee', '100001', 'news-category-finance-flash', 'em-202611153931425539-e9b44b2621', '伊朗一辆大巴倾覆致12人死亡', '据伊朗伊斯兰共和国通讯社15日报道，伊朗伊拉姆省阿卜达南市14日发生大巴倾覆事故，已致12人死亡。报道援引当地司法部门消息说，涉事大巴当时载有一家石油天然气公司的员工。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:53:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-57c9675f8b46d118', '100001', 'news-category-finance-flash', 'em-202611153931425289-0e25337b05', '禾元生物：重组人白蛋白注射液纳入2026年国家医保目录', '禾元生物(688765.SH)公告称，公司自主研发的1类创新药奥福民重组人白蛋白注射液(水稻)成功纳入《国家基本医疗保险、生育保险和工伤保险药品目录(2026年)》，新版目录自2027年1月1日起实施。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:51:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-67deeffd1359d77d', '100001', 'news-category-finance-flash', 'em-202611153931425119-c0bf488315', '天孚通信：11月13日回购40万股耗资5096万元 成交价124.19元/股-134.53元/股', '天孚通信(300394.SZ)公告称，公司于2026年11月13日通过集中竞价方式回购股份40万股，占公司总股本的0.0367%，最高成交价为人民币134.53元/股，最低成交价为人民币124.19元/股，成交总金额5095.74万元。截至2026年11月13日，公司累计回购股份50万股，占公司总股本的0.0458%，成交总金额6550.08万元。本次回购股份将用于注销并减少注册资本。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:47:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c9204007ec85d1a7', '100001', 'news-category-finance-flash', 'em-202611153931425047-ad141bea27', '方大集团：2026年限制性股票激励计划授予登记完成', '11月15日，方大集团公告称，公司2026年限制性股票激励计划授予登记完成，授予日为2026年10月22日，登记完成日为2026年11月13日，授予价格1.88元/股，授予登记数量1650.005万股，授予对象共128人，股票来源为公司从二级市场回购的A股普通股。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:42:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-38329d5f6580f504', '100001', 'news-category-finance-flash', 'em-202611153931424953-e94a88964d', '白云机场：10月旅客吞吐量809.74万人次 同比增5.96%', '11月15日，白云机场公告称，2026年10月完成飞机起降5.12万架次，同比增长5.08%；旅客吞吐量809.74万人次，同比增长5.96%；货邮吞吐量20.94万吨，同比下降5.04%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:39:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-960cdf491bf5df38', '100001', 'news-category-finance-flash', 'em-202611153931424780-d3f3cbcc68', '格林美：236.57万股限制性股票11月18日上市流通', '11月15日，格林美公告称，公司2024年限制性股票激励计划第二个解除限售期解除限售条件已部分成就，本次符合解除限售条件的激励对象共161人，可解除限售的限制性股票数量为236.5718万股，占公司总股本的0.0464%，上市流通日期为2026年11月18日。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:37:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b40db5bac221e05a', '100001', 'news-category-finance-flash', 'em-202611153931424856-3ac47ecf79', '首药控股：康特替尼颗粒首次纳入国家医保药品目录', '11月15日，首药控股公告称，公司自主研发的1类创新药康特替尼颗粒（商品名：首要泽）通过国家医保谈判，首次被纳入《国家基本医疗保险、生育保险和工伤保险药品目录（2026年）》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:36:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4e996d3b3ad96b94', '100001', 'news-category-finance-flash', 'em-202611153931424490-7a7851b008', '葛兰素史克：两款创新生物制剂纳入新版国家医保目录', '葛兰素史克（GSK）宣布，两款呼吸创新生物制剂易适来（德莫奇单抗）与新可来（美泊利珠单抗注射液）成功纳入《国家基本医疗保险、生育保险和工伤保险药品目录（2026年）》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:29:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ae4e2ef1ed691154', '100001', 'news-category-finance-flash', 'em-202611153931424345-2a0d33c279', '巴林称拦截摧毁伊朗多个空中目标', '巴林国防军今天（11月15日）发布消息称，巴军防空系统当天拦截并摧毁了来自伊朗的“多个”空中目标。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:22:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-eab4a21c9710ac6d', '100001', 'news-category-finance-flash', 'em-202611153931422385-93fcec6297', '周末要闻汇总：吴清提出资本市场六个“进一步深化”', '1、中美经贸磋商机制项下贸易理事会首次会议举行；2、央行公布10月金融统计数据报告；3、吴清提出资本市场六个“进一步深化”；4、两部门印发《“十五五”新型储能实施方案》。', 'published', NULL, FALSE, 100, 1, '2026-11-15T07:00:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5fa645a5f123125f', '100001', 'news-category-finance-flash', 'em-202611153931422255-af80655805', '中专生拍出爆火AI短片 海外播放百万级、单集成本千元', '日前，一部中国创作者制作的AI短片在海外互联网率先出圈，在YouTube、TikTok等主流视频平台上，单集作品最高播放量在百万级。该片名为《爱上大难不死的男孩的女孩》，为《哈利·波特》二创，由账号名为Foyege弗曳哥的博主创作，凭借脑洞十足的故事设定与细腻的AI画面表现，其让欧美歌手JVKE追到视频下方致谢、让好莱坞制片人PJ Accetturo主动递出橄榄枝。', 'published', NULL, FALSE, 100, 1, '2026-11-15T06:58:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c0cb4830c15120ca', '100001', 'news-category-finance-flash', 'em-202611153931422088-1c0c876b71', '中科曙光万伟：需要通过系统级创新 实现更大规模计算资源高效协作', '11月15日，第八届中国超级算力大会（ChinaSC2026）暨中国智能计算产业联盟理事会年会在北京举行。', 'published', NULL, FALSE, 100, 1, '2026-11-15T06:54:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f4e8388fc86481ec', '100001', 'news-category-finance-flash', 'em-202611153931421962-2338b3c5ae', '美军嘉手纳基地开始部署F15EX', '日本媒体报道，美军今天（11月15日）宣布，作为F-15战机后继机型的F-15EX战机已抵达冲绳县嘉手纳基地并开始部署。这是该战机首次部署在美空军的海外基地。', 'published', NULL, FALSE, 100, 1, '2026-11-15T06:45:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e08f289995e5aa3c', '100001', 'news-category-finance-flash', 'em-202611153931417449-1805902e52', '美国华人总动员！超13万人署名请求黄仁勋回归', '11月13日起，记者所在的多个美国华人微信群里，开始流传一个链接：standwithjensen.com。群主一遍遍转发，呼吁群友联署，请求英伟达董事会让黄仁勋回来。截至美东时间11月14日晚间9点，签署人数已逼近13万并仍在快速增长。', 'published', NULL, FALSE, 100, 1, '2026-11-15T05:50:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0d56a3a24c2e62fd', '100001', 'news-category-finance-flash', 'em-202611153931417568-7468c2dfe9', '中科曙光万伟：高速互连可破解算力集群规模瓶颈', '11月15日，在第八届中国超级算力大会（ChinaSC2026）暨中国智能计算产业联盟理事会年会上，中科曙光高速网络互联产品部总工程师万伟提出高速互连是算力基础设施实现规模扩展的关键，需要通过系统级创新，让更大规模的计算资源高效协作。', 'published', NULL, FALSE, 100, 1, '2026-11-15T05:48:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8aa7023fb5db3259', '100001', 'news-category-finance-flash', 'em-202611153931417371-57e1b64a98', '提前22天！宁波舟山港年集装箱吞吐量再破4000万标准箱', '据浙江发布，自2025年首次跨越4000万箱后，今年宁波舟山港年集装箱吞吐量再次站上这一台阶，比去年突破时间提前了22天。', 'published', NULL, FALSE, 100, 1, '2026-11-15T05:48:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b97c3fde941f416b', '100001', 'news-category-finance-flash', 'em-202611153931415060-424f3dde39', '徐工2000吨级起重机落地泰国', '徐工集团消息，近日，徐工XCA2000全地面起重机在泰国完成交付，刷新当地全地面起重机吨位纪录。', 'published', NULL, FALSE, 100, 1, '2026-11-15T05:35:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-30709dd3b57e919e', '100001', 'news-category-finance-flash', 'em-202611153931414295-abdac0f791', '美国迈阿密机场两架飞机发生地面碰撞 致2人轻伤', '当地时间11月14日，美国迈阿密国际机场停机坪上两架飞机发生碰撞，造成两人轻伤。机场公关总监表示，事故造成两人受伤，两名伤者伤势较轻，已在现场接受了消防救援人员的救治。目前，该局正在对这起碰撞事故展开调查。', 'published', NULL, FALSE, 100, 1, '2026-11-15T05:28:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9a10e67655ac0c7e', '100001', 'news-category-finance-flash', 'em-202611153931413838-b8ff1b6856', '国际能源署署长：中国已成清洁能源技术领域大国', '《联合国气候变化框架公约》第三十一次缔约方大会期间，能源转型成为各国代表关注的一大焦点。国际能源署署长法提赫·比罗尔在接受记者专访时表示，如何统筹能源安全与绿色转型是各国面临的共同课题，中国清洁能源的发展及绿色产业优势将帮助更多国家推进绿色低碳转型。', 'published', NULL, FALSE, 100, 1, '2026-11-15T05:17:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0d4377e0a20e4ff0', '100001', 'news-category-finance-flash', 'em-202611153931412027-3e5845f4c4', '意大利因照片隐私问题对元宇宙罚款超8亿欧元', '意大利数据保护局14日发布公告说，已对元宇宙平台公司（Meta）旗下爱尔兰公司处以8.05亿欧元（约合8.87亿美元）罚款，原因是该公司在未经安卓用户同意情况下获取手机相册信息。', 'published', NULL, FALSE, 100, 1, '2026-11-15T04:54:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b66b564edee9fc1c', '100001', 'news-category-finance-flash', 'em-202611153931411229-552ce12036', '美军：已护航超17亿桶原油通过霍尔木兹海峡', '美军中央司令部当地时间14日在社交媒体发文称，美国空军的F-16战斗机在中东地区水域上空巡逻。在美方的保护下，海湾地区的合作伙伴已通过霍尔木兹海峡运输了超过17亿桶原油。', 'published', NULL, FALSE, 100, 1, '2026-11-15T04:35:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-df6ea30fd613eee2', '100001', 'news-category-finance-flash', 'em-202611153931410378-bcde550bac', '伊朗革命卫队称打击巴林美军雷达设施', '据伊朗媒体15日报道，伊朗伊斯兰革命卫队当天称打击了位于巴林里法的美军雷达设施。', 'published', NULL, FALSE, 100, 1, '2026-11-15T04:23:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4f5c4b2c6a86b7e1', '100001', 'news-category-finance-flash', 'em-202611153931410210-59392a776d', '韩国在野党放话：明年春天结束李在明执政', '韩国最大在野党国民力量党11月14日在釜山举行大规模集会，抗议执政党共同民主党推动《捏造起诉特别检察官法》，要求总统李在明行使否决权。国民力量党党首张东赫在现场要求李在明下台，另一名资深议员甚至喊出“明年春季结束李在明政府执政”的口号。', 'published', NULL, FALSE, 100, 1, '2026-11-15T04:23:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aa94d597821bcee9', '100001', 'news-category-finance-flash', 'em-202611153931409496-ff01ef4ac3', '美团明确：11月16日至20日 深圳全城骑手订单超时免责', '为做好会议期间城市配送服务和交通秩序保障，美团同日推出骑手保障十项举措，围绕配送减负、收入保障、交通安全和骑手形象等方面作出专项安排。', 'published', NULL, FALSE, 100, 1, '2026-11-15T04:00:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-67421ed8419f5587', '100001', 'news-category-finance-flash', 'em-202611153931409512-61caf637fc', '余承东：大折叠已成为千万人的主力机', '11月15日，华为常务董事、产品投资评审委员会主任、终端BG董事长余承东在其个人社交平台表示，今年是华为MateX系列走过的第八年，现在大折叠已成为千万用户的主力机型，新一代华为MateX8将在屏幕、影像和性能体验上有新的突破。', 'published', NULL, FALSE, 100, 1, '2026-11-15T03:55:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-10bb00d16eb1801f', '100001', 'news-category-finance-flash', 'em-202611153931408897-383a685648', '小米泰坦合金2.0低碳技术突破：材料碳排放降至1/14', '在第31届联合国气候变化大会（COP31）上，小米宣布其泰坦合金2.0材料与小米SU7整车完成EPD（环境产品声明）国际认证。', 'published', NULL, FALSE, 100, 1, '2026-11-15T03:42:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0f0abf6f1236226b', '100001', 'news-category-finance-flash', 'em-202611153931408452-36ce6faffa', '联合国气候机构负责人敦促加快谈判进程', '为期两周的《联合国气候变化框架公约》（以下简称《公约》）第三十一次缔约方大会（COP31）正在土耳其安塔利亚举行。《公约》秘书处执行秘书西蒙·斯蒂尔14日表示，本次大会已过半程，各方应迅速聚焦核心难点议题，加快谈判进程。', 'published', NULL, FALSE, 100, 1, '2026-11-15T03:28:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e0602ef5c4978be7', '100001', 'news-category-finance-flash', 'em-202611153931408017-e2247c77ee', '北京拟为“粮食经纪人”立规 一线从业者讲述：售粮款现在都现结', '粮食经纪人直接向种粮农民批量购粮，是活跃粮食流通的重要力量，但经营行为也需规范。近日，北京市粮食和物资储备局起草的《北京市粮食经纪人管理服务办法（征求意见稿）》正在公开征求意见，拟对粮食经纪人收购、储存、运输、销售各环节立规矩，明确不得拖欠售粮款、不得掺杂使假、不得囤积居奇，并要求建立经营台账且保存不少于3年。', 'published', NULL, FALSE, 100, 1, '2026-11-15T03:19:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a8d5d08b1543e942', '100001', 'news-category-finance-flash', 'em-202611153931407943-777474bef5', '三川智慧赴郑州水务集团谋划新一轮全方位战略合作', '据三川智慧消息，近日，三川智慧副总裁、杭州三川国德董事长钱龙带队赴郑州水务集团拜访交流。双方围绕智慧水务数字化转型、数据要素价值释放、产业协同共建等方向深入磋商，谋划新一轮全方位战略合作。', 'published', NULL, FALSE, 100, 1, '2026-11-15T03:17:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-593f2924b885138c', '100001', 'news-category-finance-flash', 'em-202611153931406161-5bccf38935', 'SK集团会长崔泰源：我们所有子公司都要蜕变为AI企业', '据韩媒《每日经济新闻》今天报道，SK 集团会长崔泰源最近表示，他们希望打破现有框架，将 SK 集团所有子公司蜕变为 AI 企业。他认为 SK 集团应将业务范围从 AI 半导体、基础设施和能源进一步扩展至服务领域，构建出持续增长的“AI 飞轮”模式。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:56:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d36fcf56622e7a4e', '100001', 'news-category-finance-flash', 'em-202611153931406025-cf7b27659d', '中国国际商会副秘书长徐梁：深圳将设置特色参访点 拓展经贸交流合作空间', '中国国际商会副秘书长徐梁表示，深圳将为此次峰会参会代表安排两条官方参访路线、八条推荐路线的30个特色参访点，涵盖创新企业、科技园区、城市地标等场景。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:53:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5237bf464194ca9a', '100001', 'news-category-finance-flash', 'em-202611153931405329-7c0a5780ac', '啃凉透的汉堡、8个多小时里才上一次厕所：记者体验网约车司机被算法支配的一天', '随着以平台经济为代表的新业态蓬勃兴起，我国依托互联网平台就业的网约配送员、网约车司机等新就业形态劳动者已达8400万人。与此同时，平台算法规则像一根无形的指挥棒，左右着千万劳动者的接单节奏。“被困在算法里”“想停停不下来”，成为许多骑手和司机的真实感受。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:53:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8e0ad62e27d90af0', '100001', 'news-category-finance-flash', 'em-202611153931404697-38c0bb754b', '上海科技大学、同济大学、上海外国语大学、上海海事大学……上海的大学课堂“AI浓度”越来越高了', '2027年上海春季高考，上海科技大学首次加入招生行列，并开设“芯片与智能班”，在春季衔接学期开设具身智能设计思维、创新创业经济学等三门前沿课程；前不久，上海应用技术大学一口气推出11个与人工智能相关的特色微专业；与此同时，全国首个工程智能（AI4E）千卡工科智算集群落地同济大学，学校开始向全校师生免费发放Token……上海高校的“AI浓度”越来越高了。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:48:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5dac3c1bcee42334', '100001', 'news-category-finance-flash', 'em-202611153931404090-14328e8227', '周小川给资本市场支招：装个低通滤波器 让交易频率与基本面适配', '周小川表示，过高频交易容易脱离基本面、放大正反馈和市场波动，可借鉴控制理论思路，通过调节盈利空间、信息披露节奏、撮合机制等方式为市场设置 “低通滤波器”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:34:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e2e208d3e26e4aa8', '100001', 'news-category-finance-flash', 'em-202611153931402738-3663788893', '受雨雪天气影响 甘肃多条高速公路实行临时交通管制', '截至11月15日8:30，甘肃省高速公路酒泉部分路段零星小雪，天水、陇南、平凉、庆阳部分路段小雨，其余路段天气阴或多云。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:23:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-93e17b6fa359f081', '100001', 'news-category-finance-flash', 'em-202611153931401441-9e27f8e1bd', '雄忻高铁山西段进入联调联试阶段 预计2027年3月底具备开通条件', '记者从国铁太原局获悉，11月15日早晨，随着55052次检测列车从山西省忻州西站驶出，标志着雄忻高铁山西段正式进入联调联试阶段。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:19:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0ce622479ffc2d22', '100001', 'news-category-finance-flash', 'em-202611153931400979-ef49769996', '12位APEC经济体领导人将出席APEC工商领导人峰会', '在15日举行的2026年APEC工商界活动专题新闻发布会上，中国贸促会副会长李庆霜介绍，作为APEC领导人会议周的重要组成部分，2026年APEC工商领导人峰会将于11月17日至18日在深圳前海国际会议中心举办，习近平主席和澳大利亚、加拿大、智利、中国香港、印度尼西亚、韩国、马来西亚、墨西哥、俄罗斯、泰国、越南APEC经济体领导人将出席峰会并发表演讲、致辞或参与专题研讨。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:10:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7ba76f2cb2a5374b', '100001', 'news-category-finance-flash', 'em-202611153931400532-8d5c14b9c9', '英伟达两大股东向董事会发公开信：要求考虑让黄仁勋回归', '北京时间11月15日，据CNBC报道，英伟达的两大股东呼吁董事会考虑公司未来领导层的所有可能方案，其中包括“黄仁勋的回归可能性”。', 'published', NULL, FALSE, 100, 1, '2026-11-15T02:07:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4b07e7304d6de18c', '100001', 'news-category-finance-flash', 'em-202611153931399689-d0fab08199', '沙特主导的多国联军称拦截摧毁两枚射向利雅得的弹道导弹', '当地时间11月15日，沙特主导的多国联军发言人在社交媒体上发布消息称，联军防空部队拦截并摧毁了也门胡塞武装向沙特首都利雅得方向发射的两枚弹道导弹。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:55:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c7690075cc18af35', '100001', 'news-category-finance-flash', 'em-202611153931398833-6333df5f88', '巴林发布警报提示潜在威胁', '巴林内政部15日发布有关潜在威胁的警报，呼吁民众保持冷静，前往附近的安全地点。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:52:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c2118be644b94675', '100001', 'news-category-finance-flash', 'em-202611153931397955-6c95becb0e', '比特币跌至62000美元，日内跌超5%', '比特币跌至62000美元，日内跌超5%。以太坊日内跌超6%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:47:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-30cae949c6c03771', '100001', 'news-category-finance-flash', 'em-202611153931397386-5abf289aa1', '今天零时起北方多地正式集中供热', '今天（15日），北方地区进入全面供暖季。北京、天津、石家庄、济南、郑州以及陕西关中地区等地今天零时起正式集中供热。陕西关中多地持续优化供热结构，大力发展地热等清洁供暖。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:39:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6db924c06bc126df', '100001', 'news-category-finance-flash', 'em-202611153931395125-bac4a55633', '沙特首都利雅得传出剧烈爆炸声', '当地时间11月15日凌晨，沙特首都利雅得传出多声剧烈爆炸声，居民收到经由手机程序发布的防空警报。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:16:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7f3119d4f51e228b', '100001', 'news-category-finance-flash', 'em-202611153931395066-59f9c213f6', '比特币跌破63000美元 日内跌超4%', '比特币跌破63000美元，日内跌超4%。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:10:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-29c9151939c97042', '100001', 'news-category-finance-flash', 'em-202611153931394931-c3eedba1e5', '金融机构外汇存款准备金率今起提高至6%', '今天，中国人民银行上调金融机构外汇存款准备金率正式生效，外汇存款准备金率由现行的4%提高到6%。本次上调有助于促进外汇市场供求平衡，打破人民币升值预期的自我实现。', 'published', NULL, FALSE, 100, 1, '2026-11-15T01:03:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-14010aaac7cd31f7', '100001', 'news-category-finance-flash', 'em-202611153931393312-228ec93187', 'SpaceX首次实现“筷子夹飞船” 马斯克称“飞船状态很好”', '北京时间11月15日，在SpaceX星舰第十五次飞行中，星舰二级飞船返回得克萨斯州星港，在完成着陆点火和姿态翻转后，成功被发射塔“筷子”机械臂捕获。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:46:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef2d535dcea3bdd9', '100001', 'news-category-finance-flash', 'em-202611153931393252-a0d8305415', '旗下战队BLG夺冠 B站宣布大会员免费送', '11月15日，哔哩哔哩旗下战队BLG拿下S16全球总决赛冠军。为了分享这份喜悦，哔哩哔哩宣布为所有人送大会员，今日中午12点起登录B站，搜索“大会员”即可免费领取，站内直接到账。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:44:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a3db555971c5edc2', '100001', 'news-category-finance-flash', 'em-202611153931392383-4cdafefede', '两股冷空气接连来袭 局地降幅超12℃', '今天（11月15日）至18日，两股冷空气接连影响我国，中东部大部地区气温累计下降6至10℃，局地降幅将超12℃。降温过后，气温将大面积刷新今年下半年来新低，北方气温低点在17日前后，南方则在18日前后。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:33:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c23d38ba311c5fa0', '100001', 'news-category-finance-flash', 'em-202611153931392069-afb87241b4', '1至10月份国家铁路发送货物34.2亿吨', '从国铁集团获悉，今年前十个月，国家铁路累计发送货物34.2亿吨，重点物资运输保障有力、铁路物流产品持续升级、中欧（亚）班列高质量开行。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:33:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6546b019d2a03db2', '100001', 'news-category-finance-flash', 'em-202611153931391487-62b41e932f', '美国纽约州长就停飞事件要求美交通部长辞职', '14日，美国纽约州民主党籍州长霍楚尔发表声明，要求美国交通部长达菲辞职，否则应由总统特朗普将其免职。霍楚尔在声明中称：“从长期存在的空中交通管制员短缺问题，到接二连三的通信系统故障，在达菲任内，美国航空系统的严重失误已经成为一种常态。”', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:19:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dde1ccb855bd7036', '100001', 'news-category-finance-flash', 'em-202611153931391282-07b52a9f44', '比特币跌至三个月低点 加密货币持续承压', '加密货币周末大幅下挫，比特币跌至63000美元上方的三个月低点，大量杠杆多头头寸遭到强平。这一最大数字资产周六在美国时段下跌5.7%，周日在亚洲交易时段继续走低，最低触及63311美元，再跌1.7%，创下8月17日以来最低水平。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:17:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5575b0f90dd38ba8', '100001', 'news-category-finance-flash', 'em-202611153931391327-0dd8a6e3a1', '航行警告！渤海海峡黄海北部执行军事任务', '据中国海事局网站消息，大连海事局发布航行警告，11月15日16时至29日16时，渤海海峡黄海北部部分海域执行军事任务，禁止驶入。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:16:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4d0365d33d394bfd', '100001', 'news-category-finance-flash', 'em-202611153931390089-9ddf8870ca', '时隔5年再捧冠军奖杯 英雄联盟全球总决赛中国战队夺冠', '在刚刚结束的英雄联盟全球总决赛决赛中，中国BLG战队战胜韩国Gen战队，加冕S16总冠军，这是中国战队时隔五年再度捧起S赛冠军奖杯。', 'published', NULL, FALSE, 100, 1, '2026-11-15T00:02:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4aef78c0821d7fa7', '100001', 'news-category-finance-flash', 'em-202611153931389645-fd598c12ee', '俄称打击乌能源和交通基础设施 乌称击退俄军进攻', '俄罗斯国防部14日通报称，过去一天，俄军控制了扎波罗热地区一处居民点，并对142处区域的乌军目标实施打击，打击目标包括：能源和交通基础设施、无人机生产车间及储存和发射场地、弹药仓库等。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:54:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8163edb8ced3384e', '100001', 'news-category-finance-flash', 'em-202611153931389450-b3174813a4', '美军中央司令部：已护航超17亿桶原油通过霍尔木兹海峡', '当地时间14日，美军中央司令部称，在美方的保护下，海湾地区的合作伙伴已通过霍尔木兹海峡运输超过17亿桶原油。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:47:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4e755bbc0ef8499b', '100001', 'news-category-finance-flash', 'em-202611153931389516-405a6134af', '联合国呼吁恢复霍尔木兹海峡化肥运输', '联合国项目事务厅执行主任达席尔瓦14日表示，伊朗和美国应立即允许化肥运输通过霍尔木兹海峡，以缓解脆弱国家面临的危机。达席尔瓦表示，冲突前全球三分之一的化肥经霍尔木兹海峡运输，自今年美国和伊朗爆发冲突以来，全球化肥价格已上涨约30%。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:46:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0adc575d6819091a', '100001', 'news-category-finance-flash', 'em-202611153931389187-1ad759be3d', '北交所开市五周年 总市值约8000亿元', '今天（15日），北京证券交易所迎来开市五周年。截至目前，北交所有上市公司355家，总市值约8000亿元。上市公司中，国家级专精特新“小巨人”企业占比超六成，高新技术企业占比超九成，20家已成长为制造业单项冠军。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:28:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-893ccc22ea5e2218', '100001', 'news-category-finance-flash', 'em-202611153931388625-09ef890780', '踏空、重仓暴跌 基金经理该不该道歉？巴菲特给出答案！', '自今年5月份以来，AI板块个股的暴涨暴跌已是常态，资金分歧严重。不过，暴涨暴跌都会形成重大考验，今年上半年部分投资经理因为踏空AI而道歉，但伴随着5月份以来的一轮相对较大幅度的调整，又见一拨投资经理因重仓AI而道歉。那么，在投资上究竟是什么错误值得道歉，什么原因导致的净值落后无需道歉？巴菲特在60多年的投资生涯中给出了范本，那就是不因踏空某个赛道而道歉，不为净值暂时落后而道歉。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:22:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-58e5ca8a67fae020', '100001', 'news-category-finance-flash', 'em-202611153931388182-fe07564dea', '中央气象台继续发布大雾橙色预警', '中央气象台11月15日06时继续发布大雾橙色预警：预计，11月15日早晨至上午，北京中南部、天津、河北中南部和东部、山东中北部和西部、河南大部、安徽中北部、江苏西部、吉林中部、辽宁中部、湖南东部、广西中东部、广东西部等地的部分地区有大雾，其中，北京东南部、天津大部、河北中南部、山东中北部和西部、河南中北部、安徽中北部、江苏西部、广西东南部、广东西部等地的部分地区有浓雾或强浓雾，局地有能见度低于50米的特强浓雾。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:12:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5e86e50bf6fdca61', '100001', 'news-category-finance-flash', 'em-202611153931387581-c85dae36d6', '环球下周看点：英伟达迎财报日大考 Anthropic、GTA VI同日上市', '刚刚过去的一周，环球市场在算力龙头的人事巨震与通胀压力中寻找方向。虽然英伟达遭遇重挫，但标普500指数和纳指仍终结了骇人的连续四周下跌，部分AI相关股票也逐步企稳。进入下周，刚刚有所恢复的市场信心将接连迎来两场重要检验：英伟达将在黄仁勋离任后首次公布财报，Claude开发商Anthropic则将登陆纳斯达克。', 'published', NULL, FALSE, 100, 1, '2026-11-14T23:05:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5959b79bb109607f', '100001', 'news-category-finance-flash', 'em-202611143931379169-15dd885ae7', '又有两家期货公司增资落地！', '近日，南华期货公告完成注册资本工商变更，注册资本由7.18亿元增至10.38亿元，增幅约45%。而在不久前，华泰期货也在工商系统完成变更，公司注册资本由39.39亿元增至44.39亿元，增加5亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-14T22:53:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-16427c64f614b736', '100001', 'news-category-finance-flash', 'em-202611153931387216-86791adf44', '以军称打死哈马斯下属军事组织高级成员', '当地时间15日凌晨，以色列国防军发表声明称，14日晚间，以军和以色列国家安全总局（辛贝特）在联合行动中，打死一名巴勒斯坦伊斯兰抵抗运动（哈马斯）下属军事组织的高级成员。但以军尚未披露更多相关详细消息。截至目前，哈马斯方面对此暂无回应。', 'published', NULL, FALSE, 100, 1, '2026-11-14T22:37:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-184f3ad67c4abc73', '100001', 'news-category-finance-flash', 'em-202611153931385531-77edee29f9', '保险业不唯增长论英雄', '2025年，我国原保险保费收入达6.12万亿元，较2021年增长36.3%；原保险赔付支出达2.44万亿元，同比增长6.2%；科技保险为各类科技活动提供风险保障8.7万亿元，同比增长66.9%……一项项数据反映出保险业整体实力稳步增强，持续助力筑牢经济安全网、社会保障网和灾害防控网。', 'published', NULL, FALSE, 100, 1, '2026-11-14T22:30:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-67e044108e477d5f', '100001', 'news-category-finance-flash', 'em-202611153931384552-c94edb39e6', '前10月社融增量中 债券和股票融资合计占比过半', '中国人民银行最新统计数据显示，近期，宏观政策持续加力，为经济稳定增长、金融市场平稳运行营造了适宜的货币金融环境。具体来看，10月末，社会融资规模存量为469.16万亿元，同比增长7.2%；广义货币（M_2）余额359.06万亿元，同比增长7.1%；人民币贷款余额283.33万亿元，同比增长4.7%。', 'published', NULL, FALSE, 100, 1, '2026-11-14T22:17:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ece40e68d6cbbbaa', '100001', 'news-category-finance-flash', 'em-202611153931384019-eff92c207c', '伊朗称霍尔木兹海峡以南2艘油轮触雷发生爆炸', '当地时间15日凌晨，伊朗伊斯兰革命卫队海军表示，稍早前，两艘油轮在霍尔木兹海峡触碰了水雷，引发爆炸并导致火灾。革命卫队称，这两艘油轮当时存在违反相关规定行为，在关闭了导航系统和自动识别系统的情况下，试图秘密通过霍尔木兹海峡。', 'published', NULL, FALSE, 100, 1, '2026-11-14T22:01:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d62bcc8280f788ea', '100001', 'news-category-finance-flash', 'em-202611153931383818-669336fe59', '游戏业“超级印钞机”下周上新！《GTA VI》缘何牵动华尔街？', '下周四，一款连续热卖13年、累计销量接近2.35亿份的游戏续作：《Grand Theft Auto VI》（《侠盗猎车手VI》）将在全球范围内正式上线。据行业机构Sensor Tower估算，截至11月13日，《GTA VI》预售量已超过1200万份；摩根士丹利则预计，到2027年3月，销量就有可能冲到4000万份。', 'published', NULL, FALSE, 100, 1, '2026-11-14T21:55:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e4172fd18cf4970c', '100001', 'news-category-finance-flash', 'em-202611143931365626-907cd41203', '中国重汽尼日利亚子公司正式开业 加快深化西非市场布局', '中国重汽尼日利亚子公司开业仪式13日在尼日利亚拉各斯举行。此次活动是中国重汽2026年西非生态大会系列活动的重要组成部分，旨在进一步深化企业在尼日利亚市场的本地化经营，完善销售和服务网络，来自中尼两国政府、企业及行业机构的约300位代表参加活动。', 'published', NULL, FALSE, 100, 1, '2026-11-14T21:45:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4b6a8548bfe0452a', '100001', 'news-category-finance-flash', 'em-202611153931383716-c2de76f1fc', 'SpaceX首次实现“筷子夹飞船”', 'SpaceX星舰第十五次试飞的上面级飞船返回得克萨斯州星港，在完成着陆点火和姿态翻转后，成功被发射塔“筷子”机械臂捕获。这是SpaceX首次成功捕获从地球轨道返回的星舰上面级飞船，为实现星舰完全、快速重复使用迈出关键一步。此次飞船此前已完成26颗第三代星链卫星部署，但超重型助推器回收未能成功，因此本次任务未实现两级全部回收。', 'published', NULL, FALSE, 100, 1, '2026-11-14T21:22:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef5f414e5bd1f004', '100001', 'news-category-finance-flash', 'em-202611153931383686-7494fda609', '直播画面显示：星舰飞船正在重返地球大气层 按计划将在20分钟后尝试被发射台捕获', '直播画面显示，星舰飞船正在重返地球大气层，按计划将在20分钟后尝试被发射台捕获。', 'published', NULL, FALSE, 100, 1, '2026-11-14T21:13:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5fc83df5882b21f', '100001', 'news-category-finance-flash', 'em-202611143931345666-e894dc43bc', '天弘基金聂挺进：A股中长期投资价值已明显大于风险', '7月以来，A股市场经历了一轮持续数月的调整，科技板块波动尤为明显。近日，天弘基金副总经理聂挺进在接受21世纪经济报道采访时表示，本轮市场调整主要由三重外部冲击叠加情绪和筹码因素所致，并不意味着A股上市公司内在竞争力出现明显恶化。', 'published', NULL, FALSE, 100, 1, '2026-11-14T20:58:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-314d754deb975b27', '100001', 'news-category-finance-flash', 'em-202611153931383524-ebc797010b', 'SpaceX发布第十五次星舰试飞最新进展称 上面级飞船已成功完成离轨点火 正沿预定轨迹准备再入地球大气层', 'SpaceX发布第十五次星舰试飞最新进展称，上面级飞船已成功完成离轨点火，正沿预定轨迹准备再入地球大气层，将按计划在得克萨斯州星际基地尝试发射塔机械臂捕获。', 'published', NULL, FALSE, 100, 1, '2026-11-14T20:42:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a9a4f81d04b060e3', '100001', 'news-category-finance-flash', 'em-202611143931379261-ecc70bb1e4', '骤降99%！量化之王清仓式减持英伟达等个股', '素有“量化之王”之称的文艺复兴科技（Renaissance Technologies）日前提交了最新的13F文件，截至9月30日，文艺复兴科技持有的英伟达股票从第二季度末的709万股降至2.317万股，减持99.7%。Meta持股则从202万股降至1577股，减持99.9%，两家公司的持仓几乎被清空。', 'published', NULL, FALSE, 100, 1, '2026-11-14T20:40:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dfab4e985e3144a0', '100001', 'news-category-finance-flash', 'em-202611153931383428-7129dcd9dc', '成都数字文创亮相希腊雅典', '11月13日，在雅典举行的第四届中希国际戏剧节开幕式上，希腊观众被成都数字文创产品吸引。新华社记者陈刚摄据介绍，成都近年来在数字文创领域持续发力，已陆续在本土孵化了“哪吒”“八仙”“熊猫家园”“胖花”等众多文创IP。', 'published', NULL, FALSE, 100, 1, '2026-11-14T20:25:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4123f236d6a8d8bf', '100001', 'news-category-finance-flash', 'em-202611153931383352-f616f1409c', '相距约1.7万公里 挡不住生意越做越大！红利从哪里来？', '相距约1.7万公里的中国与秘鲁，因自贸协定升级议定书而越走越近。本月初，该议定书正式生效。一边是深圳糖果企业半天办结原产地证书，加快通关流程；另一边是秘鲁羊驼绒制品等特色产品加速进入中国市场。“一出一进”之间，通关更便利、关税更优惠，双边贸易额16年间增长近7倍。这样的自贸红利，正在更多APEC经济体之间持续释放。', 'published', NULL, FALSE, 100, 1, '2026-11-14T20:24:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-edcee3bf091ff288', '100001', 'news-category-finance-flash', 'em-202611153931381757-f730df4c29', '东方精工换届选举 控股股东及实控人唐灼林当选董事长 邱业致担任总经理', '11月13日，东方精工（002611）发布公告，公司完成了第六届董事会的换届选举，新董事会由7名董事组成，其中包括非独立董事唐灼林（董事长）、邱业致、邵永锋，职工代表董事陈惠仪和独立董事邓根鹏（会计专业人士）、冯志东、李侃童。', 'published', NULL, FALSE, 100, 1, '2026-11-14T20:09:37Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c5c578536b4b27b', '100001', 'news-category-finance-flash', 'em-202611143931331093-88d240778d', '从欧洲家庭到北美车间 机器人成湖南出海新力量', '长沙优龙机器人近期将2000套外骨骼机器人发往法国、意大利、英国市场。该设备可为腿部提供30%行走助力，能自动识别人体运动意图，累计出货量已超2万套。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:54:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7469287b53b49aa4', '100001', 'news-category-finance-flash', 'em-202611143931381025-c739030b28', '天士力多款产品纳入新版医保 创新品种赋能业绩增长', '近日，国家医保局、人力资源和社会保障部正式发布2026版国家基本医疗保险药品目录，天士力(600535)多款产品被纳入本次医保目录。继三季度实现多个产品新增进入国家基本药物目录以后，公司产品的市场准入再次获得进展，尤其是国产原研溶栓药物创新品种普佑克等产品获得市场准入突破与政策支持。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:39:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-941c93a5d1581777', '100001', 'news-category-finance-flash', 'em-202611153931383224-e2f969fa57', 'SpaceX：各团队完成状态确认 均同意星舰飞船返回星际基地发射场', 'SpaceX在星舰第15次试飞直播中宣布，各团队已完成返回发射场前的状态核查，一致确认可以继续执行返回任务，涉及隔热盾、襟翼、结构、气动、制导导航与控制等系统。发射台及发射塔的现场检查结果正常，发射塔已做好捕获准备。星舰将尝试返回星际基地，由发射塔首次捕获其上面级。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:23:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-397a7fdb3a5722db', '100001', 'news-category-finance-flash', 'em-202611143931356820-09e61ee76d', 'TCL华星举办DTC2026 推出显示研发设计全流程“硅基员工”', '11月13日，TCL科技旗下TCL华星举办以“臻图视界AI启星程”为主题的2026年TCL华星全球显示生态大会（DTC2026）。记者从大会上了解到，TCL华星推出显示研发设计全流程“硅基员工”，这是一款融合大模型、多智能体与专业工程工具的AI智能体，实现“端到端”产品开发，提升响应客户速度，减少产品开发周期。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:20:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e90582df933f8915', '100001', 'news-category-finance-flash', 'em-202611143931336520-829c796d0f', '比亚迪辟谣：无任何事实依据', '14日，“比亚迪网络举报中心”微信公众号发布公告称，针对网络流传“某数字能源出售给比亚迪”相关信息，经核实：该消息无任何事实依据，属于虚假信息，请广大网友切勿轻信、转发。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:10:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0f0548e584d43613', '100001', 'news-category-finance-flash', 'em-202611153931383077-e0b08b8d55', '又一国产 全球爆单！', '3D打印正在破圈，一边走进商场，成为商场吸引客流的新业态，重塑商场招商逻辑；另一边，扎根工厂车间，打破“只能打样”的刻板印象，落地小批量柔性制造。与此同时，国产3D打印设备还扬帆出海，在全球开辟微型制造新赛道。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:10:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c543b9b2b5effd1', '100001', 'news-category-finance-flash', 'em-202611153931383193-fb00decd2a', '美联邦航空局局长：全美航空运输预计15日晚恢复正常', '美国联邦航空局局长布赖恩·贝德福德14日说，全美航空运输预计15日晚能恢复正常。在全国航班停飞引发航空出行混乱后，贝德福德14日向美国公众道歉，并称“最糟糕的时期已经过去”，全国航空运输预计15日晚能恢复正常。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:08:12Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-45d29dd6d32ecccc', '100001', 'news-category-finance-flash', 'em-202611153931382992-e9af624ec3', '叙利亚大马士革农村省发生汽车炸弹爆炸致2死1伤', '叙利亚国家通讯社14日援引叙安全部队消息说，叙利亚大马士革农村省杰拉马纳区发生汽车炸弹爆炸，造成包括一名女孩在内的两人死亡，另有一人受伤。安全部队已在现场设立警戒封锁并展开调查。', 'published', NULL, FALSE, 100, 1, '2026-11-14T19:00:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-beee823c5cafbd42', '100001', 'news-category-finance-flash', 'em-202611143931380789-5ffa34ad0e', '前沿生物前三季度与三季度单季业绩分化 核心产品艾可宁已进入医保常规目录', '11月13日，前沿生物（688221）举行2026年第三季度业绩说明会。公司三季度单季营收下滑并亏损7600多万元，与前三季度业绩严重分化。', 'published', NULL, FALSE, 100, 1, '2026-11-14T18:56:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-21532dbbfbd2b580', '100001', 'news-category-finance-flash', 'em-202611143931353556-378a18822e', '百利天恒宜泽康纳入2026年版国家医保药品目录', '11月14日，2026年版国家医保药品目录在“2026年全国创新药高质量发展大会”上公布。由百利天恒自主研发的全球首个且唯一获批上市的EGFR×HER3双抗ADC宜泽康（伦康依隆妥单抗/iza-bren），通过国家医保谈判，成功纳入《国家基本医疗保险、工伤保险和生育保险药品目录（2026）》。得益于今年首次实施的医保“预申报”机制，宜泽康实现上市首年即纳入医保。新版国家医保目录将于2027年1月1日起正式实施。', 'published', NULL, FALSE, 100, 1, '2026-11-14T18:53:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8de35871ebdb5e41', '100001', 'news-category-finance-flash', 'em-202611143931343777-883d77f9f9', '金饰克价连续四日下调 较年内高点跌超500元', '截至美东时间周五，现货黄金跌破3900美元/盎司，白银跌破49美元/盎司。本周现货黄金累计下跌4.9%，创3月底以来最大周跌幅；COMEX黄金期货累计下跌4.60%，COMEX白银期货累计下跌6.34%。据央视财经报道，受国际金价下跌传导，国内多家品牌金饰价格连续四日下调，四天累计下跌约70元/克。', 'published', NULL, FALSE, 100, 1, '2026-11-14T18:44:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a4270b17bb057638', '100001', 'news-category-finance-flash', 'em-202611143931348496-3615264df7', '吴清：股票、债券等直接融资占社会融资增量的比重已近50%', '证监会主席吴清在2026中国资本市场学会年会上表示，中国金融结构迎来深刻调整，今年前九个月，股票、债券等直接融资占社会融资增量的比重已近50%。', 'published', NULL, FALSE, 100, 1, '2026-11-14T18:27:23Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-de0dd83f5308f41e', '100001', 'news-category-finance-flash', 'em-202611153931382830-a96af0d3a9', '黄仁勋被撤换 英伟达创14年来最长连跌纪录 超5万人请愿黄仁勋复职', '黄仁勋遭撤换后，英伟达股价当地时间13日再跌2%，收在每股162.85美元，全周大跌13%，创下逾18个月来最大单周跌幅，一周市值蒸发逾5700亿美元。英伟达连续六周收黑，缔造2012年以来最长连跌纪录。', 'published', NULL, FALSE, 100, 1, '2026-11-14T18:12:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c57a92a7107414db', '100001', 'news-category-finance-flash', 'em-202611153931382751-c6ef385397', '胡塞武装：沙特主导的联军对也门发动72次空袭', '当地时间11月14日晚，也门胡塞武装发表声明称，过去24小时内，沙特阿拉伯主导的多国联军对也门萨达省、塔伊兹省、拉赫季省和焦夫省的目标发动了72次空袭。声明还称，自也门新一轮军事冲突升级以来，沙特主导的联军发动的空袭和导弹袭击总数已达5020次。', 'published', NULL, FALSE, 100, 1, '2026-11-14T17:59:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-53e6fe930f8e3504', '100001', 'news-category-finance-flash', 'em-202611143931375930-02491e6403', '一场科幻赛事 三年间如何长出“产业骨骼”？', '11月13日至15日，2026成都科幻周活动在成都举行。其中，2026成都科幻周开幕式暨第三届成都天问华语科幻文学大赛（以下简称“成都天问大赛”）成果发布会于14日下午在成都科幻馆重磅开场，刘慈欣、何夕、王晋康、韩松等300位科幻作家和160余家企业代表齐聚一堂。', 'published', NULL, FALSE, 100, 1, '2026-11-14T17:40:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a6c6b687cae6ae8c', '100001', 'news-category-finance-flash', 'em-202611153931382455-0de94689c5', '哥伦比亚西南部发生一起交通事故 已致8死20伤', '当地时间11月14日凌晨，哥伦比亚一辆长途巴士在该国西南部乌伊拉省里韦拉附近的45号国道发生侧翻事故。总台记者获悉，事故已造成至少8人死亡、20人受伤。', 'published', NULL, FALSE, 100, 1, '2026-11-14T17:20:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-72fab5243ea1f7f5', '100001', 'news-category-finance-flash', 'em-202611143931377317-4cfddd366d', '永辉、盒马、山姆、叮咚都在降！猪肉价格跌到近10年最低', '全国最新批发价格监测数据显示，进入11月，全国猪肉平均批发价为14.81元/公斤，生猪价格已创出近十年新低。记者走访沪上菜场发现，部分猪肉价格已明显低于蔬菜。', 'published', NULL, FALSE, 100, 1, '2026-11-14T17:05:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c3a2c7c7695dea4c', '100001', 'news-category-finance-flash', 'em-202611153931382366-aa70c6ffaf', '马斯克：SpaceX通信卫星最终将超10万颗', '马斯克在回应“星舰单次发射可增加50Tbps星链带宽”的评价时表示，这个数据对全球国际带宽总量的实际提升“没有听起来那么好”，因为星链需要在近地轨道部署大量卫星，才能在全球范围内实现这样的带宽提升。不过，他预计，SpaceX通信卫星最终将超过10万颗，其中大多数将为V4或V5版本。（注：星舰第15次试飞搭载26颗第三代星链（V3）卫星，每颗可为星座增加约1Tbps通信容量，合计约26Tbps。马斯克所称单次发射超过50Tbps，指的是未来任务的预期。）', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:50:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-50cb0eccc8941be0', '100001', 'news-category-finance-flash', 'em-202611143931376928-2718a1ba00', '中信建投：预计2027年实际利率进一步上行空间有限 金价有望震荡上行', '中信建投发布黄金2027年投资展望称，2026年压制金价的核心矛盾来自实际利率上行，展望2027年，实际利率进一步上行空间有限，叠加本轮加息预期已被市场充分定价，同时全球央行持续购金将在金价回调阶段形成承接、构筑底部支撑，预期2027年金价有望震荡上行。风险方面，美伊地缘冲突推升油价，进而扰动通胀仍是2027年主要风险变量，但预期该因素对金价的冲击力度预计边际减弱。黄金股方面，2026年行业安全整治带来产量阶段性承压，2027年预计停产矿山陆续复产，产量有望迎来修复释放，当前板块估值安全边际充足，若金价中枢抬升，黄金板块有望迎来业绩与估值的双击行情，建议优先布局产量增长确定性强、成本管控稳健、资源禀赋与公司治理优质的标的。', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:37:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9adfb5e03c4119b9', '100001', 'news-category-finance-flash', 'em-202611153931382256-b86247d4ce', '黎巴嫩总统与联合国副秘书长举行会见 讨论联黎部队未来安排', '当地时间14日，黎巴嫩总统约瑟夫·奥恩与联合国常务副秘书长阿明娜·穆罕默德举行会见，双方就黎巴嫩南部局势及联合国驻黎巴嫩临时部队（联黎部队）的未来安排等问题进行了讨论。', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:33:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3e2b781d638b09e0', '100001', 'news-category-finance-flash', 'em-202611143931379036-b6a7f2d973', '业绩说明会上 多家券商回应股价问题', '近日，多家券商陆续召开了三季度业绩说明会。不少投资者认为，券商在业绩高增的同时股价却缺乏表现，纷纷就股价问题向管理层提问。头部券商表示，“将研究和考虑进一步丰富价值运营和价值实现手段，促进公司股价合理反映公司的投资价值”“审慎评估其他市值管理方式的可行性”。此前，券商的坏账减值计提、国际化业务等也受到关注。', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:32:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1b13eb870ff69c3a', '100001', 'news-category-finance-flash', 'em-202611143931377276-412e16328e', '宁德时代 加速换电！', '11月13日晚间，北汽极狐贝塔S3 535 ULTRA+激光换电版上市，北汽极狐贝塔T1推出换电版车型，这是北汽集团携手宁德时代完善换电生态的新动作。此前，汽车行业质疑换电，但宁德时代等巨头入局换电生态，促使众多车企重新认识换电，并快速加入换电生态。', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:30:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-374e1b3cc118ba84', '100001', 'news-category-finance-flash', 'em-202611153931381830-95ec0963b9', '欧盟敦促以色列开放加沙所有过境点', '当地时间14日，欧盟外交与安全政策高级代表卡拉斯就加沙地带人道主义局势发表声明，对当地持续恶化的人道主义危机深表关切。声明说，加沙地带遭遇的严重洪灾和严寒天气进一步加剧了当地民众的生存困境，敦促以色列立即放行人道主义援助物资。', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:10:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-555c0c0d9a54b79a', '100001', 'news-category-finance-flash', 'em-202611143931368159-3c53aee4cd', '2件8折清仓 耐克关掉三里屯大店：与滔搏合作运营不到5年 线上销售收紧后线下也在调整', '开业不到5年，耐克关掉了曾是北京最大的一家体验店。业内人士分析指出，补贴退坡，线上权被收走，或是两家大店接连关闭的原因之一。', 'published', NULL, FALSE, 100, 1, '2026-11-14T16:05:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ec01a21106d5a844', '100001', 'news-category-finance-flash', 'em-202611143931381517-60f70da631', 'SpaceX：星舰飞船仍有望返回发射场', 'SpaceX发布“星舰”第十五次试飞最新进展：星舰正在轨道上滑行，目前状态良好，仍有望于今天返回发射场。发射台和塔架系统已准备就绪，可执行捕获操作。', 'published', NULL, FALSE, 100, 1, '2026-11-14T15:52:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-86f58e86094d27f7', '100001', 'news-category-finance-flash', 'em-202611143931381266-ca4b4c5444', '特斯拉Cybercab个人购车设使用限制 且暂禁商业用途', '特斯拉向部分客户开放个人版Cybercab预订之际，媒体研究该车型的购车及订阅条款后总结称：除29990美元车价外，车主还须维持目前每月299美元的自动驾驶订阅，否则车辆无法运行；车辆仅能在特斯拉支持的地理围栏范围内使用，公司保留调整运营区域的权利；未经特斯拉书面授权或通过产品功能开放，车主不得将车辆用于网约车、配送、租赁等商业用途，也不能接入特斯拉自营Robotaxi网络。订购页面另要求支付1000美元不可退订金，预计12月交付，但交付时间并无保证。', 'published', NULL, FALSE, 100, 1, '2026-11-14T15:45:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bc8eaf73ab9d12ca', '100001', 'news-category-finance-flash', 'em-202611143931381388-58aa687b1b', '暗盘白银跌破44美元/盎司 日内跌幅达2%', '11月14日，暗盘白银跌破44美元/盎司，日内跌幅达2%。', 'published', NULL, FALSE, 100, 1, '2026-11-14T15:44:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1d7e91c556204931', '100001', 'news-category-finance-flash', 'em-202611143931381451-2384ff7f85', '暗盘金价（人民币）日内跌超1%', '11月14日，暗盘金价（人民币）日内跌超1%，现报819.7901元/克。', 'published', NULL, FALSE, 100, 1, '2026-11-14T15:44:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cae52127e89694eb', '100001', 'news-category-finance-flash', 'em-202611143931380694-80f0becb49', '北京解除空气重污染橙色预警', '11月14日晚，北京应急发布消息，根据最新空气质量预报，11月15日起，北京市空气质量将逐步好转。按照《北京市空气重污染应急预案（2023年修订）》规定，北京市空气重污染应急指挥部办公室于2026年11月14日24时解除空气重污染橙色预警。', 'published', NULL, FALSE, 100, 1, '2026-11-14T15:15:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z')
